_G.YattaEffToon = function()
    local char = LocalPlayer.Character
    local toonName = ""
    if char then
        local tAttr = char:GetAttribute("Toon") or char:GetAttribute("Character") or char:GetAttribute("ToonName")
        if tAttr then
            toonName = tostring(tAttr)
        else
            toonName = char.Name
        end
    end
    return toonName, toonName, false
end

