_G.YattaScaleOf = function(inst)
    local s, p = 1, inst
    while p and p:IsA("GuiBase2d") do
        for _, c in ipairs(p:GetChildren()) do
            if c:IsA("UIScale") then s = s * c.Scale end
        end
        p = p.Parent
    end
    return math.max(s, 0.01)
end
