function sfUpdateDrag(input)
    local delta = input.Position - sf.dragStart
    if math.abs(delta.X) > 6 or math.abs(delta.Y) > 6 then sf.moved = true end
    if not sf.moved then return end
    local cam = workspace.CurrentCamera or workspace:FindFirstChildOfClass("Camera")
    if not cam then return end
    local vp = cam.ViewportSize
    local fw = ShowFrame.AbsoluteSize.X
    local fh = ShowFrame.AbsoluteSize.Y
    local baseX = sf.startPos.X.Scale * vp.X + sf.startPos.X.Offset
    local baseY = sf.startPos.Y.Scale * vp.Y + sf.startPos.Y.Offset
    ShowFrame.Position = UDim2.new(
        0, math.clamp(baseX + delta.X, 0, vp.X - fw),
        0, math.clamp(baseY + delta.Y, 0, vp.Y - fh))
end
ShowFrame.InputBegan:Connect(function(inp)
