local pgOrds = {}
local lstOrds = {}
local hidden     = {}
function snapshotPage(page)
    local snap = {}
    for _, ch in ipairs(page:GetChildren()) do
        if ch:IsA("UIListLayout") or ch:IsA("UIPadding") then continue end
        snap[ch] = ch.LayoutOrder
    end
    pgOrds[page] = snap
end
function snapshotList(list)
    if lstOrds[list] then return end
    local snap = {}
    for _, ch in ipairs(list:GetChildren()) do
        if ch:IsA("UIListLayout") or ch:IsA("UIPadding") then continue end
        snap[ch] = ch.LayoutOrder
    end
    lstOrds[list] = snap
end
local skipText = {[""]=true, ["X"]=true, ["[ COPY ]"]=true}
function rowLabel(row)
    if row.Name:sub(1, 10) == "SecHeader_" then
        for _, ch in ipairs(row:GetChildren()) do
            if ch:IsA("TextLabel") then return ch.Text:lower() end
        end
        return row.Name:sub(11):lower():gsub("_", " ")
    end
    for _, ch in ipairs(row:GetChildren()) do
        if ch:IsA("TextLabel") then
            local t = ch.Text or ""
            if #t > 0 and not skipText[t] then
                return t:lower()
            end
        end
    end
    return ""
end
function wordMatch(text, words)
    for _, w in ipairs(words) do
        if not text:find(w, 1, true) then return false end
    end
    return true
end
function searchFilter(query, page)
    if not page or not page.Parent then return end
    query = (query or ""):lower():gsub("^%s*(.-)%s*$", "%1")
    if query == "" then
        local pageSnap = pgOrds[page]
        local pageHid  = (hidden and hidden[page]) or {}
        for _, ch in ipairs(page:GetChildren()) do
            if ch:IsA("UIListLayout") or ch:IsA("UIPadding") then continue end
            ch.Visible = not pageHid[ch]
            if pageSnap and pageSnap[ch] then ch.LayoutOrder = pageSnap[ch] end
            if ch:IsA("Frame") and ch:FindFirstChildOfClass("UIListLayout") then
                local listSnap = lstOrds[ch]
                for _, sub in ipairs(ch:GetChildren()) do
                    if sub:IsA("UIListLayout") or sub:IsA("UIPadding") then continue end
                    sub.Visible = not pageHid[sub]
                    if listSnap and listSnap[sub] then sub.LayoutOrder = listSnap[sub] end
                end
            end
        end
        pgOrds[page] = nil
        if hidden then hidden[page] = nil end
        return
    end
    if not pgOrds[page] then
        snapshotPage(page)
        local hidden = {}
        for _, ch in ipairs(page:GetChildren()) do
            if ch:IsA("UIListLayout") or ch:IsA("UIPadding") then continue end
            if not ch.Visible then hidden[ch] = true end
            if ch:IsA("Frame") and ch:FindFirstChildOfClass("UIListLayout") then
                for _, sub in ipairs(ch:GetChildren()) do
                    if not sub:IsA("UIListLayout") and not sub:IsA("UIPadding") and not sub.Visible then
                        hidden[sub] = true
                    end
                end
            end
        end
        hidden = hidden or {}
        hidden[page] = hidden
    end
    local words = {}
    for w in query:gmatch("%S+") do words[#words + 1] = w end
    if #words == 0 then return end
    local allRows = {}
    local pageSnap = pgOrds[page] or {}
    local pageHidden = (hidden and hidden[page]) or {}
    local function collectContainer(ch)
        snapshotList(ch)
        local listSnap = lstOrds[ch] or {}
        for _, sub in ipairs(ch:GetChildren()) do
            if sub:IsA("UIListLayout") or sub:IsA("UIPadding") then continue end
            if pageHidden[sub] then continue end
            allRows[#allRows + 1] = {
                obj        = sub,
                container  = ch,
                origLO     = listSnap[sub] or sub.LayoutOrder,
                listOrigLO = pageSnap[ch] or ch.LayoutOrder,
            }
        end
    end
    for _, ch in ipairs(page:GetChildren()) do
        if ch:IsA("UIListLayout") or ch:IsA("UIPadding") then continue end
        if pageHidden[ch] then continue end
        if ch:IsA("Frame") and ch:FindFirstChildOfClass("UIListLayout") then
            collectContainer(ch)
        else
            allRows[#allRows + 1] = {
                obj    = ch,
                origLO = pageSnap[ch] or ch.LayoutOrder,
            }
        end
    end
    table.sort(allRows, function(a, b) return a.origLO < b.origLO end)
    local matchedContainers = {}
    local matchedRows       = {}
    local unmatchedRows     = {}
    for _, ch in ipairs(page:GetChildren()) do
        if ch:IsA("UIListLayout") or ch:IsA("UIPadding") then continue end
        if ch.Name:sub(1, 11) == "ToggleList_" then
            local label = ch.Name:sub(12):lower():gsub("_", " ")
            if wordMatch(label, words) then
                matchedContainers[ch] = true
            end
        end
    end
    for _, entry in ipairs(allRows) do
        local obj = entry.obj
        local container = entry.container
        if container and matchedContainers[container] then
            matchedRows[#matchedRows + 1] = entry
        elseif obj.Name:sub(1, 10) == "SecHeader_" then
            unmatchedRows[#unmatchedRows + 1] = entry
        else
            local label = rowLabel(obj)
            if wordMatch(label, words) then
                matchedRows[#matchedRows + 1] = entry
            else
                unmatchedRows[#unmatchedRows + 1] = entry
            end
        end
    end
    for _, ch in ipairs(page:GetChildren()) do
        if ch:IsA("UIListLayout") or ch:IsA("UIPadding") then continue end
        ch.Visible = false
    end
    for _, entry in ipairs(unmatchedRows) do
        entry.obj.Visible = false
    end
    local order = 1
    local shownContainers = {}
    for _, entry in ipairs(matchedRows) do
        entry.obj.Visible = true
        entry.obj.LayoutOrder = order
        order = order + 1
        if entry.container then
            entry.container.Visible = true
            if not shownContainers[entry.container] then
                shownContainers[entry.container] = true
                entry.container.LayoutOrder = order
            end
        else
        end
    end
    local containerOrder = order
    for container in pairs(shownContainers) do
        container.LayoutOrder = containerOrder
        containerOrder = containerOrder + 1
    end
end
