function pngOk(d) return type(d) == "string" and #d > 67 and string.sub(d, 2, 4) == "PNG" end
function imgHttp(url)
    local req = (syn and syn.request) or http_request or request or (http and http.request)
    if type(req) == "function" then
        local ok, res = pcall(req, { Url = url, Method = "GET" })
        if ok and type(res) == "table" and (res.StatusCode == nil or res.StatusCode == 200) and type(res.Body) == "string" then
            return res.Body
        end
        return nil
    end
    if game.HttpGet then
        local ok, d = pcall(function() return game:HttpGet(url) end)
        if ok then return d end
    end
    return nil
end
function DownloadGithubImage(url, cachePath)
    local hasHttp = (syn and syn.request) or http_request or request or (http and http.request) or game.HttpGet
    if not (writefile and isfile and getcustomasset and hasHttp) then
        local miss = {}
        if not writefile then miss[#miss + 1] = "writefile" end
        if not isfile then miss[#miss + 1] = "isfile" end
        if not getcustomasset then miss[#miss + 1] = "getcustomasset" end
        if not hasHttp then miss[#miss + 1] = "HttpGet" end
        _G.YattaImgWhy = "executor lacks " .. table.concat(miss, ", ")
        return nil
    end
    local need = true
    if isfile(cachePath) then
        local okR, cur = pcall(readfile, cachePath)
        if okR and pngOk(cur) then need = false end
    end
    if need then
        if tick() < (_G.YattaImgCoolUntil or 0) then _G.YattaImgWhy = "download failed (paused)"; return nil end
        while _G.YattaImgBusy do task.wait(0.1) end
        _G.YattaImgBusy = true
        local data
        local okD = pcall(function()
            for attempt = 1, 3 do
                local d = imgHttp(url)
                if pngOk(d) then data = d; break end
                task.wait(0.6 * attempt)
            end
        end)
        _G.YattaImgBusy = false
        if not data then
            _G.YattaImgCoolUntil = tick() + 30
            _G.YattaImgWhy = "download failed"
            return nil
        end
        if not pcall(writefile, cachePath, data) then _G.YattaImgWhy = "writefile failed"; return nil end
    end
    local aok, uri = pcall(getcustomasset, cachePath)
    if aok and uri and uri ~= "" then return uri end
    _G.YattaImgWhy = "getcustomasset failed"
    return nil
end
