        ts:Create(uiScale, scaleTI, {Scale = target}):Play()
    end
    local function Anim(ns)
        state = ns
        ts:Create(togImg, tweenInfo, {ImageColor3 = ns and togColorOn or togColorOff}):Play()
        togStateLbl.Text = ns and "On" or "Off"
        for _, cb in ipairs(callbacks) do
            if state ~= ns then break end
            cb(ns)
        end
    end
    local clickBtn = Instance.new("TextButton", togWrapper)
    clickBtn.Name               = "TogClickBtn"
    clickBtn.Size               = UDim2.new(1, 0, 1, 0)
    clickBtn.BackgroundTransparency = 1
    clickBtn.Text               = ""
    clickBtn.AutoButtonColor    = false
    clickBtn.ZIndex             = 209
    clickBtn.MouseEnter:Connect(function()   hovered = true;  ApplyScale() end)
    clickBtn.MouseLeave:Connect(function()   hovered = false; held = false; ApplyScale() end)
    clickBtn.MouseButton1Down:Connect(function() held = true;  ApplyScale() end)
    clickBtn.MouseButton1Up:Connect(function()   held = false; ApplyScale() end)
    clickBtn.MouseButton1Click:Connect(function() ps(sClick); Anim(not state) end)
    local dummyTrack = Instance.new("Frame", togWrapper)
    dummyTrack.Size = UDim2.new(0, 1, 0, 1)
    dummyTrack.BackgroundTransparency = 1
    dummyTrack.BorderSizePixel = 0
    dummyTrack.ZIndex = 200
    do
        local TextSvc = game:GetService("TextService")
        local baseH = tall and Px(48) or Px(34)
        local lastW = -1
        local function fit()
            if not row.Parent then return end
            local rawW = row.AbsoluteSize.X
            if rawW <= 0 or rawW == lastW then return end
            lastW = rawW
            local aw = rawW / _G.YattaScaleOf(row)
            local availW = aw - Px(8) - (TgW + Px(14)) - Px(2)
            if availW < 20 then return end
            local okT, nat = pcall(TextSvc.GetTextSize, TextSvc, lbl.Text, lbl.TextSize, lbl.Font, Vector2.new(10000, 10000))
            if not okT then return end
            if nat.X <= availW then
                if not tall then lbl.TextWrapped = false end
                row.Size = UDim2.new(1, 0, 0, baseH)
                return
            end
            local okW, wr = pcall(TextSvc.GetTextSize, TextSvc, lbl.Text, lbl.TextSize, lbl.Font, Vector2.new(availW, 10000))
            if not okW then return end
            lbl.TextWrapped = true
            lbl.TextYAlignment = Enum.TextYAlignment.Center
            row.Size = UDim2.new(1, 0, 0, math.max(baseH, wr.Y + Px(14)))
        end
        row:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
        task.defer(fit)
    end
    local togApi = {
        GetState  = function() return state end,
        SetState  = Anim,
        OnChanged = function(f) callbacks[#callbacks + 1] = f end,
        Label     = lbl,
        Track     = dummyTrack,
        Knob      = togImg,
        ClickBtn  = clickBtn,
    }
    if S.mkFloatPin then pcall(S.mkFloatPin, row, lbl, togApi, labelText) end
    return row, togApi
end
