        held = false; ApplyScale()
    end)
    local flashBase, flashTok, flashTweens = nil, 0, {}
    local flashGray = Color3.fromRGB(180, 180, 180)
    local flashTI = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    btn.MouseButton1Click:Connect(function()
        ps(sClick)
        for _, tw in ipairs(flashTweens) do pcall(function() tw:Cancel() end) end
        flashTweens = {}
        if not flashBase then
            flashBase = { midImg.ImageColor3, leftImg.ImageColor3, rightImg.ImageColor3 }
        end
        midImg.ImageColor3   = flashGray
        leftImg.ImageColor3  = flashGray
        rightImg.ImageColor3 = flashGray
        flashTok = flashTok + 1
        local myTok = flashTok
        task.delay(0.12, function()
            if myTok ~= flashTok or not (frame and frame.Parent) then return end
            local base = flashBase
            local imgs = { midImg, leftImg, rightImg }
            for i, img in ipairs(imgs) do
                local tw = ts:Create(img, flashTI, { ImageColor3 = base[i] })
                flashTweens[#flashTweens + 1] = tw
                tw:Play()
            end
            task.delay(flashTI.Time + 0.02, function()
                if myTok ~= flashTok then return end
                midImg.ImageColor3, leftImg.ImageColor3, rightImg.ImageColor3 = base[1], base[2], base[3]
                flashBase = nil
                flashTweens = {}
            end)
        end)
    end)
    return btn, frame, lbl
end
