donateToast.BackgroundTransparency  = 1
donateToast.BorderSizePixel         = 0
donateToast.Text                    = "Copied link to clipboard."
donateToast.TextColor3              = cTM
donateToast.TextTransparency        = 1
donateToast.Font                    = rf
donateToast.TextSize                = Px(14)
donateToast.TextWrapped             = true
donateToast.ZIndex                  = 2147483647
donateToast.Visible                 = false
local donateToastStroke = ats(donateToast)
donateToastStroke.Transparency = 1
local donateToastToken = 0
local donateFadeInTI  = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local donateFadeOutTI = TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
function ShowDonateToast(msg)
    donateToastToken = donateToastToken + 1
    local myToken = donateToastToken
    donateToast.Text = msg or "Copied link to clipboard."
    donateToast.Visible = true
    ts:Create(donateToast, donateFadeInTI, {TextTransparency = 0}):Play()
    ts:Create(donateToastStroke, donateFadeInTI, {Transparency = 0}):Play()
    task.delay(3, function()
        if donateToastToken == myToken and donateToast and donateToast.Parent then
            local tw = ts:Create(donateToast, donateFadeOutTI, {TextTransparency = 1})
            ts:Create(donateToastStroke, donateFadeOutTI, {Transparency = 1}):Play()
            tw.Completed:Connect(function()
                if donateToastToken == myToken and donateToast and donateToast.Parent then
                    donateToast.Visible = false
                end
            end)
            tw:Play()
        end
    end)
end
end
do
