        l.SortOrder           = Enum.SortOrder.LayoutOrder
        l.HorizontalAlignment = Enum.HorizontalAlignment.Center
    end
    local seq, lastShown = 0, {}
    ui.Notify = function(msg, withErr, color, duration)
        if withErr then ps(sErr) end
        local now = tick()
        if lastShown[msg] and now - lastShown[msg] < 0.4 then return end
        lastShown[msg] = now
        seq = seq + 1
        local lbl = Instance.new("TextLabel", holder)
        lbl.LayoutOrder            = seq
        lbl.Size                   = UDim2.new(1, 0, 0, 0)
        lbl.AutomaticSize          = Enum.AutomaticSize.Y
        lbl.BackgroundTransparency = 1
        lbl.Text                   = msg
        lbl.TextColor3             = color or Color3.fromRGB(255, 70, 70)
        lbl.TextTransparency       = 1
        lbl.Font                   = rf
        lbl.TextSize               = Px(16)
        lbl.TextWrapped            = true
        lbl.ZIndex                 = 2147483647
        local st = ats(lbl)
        st.Transparency = 1
        ts:Create(lbl, TweenInfo.new(0.15), {TextTransparency = 0}):Play()
        ts:Create(st,  TweenInfo.new(0.15), {Transparency = 0}):Play()
        local kids = {}
        for _, c in ipairs(holder:GetChildren()) do
            if c:IsA("TextLabel") then kids[#kids + 1] = c end
        end
        table.sort(kids, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
        while #kids > 6 do table.remove(kids, 1):Destroy() end
        task.delay(duration or 3, function()
            if not (lbl and lbl.Parent) then return end
            local tw = ts:Create(lbl, TweenInfo.new(0.5), {TextTransparency = 1})
            ts:Create(st, TweenInfo.new(0.5), {Transparency = 1}):Play()
            tw.Completed:Connect(function() if lbl and lbl.Parent then lbl:Destroy() end end)
            tw:Play()
        end)
    end
    _G.YattaNotify = ui.Notify

    task.defer(function()
        task.wait(1)
        pcall(ui.Notify, "If you're having trouble with navitaging/interacting because of the UI, open settings tab and change the UI size. (1 - 15)", true, Color3.fromRGB(255, 70, 70), 10)
    end)

    local nHolder = Instance.new("Frame", ScreenGui)
    nHolder.Name                   = "YattaNotifier"
    nHolder.AnchorPoint            = Vector2.new(1, 0.5)
    nHolder.Position               = UDim2.new(1, -Px(12), 0.5, 0)
