        lbl.LayoutOrder            = nSeq
        lbl.Size                   = UDim2.new(1, 0, 0, 0)
        lbl.AutomaticSize          = Enum.AutomaticSize.Y
        lbl.BackgroundTransparency = 1
        lbl.Text                   = text
        lbl.TextColor3             = Color3.fromRGB(255, 230, 80)
        lbl.TextTransparency       = 1
        lbl.Font                   = rf
        lbl.TextSize               = Px(15)
        lbl.TextWrapped            = true
        lbl.TextXAlignment         = Enum.TextXAlignment.Right
        lbl.ZIndex                 = 2147483647
        if permanent then lbl.AutoButtonColor = false end
        local st = ats(lbl)
        st.Transparency = 1
        ts:Create(lbl, TweenInfo.new(0.15), {TextTransparency = 0}):Play()
        ts:Create(st,  TweenInfo.new(0.15), {Transparency = 0}):Play()
        if permanent then
            if nPerm and nPerm.Parent then nPerm:Destroy() end
            nPerm = lbl
            lbl.MouseButton1Click:Connect(function() lbl:Destroy() end)
            return
        end
        local kids = {}
        for _, c in ipairs(nHolder:GetChildren()) do
            if c:IsA("TextLabel") then kids[#kids + 1] = c end
