            if not (lbl and lbl.Parent) then return end
            local tw = ts:Create(lbl, TweenInfo.new(0.5), {TextTransparency = 1})
            ts:Create(st, TweenInfo.new(0.5), {Transparency = 1}):Play()
            tw.Completed:Connect(function() if lbl and lbl.Parent then lbl:Destroy() end end)
            tw:Play()
        end)
    end
    ui.isVoting = function()
        local info = workspace:FindFirstChild("Info")
        local v = (info and info:FindFirstChild("Voting")) or workspace:FindFirstChild("Voting")
        return (v and v:IsA("BoolValue") and v.Value == true) or false
    end
    _G.yattaIsVoting = ui.isVoting
end
