    btn.BackgroundTransparency = 1
    btn.Text               = ""
    btn.AutoButtonColor    = false
    btn.ZIndex             = zBase + 3
    local hovered = false
    local held    = false
    local scaleTI = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local function ApplyScale()
        local target = held and 0.94 or (hovered and 1.04 or 1.0)
        ts:Create(uiScale, scaleTI, {Scale = target}):Play()
    end
    btn.MouseEnter:Connect(function() hovered = true; ApplyScale() end)
    btn.MouseLeave:Connect(function() hovered = false; held = false; ApplyScale() end)
    btn.MouseButton1Down:Connect(function() held = true; ApplyScale() end)
    btn.MouseButton1Up:Connect(function() held = false; ApplyScale() end)
    btn.MouseButton1Click:Connect(function()
        ps(sClick)
        if setclipboard then
            pcall(setclipboard, link)
        end
        ShowDonateToast("Copied link to clipboard.")
    end)
    return btn, frame, lbl
end
