function MkCyc(parent, options, labelAbove, lo)
    local idx = 1
    local wrapper = Instance.new("Frame", parent)
    wrapper.Name            = "CycleBtnWrapper_" .. tostring(lo or 0)
    wrapper.Size            = UDim2.new(1, 0, 0, labelAbove and Px(52) or Px(34))
    wrapper.BackgroundTransparency = 1
    wrapper.BorderSizePixel = 0
    wrapper.LayoutOrder     = lo or 0
    wrapper.ZIndex          = 204
    wrapper.AutomaticSize   = Enum.AutomaticSize.Y
    do local l = Instance.new("UIListLayout", wrapper); l.Padding = UDim.new(0, Px(2)); l.SortOrder = Enum.SortOrder.LayoutOrder end
    if labelAbove then
        local aboveLbl = Instance.new("TextLabel", wrapper)
        aboveLbl.Size               = UDim2.new(1, 0, 0, Px(15))
        aboveLbl.BackgroundTransparency = 1
        aboveLbl.Text               = labelAbove
        aboveLbl.TextColor3         = cTM
        aboveLbl.Font               = rf
        aboveLbl.TextSize           = Px(10)
        aboveLbl.TextXAlignment     = Enum.TextXAlignment.Left
        aboveLbl.LayoutOrder        = 0
        aboveLbl.ZIndex             = 204
        ats(aboveLbl)
    end
    local btn, cycleBtnFrame, cycleLbl = MkWIB(wrapper, options[idx], 1)
    cycleBtnFrame.LayoutOrder = 1
    local cbs = {}
    btn.MouseButton1Click:Connect(function()
        ps(sClick); idx = (idx % #options) + 1
        cycleLbl.Text = options[idx]
        for _, f in ipairs(cbs) do f(idx, options[idx]) end
    end)
    return btn, {
        GetIdx    = function() return idx end,
        OnChanged = function(f) cbs[#cbs + 1] = f end,
        SetIdx    = function(i) idx = i; cycleLbl.Text = options[i] end
    }
end
