local MkTrig
do
local itemTriggerCardUri = nil
local itemTriggerCardDownloadStarted = false
local itemTriggerCardImgs = {}
function EnsureItemTriggerCardDownload()
    if itemTriggerCardDownloadStarted then return end
    itemTriggerCardDownloadStarted = true
    task.spawn(function()
        local uri = DownloadGithubImage(
            "https://raw.githubusercontent.com/BluuGuy-Sure/ImageResources/main/Rectangle%2050.png",
            "Yatta's Crazy GUI/images/InstantDeathCard.png")
        if uri then
            itemTriggerCardUri = uri
            for _, img in ipairs(itemTriggerCardImgs) do
                if img and img.Parent then img.Image = uri end
            end
        end
    end)
end
function MkTrig(parent, cfg, lo)
    local togWOn  = Color3.fromRGB(210, 210, 215)
    local togWOff = Color3.fromRGB(58,  58,  63)
    local safeName  = cfg.name:gsub("[^%w]", ""):sub(1, 24)
    local outer = Instance.new("ImageLabel", parent)
    outer.Name             = "TriggerRow_" .. safeName
    do
        local rows = math.ceil(#(cfg.tflags or {1,2,3,4,5,6,7}) / 4)
        local need = Px(10) + Px(22) + rows * Px(26) + (rows - 1) * Px(4) + Px(2)
        outer.Size = UDim2.new(1, 0, 0, math.max(cfg.tflags and Px(62) or Px(84), need))
    end
    outer.BackgroundTransparency = 1
    outer.Image             = itemTriggerCardUri or ""
    outer.ScaleType          = Enum.ScaleType.Stretch
    outer.BorderSizePixel  = 0
    outer.LayoutOrder      = lo or 0
    outer.ZIndex           = 204
    Instance.new("UICorner", outer).CornerRadius = UDim.new(0, Px(7))
    itemTriggerCardImgs[#itemTriggerCardImgs + 1] = outer
    EnsureItemTriggerCardDownload()
    do
        local p = Instance.new("UIPadding", outer)
        p.PaddingLeft   = UDim.new(0, Px(8)); p.PaddingRight  = UDim.new(0, Px(8))
        p.PaddingTop    = UDim.new(0, Px(5)); p.PaddingBottom = UDim.new(0, Px(5))
    end
    local nl = Instance.new("TextLabel", outer)
    nl.Size               = UDim2.new(1, 0, 0, Px(18))
    nl.Position           = UDim2.new(0, 0, 0, 0)
    nl.BackgroundTransparency = 1
    nl.Text               = cfg.name
    nl.TextColor3         = cTL
    nl.Font               = rf
    nl.TextSize           = SSz
    nl.TextXAlignment     = Enum.TextXAlignment.Left
    nl.ZIndex             = 205
    ats(nl)
    local tflags = cfg.tflags or {
        { key = "always",     label = "Always",     exclusive = true  },
        { key = "heal",       label = "Heal",       exclusive = false },
        { key = "extracting", label = "Extracting", exclusive = false },
        { key = "seen",       label = "Seen",       exclusive = false },
        { key = "ignore",     label = "Ignore",     exclusive = true  },
        { key = "stamina",    label = "Stamina",    exclusive = false },
        { key = "treadmillExtracting", label = "Treadmill Extracting", exclusive = false },
    }
    local gridCols = 4
    local gap     = Px(4)
    local imgH   = Px(26)
    local togImgs = {}
    local tweenI  = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local gridRows = math.ceil(#tflags / gridCols)
    local togRow = Instance.new("Frame", outer)
    togRow.Size               = UDim2.new(1, 0, 0, gridRows * imgH + (gridRows - 1) * gap)
    togRow.Position           = UDim2.new(0, 0, 0, Px(22))
    togRow.BackgroundTransparency = 1
    togRow.ZIndex             = 205
    do
        local g = Instance.new("UIGridLayout", togRow)
        g.CellPadding  = UDim2.new(0, gap, 0, gap)
        g.CellSize     = UDim2.new(1/gridCols, -math.ceil((gridCols-1)*gap/gridCols), 0, imgH)
        g.FillDirection = Enum.FillDirection.Horizontal
        g.SortOrder     = Enum.SortOrder.LayoutOrder
        g.HorizontalAlignment = Enum.HorizontalAlignment.Left
        g.VerticalAlignment   = Enum.VerticalAlignment.Top
    end
    local function IsExclActive()
        for _, tf in ipairs(tflags) do
            if tf.exclusive and cfg[tf.key] then return true end
        end
        return false
    end
    local function RefreshAll()
        local excOn = IsExclActive()
        for _, tf in ipairs(tflags) do
            local img = togImgs[tf.key]
            if not img then continue end
            local on = cfg[tf.key]
            local blocked = excOn and not tf.exclusive and not tf.modifier and not on
            local col = on and togWOn or (blocked and Color3.fromRGB(35,35,38) or togWOff)
            ts:Create(img, tweenI, {ImageColor3 = col}):Play()
        end
    end
    for idx, tf in ipairs(tflags) do
        local col = Instance.new("Frame", togRow)
        col.Name                  = "MiniTog_" .. tf.key
        col.BackgroundTransparency = 1
        col.ZIndex                = 205
        col.LayoutOrder           = idx
        local img = Instance.new("ImageLabel", col)
        img.Size                  = UDim2.new(1, 0, 1, 0)
        img.Position              = UDim2.new(0, 0, 0, 0)
        img.BackgroundTransparency = 1
        img.Image                 = togImgId
        img.ScaleType             = Enum.ScaleType.Fit
        img.ImageColor3           = cfg[tf.key] and togWOn or togWOff
        img.ZIndex                = 206
        togImgs[tf.key] = img
        local lbl = Instance.new("TextLabel", col)
        lbl.Size                  = UDim2.new(1, 0, 1, 0)
        lbl.Position              = UDim2.new(0, 0, 0, 0)
        lbl.BackgroundTransparency = 1
        lbl.Text                  = tf.label
        lbl.TextColor3            = Color3.fromRGB(0, 0, 0)
        lbl.Font                  = rf
        lbl.TextSize              = Px(9)
        lbl.TextScaled            = false
        lbl.TextWrapped           = true
        lbl.TextXAlignment        = Enum.TextXAlignment.Center
        lbl.TextYAlignment        = Enum.TextYAlignment.Center
        lbl.ZIndex                = 207
        do
            local ts2 = Instance.new("UITextSizeConstraint", lbl)
            ts2.MaxTextSize = 9
            ts2.MinTextSize = 5
        end
        local btn = Instance.new("TextButton", col)
        btn.Size                  = UDim2.new(1, 0, 1, 0)
        btn.BackgroundTransparency = 1
        btn.Text                  = ""
        btn.AutoButtonColor       = false
        btn.ZIndex                = 208
        btn.MouseButton1Click:Connect(function()
            ps(sClick)
            if tf.exclusive then
                local nowOn = not cfg[tf.key]
                for _, other in ipairs(tflags) do cfg[other.key] = false end
                cfg[tf.key] = nowOn
            else
                if IsExclActive() and not tf.modifier then return end
                cfg[tf.key] = not cfg[tf.key]
            end
            RefreshAll()
        end)
    end
    RefreshAll()
    cfg._refresh = RefreshAll
    return outer, togImgs
end
end
function IsEggsonUnlocked()
    local info = workspace:FindFirstChild("Info"); if not info then return false end
    local pc   = info:FindFirstChild("PickedCharacters"); if not pc then return false end
    local sv   = pc:FindFirstChild(plr.Name)
    return sv and sv:IsA("StringValue") and sv.Value == "Eggson"
end
