if isR then
    ui.restrictedMainApply = function()
        local pm = Pages.Main
        if not (pm and pm.Parent) then return end
        for _, ch in ipairs(pm:GetChildren()) do
            if not (ch:IsA("UIListLayout") or ch:IsA("UIPadding")) then
                local keep = (ch.Name == "SecHeader_Solo_Run" or ch.Name == "ToggleList_SoloRun"
                    or ch.Name == "SecHeader_Public_Run" or ch.Name == "ToggleList_PublicRun")
                if ch.Visible ~= keep then ch.Visible = keep end
            end
        end
    end
    regSpawn(function()
        while Pages.Main and Pages.Main.Parent do
            if Pages.Main.Visible then pcall(ui.restrictedMainApply) end
            task.wait(0.5)
        end
    end)
end
