;(function()
    if isR then return end
    local pm = Pages.Main
    S.itemAura      = S.itemAura or false
    S.itemAuraRange = S.itemAuraRange or 10
    Gap(pm, 6, 70)
    SecH(pm, "Aura", 71)
    local auraList = Instance.new("Frame", pm)
    auraList.Name            = "ToggleList_Aura"
    auraList.Size            = UDim2.new(1, 0, 0, 0)
    auraList.AutomaticSize   = Enum.AutomaticSize.Y
    auraList.BackgroundTransparency = 1
    auraList.LayoutOrder     = 72
    auraList.ZIndex          = 204
    do local l = Instance.new("UIListLayout", auraList); l.Padding = UDim.new(0, Px(3)); l.SortOrder = Enum.SortOrder.LayoutOrder end
    local _, auraTog = MkTog(auraList, "Item Aura", S.itemAura, 1)
    auraTog.OnChanged(function(v) S.itemAura = v end)
    ui.itemAuraTog = auraTog
    local _, auraRangeApi = MkSldr(auraList, "Aura Range", 3, 40, S.itemAuraRange, 2,
        function(v) S.itemAuraRange = v end)
    ui.itemAuraRangeApi = auraRangeApi

    local function invFull()
        local igp = workspace:FindFirstChild(_G.YattaIGP)
        local pmod = igp and igp:FindFirstChild(plr.Name)
        local inv = pmod and (pmod:FindFirstChild("Inventory") or pmod:FindFirstChild("Items"))
        if not inv then return false end
        local filled = 0
        for i = 1, 4 do
            local slot = inv:FindFirstChild("Slot" .. i) or inv:FindFirstChild("Item" .. i)
            local val = slot and slot:IsA("StringValue") and slot.Value or ""
            if val ~= "" and val ~= "None" then filled += 1 end
        end
        return filled >= 4
    end
    local lastFire = setmetatable({}, { __mode = "k" })
    regSpawn(function()
        if isR then return end
        while true do
            task.wait(0.2)
            if not S.itemAura then continue end
            pcall(function()
                local char = plr.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                local cr = workspace:FindFirstChild("CurrentRoom")
                if not cr then return end
                local range = S.itemAuraRange or 10
                local full = invFull()
                local now = tick()
                for _, room in ipairs(cr:GetChildren()) do
                    local items = room:FindFirstChild("Items")
                    if not items then continue end
                    for _, item in ipairs(items:GetChildren()) do
                        local nm = item.Name
                        if nm == "GigiHoard" then continue end
                        if S.itemAuraBlacklist[nm] then continue end
                        if full and nm ~= "Tape" and nm ~= "ResearchCapsule" then continue end
                        if lastFire[item] and now - lastFire[item] < 0.35 then continue end
                        local handle = item:IsA("BasePart") and item or item:FindFirstChildWhichIsA("BasePart", true)
                        if not handle or not handle.Parent then continue end
                        if (handle.Position - hrp.Position).Magnitude > range then continue end
                        local prompt
                        for _, d in ipairs(item:GetDescendants()) do
                            if d:IsA("ProximityPrompt") and d.Enabled ~= false then prompt = d; break end
                        end
                        if not prompt then continue end
                        lastFire[item] = now
                        pcall(function()
                            if prompt.MaxActivationDistance < range then prompt.MaxActivationDistance = range end
                            prompt.RequiresLineOfSight = false
                            prompt.HoldDuration = 0
                        end)
                        if fireproximityprompt then
                            pcall(fireproximityprompt, prompt)
                        else
                            pcall(function() prompt:InputHoldBegin(); prompt:InputHoldEnd() end)
                        end
                    end
                end
            end)
        end
    end)
end)()
;(function()
    local pm = Pages.Main
    local autoList = pm:FindFirstChild("ToggleList_Automation")
    local miscList = pm:FindFirstChild("ToggleList_Misc")
    if not (autoList and miscList) then return end
    local function mkList(title, hdrOrder, listOrder, name)
        local hdr = SecH(pm, title, hdrOrder)
        local l = Instance.new("Frame", pm)
        l.Name = "ToggleList_" .. name
        l.Size = UDim2.new(1, 0, 0, 0); l.AutomaticSize = Enum.AutomaticSize.Y
        l.BackgroundTransparency = 1; l.LayoutOrder = listOrder; l.ZIndex = 204
        local lay = Instance.new("UIListLayout", l)
        lay.Padding = UDim.new(0, Px(3)); lay.SortOrder = Enum.SortOrder.LayoutOrder
        if isR then l.Visible = false; if hdr then hdr.Visible = false end end
        return l
    end
    local farmList = mkList("AutoFarm", -2, -1, "AutoFarm")
    local expList  = mkList("Experimental", 3, 4, "Experimental")
    if not isR and ui.safeHideTog then
        local _, mirror = MkTog(miscList, "Safe Hide", S.shWanted, 1)
        local orig = ui.safeHideTog
        mirror.OnChanged(function() local c = mirror.GetState(); if orig.GetState() ~= c then orig.SetState(c) end end)
        orig.OnChanged(function() local c = orig.GetState(); if mirror.GetState() ~= c then mirror.SetState(c) end end)
        if mirror.GetState() ~= orig.GetState() then mirror.SetState(orig.GetState()) end
    end
    local function labelOf(r)
        for _, c in ipairs(r:GetChildren()) do if c:IsA("TextLabel") then return c.Text end end
        return ""
    end
    local function groupsOf(list)
        local kids = {}
        for _, c in ipairs(list:GetChildren()) do if c:IsA("GuiObject") then kids[#kids + 1] = c end end
        table.sort(kids, function(a, b)
            if a.LayoutOrder ~= b.LayoutOrder then return a.LayoutOrder < b.LayoutOrder end
            return a.Name < b.Name
        end)
        local gs, byText = {}, {}
        for _, c in ipairs(kids) do
            if c.Name:sub(1, 10) == "ToggleRow_" then
                local g = { row = c, items = { c }, text = labelOf(c) }
                gs[#gs + 1] = g
                byText[g.text] = g
            end
        end
        for _, c in ipairs(kids) do
            if c.Name:sub(1, 10) ~= "ToggleRow_" then
                local g = byText[c:GetAttribute("YOwner") or ""]
                if g then g.items[#g.items + 1] = c end
            end
        end
        return gs
    end
    local expText   = { ["Pathfind Mode"] = true, ["Safer Pathfind Hide"] = true, ["Safe Hide"] = "exp" }
    local miscText  = { ["Exclude full researched twisteds"] = true, ["Extract Treadmills First"] = true,
                        ["Auto Dodge (Tendrils, Blot Hands)"] = true }
    local autoGroups, expGroups, miscGroups, farmGroups, lastGroup = {}, {}, {}, {}, nil
    for _, g in ipairs(groupsOf(autoList)) do
        if g.text == "Start Farm" then farmGroups[#farmGroups + 1] = g
        elseif expText[g.text] then expGroups[#expGroups + 1] = g
        elseif miscText[g.text] then miscGroups[#miscGroups + 1] = g
        elseif g.text == "Auto Hide (Connie)" then
            local api = ui.connieHideTog
            if api then api.SetState = function() end end
            S.autoConnieHide = false
            for _, it in ipairs(g.items) do it.Visible = false; it.Parent = nil end
        elseif g.text == "Auto Stop Autofarm" then lastGroup = g
        else autoGroups[#autoGroups + 1] = g end
    end
    for _, g in ipairs(groupsOf(miscList)) do miscGroups[#miscGroups + 1] = g end
    local function place(list, groups, last)
        table.sort(groups, function(a, b)
            if #a.text ~= #b.text then return #a.text > #b.text end
            return a.text < b.text
        end)
        for _, rule in ipairs({ { "Auto Skillcheck", "Instant Skillcheck" }, { "Auto Barnaby", "Auto Barnaby (Glide)" },
                                { "Safer Pathfind Hide", "Pathfind Mode" } }) do
            local fi, ai
            for i, g in ipairs(groups) do
                if g.text == rule[1] then fi = i elseif g.text == rule[2] then ai = i end
            end
            if fi and ai then
                local fg = table.remove(groups, fi)
                if fi < ai then ai = ai - 1 end
                table.insert(groups, ai + 1, fg)
            end
        end
        if last then groups[#groups + 1] = last end
        for i, g in ipairs(groups) do
            for k, it in ipairs(g.items) do
                it.Parent = list
                it.LayoutOrder = i * 10 + (k - 1)
            end
        end
    end
    place(farmList, farmGroups)
    place(autoList, autoGroups, lastGroup)
    place(expList, expGroups)
    place(miscList, miscGroups)
end)()
