            confirmLbl.Visible  = true
            pendingToken        = pendingToken + 1
            local myToken       = pendingToken
            task.delay(3, function()
                if pendingToken == myToken then
                    pendingConfirm      = false
                    confirmLbl.Visible  = false
                end
            end)
        end)
    end
end)()
