        local STgH = Px(20)
        local subRow = Instance.new("Frame", parent)
        subRow.Name               = "SubTogRow_" .. labelText:gsub("[^%w]", ""):sub(1,20)
        subRow.Size               = UDim2.new(1, 0, 0, Px(28))
