        end
        Instance.new("UICorner", subRow).CornerRadius = UDim.new(0, Px(5))
        local subLbl = Instance.new("TextLabel", subRow)
        subLbl.Size               = UDim2.new(1, -(STgW + Px(10)), 1, 0)
        subLbl.BackgroundTransparency = 1
        subLbl.Text               = labelText
        subLbl.TextColor3         = cTM
        subLbl.Font               = rf
        subLbl.TextSize           = Px(12)
