        togWrapper.BackgroundTransparency = 1
        togWrapper.BorderSizePixel    = 0
        togWrapper.ZIndex             = 205
        togWrapper.ClipsDescendants   = false
        local uiScale2 = Instance.new("UIScale", togWrapper)
        uiScale2.Scale = 1
        local subTogImg = Instance.new("ImageLabel", togWrapper)
        subTogImg.Name                   = "SubTogImg"
        subTogImg.Size                   = UDim2.new(1, 0, 1, 0)
        subTogImg.AnchorPoint            = Vector2.new(0.5, 0.5)
