        subTogImg.BackgroundTransparency = 1
        subTogImg.Image                  = togImgId
        subTogImg.ScaleType              = Enum.ScaleType.Fit
        subTogImg.ImageColor3            = subState and togColorOn or togColorOff
        subTogImg.ZIndex                 = 206
        local subStateLbl = Instance.new("TextLabel", togWrapper)
        subStateLbl.Size                   = UDim2.new(1, 0, 1, 0)
        subStateLbl.AnchorPoint            = Vector2.new(0.5, 0.5)
        subStateLbl.Position               = UDim2.new(0.5, 0, 0.5, 0)
        subStateLbl.BackgroundTransparency = 1
        subStateLbl.Text                   = subState and "On" or "Off"
        subStateLbl.TextColor3             = Color3.fromRGB(255, 255, 255)
        subStateLbl.Font                   = rf
        subStateLbl.TextSize               = Px(11)
        subStateLbl.TextXAlignment         = Enum.TextXAlignment.Center
        subStateLbl.TextYAlignment         = Enum.TextYAlignment.Center
        subStateLbl.ZIndex                 = 207
        ats(subStateLbl, Color3.fromRGB(0, 0, 0), 1)
        local subTweenInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local scaleTI2     = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local hov2, hld2 = false, false
        local function ApplyScale2()
            local t = hld2 and 0.90 or (hov2 and 1.10 or 1.0)
            ts:Create(uiScale2, scaleTI2, {Scale = t}):Play()
        end
        local function SubAnim(ns)
            subState = ns
            ts:Create(subTogImg, subTweenInfo, {ImageColor3 = ns and togColorOn or togColorOff}):Play()
            subStateLbl.Text = ns and "On" or "Off"
            for _, cb2 in ipairs(subCbs) do cb2(ns) end
        end
        local subBtn = Instance.new("TextButton", togWrapper)
