        subBtn.ZIndex             = 209
        subBtn.MouseEnter:Connect(function()    hov2 = true;  ApplyScale2() end)
        subBtn.MouseLeave:Connect(function()    hov2 = false; hld2 = false; ApplyScale2() end)
        subBtn.MouseButton1Down:Connect(function() hld2 = true;  ApplyScale2() end)
        subBtn.MouseButton1Up:Connect(function()   hld2 = false; ApplyScale2() end)
        subBtn.MouseButton1Click:Connect(function() ps(sClick); SubAnim(not subState) end)
        return subRow, {
            GetState  = function() return subState end,
            SetState  = SubAnim,
            OnChanged = function(f) subCbs[#subCbs + 1] = f end,
