        local tracerTog, infoTog
        local noTracerInfo = (capDef.key == "tendrils")
        if not noTracerInfo then
            local _, iTog = MakeSubToggle(subContainer, "  Info",   capDef.key == "gigiMachine" or capDef.key == "totDoors" or capDef.key == "collectibles" or capDef.key == "elevator" or capDef.key == "fakeElevator", 2)
            infoTog = iTog
        end
        hlTog.OnChanged(function(v)
            hle[capDef.key] = v
            if esph[capDef.key] then
                for _, hl in pairs(esph[capDef.key]) do
                    pcall(function() hl.Enabled = v end)
                end
            end
        end)
        if tracerTog then tracerTog.OnChanged(function(v) end) end
        if infoTog   then infoTog.OnChanged(function(v) end)   end
        local hideDoneTog
        if capDef.key == "generators" or capDef.key == "totDoors" then
            S.espHideDone = S.espHideDone or {}
            S.espHideDone[capDef.key] = false
            local _, hdTog = MakeSubToggle(subContainer, "  Hide When Completed", false, 3)
            hdTog.OnChanged(function(v) S.espHideDone[capDef.key] = v end)
            hideDoneTog = hdTog
        end
        if capDef.key == "gigiMachine" then
            S.gigiEspInfo = true
            if infoTog then infoTog.OnChanged(function(v) S.gigiEspInfo = v end) end
        end
        if capDef.key == "totDoors" or capDef.key == "collectibles" or capDef.key == "elevator" or capDef.key == "fakeElevator" then
            S.espInfo = S.espInfo or {}
            S.espInfo[capDef.key] = true
            if infoTog then infoTog.OnChanged(function(v) S.espInfo[capDef.key] = v end) end
        end
        local function espNow()
            if S.espRefresh and S.espRefresh[capDef.key] then pcall(S.espRefresh[capDef.key]) end
        end
        hlTog.OnChanged(espNow)
        if infoTog then infoTog.OnChanged(espNow) end
        if hideDoneTog then hideDoneTog.OnChanged(espNow) end
        ui.testToggles[capDef.key] = {
            highlight = hlTog,
            tracer    = tracerTog,
            info      = infoTog,
            hideDone  = hideDoneTog,
        }
        ui.espSubContainers[capDef.key] = subContainer
        espTog.OnChanged(function(v)
            if isR and not capDef.showRestricted then return end
            subContainer.Visible = v
        end)
    end
end)()
