            if hasSprout then
                tapeCfg.sproutManuallyEnabled = false
                if not tapeCfg.blacklisted then
                    tapeCfg.blacklisted = true
                    tapeCfg.autoBlacklisted = true
                end
            else
                if tapeCfg.autoBlacklisted then
                    tapeCfg.blacklisted = false
                end
                tapeCfg.autoBlacklisted = false
