function ApplyFont(obj, fontEntry)
    if not obj or not fontEntry then return end
    if type(fontEntry) == "table" and fontEntry.isFontFace then
        pcall(function() obj.FontFace = fontEntry.face end)
    else
        pcall(function() obj.Font = fontEntry end)
    end
end
local sbShrink = 0.72
function ApplyFontToAll(fontEntry)
    local isSB = type(fontEntry) == "table" and fontEntry.isFontFace
    for _, pg in pairs(Pages) do
        for _, v in ipairs(pg:GetDescendants()) do
            if v:IsA("TextLabel") or v:IsA("TextButton") or v:IsA("TextBox") then
                ApplyFont(v, fontEntry)
                if isSB and not v:GetAttribute("_sbOrigSz") then
                    v:SetAttribute("_sbOrigSz", v.TextSize)
                end
                if isSB then
                    local orig = v:GetAttribute("_sbOrigSz") or v.TextSize
                    v.TextSize = math.max(6, math.floor(orig * sbShrink + 0.5))
                elseif v:GetAttribute("_sbOrigSz") then
                    v.TextSize = v:GetAttribute("_sbOrigSz")
                end
            end
        end
    end
    for _, ref in ipairs({TitleLabel, SubLabel, MinBtn, CreditLabel, DragLockBtn, FloatBtn}) do
        if ref then
            ApplyFont(ref, fontEntry)
            if isSB then
                if not ref:GetAttribute("_sbOrigSz") then
                    ref:SetAttribute("_sbOrigSz", ref.TextSize)
                end
                local orig = ref:GetAttribute("_sbOrigSz") or ref.TextSize
                ref.TextSize = math.max(6, math.floor(orig * sbShrink + 0.5))
            elseif ref:GetAttribute("_sbOrigSz") then
                ref.TextSize = ref:GetAttribute("_sbOrigSz")
            end
        end
    end
end
