    local fullId       = P.fid
    local restrictedId = P.rid
    local configAllowed = (game.PlaceId == fullId or game.PlaceId == restrictedId)
    local cfgPrefix    = "YattaCrazyGUI_"
    local cfgSuffix    = ".json"
    local cfgFolder    = _G.yattaCFGSAVES or "Yatta's Crazy GUI/Saved Configs"
    local HttpSvc      = game:GetService("HttpService")

    local function CfgFilename(name)
        local safe = (name or "default"):gsub("[^%w_%-]", "_"):sub(1, 32)
        if safe == "" then safe = "default" end
        return cfgFolder .. "/" .. cfgPrefix .. safe .. cfgSuffix
    end

    local function ConfigDisplayName(path)
        local filename = tostring(path or ""):match("[^/\\]+$") or tostring(path or "")
        filename = filename:gsub("%.json$", "")
        if filename:sub(1, #cfgPrefix) == cfgPrefix then
            filename = filename:sub(#cfgPrefix + 1)
        end
        return filename ~= "" and filename or "Unnamed"
    end

    local function ReadConfigEntries()
        local entries = {}
        if not listfiles then
            return entries
        end

        local ok, files = pcall(function()
            return listfiles(cfgFolder)
        end)
        if not ok or type(files) ~= "table" then
            return entries
        end

        for _, path in ipairs(files) do
            path = tostring(path)
            local lower = path:lower()
            if lower:sub(-#cfgSuffix) == cfgSuffix
                and not lower:match("[\\/]yattacrazygui_index%.json$") then
                entries[#entries + 1] = {
                    name = ConfigDisplayName(path),
                    source = path,
                    remote = false,
                }
            end
        end

        table.sort(entries, function(a, b)
            return a.name:lower() < b.name:lower()
        end)
        return entries
    end

    local function ReadIndex()
        local names = {}
        for _, entry in ipairs(ReadConfigEntries()) do
            names[#names + 1] = entry.name
        end
        return names
    end

    local function AddToIndex(_name)
    end

    local function RemoveFromIndex(_name)
    end

    local function FindConfigEntry(name)
        for _, entry in ipairs(ReadConfigEntries()) do
            if entry.name == name then return entry end
        end
        return nil
    end

    local function ReadConfigData(name, selectedEntry)
        local entry = selectedEntry
        if not entry or entry.name ~= name then
            entry = FindConfigEntry(name)
        end

        local source = entry and entry.source
        if source and source ~= "" then
            if source:match("^https?://") then
                local ok, body = pcall(function()
                    return game:HttpGet(source, true)
                end)
                if ok and type(body) == "string" and body ~= "" then
                    local dok, data = pcall(function()
                        return HttpSvc:JSONDecode(body)
                    end)
                    if dok and type(data) == "table" then
                        return true, data
                    end
                end
                return false, nil
            end

            local ok, body = pcall(function() return readfile(source) end)
            if ok and type(body) == "string" and body ~= "" then
                local dok, data = pcall(function()
                    return HttpSvc:JSONDecode(body)
                end)
                if dok and type(data) == "table" then
                    return true, data
                end
            end
            return false, nil
        end

        local ok, body = pcall(function() return readfile(CfgFilename(name)) end)
        if not ok then return false, nil end
        local dok, data = pcall(function() return HttpSvc:JSONDecode(body) end)
        return dok and type(data) == "table", data
    end

