            snap.itemTriggers[cfg.name] = {
                always     = cfg.always     or false,
                heal       = cfg.heal       or false,
                extracting = cfg.extracting or false,
                seen       = cfg.seen       or false,
                ignore     = cfg.ignore     or false,
                stamina    = cfg.stamina    or false,
                treadmillExtracting = cfg.treadmillExtracting or false,
            }
        end
        snap.autoTriggers = {}
        for key, tc in pairs(S.autoTrig) do
            snap.autoTriggers[key] = { always = tc.always or false, panic = tc.panic or false, floorStart = tc.floorStart or false }
        end
        do
            local at = S.abilTrig
            snap.abilityTrigger = {
                always = at.always or false, floorStart = at.floorStart or false, nearPlayers = at.nearPlayers or false,
                seen = at.seen or false, hit = at.hit or false, stamina = at.stamina or false,
                extracting = at.extracting or false, treadmillExtracting = at.treadmillExtracting or false, oncePerFloor = at.oncePerFloor or false,
            }
            local gt = S.galaTrig
            snap.galaAbilityTrigger = {
                always = gt.always or false, floorStart = gt.floorStart or false, nearPlayers = gt.nearPlayers or false,
                seen = gt.seen or false, hit = gt.hit or false, stamina = gt.stamina or false,
                extracting = gt.extracting or false, treadmillExtracting = gt.treadmillExtracting or false, oncePerFloor = gt.oncePerFloor or false,
            }
        end
        return snap
    end
    local function ApplyConfig(data)
        local applyCount = 0
        local function applyYield()
            applyCount = applyCount + 1
            if applyCount % 6 == 0 then task.wait() end
        end
        local function ApplyTog(key, togRef)
            local camel = key:lower():gsub("_(%a)", function(c) return c:upper() end)
            local v = data[camel]
            if v == nil then v = data[key] end
            if v == nil then return end
            S[camel] = v
            applyYield()
            if togRef and togRef.SetState then pcall(function() togRef.SetState(v) end) end
        end
        ApplyTog("AUTO_ENABLED",              ui.autoFarmTog)
        if data.pathfindMode ~= nil and ui.pathfindTog and ui.pathfindTog.SetState then
            applyYield()
            pcall(function() ui.pathfindTog.SetState(data.pathfindMode) end)
        end
        if data.autoTrickTreat ~= nil then
            S.autoTrickTreat = data.autoTrickTreat
            if ui.trickTog and ui.trickTog.SetState then
                applyYield()
                pcall(function() ui.trickTog.SetState(data.autoTrickTreat) end)
            end
        end
        if data.autoJoinMatch ~= nil and isR and not data.autoRunSolo and not data.autoJoinRun then
            S.autoJoinMatch = data.autoJoinMatch
            if ui.autoJoinMatchTog and ui.autoJoinMatchTog.SetState then
                applyYield()
                pcall(function() ui.autoJoinMatchTog.SetState(data.autoJoinMatch) end)
            end
        end
        if data.autoJoinRun ~= nil and isR and not data.autoRunSolo then
            S.autoJoinRun = data.autoJoinRun
            if ui.autoJoinRunTog and ui.autoJoinRunTog.SetState then
                applyYield()
                pcall(function() ui.autoJoinRunTog.SetState(data.autoJoinRun) end)
            end
        end
        if data.autoRunAllowFriends ~= nil and isR then
            S.autoRunAllowFriends = data.autoRunAllowFriends == true
            if ui.allowFriendsTog and ui.allowFriendsTog.SetState then
                pcall(function() ui.allowFriendsTog.SetState(S.autoRunAllowFriends) end)
            end
        end
        if data.autoRunSolo ~= nil and isR then
            S.autoRunSolo = data.autoRunSolo
            if ui.autoRunSoloTog and ui.autoRunSoloTog.SetState then
                applyYield()
                pcall(function() ui.autoRunSoloTog.SetState(data.autoRunSolo) end)
            end
        end
        if data.extraSpeedEnabled ~= nil then
            S.extraSpeedEnabled = data.extraSpeedEnabled
            if ui.extraSpeedTog and ui.extraSpeedTog.SetState then
                applyYield()
                pcall(function() ui.extraSpeedTog.SetState(data.extraSpeedEnabled) end)
            end
        end
        if tonumber(data.extraSpeedValue) then
            S.extraSpeedValue = tonumber(data.extraSpeedValue)
            if ui.extraSpeedBox then ui.extraSpeedBox.Text = tostring(S.extraSpeedValue) end
        end
        for _, kv in ipairs({ { "autoHeal", ui.autoHealTog }, { "infStamina", ui.infStaminaTog },
                              { "showRealStamina", ui.showRealStaminaTog },
                              { "fullbright", ui.fullbrightTog }, { "noFog", ui.noFogTog } }) do
            local key, tog = kv[1], kv[2]
            if isR and (key == "infStamina" or key == "showRealStamina") then
                S[key] = false
            elseif data[key] ~= nil then
                S[key] = data[key]
                if tog and tog.SetState then
                    applyYield()
                    pcall(function() tog.SetState(data[key]) end)
                end
            end
        end
        S.stamDebug = false
        if ui.stamDebugTog and ui.stamDebugTog.GetState and ui.stamDebugTog.GetState() then pcall(function() ui.stamDebugTog.SetState(false) end) end
        if data.excludeFullResearch ~= nil then
            S.excludeFullResearch = data.excludeFullResearch
            if ui.exclFullResearchTog and ui.exclFullResearchTog.SetState then
                applyYield()
                pcall(function() ui.exclFullResearchTog.SetState(data.excludeFullResearch) end)
            end
        end
        if data.saferPathfindHide ~= nil then
            S.saferPathfindHide = data.saferPathfindHide
            if ui.saferPathfindHideTog and ui.saferPathfindHideTog.SetState then
                applyYield()
                pcall(function() ui.saferPathfindHideTog.SetState(data.saferPathfindHide) end)
            end
        end
        ApplyTog("ANTI_AFK",                  ui.antiAfkTog)
        ApplyTog("ANTI_MEMORY_LEAK",          ui.antiMemLeakTog)
        ApplyTog("FIRE_STOP",                 ui.fireStopTog)
        ApplyTog("PICKUP_ENABLED",            ui.pickupTog)
        ApplyTog("SAFE_TP",                   ui.safeTpTog)
        if data.safeHide ~= nil then
            S.safeHide = data.safeHide
            if ui.safeHideTog and ui.safeHideTog.SetState then
                applyYield()
                pcall(function() ui.safeHideTog.SetState(data.safeHide) end)
            end
        end
        ApplyTog("AUTO_USE_ITEMS",            ui.autoUseTog)
        ApplyTog("AUTO_VOTE",                 ui.autoVoteTog)
        ApplyTog("AUTO_BUY",                  ui.autoBuyTog)
        ApplyTog("AUTO_WASTE_HEALS",          ui.autoWasteHealsTog)
        ApplyTog("AUTO_SQUIRM_ESCAPE",        ui.squirmTog)
        ApplyTog("ANTI_VEE_POPUP",            ui.antiVeeTog)
        ApplyTog("INSTANT_SKILLCHECK",        ui.skillcheckTog)
        ApplyTog("AUTO_SKILLCHECK",           ui.autoSkillTog)
        ApplyTog("AUTO_SPRINT",               ui.autoSprintTog)
        ApplyTog("AUTO_PANIC_TP",             ui.autoPanicTPTog)
        ApplyTog("WALKSPEED_ENABLED",         ui.walkSpeedTog)
        ApplyTog("TELEPORT_WALK_ENABLED",     ui.teleportWalkTog)
        ApplyTog("TELEPORT_WALK_ONLY_DECODE", ui.teleportWalkOnlyDecodeTog)
        ApplyTog("REJOIN_ON_DEATH",           ui.rejoinOnDeathTog)
        ApplyTog("EGGSON_MODE",               ui.eggsonTog)
        ApplyTog("EXTRACT_TREADMILLS_FIRST",  ui.extractTreadmillsTog)
        ApplyTog("AUTO_DODGE_TENDRILS",       ui.autoDodgeTendrilsTog)
        ApplyTog("AUTO_CONNIE_HIDE",          ui.connieHideTog)
        ApplyTog("AUTO_STOP_FLOOR_ENABLED",   ui.autoStopFloorTog)
        ApplyTog("AUTO_GIGI_CLAW",            ui.gigiClawTog)
        ApplyTog("AUTO_COLLECT",              ui.collectTog)
        ApplyTog("SHELLY_MODE",               ui.shellyTog)
        ApplyTog("AUTO_USE_ABILITY_SQUIRM",   ui.squirmAbilTog)
        ApplyTog("AUTO_USE_ABILITY_SOULVESTER", ui.soulAbilTog)
        ApplyTog("AUTO_USE_ABILITY_CONNIE",   ui.connieAbilTog)
        ApplyTog("AUTO_USE_ABILITY",          ui.autoAbilTog)
        ApplyTog("AUTO_USE_ABILITY_GALA",     ui.galaAbilTog)
        ApplyTog("AUTO_USE_ABILITY_TEAGAN",   ui.teaganAbilTog)
        if not isR then ApplyTog("AUTO_BARNABY_GLIDE",        ui.autoBarnabyGlideTog) end
        ApplyTog("ITEM_AURA",                 ui.itemAuraTog)
        if tonumber(data.autoStopFloor) then
            S.autoStopFloor = tonumber(data.autoStopFloor)
            if ui.autoStopFloorBox then ui.autoStopFloorBox.Text = tostring(S.autoStopFloor) end
        end
        if tonumber(data.itemAuraRange) then
            S.itemAuraRange = tonumber(data.itemAuraRange)
            if ui.itemAuraRangeApi then pcall(function() ui.itemAuraRangeApi.SetValue(S.itemAuraRange) end) end
        end
        for _, kv in ipairs({ { "noclip", ui.noclipTog }, { "antiVoid", ui.antiVoidTog } }) do
            local key, tog = kv[1], kv[2]
            local v = data[key]
            if v ~= nil and not (isR and key == "noclip") and not (key == "noclip" and v == false and S.NoclipLocked()) then
                S[key] = v
                applyYield()
                if tog and tog.SetState then pcall(function() tog.SetState(v) end) end
            end
        end
        if data.flipEnabled ~= nil then
            S.flipEnabled = data.flipEnabled
            if _G.FlipSetEnabled then pcall(_G.FlipSetEnabled, data.flipEnabled) end
            local p2ft = _G.YattaP2 and _G.YattaP2.flipTog
            applyYield()
            if p2ft then pcall(function() p2ft.SetState(data.flipEnabled) end) end
        end
        if data.walkspeedValue then
            S.walkspeedValue = data.walkspeedValue
            if ui.walkSpeedSliderApi then pcall(function() ui.walkSpeedSliderApi.SetValue(data.walkspeedValue) end) end
        end
        if data.uiSizeLevel then
            S.uiSizeLevel = math.clamp(math.floor(data.uiSizeLevel + 0.5), 1, 15)
            if ui.uiSizeSliderApi then pcall(function() ui.uiSizeSliderApi.SetValue(S.uiSizeLevel) end) end
            pcall(function() applyScale(getVisualScale()) end)
        end
        if data.teleportWalkDist then
            C.teleportWalkDist = data.teleportWalkDist
            if ui.teleportWalkDistApi then pcall(function() ui.teleportWalkDistApi.SetValue(data.teleportWalkDist) end) end
        end
        if data.maxHeals then
            C.maxHeals = math.clamp(math.floor(data.maxHeals + 0.5), 1, 4)
            if ui.maxHealsSliderApi then pcall(function() ui.maxHealsSliderApi.SetValue(C.maxHeals) end) end
        end
        if data.flySpeed then
            fs.speed = data.flySpeed
            if ui.flySpeedSliderApi then pcall(function() ui.flySpeedSliderApi.SetValue(data.flySpeed) end) end
        end
        if data.teleportMode and ui.moveModeApi and ui.moveModes then
            C.teleportMode = data.teleportMode
            local mi = table.find(ui.moveModes, data.teleportMode) or 1
            pcall(function()
                ui.moveModeApi.SetIdx(mi)
            end)
        end
        if data.fontIdx then
            idx.font = data.fontIdx
            fa.SetIdx(data.fontIdx)
            local fontEntry = fOpts[data.fontIdx]
            if fontEntry then
                if type(fontEntry) ~= "table" then Th.Font = fontEntry end
                task.defer(function() ApplyFontToAll(fontEntry) end)
            end
        end
        if type(data.espEnabled) == "table" and ui.espToggles then
            for cat, v in pairs(data.espEnabled) do
                espe[cat] = v
                local tog = ui.espToggles[cat]
                applyYield()
                if tog and tog.SetState then pcall(function() tog.SetState(v) end) end
            end
        end
        if type(data.highlightEnabled) == "table" then
            for cat, v in pairs(data.highlightEnabled) do
                hle[cat] = v
                if P.esph and P.esph[cat] then
                    for _, hl in pairs(P.esph[cat]) do
                        pcall(function() hl.Enabled = v end)
                    end
                end
                if ui.testToggles and ui.testToggles[cat] and ui.testToggles[cat].highlight then
                    applyYield()
                    pcall(function() ui.testToggles[cat].highlight.SetState(v) end)
                end
            end
        end
        if type(data.tracerEnabled) == "table" and ui.testToggles then
            for cat, v in pairs(data.tracerEnabled) do
                if ui.testToggles[cat] and ui.testToggles[cat].tracer then
                    applyYield()
                    pcall(function() ui.testToggles[cat].tracer.SetState(v) end)
                end
            end
        end
        if type(data.infoEnabled) == "table" and ui.testToggles then
            for cat, v in pairs(data.infoEnabled) do
                if ui.testToggles[cat] and ui.testToggles[cat].info then
                    applyYield()
                    pcall(function() ui.testToggles[cat].info.SetState(v) end)
                end
            end
        end
        if type(data.espHideDone) == "table" and ui.testToggles then
            for cat, v in pairs(data.espHideDone) do
                if ui.testToggles[cat] and ui.testToggles[cat].hideDone then
                    applyYield()
                    pcall(function() ui.testToggles[cat].hideDone.SetState(v) end)
                end
            end
        end
        if type(data.monsterRadii) == "table" then
            for name, radius in pairs(data.monsterRadii) do
                if name == "RollingPumpkin" and type(radius) == "number" then S.pumpkinRadius = radius end
                if mons[name] then
                    mons[name].detRadius  = radius
                    P.mr[name]    = radius
                end
                if ui.monsterRadiusSliders and ui.monsterRadiusSliders[name] then
                    pcall(function() ui.monsterRadiusSliders[name].SetValue(radius) end)
                end
            end
        end
        if type(data.cardTiers) == "table" then
            local cardTierValues  = {1, 2, 3, 4, 99}
            local cardTierOptions = {"Tier 1", "Tier 2", "Tier 3", "Tier 4", "Ignore"}
            local cardTierColors  = {cTW, cTW, cTW, cTW, cRd}
            for _, cardCfg in ipairs(cc) do
                local saved = data.cardTiers[cardCfg.name]
                if saved ~= nil then
                    cardCfg.tier = saved
                    if ui.cardTierRowRefs then
                        for _, ref in ipairs(ui.cardTierRowRefs) do
                            if ref.cfg == cardCfg then
                                local tierIdx = 2
                                for i, v in ipairs(cardTierValues) do if v == saved then tierIdx = i; break end end
                                pcall(function()
                                    local btn = ref.btn or (ref.row and ref.row:FindFirstChildWhichIsA("TextButton", true))
                                    if btn then
                                        btn.Text = cardTierOptions[tierIdx]
                                        local isIgnored = cardTierOptions[tierIdx] == "Ignore"
                                        btn.TextColor3 = isIgnored
                                            and Color3.fromRGB(255, 255, 255)
                                            or  Color3.fromRGB(120, 120, 120)
                                        if btn.Parent then
                                            local pc = isIgnored
                                                and Color3.fromRGB(200, 55, 55)
                                                or  Color3.fromRGB(255, 255, 255)
                                            for _, im in ipairs(btn.Parent:GetChildren()) do
                                                if im:IsA("ImageLabel") then im.ImageColor3 = pc end
                                            end
                                        end
                                    end
                                end)
                                break
                            end
                        end
                    end
                end
            end
        end
        if type(data.buyBlacklist) == "table" then
            for _, cfg in ipairs(bbl) do
                local saved = data.buyBlacklist[cfg.name]
                if saved ~= nil then
                    cfg.blacklisted = saved
                    if ui.buyBlacklistRefs then
                        for _, ref in ipairs(ui.buyBlacklistRefs) do
                            if ref.cfg == cfg then
                                applyYield()
                                pcall(function() ref.api.SetState(saved) end); break
                            end
                        end
                    end
                end
            end
        end
        if type(data.aeBlacklist) == "table" and ui.aeBlacklistRefs then
            for _, ref in ipairs(ui.aeBlacklistRefs) do
                local saved = data.aeBlacklist[ref.name]
                if saved ~= nil then
                    S.aeBlacklist[ref.name] = saved == true
                    applyYield()
                    pcall(function() ref.api.SetState(saved == true) end)
                end
            end
        end
        if type(data.pickupBlacklist) == "table" then
            for _, cfg in ipairs(pcfg) do
                local saved = data.pickupBlacklist[cfg.name]
                if saved ~= nil then
                    cfg.blacklisted = saved
                    cfg.autoBlacklisted = false
                    if ui.pickupCheckRefs then
                        for _, ref in ipairs(ui.pickupCheckRefs) do
                            if ref.cfg == cfg then
                                applyYield()
                                pcall(function() ref.api.SetState(saved) end); break
                            end
                        end
                    end
                end
            end
        end
        if type(data.gigiWhitelist) == "table" then
            for _, cfg in ipairs(gigiWL) do
                local saved = data.gigiWhitelist[cfg.name]
                if saved ~= nil then
                    cfg.whitelisted = saved
                    if ui.gigiWLRefs then
                        for _, ref in ipairs(ui.gigiWLRefs) do
                            if ref.cfg == cfg then
                                applyYield()
                                pcall(function() ref.api.SetState(saved) end); break
                            end
                        end
                    end
                end
            end
        end
        if type(data.autoTriggers) == "table" then
            for key, tc in pairs(S.autoTrig) do
                local sv = data.autoTriggers[key]
                if type(sv) == "table" then
                    tc.always = sv.always or false; tc.panic = sv.panic or false; tc.floorStart = sv.floorStart or false
                    if tc._refresh then pcall(tc._refresh) end
                end
            end
        end
        if type(data.abilityTrigger) == "table" then
            local at, sv = S.abilTrig, data.abilityTrigger
            for _, k in ipairs({ "always", "floorStart", "nearPlayers", "seen", "hit", "stamina", "extracting", "treadmillExtracting", "oncePerFloor" }) do
                at[k] = sv[k] == true
            end
            if at._refresh then pcall(at._refresh) end
        end
        if type(data.galaAbilityTrigger) == "table" then
            local gt, sv = S.galaTrig, data.galaAbilityTrigger
            for _, k in ipairs({ "always", "floorStart", "nearPlayers", "seen", "hit", "stamina", "extracting", "treadmillExtracting", "oncePerFloor" }) do
                gt[k] = sv[k] == true
            end
            if gt._refresh then pcall(gt._refresh) end
        end
        if type(data.itemTriggers) == "table" then
            for _, cfg in ipairs(ic) do
                local saved = data.itemTriggers[cfg.name]
                if type(saved) == "table" then
                    cfg.always     = saved.always     or false
                    cfg.heal       = saved.heal       or false
                    cfg.extracting = saved.extracting or false
                    cfg.seen       = saved.seen       or false
                    cfg.ignore     = saved.ignore     or false
                    cfg.stamina    = saved.stamina    or false
                    cfg.treadmillExtracting = saved.treadmillExtracting or false
                    if ui.itemTriggerRowRefs then
                        for _, ref in ipairs(ui.itemTriggerRowRefs) do
                            if ref.cfg == cfg and ref.refreshFn then
                                pcall(ref.refreshFn); break
                            end
                        end
                    end
                end
            end
        end
        if data.autoEncounter ~= nil then
            local want = data.autoEncounter == true and not S.pathfindMode
            S.autoEncounter = want
            if ui.encounterTog and ui.encounterTog.SetState then
                applyYield()
                pcall(function() ui.encounterTog.SetState(want) end)
            end
        end
        if data.autoBarnaby ~= nil and not isR and not S.isXeno then
            local want = data.autoBarnaby == true
            S.autoBarnaby = want
            if ui.autoBarnabyTog and ui.autoBarnabyTog.SetState then
                applyYield()
                pcall(function() ui.autoBarnabyTog.SetState(want) end)
            end
        end
        if type(data.itemAuraBlacklist) == "table" and ui.auraBlacklistRefs then
            S.itemAuraBlacklist = S.itemAuraBlacklist or {}
            for _, ref in ipairs(ui.auraBlacklistRefs) do
                local saved = data.itemAuraBlacklist[ref.name]
                if saved ~= nil then
                    S.itemAuraBlacklist[ref.name] = saved == true
                    applyYield()
                    pcall(function() ref.api.SetState(saved == true) end)
                end
            end
        end
    end
    if not configAllowed then
        local restrictNote = InfL(ps, "Config save/load is only available in the allowed place IDs.", cRd, 6)
        restrictNote.TextSize = Px(10); restrictNote.TextWrapped = true
    else
        local nameNote = InfL(ps, "Config name:", cTD, 6)
        nameNote.TextSize = Px(10)
        local cfgH    = Px(34)
        local cfgCapW = math.floor(cfgH / 2) + Px(3)
        local nameFrame = Instance.new("Frame", ps)
        nameFrame.Name                   = "CfgNameFrame"
        nameFrame.Size                   = UDim2.new(1, 0, 0, cfgH)
        nameFrame.BackgroundTransparency = 1
        nameFrame.BorderSizePixel        = 0
        nameFrame.LayoutOrder            = 7
        nameFrame.ZIndex                 = 204
        local nameLeft = Instance.new("ImageLabel", nameFrame)
        nameLeft.Name                   = "CfgNameLeft"
        nameLeft.Size                   = UDim2.new(0, cfgCapW, 1, 0)
        nameLeft.BackgroundTransparency = 1
        nameLeft.Image                  = wideBtnLeft
        nameLeft.ScaleType              = Enum.ScaleType.Stretch
        nameLeft.ZIndex                 = 205
        local nameMid = Instance.new("ImageLabel", nameFrame)
        nameMid.Name                   = "CfgNameMid"
        nameMid.Size                   = UDim2.new(1, -(cfgCapW * 2), 1, 0)
        nameMid.Position               = UDim2.new(0, cfgCapW, 0, 0)
        nameMid.BackgroundTransparency = 1
        nameMid.Image                  = wideBtnMid
        nameMid.ScaleType              = Enum.ScaleType.Stretch
        nameMid.ZIndex                 = 205
        local nameRight = Instance.new("ImageLabel", nameFrame)
        nameRight.Name                   = "CfgNameRight"
        nameRight.Size                   = UDim2.new(0, cfgCapW, 1, 0)
        nameRight.Position               = UDim2.new(1, -cfgCapW, 0, 0)
        nameRight.BackgroundTransparency = 1
        nameRight.Image                  = wideBtnRight
        nameRight.ScaleType              = Enum.ScaleType.Stretch
        nameRight.ZIndex                 = 205
        local nameBox = Instance.new("TextBox", nameFrame)
        nameBox.Name              = "CfgNameBox"
        nameBox.Size              = UDim2.new(1, -(cfgCapW * 2) - Px(4), 1, -Px(4))
        nameBox.Position          = UDim2.new(0, cfgCapW, 0, Px(2))
        nameBox.BackgroundTransparency = 1
        nameBox.Text              = "default"
        nameBox.PlaceholderText   = "Enter config name..."
        nameBox.PlaceholderColor3 = cTD
        nameBox.TextColor3        = Color3.fromRGB(0, 0, 0)
        nameBox.Font              = rf
        nameBox.TextSize          = Px(12)
        nameBox.TextXAlignment    = Enum.TextXAlignment.Left
        nameBox.ClearTextOnFocus  = false
        nameBox.ZIndex            = 207
        local btnRow = Instance.new("Frame", ps)
        btnRow.Name                   = "CfgBtnRow"
        btnRow.Size                   = UDim2.new(1, 0, 0, Px(30))
        btnRow.BackgroundTransparency = 1
        btnRow.LayoutOrder            = 8
        btnRow.ZIndex                 = 204
        do
            local btnGrid = Instance.new("UIGridLayout", btnRow)
            btnGrid.CellSize            = UDim2.new(0.25, -Px(3), 1, 0)
            btnGrid.CellPadding         = UDim2.new(0, Px(4), 0, 0)
            btnGrid.FillDirection       = Enum.FillDirection.Horizontal
            btnGrid.HorizontalAlignment = Enum.HorizontalAlignment.Left
            btnGrid.VerticalAlignment   = Enum.VerticalAlignment.Center
            btnGrid.SortOrder           = Enum.SortOrder.LayoutOrder
        end
        local function MakeToggleStyleBtn(labelText, lo)
            local bg = Instance.new("ImageLabel", btnRow)
            bg.Name             = "CfgBtn_" .. labelText:gsub("[^%w]","")
            bg.BackgroundTransparency = 1
            bg.Image            = togImgId
            bg.ScaleType        = Enum.ScaleType.Stretch
            bg.ImageColor3      = Color3.fromRGB(60, 200, 90)
            bg.LayoutOrder      = lo
            bg.ZIndex           = 204
            local btn = Instance.new("TextButton", bg)
            btn.Size                   = UDim2.new(1, 0, 1, 0)
            btn.BackgroundTransparency = 1
            btn.Text                   = labelText
            btn.Font                   = rf
            btn.TextSize               = Px(11)
            btn.TextColor3             = Color3.fromRGB(255, 255, 255)
            btn.AutoButtonColor        = false
            btn.ZIndex                 = 206
            ats(btn)
            btn.MouseEnter:Connect(function() bg.ImageColor3 = Color3.fromRGB(75, 225, 105) end)
            btn.MouseLeave:Connect(function() bg.ImageColor3 = Color3.fromRGB(60, 200, 90) end)
            btn.MouseButton1Down:Connect(function() bg.ImageColor3 = Color3.fromRGB(45, 165, 75) end)
            return btn
        end
        local saveBtn    = MakeToggleStyleBtn("Save",    1)
        local loadBtn     = MakeToggleStyleBtn("Load",    2)
        local refreshBtn  = MakeToggleStyleBtn("Refresh", 3)
        local deleteBtn   = MakeToggleStyleBtn("Delete",  4)
        local selectedConfigEntry = nil
        local cfgStatusLbl = InfL(ps, "", cTD, 9)
        cfgStatusLbl.Name = "CfgStatusLbl"
        cfgStatusLbl.TextSize = Px(10)
        cfgStatusLbl.Visible = false
        local function SetStatus(msg, col)
            cfgStatusLbl.Text       = msg
            cfgStatusLbl.TextColor3 = col or cTD
            cfgStatusLbl.Visible    = (msg ~= "")
            task.delay(3, function()
                if cfgStatusLbl and cfgStatusLbl.Parent then
                    cfgStatusLbl.Text    = ""
                    cfgStatusLbl.Visible = false
                end
            end)
        end
        local listNote = InfL(ps, "Saved Configs:", cTD, 10)
        listNote.TextSize = Px(10)
        local cfgListFrame = Instance.new("ScrollingFrame", ps)
        cfgListFrame.Name                = "CfgListFrame"
        cfgListFrame.Size                = UDim2.new(1, 0, 0, Px(90))
        cfgListFrame.BackgroundTransparency = 1
        cfgListFrame.BorderSizePixel     = 0
        cfgListFrame.ScrollBarThickness  = Px(3)
        cfgListFrame.ScrollBarImageColor3= cTD
        cfgListFrame.CanvasSize          = UDim2.new(0, 0, 0, 0)
        cfgListFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
        cfgListFrame.LayoutOrder         = 11
        cfgListFrame.ZIndex              = 204
        do
            local ll = Instance.new("UIListLayout", cfgListFrame)
            ll.Padding   = UDim.new(0, Px(3))
            ll.SortOrder = Enum.SortOrder.LayoutOrder
        end
        local cfgListEmptyLbl = Instance.new("TextLabel", cfgListFrame)
        cfgListEmptyLbl.Name               = "EmptyLbl"
        cfgListEmptyLbl.Size               = UDim2.new(1, 0, 0, Px(20))
        cfgListEmptyLbl.BackgroundTransparency = 1
        cfgListEmptyLbl.Text               = "No saved configs yet."
        cfgListEmptyLbl.TextColor3         = cTD
        cfgListEmptyLbl.Font               = rf
        cfgListEmptyLbl.TextSize           = Px(11)
        cfgListEmptyLbl.LayoutOrder        = 1
        cfgListEmptyLbl.ZIndex             = 205
        ats(cfgListEmptyLbl)
        local function RebuildConfigList()
            for _, ch in ipairs(cfgListFrame:GetChildren()) do
                if not ch:IsA("UIListLayout") and ch.Name ~= "EmptyLbl" then
                    ch:Destroy()
                end
            end
            local entries = ReadConfigEntries()
            if #entries == 0 then cfgListEmptyLbl.Visible = true; return end
            cfgListEmptyLbl.Visible = false
            for i, entry in ipairs(entries) do
                local name = entry.name
                local row = Instance.new("Frame", cfgListFrame)
                row.Name             = "CfgEntry_" .. i
                row.Size             = UDim2.new(1, 0, 0, Px(24))
                row.BackgroundTransparency = 1
                row.LayoutOrder      = i
                row.ZIndex           = 204
                local capW = Px(7)
                local rLeft = Instance.new("ImageLabel", row)
                rLeft.Size                   = UDim2.new(0, capW, 1, 0)
                rLeft.BackgroundTransparency = 1
                rLeft.Image                  = wideBtnLeft
                rLeft.ImageColor3            = Color3.fromRGB(120, 120, 128)
                rLeft.ScaleType              = Enum.ScaleType.Stretch
                rLeft.ZIndex                 = 205
                local rMid = Instance.new("ImageLabel", row)
                rMid.Size                   = UDim2.new(1, -(capW * 2), 1, 0)
                rMid.Position               = UDim2.new(0, capW, 0, 0)
                rMid.BackgroundTransparency = 1
                rMid.Image                  = wideBtnMid
                rMid.ImageColor3            = Color3.fromRGB(120, 120, 128)
                rMid.ScaleType              = Enum.ScaleType.Stretch
                rMid.ZIndex                 = 205
                local rRight = Instance.new("ImageLabel", row)
                rRight.Size                   = UDim2.new(0, capW, 1, 0)
                rRight.Position               = UDim2.new(1, -capW, 0, 0)
                rRight.BackgroundTransparency = 1
                rRight.Image                  = wideBtnRight
                rRight.ImageColor3            = Color3.fromRGB(120, 120, 128)
                rRight.ScaleType              = Enum.ScaleType.Stretch
                rRight.ZIndex                 = 205
                local rowBtn = Instance.new("TextButton", row)
                rowBtn.Size                   = UDim2.new(1, 0, 1, 0)
                rowBtn.BackgroundTransparency = 1
                rowBtn.Text                   = ""
                rowBtn.AutoButtonColor        = false
                rowBtn.ZIndex                 = 206
                local rowLbl = Instance.new("TextLabel", row)
                rowLbl.Size               = UDim2.new(1, -Px(14), 1, 0)
                rowLbl.Position           = UDim2.new(0, Px(10), 0, 0)
                rowLbl.BackgroundTransparency = 1
                rowLbl.Text               = name
                rowLbl.TextColor3         = Color3.fromRGB(255, 255, 255)
                rowLbl.Font               = rf
                rowLbl.TextSize           = Px(11)
                rowLbl.TextXAlignment     = Enum.TextXAlignment.Left
                rowLbl.ZIndex             = 207
                ats(rowLbl)
                local function setTint(c)
                    rLeft.ImageColor3 = c; rMid.ImageColor3 = c; rRight.ImageColor3 = c
                end
                rowBtn.MouseEnter:Connect(function() setTint(Color3.fromRGB(140, 140, 148)) end)
                rowBtn.MouseLeave:Connect(function() setTint(Color3.fromRGB(120, 120, 128)) end)
                rowBtn.MouseButton1Click:Connect(function()
                    nameBox.Text = name
                    selectedConfigEntry = entry
                    setTint(Color3.fromRGB(95, 95, 102))
                    task.delay(0.15, function()
                        if rLeft and rLeft.Parent then setTint(Color3.fromRGB(120, 120, 128)) end
                    end)
                end)
            end
        end
        RebuildConfigList()

        local rootDir  = cfgFolder:match("^(.*)/[^/]*$") or "Yatta's Crazy GUI"
        local arFlag   = rootDir .. "/AutoRunAgain.flag"
        local arcFlag  = rootDir .. "/AutoReconnect.flag"
        local arLoader = rootDir .. "/AutoRunLoader.txt"
        do
        local asPath   = rootDir .. "/AutoStartConfig.json"
        local asData = { lobby = { enabled = false, name = "" }, run = { enabled = false, name = "" } }
        pcall(function()
            if readfile and isfile and isfile(asPath) then
                local d = HttpSvc:JSONDecode(readfile(asPath))
                if type(d) == "table" then
                    for _, k in ipairs({ "lobby", "run" }) do
                        if type(d[k]) == "table" then
                            asData[k].enabled = d[k].enabled == true
                            asData[k].name    = tostring(d[k].name or "")
                        end
                    end
                end
            end
        end)
        local function SaveAutoStart()
            if writefile then pcall(function() writefile(asPath, HttpSvc:JSONEncode(asData)) end) end
        end
        local asEntry = {}
        local GREY, GREEN = Color3.fromRGB(120, 120, 128), Color3.fromRGB(80, 150, 100)
        local function MkWide(parent, size, pos, text, order, centered)
            local row = Instance.new("Frame", parent)
            row.Size = size
            if pos then row.Position = pos end
            row.BackgroundTransparency = 1
            row.LayoutOrder = order or 0
            row.ZIndex = 204
            local capW = Px(7)
            local parts = {}
            local function img(id, sz, ps2)
                local im = Instance.new("ImageLabel", row)
                im.Size = sz; im.Position = ps2 or UDim2.new()
                im.BackgroundTransparency = 1; im.Image = id
                im.ImageColor3 = GREY; im.ScaleType = Enum.ScaleType.Stretch; im.ZIndex = 205
                parts[#parts + 1] = im
            end
            img(wideBtnLeft,  UDim2.new(0, capW, 1, 0))
            img(wideBtnMid,   UDim2.new(1, -(capW * 2), 1, 0), UDim2.new(0, capW, 0, 0))
            img(wideBtnRight, UDim2.new(0, capW, 1, 0), UDim2.new(1, -capW, 0, 0))
            local btn = Instance.new("TextButton", row)
            btn.Size = UDim2.new(1, 0, 1, 0); btn.BackgroundTransparency = 1
            btn.Text = ""; btn.AutoButtonColor = false; btn.ZIndex = 206
            local lbl = Instance.new("TextLabel", row)
            lbl.Size = UDim2.new(1, -Px(14), 1, 0); lbl.Position = UDim2.new(0, Px(7), 0, 0)
            lbl.BackgroundTransparency = 1; lbl.Text = text
            lbl.TextColor3 = Color3.fromRGB(255, 255, 255); lbl.Font = rf; lbl.TextSize = Px(11)
            lbl.TextXAlignment = centered and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left
            lbl.TextTruncate = Enum.TextTruncate.AtEnd
            lbl.ZIndex = 207
            local function tint(c) for _, im in ipairs(parts) do im.ImageColor3 = c end end
            return row, btn, lbl, tint
        end
        local function MkAutoStartRow(slot, label, order)
            local _, tg = MkTog(ps, label, asData[slot].enabled, order)
            local box = Instance.new("Frame", ps)
            box.Name = "AutoStartPicker_" .. slot
            box.Size = UDim2.new(1, 0, 0, 0)
            box.AutomaticSize = Enum.AutomaticSize.Y
            box.BackgroundTransparency = 1
            box.LayoutOrder = order + 0.5
            box.ZIndex = 204
            do local l = Instance.new("UIListLayout", box); l.Padding = UDim.new(0, Px(3)); l.SortOrder = Enum.SortOrder.LayoutOrder end
            local top = Instance.new("Frame", box)
            top.Size = UDim2.new(1, 0, 0, Px(24)); top.BackgroundTransparency = 1; top.LayoutOrder = 1; top.ZIndex = 204
            local _, headBtn, headLbl = MkWide(top, UDim2.new(1, -Px(66), 1, 0), nil, "", 1, false)
            local refBg = Instance.new("ImageLabel", top)
            refBg.Name = "AutoStartRefresh_" .. slot
            refBg.Size = UDim2.new(0, Px(62), 1, 0)
            refBg.Position = UDim2.new(1, -Px(62), 0, 0)
            refBg.BackgroundTransparency = 1
            refBg.Image = togImgId
            refBg.ScaleType = Enum.ScaleType.Fit
            refBg.ImageColor3 = Color3.fromRGB(60, 200, 90)
            refBg.LayoutOrder = 2
            refBg.ZIndex = 204
            local refBtn = Instance.new("TextButton", refBg)
            refBtn.Size = UDim2.new(1, 0, 1, 0)
            refBtn.BackgroundTransparency = 1
            refBtn.Text = "Refresh"
            refBtn.Font = rf
            refBtn.TextSize = Px(11)
            refBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
            refBtn.AutoButtonColor = false
            refBtn.ZIndex = 206
            ats(refBtn)
            refBtn.MouseEnter:Connect(function() refBg.ImageColor3 = Color3.fromRGB(75, 225, 105) end)
            refBtn.MouseLeave:Connect(function() refBg.ImageColor3 = Color3.fromRGB(60, 200, 90) end)
            refBtn.MouseButton1Down:Connect(function() refBg.ImageColor3 = Color3.fromRGB(45, 165, 75) end)
            local list = Instance.new("ScrollingFrame", box)
            list.Size = UDim2.new(1, 0, 0, Px(90))
            list.BackgroundTransparency = 1
            list.BorderSizePixel = 0
            list.ScrollBarThickness = Px(3)
            list.ScrollBarImageColor3 = cTD
            list.CanvasSize = UDim2.new(0, 0, 0, 0)
            list.AutomaticCanvasSize = Enum.AutomaticSize.Y
            list.LayoutOrder = 2
            list.ZIndex = 204
            list.Visible = false
            do local l = Instance.new("UIListLayout", list); l.Padding = UDim.new(0, Px(3)); l.SortOrder = Enum.SortOrder.LayoutOrder end
            local function Title()
                local nm = asData[slot].name
                headLbl.Text = (nm ~= "") and ("Config: " .. nm) or "None"
            end
            Title()
            local function Fill()
                for _, c in ipairs(list:GetChildren()) do
                    if not c:IsA("UIListLayout") then c:Destroy() end
                end
                local _, nb, _, nTint = MkWide(list, UDim2.new(1, 0, 0, Px(24)), nil, "None", 0, false)
                nTint(asData[slot].name == "" and GREEN or GREY)
                nb.MouseButton1Click:Connect(function()
                    asData[slot].name = ""; asData[slot].enabled = false; asEntry[slot] = nil
                    SaveAutoStart(); Title()
                    pcall(function() tg.SetState(false) end)
                    list.Visible = false
                    ui.Notify("Auto start config (" .. slot .. "): none")
                end)
                for i, entry in ipairs(ReadConfigEntries()) do
                    local shown = entry.name
                    if string.lower(shown) == "none" then shown = shown .. " (config)" end
                    local _, eb, _, eTint = MkWide(list, UDim2.new(1, 0, 0, Px(24)), nil, shown, i, false)
                    eTint(entry.name == asData[slot].name and GREEN or GREY)
                    eb.MouseButton1Click:Connect(function()
                        asData[slot].name = entry.name
                        asEntry[slot] = entry
                        SaveAutoStart(); Title()
                        list.Visible = false
                        ui.Notify("Auto start config (" .. slot .. "): " .. entry.name)
                    end)
                end
            end
            headBtn.MouseButton1Click:Connect(function()
                list.Visible = not list.Visible
                if list.Visible then Fill() end
            end)
            refBtn.MouseButton1Click:Connect(function()
                if list.Visible then Fill() end
                Title()
            end)
            tg.OnChanged(function(v)
                if v then
                    local nm = asData[slot].name
                    local okC = nm ~= "" and ReadConfigData(nm, asEntry[slot])
                    if not okC then
                        ui.Notify(nm == "" and "Choose a saved config first (None = nothing runs)!" or ("Config not found: " .. nm), true)
                        pcall(function() tg.SetState(false) end)
                        return
                    end
                    asData[slot].enabled = true
                    SaveAutoStart(); Title()
                    ui.Notify("Auto start config: " .. nm)
                else
                    asData[slot].enabled = false
                    SaveAutoStart()
                end
            end)
            return tg
        end
        local isLobbyPlace = (game.PlaceId == restrictedId)
        local isRunPlace   = (game.PlaceId == fullId)
        if isLobbyPlace then MkAutoStartRow("lobby", "Auto Start Config (Lobby)", 12) end
        if isLobbyPlace or isRunPlace then MkAutoStartRow("run", "Auto Start Config (Run)", 13) end

        do
            local ent = isLobbyPlace and asData.lobby or (isRunPlace and asData.run) or nil
            if ent and ent.enabled and ent.name ~= "" then
                regSpawn(function()
                    task.wait(2)
                    local t0 = tick()
                    while not workspace:FindFirstChild("Info") and tick() - t0 < 15 do task.wait(0.5) end
                    local okR, data = ReadConfigData(ent.name)
                    if not okR or type(data) ~= "table" then
                        ui.Notify("Auto start config not found: " .. ent.name, true)
                        return
                    end
                    if ui.isVoting() then
                        ui.Notify("Waiting for game to start.")
                        repeat task.wait(0.5) until not ui.isVoting()
                        task.wait(0.3)
                    end
                    local okA, errA = pcall(ApplyConfig, data)
                    if okA then ui.Notify("Auto start config loaded: " .. ent.name)
                    else  end
                end)
            end
        end

        end

        local function ReadLoader()
            local url = (getgenv and getgenv().YattaScriptURL) or _G.YattaScriptURL
            if type(url) == "string" and url:match("^https?://") then
                return string.format("loadstring(game:HttpGet(%q))()", url)
            end
            if readfile and isfile and isfile(arLoader) then
                local okR, body = pcall(readfile, arLoader)
                body = okR and tostring(body):match("^%s*(.-)%s*$") or ""
                if body:match("^https?://[^%s]+$") then
                    return string.format("loadstring(game:HttpGet(%q))()", body)
                end
                if body ~= "" then return body end
            end
            return string.format("loadstring(game:HttpGet(%q))()",
                "https://raw.githubusercontent.com/BluuGuy-Sure/BluuHead-Dandy-s-World/refs/heads/main/JustThisOnce.lua")
        end
        local qot = queue_on_teleport or (syn and syn.queue_on_teleport) or queueonteleport
        local function QueueRerun()
            if not qot then return false, "noqueue" end
            local loader = ReadLoader()
            if not loader then return false, "noloader" end
            if S.arQueued then return true end
            local code = string.format("local function fOn(p) local okF, on = pcall(function() return readfile(p) end) return okF and on == \"1\" end\nif not fOn(%q) then return end\nif not game:IsLoaded() then game.Loaded:Wait() end\ntask.wait(1)\n%s\n", arFlag, loader)
            local okQ = pcall(qot, code)
            if okQ then S.arQueued = true end
            return okQ
        end
        local arOn = false
        pcall(function()
            if isfile and readfile and isfile(arFlag) and readfile(arFlag) == "1" then arOn = true end
        end)
        S.autoRunAgain = arOn
        local _, tAR = MkTog(ps, "Auto Run Script Again", arOn, 14)
        tAR.Label.TextSize = math.floor(FSz * 0.75)
        tAR.OnChanged(function(v)
            S.autoRunAgain = v
            if writefile then pcall(writefile, arFlag, v and "1" or "0") end
            if v then
                local okQ, why = QueueRerun()
                if not okQ then
                    if why == "noqueue" then
                        ui.Notify("Your executor has no queue_on_teleport.", true)
                    else
                        ui.Notify("Put the script URL in " .. arLoader .. " first!", true)
                    end
                    pcall(function() tAR.SetState(false) end)
                end
            end
        end)
        if arOn then
            regSpawn(function()
                task.wait(3)
                local okQ, why = QueueRerun()
                if not okQ then
                    ui.Notify(why == "noqueue" and "Your executor has no queue_on_teleport."
                        or ("Auto run again needs the script URL in " .. arLoader), true)
                end
            end)
        end

        local rcOn = false
        pcall(function()
            if isfile and readfile and isfile(arcFlag) then rcOn = (readfile(arcFlag) == "1") end
        end)
        S.autoReconnect = rcOn
        local _, tRC = MkTog(ps, "Auto Reconnect", rcOn, 14.5)
        tRC.OnChanged(function(v)
            S.autoReconnect = v
            if writefile then pcall(writefile, arcFlag, v and "1" or "0") end
        end)
        ui.autoReconnectTog = tRC
        do
            local GuiSvc = game:GetService("GuiService")
            local TpS    = game:GetService("TeleportService")
            local busy   = false
            local function disconnected()
                local msg = ""
                pcall(function() msg = GuiSvc:GetErrorMessage() end)
                if type(msg) == "string" and msg ~= "" then return true end
                local okC, found = pcall(function()
                    local pg = game:GetService("CoreGui"):FindFirstChild("RobloxPromptGui")
                    local po = pg and pg:FindFirstChild("promptOverlay")
                    return po ~= nil and po:FindFirstChild("ErrorPrompt") ~= nil
                end)
                return okC and found == true
            end
            local function reconnect()
                if busy then return end
                busy = true
                task.wait(2)
                for attempt = 1, 30 do
                    if not S.autoReconnect then break end
                    local inLobby = (game.PlaceId == restrictedId)
                    local inRun   = (game.PlaceId == fullId)
                    if not (inLobby or inRun) then break end
                    if S.autoRunAgain then pcall(QueueRerun) end   
                    if inLobby then
                        if attempt % 2 == 1 and game.JobId ~= "" then
                            pcall(function() TpS:TeleportToPlaceInstance(game.PlaceId, game.JobId, plr) end)
                        else
                            pcall(function() TpS:Teleport(restrictedId, plr) end)
                        end
                    else
                        pcall(function() TpS:Teleport(restrictedId, plr) end)
                    end
                    task.wait(7)
                end
                busy = false
            end
            regSpawn(function()
                while true do
                    task.wait(1)
                    if S.autoReconnect and not busy and disconnected() then task.spawn(reconnect) end
                end
            end)
        end

        saveBtn.MouseButton1Click:Connect(function()
            if not writefile then return end
            local name = nameBox.Text
            selectedConfigEntry = nil
            local ok, err = pcall(function()
                writefile(CfgFilename(name), HttpSvc:JSONEncode(BuildConfigSnapshot()))
            end)
            if ok then
                RebuildConfigList()
            end
        end)
        loadBtn.MouseButton1Click:Connect(function()
            if not readfile then return end
            local name = nameBox.Text
            local ok, data = ReadConfigData(name, selectedConfigEntry)
            if not ok or type(data) ~= "table" then
                SetStatus("Could not load config.", cRd)
                return
            end
            if ui.isVoting() then
                if ui.cfgWaiting then
                    ui.Notify("A config is already waiting to be loaded!", true)
                    return
                end
                ui.cfgWaiting = true
                ui.Notify("Waiting for game to start.")
                regSpawn(function()
                    repeat task.wait(0.5) until not ui.isVoting()
                    task.wait(0.3)
                    ui.cfgWaiting = false
                    local okA, errA = pcall(ApplyConfig, data)
                    SetStatus(okA and "Config loaded." or "Config loaded, but some settings failed.", okA and cGr or cRd)
                    if not okA then  end
                end)
            else
                local okA, errA = pcall(ApplyConfig, data)
                SetStatus(okA and "Config loaded." or "Config loaded, but some settings failed.", okA and cGr or cRd)
                if not okA then  end
            end
        end)
        refreshBtn.MouseButton1Click:Connect(function()
            local keepName = nameBox.Text
            selectedConfigEntry = nil
            for _, entry in ipairs(ReadConfigEntries()) do
                if entry.name == keepName then
                    selectedConfigEntry = entry
                    break
                end
            end
            RebuildConfigList()
            if selectedConfigEntry then
                nameBox.Text = selectedConfigEntry.name
            end
            SetStatus("Configs refreshed.", cTD)
        end)
        deleteBtn.MouseButton1Click:Connect(function()
            if not readfile then return end
            local name = nameBox.Text
            if name == "" then return end
            local selected = selectedConfigEntry
            local filename = (selected and selected.name == name and selected.source) or CfgFilename(name)
            local exists = pcall(function() readfile(filename) end)
            if not exists then
                return
            end
            local ok = pcall(function()
                if delfile then
                    delfile(filename)
                else
                    writefile(filename, "{\"_deleted\":true}")
                end
            end)
            if ok then
                selectedConfigEntry = nil
                RebuildConfigList()
            end
        end)
    end
end)()
;(function()
