        bg.BorderSizePixel        = 0
        bg.ZIndex                 = 205
        local bgCorner = Instance.new("UICorner", bg)
        bgCorner.CornerRadius     = UDim.new(0, Px(6))
        local box = Instance.new("TextBox", frame)
        box.Name                   = name .. "Input"
        box.Size                   = UDim2.new(1, -Px(8), 1, -Px(4))
        box.Position               = UDim2.new(0, Px(4), 0, Px(2))
        box.BackgroundTransparency = 1
        box.PlaceholderText        = placeholder
        box.PlaceholderColor3      = cTD
        box.Text                   = ""
        box.Font                   = rf
