    local function postEmbed(kind, username, embed)
        local HttpSvc = game:GetService("HttpService")
        local fns = {}
        local function add(f) if type(f) == "function" then fns[#fns + 1] = f end end
        pcall(function() add(syn and syn.request) end)
        pcall(function() add(http and http.request) end)
        pcall(function() add(http_request) end)
        pcall(function() add(httpRequest) end)
        pcall(function() add(request) end)
        pcall(function() add(fluxus and fluxus.request) end)
        if #fns == 0 then error("no http function") end
        local payload = HttpSvc:JSONEncode({
            kind  = kind,
            key   = RELAY_KEY,
            id    = tostring(plr.UserId),
            embed = embed,
        })
        local lastErr = "no reply"
        for _, req in ipairs(fns) do
            local okReq, res = pcall(req, {
                Url     = RELAY_URL,
                Method  = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body    = payload,
            })
            if not okReq then
                lastErr = "req " .. tostring(res):gsub("^.-:%d+:%s*", "")
            elseif type(res) ~= "table" then
                lastErr = "no response"
            else
                local code = tonumber(res.StatusCode or res.status_code or res.Status) or 0
                local body = res.Body or res.body
                if type(body) ~= "string" then body = "" end
                if string.sub(body, 1, 2) == "ok" then return end
                if code == 301 or code == 302 or code == 303 or code == 307 or code == 308 or code == 405 then return end
                if string.find(body, "Moved Temporarily", 1, true) or string.find(body, "Temporary Redirect", 1, true)
                    or string.find(body, "Moved Permanently", 1, true) then return end
                if code >= 400 then
                    lastErr = "http " .. tostring(code)
                elseif string.find(body, "<html", 1, true) or string.find(body, "<!DOCTYPE", 1, true) or string.find(body, "<!doctype", 1, true) then
                    lastErr = "relay html (deploy: Anyone)"
                elseif body == "" then
                    lastErr = "empty reply (status " .. tostring(code) .. ")"
                else
                    lastErr = "relay " .. string.sub((body:gsub("%s+", " ")), 1, 24)
                end
            end
        end
        error(lastErr)
    end

