    local function mkReplyCol(tag, cx, head)
        local sc = Instance.new("ScrollingFrame", replyFrame)
        sc.Name                   = "DevReply" .. tag .. "Scroll"
        sc.AnchorPoint            = Vector2.new(0.5, 0)
