        blk.Name = "DevReply" .. tag .. "Block"
        blk.BackgroundTransparency = 1; blk.BorderSizePixel = 0; blk.ZIndex = 451
        local hd = Instance.new("TextLabel", blk)
        hd.Name = "DevReply" .. tag .. "Head"
        hd.Size = UDim2.new(1, 0, 0, Px(24)); hd.BackgroundTransparency = 1; hd.BorderSizePixel = 0
        hd.Text = head; hd.TextColor3 = cTW; hd.Font = rf; hd.TextSize = Px(17); hd.TextWrapped = true
        hd.TextXAlignment = Enum.TextXAlignment.Center; hd.ZIndex = 452
        do local st = Instance.new("UIStroke", hd); st.Thickness = 2; st.Color = Color3.fromRGB(0, 0, 0) end
        local body = Instance.new("TextLabel", blk)
        body.Name                   = "DevReply" .. tag .. "Text"
        body.Position               = UDim2.new(0, 0, 0, Px(32))
        body.Size                   = UDim2.new(1, 0, 0, Px(20))
        body.BackgroundTransparency = 1
        body.BorderSizePixel        = 0
        body.Text                   = ""
        body.TextColor3             = cTW
        body.Font                   = rf
        body.TextSize               = Px(16)
        body.TextWrapped            = true
        body.TextXAlignment         = Enum.TextXAlignment.Center
        body.TextYAlignment         = Enum.TextYAlignment.Top
        body.ZIndex                 = 452
        do local st = Instance.new("UIStroke", body); st.Thickness = 1; st.Color = Color3.fromRGB(0, 0, 0) end
        body.TextSize      = Px(16)
        body.TextWrapped   = true
        body.TextTruncate  = Enum.TextTruncate.None
        body.AutomaticSize = Enum.AutomaticSize.None
        local fitBusy = false
        local function measure(width)
            local okM, h = pcall(function()
                local prm = Instance.new("GetTextBoundsParams")
                prm.Text  = body.Text
                prm.Font  = body.FontFace
                prm.Size  = body.TextSize
                prm.Width = math.max(width, 10)
                return TextSvc0:GetTextBoundsAsync(prm).Y
            end)
            if okM and type(h) == "number" then return h end
            local cpl   = math.max(1, math.floor(width / (body.TextSize * 0.5)))
            local lines = 0
            for line in (body.Text .. "\n"):gmatch("(.-)\n") do lines = lines + math.max(1, math.ceil(#line / cpl)) end
            return lines * body.TextSize * 1.2
        end
        local function fit()
            if fitBusy then return end
            local scl  = _G.YattaScaleOf(sc)
            local W, H = sc.AbsoluteSize.X / scl, sc.AbsoluteSize.Y / scl
            if W <= 0 or H <= 0 then return end
            fitBusy = true
            local headH = Px(32)
            local bw    = W - Px(8)
            local bh    = math.ceil(measure(bw - 2)) + Px(10)   
            local total = headH + bh
            body.Size     = UDim2.new(1, 0, 0, bh)
            blk.Size      = UDim2.new(1, -Px(8), 0, total)
            blk.Position  = UDim2.new(0, 0, 0, math.max(0, math.floor((H - total) / 2)))
            sc.CanvasSize = UDim2.new(0, 0, 0, math.max(H, total))
            fitBusy = false
        end
        body:GetPropertyChangedSignal("Text"):Connect(fit)
        replyFits[#replyFits + 1] = fit
        sc:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
        return function(txt, col)
            body.Text = txt; body.TextColor3 = col or cTW
            sc.CanvasPosition = Vector2.new(0, 0)
            fit()
        end
    end
