    local function newTicket(prefix)
        local chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
        local rng, t = Random.new(), ""
        for _ = 1, 5 do local i = rng:NextInteger(1, #chars); t = t .. chars:sub(i, i) end
        return prefix .. "-" .. t
    end
    local function checkReplies()
        if next(tickets) == nil then return end
        local req = (syn and syn.request) or (http and http.request) or (httpRequest) or (request)
        if not req then return end
        local ok, res = pcall(req, { Url = REPLIES_URL .. "?t=" .. tostring(os.time()), Method = "GET" })
        if not ok or type(res) ~= "table" or res.StatusCode ~= 200 or type(res.Body) ~= "string" then return end
        local okD, map = pcall(function() return HttpSvc0:JSONDecode(res.Body) end)
        if not okD or type(map) ~= "table" then return end
        local got = false
        for tk, old in pairs(tickets) do
            local txt = map[tk]
            if type(txt) == "string" and txt ~= "" and txt ~= old then
                tickets[tk] = string.sub(txt, 1, 1000)
                got = true
                replyQueue[#replyQueue + 1] = { ticket = tk, text = string.sub(txt, 1, 1000), orig = ticketMsgs[tk] }
            end
        end
        if got then
            saveTickets()
            if not replyShowing then showNextReply() end
        end
    end

    local function wireSend(btn, box, status, o)
        btn.MouseButton1Click:Connect(function()
            if tick() - lastSend < FB_COOLDOWN then
                flash(status, cRd, "Wait before sending another!")
                return
            end
            local text = box.Text
            if not text or text:gsub("%s+", "") == "" then
                flash(status, cRd, "Please type something first!")
                return
            end
            if #text > 1000 then
                flash(status, cRd, "Message too long (max 1000 chars).")
                return
            end
            if text:find("@") then
                flash(status, cRd, "Pinging isn't allowed! Please edit your message.")
                return
            end
            if text:find("%.com") or text:find("%.gg") or text:find("%.net") or text:find("%.org")
                or text:find("%.co") or text:find("%.io") or text:find("%.tv") or text:find("%.xyz")
                or text:find("http://") or text:find("https://") or text:find("www%.") then
                flash(status, cRd, "Links are not allowed! Please remove the link!")
                return
            end
            lastSend = tick()
            status.TextColor3 = cTD
            status.Text = "Sending..."
            status:SetAttribute("fbFlash", (status:GetAttribute("fbFlash") or 0) + 1)
            local senderName = fbAnon and "Anonymous" or plr.Name
            local safeText   = (text:gsub("```", "'''"))
            local ticket = newTicket(o.prefix or "FB")
            local embedFields = {}
            local p1 = _G.YattaP1
            local onAllowedPlace = p1 and (game.PlaceId == p1.fid or game.PlaceId == p1.rid)
            local inRun = workspace:FindFirstChild("CurrentRoom") ~= nil
            if onAllowedPlace then
                local execName = "Unknown"
                pcall(function() execName = identifyexecutor and identifyexecutor() or "Unknown" end)
                local gameName = "Unknown"
                if game.PlaceId == 16552821455 then gameName = "Dandy's World (Main)" else gameName = "PlaceId: " .. tostring(game.PlaceId) end
                embedFields = {
                    { name = "Executor", value = execName, inline = true },
                    { name = "Game", value = gameName, inline = true },
                }
                if inRun then
                    local hearts = "?"
                    local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
                    if hum then hearts = tostring(math.floor(hum.Health + 0.5)) end
                    local floorNum = "?"
                    local info = workspace:FindFirstChild("Info")
                    local fv = info and info:FindFirstChild("Floor")
                    if fv and fv:IsA("IntValue") then floorNum = tostring(fv.Value) end
                    table.insert(embedFields, { name = "Hearts", value = hearts, inline = true })
                    table.insert(embedFields, { name = "Floor", value = floorNum, inline = true })
                end
            end
            local embed = {
                description = string.format("`%s` has sent %s.\n\n```%s```", senderName, o.phrase, safeText),
                color       = o.color,
                footer      = { text = "Ticket " .. ticket .. (fbAnon and "" or (" | UserId " .. tostring(plr.UserId))) },
                fields      = embedFields,
            }
            regSpawn(function()
                local ok, perr = pcall(postEmbed, o.hook, o.username, embed)
                if not ok then  end
                if status and status.Parent then
                    if ok then
                        tickets[ticket] = ""
                        ticketMsgs[ticket] = string.sub(text, 1, 1000)
                        saveTickets()
                        flash(status, cGr, o.okText .. " Ticket: " .. ticket, 6)
                        box.Text = ""
                    else
                        lastSend = 0
                        local why = tostring(perr or ""):gsub("^.-:%d+:%s*", "")
                        flash(status, cRd, "Failed to send. Try again." .. (why ~= "" and (" (" .. string.sub(why, 1, 28) .. ")") or ""), 4)
                    end
                end
            end)
        end)
    end

    local function tintBtn(frame, c)
        local inner = frame:FindFirstChild("BtnInner")
        if inner then
            local l = inner:FindFirstChild("BtnLeft");  if l then l.ImageColor3 = c end
            local m = inner:FindFirstChild("BtnMid");   if m then m.ImageColor3 = c end
            local r = inner:FindFirstChild("BtnRight"); if r then r.ImageColor3 = c end
        end
    end

