    local _, anonTog = MkTog(list, "Anonymous Mode", false, 22)
    anonTog.OnChanged(function(v) WH.anon = v end)

    Gap(pw, 4, 23)
    SecH(pw, "Separate webhook logging", 24)
    local descLabel = Instance.new("TextLabel", pw)
    descLabel.Name                   = "SepWebhookDesc"
    descLabel.Size                   = UDim2.new(1, -Px(10), 0, Px(30))
    descLabel.BackgroundTransparency = 1
    descLabel.Text                   = "note that this is optional; if it's empty then it will send the log to the original webhook you sent in the webhook logging list."
    descLabel.TextColor3             = Color3.fromRGB(150, 150, 150)
    descLabel.Font                   = rf
    descLabel.TextSize               = Px(10)
    descLabel.TextXAlignment         = Enum.TextXAlignment.Left
    descLabel.TextWrapped            = true
    descLabel.LayoutOrder            = 24.5
    descLabel.ZIndex                 = 204
    local sepList = mkList("ToggleList_Separate_Webhook", 25)

    local function trim(s) return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")) end
    local function refreshUrl() WH.url = trim(urlBox.Text) end

    local sepUrlBoxes = {}
    local function makeSepUrlBox(key, label, layoutOrder, fileName)
        local boxH   = Px(30)
        local boxCap = math.floor(boxH / 2) + Px(3)
        local labelH = Px(18)
        local totalH = boxH + labelH + Px(4)

        local container = Instance.new("Frame", sepList)
        container.Name                   = "SepWebhook_" .. key
        container.Size                   = UDim2.new(1, 0, 0, totalH)
        container.BackgroundTransparency = 1
        container.BorderSizePixel        = 0
        container.LayoutOrder            = layoutOrder
        container.ZIndex                 = 204

        local nameLabel = Instance.new("TextLabel", container)
        nameLabel.Name                   = "SepWebhookLabel"
        nameLabel.Size                   = UDim2.new(1, 0, 0, labelH)
        nameLabel.Position               = UDim2.new(0, 0, 0, 0)
        nameLabel.BackgroundTransparency = 1
        nameLabel.Text                   = label
        nameLabel.TextColor3             = cTL
        nameLabel.Font                   = rf
        nameLabel.TextSize               = FSz
        nameLabel.TextXAlignment         = Enum.TextXAlignment.Left
        nameLabel.ZIndex                 = 205
        ats(nameLabel)

        local boxFrame = Instance.new("Frame", container)
        boxFrame.Name                   = "SepWebhookBoxFrame"
        boxFrame.Size                   = UDim2.new(1, 0, 0, boxH)
        boxFrame.Position               = UDim2.new(0, 0, 0, labelH + Px(4))
        boxFrame.BackgroundTransparency = 1
        boxFrame.BorderSizePixel        = 0
        boxFrame.ZIndex                 = 204

        local bl = Instance.new("ImageLabel", boxFrame)
        bl.Name = "SepWebhookBoxLeft"
        bl.Size = UDim2.new(0, boxCap, 1, 0)
        bl.BackgroundTransparency = 1
        bl.Image = wideBtnLeft
        bl.ScaleType = Enum.ScaleType.Stretch
        bl.ZIndex = 205
        local bm = Instance.new("ImageLabel", boxFrame)
        bm.Name = "SepWebhookBoxMid"
        bm.Size = UDim2.new(1, -(boxCap * 2), 1, 0)
        bm.Position = UDim2.new(0, boxCap, 0, 0)
        bm.BackgroundTransparency = 1
        bm.Image = wideBtnMid
        bm.ScaleType = Enum.ScaleType.Stretch
        bm.ZIndex = 205
        local br = Instance.new("ImageLabel", boxFrame)
        br.Name = "SepWebhookBoxRight"
        br.Size = UDim2.new(0, boxCap, 1, 0)
        br.Position = UDim2.new(1, -boxCap, 0, 0)
        br.BackgroundTransparency = 1
        br.Image = wideBtnRight
        br.ScaleType = Enum.ScaleType.Stretch
        br.ZIndex = 205
        local urlBox = Instance.new("TextBox", boxFrame)
        urlBox.Name                   = "SepWebhookUrlBox_" .. key
        urlBox.Size                   = UDim2.new(1, -(boxCap * 2) - Px(4), 1, -Px(4))
        urlBox.Position               = UDim2.new(0, boxCap, 0, Px(2))
        urlBox.BackgroundTransparency = 1
        urlBox.Text                   = ""
        urlBox.PlaceholderText        = "enter webhook name here"
        urlBox.PlaceholderColor3      = cTD
        urlBox.TextColor3             = Color3.fromRGB(0, 0, 0)
        urlBox.Font                   = rf
        urlBox.TextSize               = Px(11)
        urlBox.TextXAlignment         = Enum.TextXAlignment.Left
        urlBox.ClearTextOnFocus       = false
        urlBox.ClipsDescendants       = true
        urlBox.ZIndex                 = 207

        local function refreshSepUrl()
            WH.separate[key] = trim(urlBox.Text)
        end

        pcall(function()
            if isfile and readfile and isfile(fileName) then
                local saved = trim(readfile(fileName))
                if saved ~= "" then urlBox.Text = saved end
            end
        end)
        refreshSepUrl()
        urlBox:GetPropertyChangedSignal("Text"):Connect(refreshSepUrl)
        urlBox.FocusLost:Connect(function()
            refreshSepUrl()
            pcall(function() if writefile then writefile(fileName, WH.separate[key]) end end)
        end)

        sepUrlBoxes[key] = urlBox
    end

    makeSepUrlBox("floor",    "Log Floor",           30, "Yatta_Webhook_Floor.txt")
    makeSepUrlBox("items",    "Log Floor Items",     31, "Yatta_Webhook_Items.txt")
    makeSepUrlBox("twisteds", "Log Floor Twisteds",  32, "Yatta_Webhook_Twisteds.txt")
    makeSepUrlBox("shop",     "Log Dandy Shop Items",33, "Yatta_Webhook_Shop.txt")
    makeSepUrlBox("status",   "Log Floor Status",    34, "Yatta_Webhook_Status.txt")
    makeSepUrlBox("blackout", "Log Floor Blackouts", 35, "Yatta_Webhook_Blackout.txt")
    makeSepUrlBox("health",   "Log Health",          36, "Yatta_Webhook_Health.txt")
    makeSepUrlBox("death",    "Log Player Death",    37, "Yatta_Webhook_Death.txt")

    local function refreshUrl() WH.url = trim(urlBox.Text) end

    refreshUrl()
    urlBox:GetPropertyChangedSignal("Text"):Connect(refreshUrl)
    urlBox.FocusLost:Connect(function()
        refreshUrl()
        if WH.url == "" and startTog.GetState() then startTog.SetState(false) end
    end)

    startTog.OnChanged(function(v)
        if v then
            refreshUrl()
            if WH.url == "" then
                ps(sErr)
                startTog.SetState(false)
                return
            end
            WH.running = true
        else
            WH.running = false
        end
    end)

    Gap(pw, 4, 7)
    SecH(pw, "Notifier", 8)
    local nlist = mkList("ToggleList_Notifier", 9)
    addLogs(nlist, "nf")

    local YELLOW = 0xFFFF00
    local queue, pumping = {}, false
    local function httpReq(opts)
        local r = (syn and syn.request) or (http and http.request) or httpRequest or request
        if r then return r(opts) end
    end
    local function pump()
        if pumping then return end
        pumping = true
        regSpawn(function()
            while #queue > 0 do
                local item = table.remove(queue, 1)
                local body = item.body
                local url = item.url or WH.url
                local ok, res = pcall(httpReq, {
                    Url = url, Method = "POST",
                    Headers = { ["Content-Type"] = "application/json" },
                    Body = body,
                })
                if ok and res and res.StatusCode == 429 then
                    local wait = 2
                    pcall(function() wait = (HttpSvc:JSONDecode(res.Body).retry_after or 2) end)
                    task.wait(math.clamp(wait, 0.5, 10))
                    table.insert(queue, 1, item)
                end
                task.wait(0.6)
            end
            pumping = false
        end)
    end
    local function flatMsg(msg)
        if type(msg) ~= "table" then return msg end
        local out = { msg.desc or "" }
        for _, f in ipairs(msg.fields or {}) do out[#out + 1] = f.name .. ":\n" .. f.value end
        return table.concat(out, "\n\n")
    end
    local function sendEmbed(msg, url)
        local sendUrl = (url and url ~= "") and url or WH.url
        if sendUrl == "" then return end
        local ok, body = pcall(function()
            if type(msg) == "table" and msg.plain then
                return HttpSvc:JSONEncode({ content = msg.desc })
            end
            local emb = { color = YELLOW }
            if type(msg) == "table" then
                emb.description = msg.desc
                if msg.fields and #msg.fields > 0 then emb.fields = msg.fields end
            else
                emb.description = msg
            end
            if type(msg) == "table" and msg.content then
                return HttpSvc:JSONEncode({ content = msg.content, embeds = { emb } })
            end
            return HttpSvc:JSONEncode({ embeds = { emb } })
        end)
        if not ok then return end
        queue[#queue + 1] = { body = body, url = sendUrl }
        pump()
    end

    local dests = {
        {
            id = "wh", flags = FLAGS.wh,
            ready = function() return WH.running and (WH.url ~= "" or next(WH.separate) ~= nil) end,
            send  = function(text, perm, key) sendEmbed(text, key and WH.separate[key]) end,
            name  = function() return WH.anon and "Anonymous" or plr.Name end,
        },
        {
            id = "nf", flags = FLAGS.nf,
            ready = function() return true end,
            send  = function(text, perm) if ui.Notice then ui.Notice(flatMsg(text), perm) end end,
            name  = function() return WH.anon and "Anonymous" or plr.Name end,
        },
    }
    local function emit(key, build, perm)
        for _, d in ipairs(dests) do
            if d.flags[key] and d.ready() then
                d.send(build(d), perm and d.id == "nf", key)
            end
        end
    end

    local function joinNames(names)
        local count, order = {}, {}
        for _, nm in ipairs(names) do
            if count[nm] == nil then count[nm] = 0; order[#order + 1] = nm end
            count[nm] = count[nm] + 1
        end
        table.sort(order, function(a, b) return a:lower() < b:lower() end)
        local parts = {}
        for i, nm in ipairs(order) do
            parts[i] = (count[nm] >= 2) and string.format("%s(%dx)", nm, count[nm]) or nm
        end
        local n = #parts
        if n == 0 then return "" end
        if n == 1 then return parts[1] end
        return table.concat(parts, ", ", 1, n - 1) .. ", and " .. parts[n]
    end

    local function fmtTime(sec)
        sec = math.max(0, math.floor(sec + 0.5))
        local h, m, s = math.floor(sec / 3600), math.floor(sec / 60) % 60, sec % 60
        if h > 0 then return string.format("%dh %dm %ds", h, m, s) end
        if m > 0 then return string.format("%dm %ds", m, s) end
        return string.format("%ds", s)
    end

    local function info() return workspace:FindFirstChild("Info") end
    local function numVal(name)
        local i = info(); local v = i and i:FindFirstChild(name)
        if v and (v:IsA("NumberValue") or v:IsA("IntValue")) then return v.Value end
    end
    local function boolVal(name)
        local i = info(); local v = i and i:FindFirstChild(name)
        return v and v:IsA("BoolValue") and v.Value == true or false
    end

    local function scanItemNames()
        local out = {}
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return out end
        for _, room in ipairs(cr:GetChildren()) do
            local f = room:FindFirstChild("Items")
            if f then for _, it in ipairs(f:GetChildren()) do if it.Name ~= "GigiHoard" then out[#out + 1] = it.Name end end end
        end
        return out
    end
    local function scanTwistedNames()
        local out = {}
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return out end
        for _, room in ipairs(cr:GetChildren()) do
            local f = room:FindFirstChild("Monsters")
            if f then
                for _, m in ipairs(f:GetChildren()) do
                    if m:IsA("Model") then
                        local cfg = mons[m.Name]
                        local okAdd = false
                        if cfg then okAdd = not cfg.isGrab
                        else
                            local ok, r = pcall(iumo, m)
                            okAdd = ok and r and true or false
                        end
                        if okAdd then out[#out + 1] = m.Name end
                    end
                end
            end
        end
        return out
    end
    local function scanShopNames()
        local out = {}
        local el = workspace:FindFirstChild("Elevators")
        local e  = el and el:FindFirstChild("Elevator")
        local ds = e and e:FindFirstChild("DandyStore")
        if not ds then return out end
        for i = 1, 3 do
            local slot = ds:FindFirstChild("Slot" .. i)
            if slot then
                for _, c in ipairs(slot:GetChildren()) do
                    if c:IsA("Model") or c:IsA("BasePart") then out[#out + 1] = c.Name end
                end
            end
        end
        return out
    end

    local function logWhenReady(d, scan, flagKey, stillValid, build)
        regSpawn(function()
            for _ = 1, 12 do
                task.wait(1)
                if not stillValid() then return end
                local names = scan()
                if #names > 0 then
                    if d.flags[flagKey] and d.ready() then d.send(build(joinNames(names)), false, flagKey) end
                    return
                end
            end
        end)
    end

    local function logFloorOpened(d, wI, wT, wS)
        regSpawn(function()
            local items, tws = {}, {}
            for _ = 1, 12 do
                task.wait(1)
                if not boolVal("FloorActive") then return end
                items = wI and scanItemNames() or {}
                tws   = wT and scanTwistedNames() or {}
                if (not wI or #items > 0) and (not wT or #tws > 0) then break end
            end
            if not (boolVal("FloorActive") and d.ready()) then return end
            local floorNum = numVal("Floor") or "?"
            local headLine = string.format("Floor `%s` has opened in **%s's** Run.", tostring(floorNum), d.name())
            local reqGens = numVal("RequiredGenerators")
            if reqGens then
                headLine = headLine .. string.format("\nthere are `%d` machines available on this floor.", reqGens)
            end
            local function fieldVal(t)
                if #t > 1000 then t = string.sub(t, 1, 997) .. "..." end
                return "`" .. t .. "`"
            end
            local fields = {}
            if wT then
                fields[#fields + 1] = { name = "Twisteds", value = fieldVal(#tws > 0 and joinNames(tws) or "none"), inline = true }
            end
            if wI then
                fields[#fields + 1] = { name = "Items", value = fieldVal(#items > 0 and joinNames(items) or "none"), inline = true }
            end
            d.send({ desc = headLine, fields = fields }, false, nil)
        end)
    end

    local function onFloorOpen(d)
        local f = d.flags
        local wI, wT, wS = f.items, f.twisteds, f.status
        local n = (wI and 1 or 0) + (wT and 1 or 0) + (wS and 1 or 0)
        if n >= 2 then
            logFloorOpened(d, wI, wT, wS)
        else
            if wI then
                logWhenReady(d, scanItemNames, "items", function() return boolVal("FloorActive") end,
                    function(txt) return "the items available on this floor are:\n```" .. txt .. ".```" end)
            end
            if wT then
                logWhenReady(d, scanTwistedNames, "twisteds", function() return boolVal("FloorActive") end,
                    function(txt) return "the twisteds available on this floor are:\n```" .. txt .. ".```" end)
            end
        end
    end

    local last = {
        floor = nil, floorAt = tick(), active = false, store = false,
        req = nil, comp = nil, statusAt = nil, statusSkip = false,
        hum = nil, hearts = nil, maxHp = nil,
        blackout = false,
        farmOn = false, farmSince = nil, farmAcc = 0,
        deathHum = nil, deathFired = false,
    }

    local function onDeath(h)
        if last.deathFired or last.deathHum ~= h then return end
        last.deathFired = true
        local now = tick()
        local total = last.farmAcc + (last.farmSince and (now - last.farmSince) or 0)
        last.farmAcc = 0
        if last.farmSince then last.farmSince = now end
        local server = workspace.DistributedGameTime
        local function stat(name)
            local v = 0
            pcall(function()
                local i  = workspace:FindFirstChild("Info")
                local ps = i and i:FindFirstChild("PlayerStats")
                local me = ps and ps:FindFirstChild(plr.Name)
                local sv = me and me:FindFirstChild(name)
                if sv and (sv:IsA("NumberValue") or sv:IsA("IntValue")) then v = math.floor(sv.Value + 0.5) end
            end)
            return v
        end
        local function plural(n, one, many) return (n == 1) and one or many end
        local tapes, twisteds, items = stat("SurvivalPoints"), stat("Monsters"), stat("Items")
        local gens, ichor, pumpkins  = stat("Generators"), stat("Ichor"), stat("HolidayCollectibleItem")
        local rows = {
            string.format("you had **%d** %s when you died.", tapes, plural(tapes, "tape", "tapes")),
            string.format("you encountered **%d** %s when you died.", twisteds, plural(twisteds, "twisted", "twisteds")),
            string.format("you picked up **%d** %s when you died.", items, plural(items, "item", "items")),
            string.format("you completed **%d** %s when you died.", gens, plural(gens, "generator", "generators")),
            string.format("you collected **%d** ichor when you died.", ichor),
            string.format("you collected **%d** %s when you died.", pumpkins, plural(pumpkins, "pumpkin", "pumpkins")),
        }
        local idx = {}
        for i = 1, #rows do idx[i] = i end
        table.sort(idx, function(a, b)
            local la, lb = #rows[a], #rows[b]
            if la ~= lb then return la > lb end
            return a < b
        end)
        local sorted = {}
        for _, i in ipairs(idx) do sorted[#sorted + 1] = rows[i] end
        local floorNum = numVal("Floor") or "?"
        emit("death", function(d)
            return {
                content = string.format("**%s** has Died in floor **%s**!", d.name(), tostring(floorNum)),
                desc = string.format("Autofarm has been running for `%s`.\nServer has been running for `%s`.\n\n%s",
                    fmtTime(total), fmtTime(server), table.concat(sorted, "\n")),
            }
        end)
    end

    regSpawn(function()
        if isR then return end
        while true do
            task.wait(0.2)

            local fl = numVal("Floor")
            if fl ~= nil then
                if last.floor ~= nil and fl ~= last.floor then
                    local took = tick() - last.floorAt
                    last.floorAt = tick()
                    emit("floor", function(d)
                        return { plain = true, desc = string.format("**%s** has reached floor **%d** in **%s**.",
                            d.name(), fl, fmtTime(took)) }
                    end)
                elseif last.floor == nil then
                    last.floorAt = tick()
                end
                last.floor = fl
            end

            local active = boolVal("FloorActive")
            if active and not last.active then
                for _, d in ipairs(dests) do
                    if d.ready() then onFloorOpen(d) end
                end
            end
            last.active = active

            local bo = (active and boolVal("BlackOut")) and true or false
            if bo and not last.blackout then
                local floorNum = numVal("Floor") or "?"
                emit("blackout", function(d)
                    if d.id == "nf" then
                        return { plain = true, desc = string.format("A blackout happened in this Floor. **%s**", tostring(floorNum)) }
                    end
                    return { plain = true, desc = string.format("A blackout happened in **%s**'s Floor. **%s**", d.name(), tostring(floorNum)) }
                end)
            end
            last.blackout = bo

            local farm = S.autoEnabled == true
            if farm and not last.farmOn then
                last.farmSince = tick()
            elseif (not farm) and last.farmOn and last.farmSince then
                last.farmAcc = last.farmAcc + (tick() - last.farmSince)
                last.farmSince = nil
            end
            last.farmOn = farm

            local store = boolVal("DandyStoreOpen")
            if store and not last.store then
                for _, d in ipairs(dests) do
                    if d.flags.shop and d.ready() then
                        logWhenReady(d, scanShopNames, "shop", function() return boolVal("DandyStoreOpen") end,
                            function(txt) return "the items on dandy's shop are:\n```" .. txt .. ".```" end)
                    end
                end
            end
            last.store = store

            local req, comp = numVal("RequiredGenerators"), numVal("GeneratorsCompleted")
            if req ~= nil and comp ~= nil then
                if last.req ~= nil and (req ~= last.req or comp ~= last.comp) then
                    if req < last.req then last.statusSkip = true end
                    last.statusAt = tick()
                end
                last.req, last.comp = req, comp
            end
            if last.statusAt and tick() - last.statusAt >= 0.4 then
                local skip = last.statusSkip
                last.statusAt, last.statusSkip = nil, false
                if not skip and active and req and comp then
                    emit("status", function(d)
                        return { plain = true, desc = string.format("**%s** has `%d/%d` machines completed in this floor.",
                            d.name(), comp, req) }
                    end)
                end
            end

            local char = plr.Character
            local hum  = char and char:FindFirstChildWhichIsA("Humanoid")
            if hum then
                local hearts = math.floor(hum.Health + 0.5)
                local maxHp  = math.floor(hum.MaxHealth + 0.5)
                if hum ~= last.hum or maxHp ~= last.maxHp then
                    last.hum, last.maxHp, last.hearts = hum, maxHp, hearts
                elseif hearts ~= last.hearts then
                    local diff = hearts - last.hearts
                    last.hearts = hearts
                    emit("health", function(d)
                        local amt = math.abs(diff)
                        local what = (amt == 1) and "a heart" or (amt .. " hearts")
                        return { plain = true, desc = string.format("**%s** has %s %s!\nremaining heart(s) are `%d/%d`",
                            d.name(), diff < 0 and "lost" or "gained", what, hearts, maxHp) }
                    end)
                end
                if last.deathHum ~= hum then
                    last.deathHum = hum
                    last.deathFired = hum.Health <= 0
                    pcall(function() hum.Died:Connect(function() onDeath(hum) end) end)
                end
                if hum.Health <= 0 then onDeath(hum) else last.deathFired = false end
            else
                last.hum = nil
            end
        end
    end)

    ui.whSnapshot = function()
        local t = { anon = WH.anon, wh = {}, nf = {} }
        for k, v in pairs(FLAGS.wh) do t.wh[k] = v end
        for k, v in pairs(FLAGS.nf) do t.nf[k] = v end
        return t
    end
    ui.whApply = function(t)
        if type(t) ~= "table" then return end
        if t.anon ~= nil then anonTog.SetState(t.anon == true) end
        for _, dest in ipairs({ "wh", "nf" }) do
            if type(t[dest]) == "table" then
                for key, api in pairs(refs[dest]) do
                    if t[dest][key] ~= nil then api.SetState(t[dest][key] == true) end
                end
            end
        end
    end
end)()
