        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if hrp then
            local function ppPos(p)
                local pa = p.Parent
                if not pa then return nil end
                if pa:IsA("Attachment") then return pa.WorldPosition end
                if pa:IsA("BasePart") then return pa.Position end
                if pa:IsA("Model") then return pa:GetPivot().Position end
                return nil
            end
            local best, bestD = nil, math.huge
            for _, p in ipairs(prompts) do
                if p and p.Parent and p.Enabled then
                    local pos = ppPos(p)
                    if pos then
                        local d = (pos - hrp.Position).Magnitude
                        if d < bestD then best, bestD = p, d end
                    end
                end
            end
            if best then fireOnePrompt(best); return end
        end
    end
    for _, p in ipairs(prompts) do
        if p and p.Parent and p.Enabled then
            fireOnePrompt(p)
            return
        end
    end
    for _, p in ipairs(prompts) do
        if p and p.Parent then
            fireOnePrompt(p)
            return
        end
    end
