function watchGenStats(gen)
    if not gen or not gen.Parent then return end
    if cn.statsWatched[gen] then return end
    cn.statsWatched[gen] = true
    local conns = {}
    cn.statsConns[gen] = conns
    local lastRefresh = 0
    local refreshPending = false
    local function refresh()
        local now = tick()
        if (now - lastRefresh) < 0.02 then
            if not refreshPending then
                refreshPending = true
                task.defer(function()
                    refreshGenStats(gen)
                    lastRefresh = tick()
                    refreshPending = false
                end)
            end
            return
        end
        refreshGenStats(gen)
        lastRefresh = now
    end
    local st = gen:FindFirstChild("Stats")
    if st then
        local cur  = st:FindFirstChild("CurrentAmount")
        local req  = st:FindFirstChild("RequiredAmount")
        local comp = st:FindFirstChild("Completed")
        if cur  then conns[#conns+1] = cur.Changed:Connect(refresh)  end
        if req  then conns[#conns+1] = req.Changed:Connect(refresh)  end
        if comp then conns[#conns+1] = comp.Changed:Connect(refresh) end
        conns[#conns+1] = st.ChildAdded:Connect(function(child)
            if child.Name == "CurrentAmount" or child.Name == "RequiredAmount"
                or child.Name == "Completed" then
                conns[#conns+1] = child.Changed:Connect(refresh)
