            conns[#conns+1] = child.Changed:Connect(function() onConnieChanged(child) end)
            onConnieChanged(child)
        end
        InvalidateGenPPCache(gen)
        cn.baseMachinePartCache[gen] = nil
    end)
    conns[#conns+1] = gen.AncestryChanged:Connect(function()
        if not gen.Parent then
            cn.connieCache[gen]            = nil
            cn.watchedGens[gen]      = nil
            cn.baseMachinePartCache[gen] = nil
            InvalidateGenPPCache(gen)
            local c = cn.watchConns[gen]
            if c then
                for _, conn in ipairs(c) do pcall(function() conn:Disconnect() end) end
            end
            cn.watchConns[gen] = nil
        end
    end)
    cn.connieCache[gen] = isConnieTrue(gen)
end
function teardownConnieWatchers()
