end
local setupRazzleAttributeWatch
do
local razzleUnsafeGens       = setmetatable({}, { mode = "k" })
local razzleBalls        = setmetatable({}, { mode = "k" })
local razzleGensFlagged  = setmetatable({}, { mode = "k" })
local razzleAwakeConns   = setmetatable({}, { mode = "k" })
local razzleUpdateConns  = setmetatable({}, { mode = "k" })
local razzleBallRadius   = 60
S.razzleRadius = razzleBallRadius
local razzleBallRadiusSq = razzleBallRadius * razzleBallRadius
local razzleUpdateInterval = 0.5
function destroyRazzleBall(model)
    local b = razzleBalls[model]
    if b then pcall(function() b:Destroy() end); razzleBalls[model] = nil end
end
function clearRazzleGenFlags()
    for gen in pairs(razzleGensFlagged) do
        S.genUnsafeByTendril[gen] = nil
        razzleGensFlagged[gen] = nil
    end
end
function updateRazzleGenFlags(razzlePos)
    for gen in pairs(razzleGensFlagged) do
        S.genUnsafeByTendril[gen] = nil
        razzleGensFlagged[gen] = nil
    end
    local currentRoom = workspace:FindFirstChild("CurrentRoom")
    if not currentRoom then return end
    for _, roomModel in ipairs(currentRoom:GetChildren()) do
        if not roomModel:IsA("Model") then continue end
        local gf = roomModel:FindFirstChild("Generators")
        if not gf then continue end
        for _, gen in ipairs(gf:GetChildren()) do
            if not gen:IsA("Model") then continue end
            local ok, pivot = pcall(function() return gen:GetPivot().Position end)
            if not ok then continue end
            local d = pivot - razzlePos
            if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= razzleBallRadiusSq then
                S.genUnsafeByTendril[gen] = true
                razzleGensFlagged[gen]   = true
            end
        end
    end
end
setupRazzleAttributeWatch = function(model)
    if razzleAwakeConns[model] then return end
    local function onAwakeChanged()
        local awake = model:GetAttribute("Awake")
        if awake == true then
            local prim = model.PrimaryPart or model:FindFirstChild("HumanoidRootPart")
                      or model:FindFirstChildWhichIsA("BasePart", true)
            if not prim then return end
            if not (razzleBalls[model] and razzleBalls[model].Parent) then
                destroyRazzleBall(model)
                local b = Instance.new("Part")
                b.Name         = "RazzleDazzleAwakeBall"
                b.Shape        = Enum.PartType.Ball
                local d = razzleBallRadius * 2
                b.Size         = Vector3.new(d, d, d)
                b.Material     = Enum.Material.ForceField
                b.Anchored     = false
                b.Massless     = true
                b.CanCollide   = false
                b.CastShadow   = false
                b.Color        = Color3.fromRGB(255, 50, 200)
                b.Transparency = 1
                b.CFrame       = prim.CFrame
                b.Parent       = R.vf or workspace
                local weld = Instance.new("WeldConstraint")
                weld.Part0  = b
                weld.Part1  = prim
                weld.Parent = b
                razzleBalls[model] = b
            end
            updateRazzleGenFlags(prim.Position)
            if razzleUpdateConns[model] then return end
            razzleUpdateConns[model] = true
            regSpawn(function()
                while razzleUpdateConns[model] do
                    task.wait(razzleUpdateInterval)
                    if not model.Parent then break end
                    local awakeNow = model:GetAttribute("Awake")
                    if awakeNow ~= true then break end
                    local p2 = model.PrimaryPart or model:FindFirstChild("HumanoidRootPart")
                           or model:FindFirstChildWhichIsA("BasePart", true)
                    if not p2 or not p2.Parent then break end
                    updateRazzleGenFlags(p2.Position)
                end
                razzleUpdateConns[model] = nil
                destroyRazzleBall(model)
                clearRazzleGenFlags()
            end)
        else
            razzleUpdateConns[model] = nil
            destroyRazzleBall(model)
            clearRazzleGenFlags()
        end
    end
    local conn = model:GetAttributeChangedSignal("Awake"):Connect(onAwakeChanged)
    razzleAwakeConns[model] = conn
    model.AncestryChanged:Connect(function()
        if not model.Parent then
            local c = razzleAwakeConns[model]
            if c then pcall(function() c:Disconnect() end) end
            razzleAwakeConns[model] = nil
            razzleUpdateConns[model] = nil
            destroyRazzleBall(model)
            clearRazzleGenFlags()
        end
    end)
    onAwakeChanged()
end
end
do
local p1IsGenSafe = R.igs
function IsGenSafeEx(gen)
    if S.genUnsafeByTendril and S.genUnsafeByTendril[gen] then return false end
    local genPos = gen and gen.Parent and gen:GetPivot().Position
    if genPos then
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        local excl = {}
        for _, plr in ipairs(Plrs:GetPlayers()) do
            if plr.Character then excl[#excl+1] = plr.Character end
        end
        excl[#excl+1] = R.vf
        local currentRoom = workspace:FindFirstChild("CurrentRoom")
        if currentRoom then
            for _, rm in ipairs(currentRoom:GetChildren()) do
                local mf = rm:FindFirstChild("Monsters")
                if mf then excl[#excl+1] = mf end
            end
        end
        rayParams.FilterDescendantsInstances = excl
        if currentRoom then
            for _, roomModel in ipairs(currentRoom:GetChildren()) do
                if not roomModel:IsA("Model") then continue end
                local mf = roomModel:FindFirstChild("Monsters")
                if not mf then continue end
                for _, obj in ipairs(mf:GetChildren()) do
                    if not obj:IsA("Model") then continue end
                    local cfg = R.mons[obj.Name]
                    if not cfg or cfg.isGrab or cfg.farmIgnore then continue end
                    local prim = obj.PrimaryPart or obj:FindFirstChild("HumanoidRootPart")
                    if not prim then continue end
                    local dir = genPos - prim.Position
                    local dist = dir.Magnitude
                    if dist > (cfg.detRadius or 50) + 10 then continue end
                    local result = workspace:Raycast(prim.Position, dir, rayParams)
                    if not result then return false end
                end
            end
        end
    end
    return p1IsGenSafe(gen)
end
R.igs = IsGenSafeEx
end
function IsGenSafeFromBalls(gen)
