S.puCapped = false
function S.pickupFloorBlocked(forCollect)
    local fa = R.gfv()
    if not (fa and fa:IsA("BoolValue") and fa.Value == true) then return false end
    if S.isDyleFloor() then return true end
    if not forCollect and not S.pathfindMode and IsPanicActive() and (S.puPanicUsed or 0) >= (S.PICKUP_PANIC_WINDOW or 5) then
        return true
    end
    if S.puCapped then
        if S.pathfindMode then return false end
        if IsPanicActive() then
            if forCollect then
                local c = S.autoTrig and S.autoTrig.collect
                return not (c and (c.always or c.panic))
            end
            return (S.puPanicUsed or 0) >= (S.PICKUP_PANIC_WINDOW or 5)
        end
        return true
    end
    return false
end
S.PICKUP_SH_WINDOW    = 5
S.PICKUP_PANIC_WINDOW = 5
S.puUsed, S.puPanicUsed, S.panicStartT = 0, 0, nil
regSpawn(function()
    if R.isR then return end
    local PICKUP_WINDOW = 30
    local t0, lastStart, prevT, prevPanic = nil, nil, tick(), false
    while true do
        task.wait(0.25)
        local now = tick()
        local dt  = now - prevT
        prevT = now
        local fa = R.gfv()
        local floorOn = fa and fa:IsA("BoolValue") and fa.Value == true
        if not floorOn then
            t0 = nil; S.puCapped = false; lastStart = nil
            S.puUsed, S.puPanicUsed, S.panicStartT, prevPanic = 0, 0, nil, false
        else
            if S.floorStartT ~= lastStart then
                lastStart = S.floorStartT; t0 = now; S.puCapped = false
                S.puUsed, S.puPanicUsed, S.panicStartT, prevPanic = 0, 0, nil, false
            end
            t0 = t0 or now
            local panicNow = IsPanicActive()
            if panicNow and not prevPanic then S.puPanicUsed = 0; S.panicStartT = now end
            if not panicNow then S.panicStartT = nil end
            prevPanic = panicNow
            if S.pickingUp and not S.totBusy and not S.collectBusy then
                if panicNow then S.puPanicUsed = S.puPanicUsed + dt else S.puUsed = S.puUsed + dt end
            end
            if S.safeHide then
                S.puCapped = S.puUsed >= S.PICKUP_SH_WINDOW
            else
                S.puCapped = (now - t0 >= PICKUP_WINDOW)
            end
        end
    end
end)
S.genAvoid = setmetatable({}, { __mode = "k" })
S.GEN_STUCK_T, S.GEN_STUCK_R, S.GEN_AVOID_T = 8, 30, 20
S.regGame(function()
