            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if not (S.autoEnabled and hrp and hum and hum.Health > 0) then nearSince, lastNear = nil, nil; return end
            for ag, until0 in pairs(S.genAvoid) do
