function S.rollingPumpkins()
    if R.isR then return {} end
    local now = tick()
    if S._rpT and now - S._rpT < 0.2 then return S._rpList or {} end
    S._rpT = now
    local list = {}
    if not S._rpConn then
        S._rpConn = true
        S._rpExtra = {}
        regC(workspace.DescendantAdded, function(d)
            local l = string.lower(d.Name)
            if (l == "rollingpumpkin" or (string.find(l, "rolling", 1, true) and string.find(l, "pumpkin", 1, true)))
               and (d:IsA("Model") or d:IsA("BasePart")) then S._rpExtra[d] = true end
        end)
    end
    local function add(c)
        local part
        if c:IsA("BasePart") then part = c
        elseif c:IsA("Model") then part = c.PrimaryPart or c:FindFirstChildWhichIsA("BasePart", true) end
        if part and part.Parent then
            local v = part.AssemblyLinearVelocity
            local vel = Vector3.new(v.X, 0, v.Z)
            S._rpPrev = S._rpPrev or setmetatable({}, { __mode = "k" })
            local pv = S._rpPrev[c]
            local pos = part.Position
            if pv and now - pv.t > 0.05 then
                local mv = Vector3.new(pos.X - pv.pos.X, 0, pos.Z - pv.pos.Z) / (now - pv.t)
                if mv.Magnitude > vel.Magnitude then vel = mv end
            end
            if not pv or now - pv.t > 0.05 then S._rpPrev[c] = { pos = pos, t = now } end
            list[#list + 1] = { pos = pos, vel = vel, obj = c }
        end
    end
    local deep = (not S._rpDeepT) or now - S._rpDeepT > 1.5
    if deep then S._rpDeepT = now; S._rpDeep = {} end
    local room = workspace:FindFirstChild("CurrentRoom")
    if room then
        for _, rm in ipairs(room:GetChildren()) do
            local tot = rm:FindFirstChild("TrickOrTreatDoors") or rm:FindFirstChild("TrickOrTreatDoor")
            for _, folder in ipairs(tot and { tot, rm } or { rm }) do
                for _, c in ipairs(folder:GetChildren()) do
                    local cl = string.lower(c.Name)
                    if cl == "rollingpumpkin" or (string.find(cl, "rolling", 1, true) and string.find(cl, "pumpkin", 1, true)) then add(c) end
                end
            end
            if tot and deep then
                for _, d in ipairs(tot:GetDescendants()) do
                    local dl = string.lower(d.Name)
                    if (dl == "rollingpumpkin" or (string.find(dl, "rolling", 1, true) and string.find(dl, "pumpkin", 1, true)))
                       and (d:IsA("Model") or d:IsA("BasePart")) then
                        S._rpDeep[#S._rpDeep + 1] = d
                    end
                end
            end
        end
    end
    local seen = {}
    for _, e in ipairs(list) do seen[e.obj] = true end
    for _, d in ipairs(S._rpDeep or {}) do
        if d.Parent and not seen[d] then seen[d] = true; add(d) end
    end
    for d in pairs(S._rpExtra or {}) do
        if not d.Parent then S._rpExtra[d] = nil
        elseif not seen[d] then seen[d] = true; add(d) end
    end
    S._rpList = list
    return list
end
function S.pumpkinNear(pos, range)
    local l = S.rollingPumpkins()
    for i = 1, #l do
        local d = l[i].pos - pos
        if d.X * d.X + d.Z * d.Z <= range * range and math.abs(d.Y) < 40 then return true, l[i] end
    end
    return false
end

function S.pumpkinThreat(pos, range)
    range = S.pumpkinRadius or range or 45
    local l = S.rollingPumpkins()
    for i = 1, #l do
        local e = l[i]
        local rx, rz = e.pos.X - pos.X, e.pos.Z - pos.Z
        local dist = math.sqrt(rx * rx + rz * rz)
        if math.abs(e.pos.Y - pos.Y) < 40 then
            if dist <= range then return true, e end
            local vx, vz = e.vel.X, e.vel.Z
            local sp = math.sqrt(vx * vx + vz * vz)
            if sp > 6 and dist < 160 then
                local closing = -(rx * vx + rz * vz) / dist
                if closing > 4 then
                    local ttc  = dist / closing
                    local miss = math.abs(rx * vz - rz * vx) / sp
                    if ttc < 3.0 and miss < 14 then return true, e end
                end
            end
        end
    end
    return false
end

function GetDangerState()
    local count    = gcc()
    local chaseDanger = count >= C.chaseCountThreshold
    local pumpkinDanger = false
    local ch  = plr.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if hrp then
        pumpkinDanger = S.pumpkinThreat(hrp.Position, 45) == true
    end
    return chaseDanger or pumpkinDanger, chaseDanger, count, pumpkinDanger
end
function IsInChaseClearWait()
    return S.chaseWait and (tick() - S.chaseClrT < K.chaseClearWait)
end
function UpdateChaseClearState(currentChase)
    local prev = S.prevChase
    if prev >= C.chaseCountThreshold and currentChase < C.chaseCountThreshold then
        S.chaseClrT    = tick()
        S.chaseWait = true
    end
    if S.chaseWait and (tick() - S.chaseClrT >= K.chaseClearWait) then
        S.chaseWait = false
    end
    S.prevChase = currentChase
end
