function IsTendrilNearGen(genPos)
    local r2 = K.tenGenRsq
    local hasTendril, hasBlot = false, false
    local ten = Cache.tendrilPositions
    for i = 1, #ten do
        local d = ten[i].pos - genPos
        if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= r2 then
            if ten[i].isBlot then hasBlot = true else hasTendril = true end
            if hasTendril and hasBlot then return true, true end
        end
    end
    return hasTendril, hasBlot
