function IsCachedMonsterNearPosition(pos, radius, isDecodeCheck, isFarmCheck)
    if S.pumpkinNear(pos, math.max(radius, 30)) then return true end
    local r2  = radius * radius
    local mon = Cache.monsterPositions
    for i = 1, #mon do
        local entry = mon[i]
        if isDecodeCheck then
            if entry.decodeEligible then
                local r = entry.stopRadius
                local d = entry.pos - pos
                if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= (r*r) then return true end
            end
        elseif isFarmCheck then
            if entry.farmEligible then
                local d = entry.pos - pos
                if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= r2 then return true end
            end
        else
            local d = entry.pos - pos
            if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= r2 then return true end
        end
    end
    return false
end
