do
local twLive = { t = 0, list = {} }
function twRefresh(force)
    local now = tick()
    if not force and now - twLive.t < 0.1 then return twLive.list end
    twLive.t = now
    local list, seen = {}, {}
    local function add(obj, cfg)
        if seen[obj] or not obj.Parent then return end
        seen[obj] = true
        if cfg and cfg.isGrab then return end
        local farmOk = true
        local eggOk  = true
        local stop   = 0
        if cfg then
            farmOk = not cfg.farmIgnore
            eggOk  = not cfg.eggsonIgnore
            stop   = cfg.stopRadius or 0
            if obj.Name == "GourdyMonster" and S.gourdyThreat and not S.gourdyThreat(obj) then farmOk = false end
            if obj.Name == "RazzleDazzleMonster" then farmOk = _G.YattaRZ.razzleThreat(obj); stop = 60 end
            if obj.Name == "RodgerMonster" then farmOk = _G.YattaRZ.rodgerThreat(obj) end
            if obj.Name == "GlistenMonster" then
                if not (obj:GetAttribute("GlistenActivated") == true and obj:GetAttribute("GlistenInitialized") == true) then farmOk = false end
            end
        end
        if not farmOk and not eggOk then return end
        local okb, cf, size = pcall(function() return obj:GetBoundingBox() end)
        if not okb or not cf then
            local okp, piv = pcall(function() return obj:GetPivot() end)
            if not okp then return end
            cf, size = piv, Vector3.zero
        end
        list[#list + 1] = { obj = obj, cf = cf, size = size, farmOk = farmOk, eggOk = eggOk, stop = stop }
    end
    local cr = workspace:FindFirstChild("CurrentRoom")
    if cr then
        for _, rm in ipairs(cr:GetChildren()) do
            local mf = rm:IsA("Model") and rm:FindFirstChild("Monsters")
            if mf then
                for _, obj in ipairs(mf:GetChildren()) do
                    if obj:IsA("Model") and not R.TSet[obj.Name] then
                        local cfg = R.mons[obj.Name]
                        if cfg then add(obj, cfg)
                        elseif R.iumo and R.iumo(obj) then add(obj, nil) end
                    end
                end
            end
        end
    end
    for obj in pairs(S.extraMons) do
        if not obj.Parent then S.extraMons[obj] = nil else add(obj, R.mons[obj.Name]) end
    end
    twLive.list = list
    return list
end
function twDist(e, pos)
    local rel = e.cf:PointToObjectSpace(pos)
    local hx = math.min(e.size.X * 0.5, 12)
    local hy = math.min(e.size.Y * 0.5, 12)
    local hz = math.min(e.size.Z * 0.5, 12)
    local dx = math.max(math.abs(rel.X) - hx, 0)
    local dy = math.max(math.abs(rel.Y) - hy, 0)
    local dz = math.max(math.abs(rel.Z) - hz, 0)
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end
function S.twistedNearGen(pos, radius, forEggson, fresh)
    local list = twRefresh(fresh)
    for i = 1, #list do
        local e = list[i]
        if e.obj.Parent then
            local ok = forEggson and e.eggOk or ((not forEggson) and e.farmOk)
            if ok then
                local reach = forEggson and radius or math.max(radius, e.stop)
                if twDist(e, pos) <= reach then return true, e.obj end
            end
        end
    end
    return false
end
end
function IsCachedMonsterNearGen(genPos, radius, forEggson)
    local r2  = radius * radius
    local mon = Cache.monsterPositions
    for i = 1, #mon do
        local entry = mon[i]
        local eligible = forEggson
            and entry.eggsonEligible
            or  entry.farmEligible
        if eligible then
            local livePos  = entry.livePart and entry.livePart.Parent and entry.livePart.Position
            local checkPos = livePos or entry.pos
            local d = checkPos - genPos
            if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= r2 then return true end
        end
    end
    if S.twistedNearGen and S.twistedNearGen(genPos, radius, forEggson) then return true end
    return false
end
local prevHealth = nil
function WatchSlots()
    local char = plr.Character
    local hum  = char and char:FindFirstChildWhichIsA("Humanoid")
    local currentHealth = hum and hum.Health or nil
    local votingNow = (_G.yattaIsVoting and _G.yattaIsVoting()) or false
    if votingNow then
        S.hitsWasVoting = true
    elseif S.hitsWasVoting then
        S.hitsWasVoting  = false
        S.hitsGraceUntil = tick() + 3
    end
    local hitsGrace = votingNow or (S.hitsGraceUntil and tick() < S.hitsGraceUntil)
    if currentHealth and prevHealth and currentHealth < prevHealth and not hitsGrace then
        S.hitsTakenCount = S.hitsTakenCount + 1
    end
    local igp = workspace:FindFirstChild(_G.YattaIGP)
    local pm  = igp and igp:FindFirstChild(plr.Name)
    if not pm then
        prevHealth = currentHealth
        return
    end
    local inv = pm:FindFirstChild("Inventory") or pm:FindFirstChild("Items")
    if not inv then
        prevHealth = currentHealth
        return
    end
    local last = R.lSI
    local heal = K.healItemNames
    for i = 1, 4 do
        local slot        = inv:FindFirstChild("Slot"..i) or inv:FindFirstChild("Item"..i)
        local currentItem = (slot and slot:IsA("StringValue") and slot.Value) or ""
        local prevItem    = last[i]
        if heal[prevItem] and not heal[currentItem] then
            if currentHealth and prevHealth and currentHealth > prevHealth then
                S.healUsedCount = S.healUsedCount + 1
            else
                S.droppedStolenCount = S.droppedStolenCount + 1
            end
        end
        last[i] = currentItem
    end
    prevHealth = currentHealth
end
