local MainFrame = R.MainFrame
function ClampGUIToScreen()
    local cam = workspace.CurrentCamera
    if not cam then return end
    if not MainFrame then return end
    local vp      = cam.ViewportSize
    local halfW   = R.tw / 2
    local curH    = MainFrame.Size.Y.Offset > 0 and MainFrame.Size.Y.Offset or R.th
    local halfH   = curH / 2
    local curX    = MainFrame.Position.X.Scale * vp.X + MainFrame.Position.X.Offset
    local curY    = MainFrame.Position.Y.Scale * vp.Y + MainFrame.Position.Y.Offset
    local cx      = math.clamp(curX, halfW, vp.X - halfW)
    local cy      = math.clamp(curY, halfH, vp.Y - halfH)
    if cx ~= curX or cy ~= curY then
        MainFrame.Position = UDim2.new(0, cx, 0, cy)
        R.UpdateCreditPos()
    end
end
