local fakeElevFallbackPart = nil
function createFakeElevEmergencyPart()
    if fakeElevFallbackPart and fakeElevFallbackPart.Parent then
        return fakeElevFallbackPart
    end
    do
        local floorVal = R.gfv()
        if not (floorVal and floorVal:IsA("BoolValue") and floorVal.Value == true) then
            return nil
        end
    end
    local hasGen = false
    local currentRoom = workspace:FindFirstChild("CurrentRoom")
    if currentRoom then
        for _, roomModel in ipairs(currentRoom:GetChildren()) do
            if not roomModel:IsA("Model") then continue end
            local gf = roomModel:FindFirstChild("Generators")
            if not gf then continue end
            for _, g in ipairs(gf:GetChildren()) do
                if g:IsA("Model") and
                   (g.Name == "Generator" or g.Name:match("^DualGen_%d+_%d+$") or g.Name:match("^TrickOrTreatGen")) then
                    hasGen = true; break
                end
            end
            if hasGen then break end
        end
    end
    if not hasGen and currentRoom then
        for _, rm in ipairs(currentRoom:GetChildren()) do
            if rm:IsA("Model") and #_G.YattaTotExtra(rm, rm:FindFirstChild("Generators")) > 0 then hasGen = true; break end
        end
    end
    if not hasGen then return nil end
    local roomHeight = 0
    if currentRoom then
        for _, roomModel in ipairs(currentRoom:GetChildren()) do
            if roomModel:IsA("Model") then
                local ok, bb = pcall(function() return roomModel:GetExtentsSize() end)
                if ok and bb then
                    local pivot = roomModel:GetPivot()
                    local topY  = pivot.Position.Y + bb.Y / 2
                    if topY > roomHeight then roomHeight = topY end
                end
            end
        end
    end
    local spawnY = roomHeight + 500
    local roomWidth = 200
    if currentRoom then
        local ok, bb = pcall(function() return currentRoom:GetExtentsSize() end)
        if ok and bb then
            roomWidth = math.max(200, bb.X * 2, bb.Z * 2)
        end
    end
    local ep = Instance.new("Part")
    ep.Name        = "FakeElevEmergencyBase"
    ep.Size        = Vector3.new(roomWidth, 1, roomWidth)
    ep.Position    = Vector3.new(0, spawnY, 0)
    ep.Anchored    = true
    ep.CanCollide  = true
    ep.Transparency = 1
    ep.Material    = Enum.Material.SmoothPlastic
    ep.Parent      = workspace
    fakeElevFallbackPart = ep
    return ep
end
function FindFakeElevatorBasePart()
    local elevs = workspace:FindFirstChild("Elevators")
    if elevs then
        local elev = elevs:FindFirstChild(K.fakeElevMdl)
        if elev then
            local basePart = elev:FindFirstChild(K.elevBase, true)
            if basePart and basePart:IsA("BasePart") then
                if fakeElevFallbackPart then
                    pcall(function() fakeElevFallbackPart:Destroy() end)
                    fakeElevFallbackPart = nil
                end
                pcall(function()
                    basePart.Transparency = 1
                    basePart.CanCollide   = true
                end)
                return basePart
            end
        end
    end
    local elevModel = workspace:FindFirstChild(K.fakeElevMdl)
    if elevModel then
        local innerModel = elevModel:FindFirstChild(K.fakeElevMdl)
        local searchIn   = innerModel or elevModel
        local basePart   = searchIn:FindFirstChild(K.elevBase, true)
        if basePart and basePart:IsA("BasePart") then
            if fakeElevFallbackPart then
                pcall(function() fakeElevFallbackPart:Destroy() end)
