function BuildOrientedCFrame(position, referenceCF, keepPlayerY)
    if referenceCF then
        local look  = referenceCF.LookVector
        local flatX = look.X
        local flatZ = look.Z
        local mag   = math.sqrt(flatX*flatX + flatZ*flatZ)
        if mag > 0.001 then flatX = flatX / mag; flatZ = flatZ / mag
        else flatX = 0; flatZ = 1 end
        local origin = Vector3.new(position.X, position.Y, position.Z)
        local target = origin + Vector3.new(flatX, 0, flatZ)
        return CFrame.lookAt(origin, target)
    else
        return CFrame.new(position)
    end
end
function S.elevFrontCF(base, pos)
    local look
    local model = base and base:FindFirstAncestorOfClass("Model")
    local pp = model and model.PrimaryPart
    if pp then look = pp.CFrame.LookVector
    elseif base then look = (base.CFrame * CFrame.Angles(0, -math.pi / 2, 0)).LookVector end
    local flat = look and Vector3.new(look.X, 0, look.Z) or Vector3.zero
    if flat.Magnitude < 0.001 then flat = Vector3.new(0, 0, 1) else flat = flat.Unit end
    return CFrame.lookAt(pos, pos + flat)
end
function S.anyElevTpOn()
    return S.autoEnabled or S.safeTp or S.autoPanicTp or S.autoEncounter or S.autoStopFloorEnabled
        or S.fireStop or S.pathfindMode or S.eggsonMode or S.pickupEnabled or false
end
function IsInventoryFull()
    local igp = workspace:FindFirstChild(_G.YattaIGP)
    local pm  = igp and igp:FindFirstChild(plr.Name)
    if not pm then return false end
    local inv = pm:FindFirstChild("Inventory") or pm:FindFirstChild("Items")
    if not inv then return false end
    local filled = 0
    for i = 1, 4 do
        local slot = inv:FindFirstChild("Slot"..i) or inv:FindFirstChild("Item"..i)
        local val  = slot and slot:IsA("StringValue") and slot.Value or ""
        if val ~= "" and val ~= "None" then filled += 1 end
    end
    return filled >= 4
end
