local diw = { ref = nil, origCC = nil, disabled = false }
function findDandyInvisWall()
    if diw.ref and diw.ref.Parent then
        return diw.ref
    end
    local ds = workspace:FindFirstChild(K.storeFld)
        or workspace:FindFirstChild("DandyStore")
    if ds then
