function updateDandyInvisWallCollision(shouldDisable)
    if shouldDisable then
        if not diw.disabled then
            local part = findDandyInvisWall()
            if part then
                diw.origCC   = part.CanCollide
                part.CanCollide = false
                diw.disabled = true
            end
        end
    else
        if diw.disabled then
            local part = findDandyInvisWall()
            if part then
                part.CanCollide = (diw.origCC ~= nil) and diw.origCC or true
            end
            diw.disabled = false
            diw.origCC   = nil
        end
    end
