do
local Drag = { dragging=false, dragInput=nil, dragStartPos=nil, frameStartPos=nil, touches={} }
function GetTouchCount()
    local n = 0; for _ in pairs(Drag.touches) do n += 1 end; return n
end
local dragCAS      = game:GetService("ContextActionService")
local dragAction  = "YattaTitleBarDrag"
local dragSinking  = false
function dragApplyMove(input)
    if not Drag.dragging or Drag.dragInput == nil or input ~= Drag.dragInput then return end
    if S.dragLocked then Drag.dragging = false; Drag.dragInput = nil; return end
    local cam = workspace.CurrentCamera
    if not cam then return end
    if not MainFrame then return end
    local vp    = cam.ViewportSize
    local delta = input.Position - Drag.dragStartPos
    local rawX  = Drag.frameStartPos.X.Scale*vp.X + Drag.frameStartPos.X.Offset + delta.X
    local rawY  = Drag.frameStartPos.Y.Scale*vp.Y + Drag.frameStartPos.Y.Offset + delta.Y
    local halfW = R.tw / 2
    local curH  = MainFrame.Size.Y.Offset > 0 and MainFrame.Size.Y.Offset or R.th
    local halfH = curH / 2
    MainFrame.Position = UDim2.new(0, rawX, 0, rawY)
    R.UpdateCreditPos()
end
function dragRelease(input)
    if input.UserInputType == Enum.UserInputType.Touch then Drag.touches[input] = nil end
    if Drag.dragInput == input then
        Drag.dragging  = false
        Drag.dragInput = nil
    end
    if not Drag.dragging and dragSinking then
        dragSinking = false
        pcall(function() dragCAS:UnbindAction(dragAction) end)
    end
end
function dragStartSink()
    if dragSinking then return end
    dragSinking = true
    dragCAS:BindActionAtPriority(
        dragAction,
        function(name, state, input)
            if input ~= Drag.dragInput then
                return Enum.ContextActionResult.Pass
            end
            if state == Enum.UserInputState.Change then
                dragApplyMove(input)
            elseif state == Enum.UserInputState.End then
                dragRelease(input)
            end
            return Enum.ContextActionResult.Sink
        end,
        false,
        2048,
        Enum.UserInputType.Touch
    )
end
R.TitleBar.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then return end
    if input.UserInputType == Enum.UserInputType.Touch then Drag.touches[input] = true end
    if S.dragLocked then return end
    if GetTouchCount() > 1 then Drag.dragging=false; Drag.dragInput=nil; return end
    Drag.dragging      = true
    Drag.dragInput     = input
    Drag.dragStartPos  = input.Position
    Drag.frameStartPos = MainFrame.Position
    if input.UserInputType == Enum.UserInputType.Touch then
        dragStartSink()
    else
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                dragRelease(input)
            end
        end)
    end
end)
R.TitleBar.InputEnded:Connect(function(input)
    dragRelease(input)
end)
regC(R.uis.InputChanged, function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseMovement then return end
    if not Drag.dragging or not Drag.dragInput then return end
    if S.dragLocked then Drag.dragging = false; Drag.dragInput = nil; return end
    local cam = workspace.CurrentCamera
    if not cam then return end
    if not MainFrame then return end
    local vp    = cam.ViewportSize
    local delta = input.Position - Drag.dragStartPos
    local rawX  = Drag.frameStartPos.X.Scale*vp.X + Drag.frameStartPos.X.Offset + delta.X
    local rawY  = Drag.frameStartPos.Y.Scale*vp.Y + Drag.frameStartPos.Y.Offset + delta.Y
    local halfW = R.tw / 2
    local curH  = MainFrame.Size.Y.Offset > 0 and MainFrame.Size.Y.Offset or R.th
    local halfH = curH / 2
    MainFrame.Position = UDim2.new(0, rawX, 0, rawY)
    R.UpdateCreditPos()
end)
regC(R.uis.InputEnded, function(input)
    dragRelease(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 then
        Drag.dragging  = false
        Drag.dragInput = nil
    end
end)
