local ba = {
    m  = R.db,
    t  = R.tb,
    g  = R.gb,
    u  = R.uB,
    mP = Cache.ballLiveParts         or setmetatable({},{mode="k"}),
    gP = Cache.grabBallLiveParts     or setmetatable({},{mode="k"}),
    tP = Cache.tendrilBallLiveParts  or setmetatable({},{mode="k"}),
    uP = Cache.unknownBallLiveParts  or setmetatable({},{mode="k"}),
}
Cache.ballLiveParts        = ba.mP
Cache.grabBallLiveParts    = ba.gP
Cache.tendrilBallLiveParts = ba.tP
Cache.unknownBallLiveParts = ba.uP
local gfx = { white = Color3.fromRGB(255,255,255), folder = R.vf }
function createWorkspaceBall(radius, color)
    local b = Instance.new("Part")
    b.Name         = "YattaBall"
    b.Shape        = Enum.PartType.Ball
    local d = radius * 2
    b.Size         = Vector3.new(d, d, d)
    b.Material     = Enum.Material.ForceField
    b.Anchored     = false
    b.Massless     = true
    b.CanCollide   = false
    b.CastShadow   = false
    b.Color        = color or Color3.fromRGB(0, 255, 255)
    b.Transparency = 1
    b.Parent       = gfx.folder or workspace
    return b
end
function AttachBallToTarget(b, prim)
    b.CFrame = prim.CFrame
    local existingWeld = b:FindFirstChildWhichIsA("WeldConstraint")
    if existingWeld then existingWeld:Destroy() end
    local weld = Instance.new("WeldConstraint")
    weld.Part0  = b
    weld.Part1  = prim
    weld.Parent = b
end
function EnsureMonsterBall(model, prim, radius, color)
    local existing = ba.m[model]
    if existing and existing.Parent then
        if existing.Color ~= color then existing.Color = color end
        local d = radius * 2
        if existing.Size.X ~= d then existing.Size = Vector3.new(d,d,d) end
        if ba.mP[model] ~= prim then AttachBallToTarget(existing, prim) end
        ba.mP[model] = prim
        return existing
    end
    if existing then pcall(function() existing:Destroy() end) end
    local b = createWorkspaceBall(radius, color)
    AttachBallToTarget(b, prim)
    ba.m[model]     = b
