function EnsureGrabBall(model, prim, radius, color)
    local existing = ba.g[model]
    if existing and existing.Parent then
        if ba.gP[model] ~= prim then AttachBallToTarget(existing, prim) end
        ba.gP[model] = prim; return existing
    end
    if existing then pcall(function() existing:Destroy() end) end
    local b = createWorkspaceBall(radius, color)
    AttachBallToTarget(b, prim)
    ba.g[model]     = b
    ba.gP[model]  = prim
    return b
end
function EnsureTendrilBall(model, prim, radius, color)
    if model and model.Name ~= "SproutTendril" then return end
    local existing = ba.t[model]
    if existing and existing.Parent then
        if ba.tP[model] ~= prim then AttachBallToTarget(existing, prim) end
        ba.tP[model] = prim; return existing
    end
    if existing then pcall(function() existing:Destroy() end) end
    local b = createWorkspaceBall(radius, color)
    AttachBallToTarget(b, prim)
    ba.t[model]     = b
    ba.tP[model]  = prim
    return b
end
function EnsureUnknownBall(model, prim)
    local existing = ba.u[model]
