end
function RemoveBall(tbl, partTbl, model)
    local b = tbl[model]
    if b then pcall(function() b:Destroy() end); tbl[model] = nil end
    if partTbl then partTbl[model] = nil end
end
local bhb = { conn = nil, lastTick = 0, interval = 1/10 }
do
function StartBallHeartbeat()
    if bhb.conn then return end
    bhb.conn = regC(rs.Heartbeat, function()
        local now = tick()
        if (now - bhb.lastTick) < bhb.interval then return end
        bhb.lastTick = now
        for model, prim in pairs(ba.mP) do
            local b = ba.m[model]
            if not (b and b.Parent and prim and prim.Parent) then
                ba.mP[model] = nil
            end
        end
        for model, prim in pairs(ba.gP) do
            local b = ba.g[model]
            if not (b and b.Parent and prim and prim.Parent) then
                ba.gP[model] = nil
            end
        end
        for model, prim in pairs(ba.tP) do
            local b = ba.t[model]
            if not (b and b.Parent and prim and prim.Parent) then
                ba.tP[model] = nil
            end
        end
        for model, prim in pairs(ba.uP) do
            local b = ba.u[model]
            if not (b and b.Parent and prim and prim.Parent) then
                ba.uP[model] = nil
            end
        end
    end)
end
StartBallHeartbeat()
end
