local hLKey = { monster = {}, tendril = {}, unknown = {} }
local rb = { hue = 0, hls = setmetatable({}, {mode="k"}), balls = setmetatable({}, {mode="k"}) }
local pl = { t = 0, hls = setmetatable({}, {mode="k"}), balls = setmetatable({}, {mode="k"}) }
local pm = { t = 0, hls = setmetatable({}, {mode="k"}), balls = setmetatable({}, {mode="k"}) }
function getMonsterBallColor(cfg)
    local cat = cfg and cfg.espCategory
    if cat == "lethal" then
        return Color3.fromRGB(80, 0, 0)
    elseif cat == "main" then
        return Color3.fromRGB(200, 30, 0)
    elseif cat == "grabber" then
        return Color3.fromRGB(230, 100, 0)
    elseif cat == "event" then
        return Color3.fromRGB(255, 0, 220)
    elseif cat == "ignored" then
        return Color3.fromRGB(130, 130, 130)
    else
        return Color3.fromRGB(220, 50, 50)
    end
end
function getMonsterFillColor(cfg, isDanger)
    if isDanger then return Color3.fromRGB(255, 60, 60) end
    local cat = cfg and cfg.espCategory
    if cat == "lethal"  then return Color3.fromRGB(80, 0, 0)    end
    if cat == "main"    then return Color3.fromRGB(200, 30, 0)   end
    if cat == "grabber" then return Color3.fromRGB(230, 100, 0)  end
    if cat == "event"   then return Color3.fromRGB(255, 0, 220) end
    if cat == "ignored" then return Color3.fromRGB(110, 110, 110) end
    return Color3.fromRGB(200, 50, 50)
end
function ApplyMonsterHighlight(model, cfg, isDanger)
    local cat = cfg and cfg.espCategory
    local isEvent   = cfg and cfg.isEvent
    local isLethal  = (cat == "lethal")
    local isMain    = (cat == "main")
    if cfg and cfg.farmIgnore and not isDanger then
        local fillC = Color3.fromRGB(110, 110, 110)
        local key   = "ignored"
        local hl    = R.esph.monsters[model]
        if hl and hl.Parent and hLKey.monster[model] == key then return end
        hLKey.monster[model] = key
        R.eh("monsters", model, fillC, gfx.white, 0.5,
            Enum.HighlightDepthMode.AlwaysOnTop)
        local newHl = R.esph.monsters[model]
        if newHl then
            local hlEnabled = P.hle
            if hlEnabled and hlEnabled["monsters"] == false then
                pcall(function() newHl.Enabled = false end)
            end
            rb.hls[model] = nil
            pl.hls[model] = nil
            pm.hls[model] = nil
        end
        return
    end
    local fillC = getMonsterFillColor(cfg, isDanger)
    local key = tostring(cat) .. tostring(isDanger)
    local hl  = R.esph.monsters[model]
    if isEvent then
        if not hl or not hl.Parent then
            R.eh("monsters", model, fillC, gfx.white, 0.35,
                Enum.HighlightDepthMode.AlwaysOnTop)
        end
        local newHl = R.esph.monsters[model]
        if newHl then
            rb.hls[model] = newHl
            pl.hls[model] = nil
            pm.hls[model] = nil
            local hlEnabled = P.hle
            if hlEnabled and hlEnabled["monsters"] == false then
                pcall(function() newHl.Enabled = false end)
            end
        end
    elseif isLethal then
        if not hl or not hl.Parent then
            R.eh("monsters", model, fillC, Color3.fromRGB(100, 0, 0), 0.3,
                Enum.HighlightDepthMode.AlwaysOnTop)
        end
        local newHl = R.esph.monsters[model]
        if newHl then
            pl.hls[model] = newHl
            rb.hls[model] = nil
            pm.hls[model] = nil
            local hlEnabled = P.hle
            if hlEnabled and hlEnabled["monsters"] == false then
                pcall(function() newHl.Enabled = false end)
            end
        end
    elseif isMain then
        if not hl or not hl.Parent then
            R.eh("monsters", model, fillC, Color3.fromRGB(255, 80, 0), 0.35,
                Enum.HighlightDepthMode.AlwaysOnTop)
        end
        local newHl = R.esph.monsters[model]
        if newHl then
            pm.hls[model] = newHl
            rb.hls[model] = nil
            pl.hls[model] = nil
            local hlEnabled = P.hle
            if hlEnabled and hlEnabled["monsters"] == false then
                pcall(function() newHl.Enabled = false end)
            end
        end
    else
        if hl and hl.Parent and hLKey.monster[model] == key then return end
        hLKey.monster[model] = key
        R.eh("monsters", model, fillC, gfx.white, 0.4,
            Enum.HighlightDepthMode.AlwaysOnTop)
        local newHl = R.esph.monsters[model]
        if newHl then
            local hlEnabled = P.hle
            if hlEnabled and hlEnabled["monsters"] == false then
                pcall(function() newHl.Enabled = false end)
            end
            rb.hls[model] = nil
            pl.hls[model] = nil
            pm.hls[model] = nil
        end
    end
end
function ApplyTendrilHighlight(model)
    if R.isR then return end
    if model.Name ~= "SproutTendril" then return end
    local fillC  = Color3.fromRGB(150, 0, 255)
    local eKey   = "tendrils"
    local key    = tostring(fillC)
    local hl = R.esph[eKey][model]
    if hl and hl.Parent and hLKey.tendril[model] == key then return end
    if hl and hl.Parent and hLKey.tendril[model] == nil then
        hLKey.tendril[model] = key
        return
    end
    hLKey.tendril[model] = key
    R.eh(eKey, model, fillC, gfx.white, 0.4,
        Enum.HighlightDepthMode.AlwaysOnTop)
    local newHl = R.esph[eKey][model]
    if newHl then
        local hlEnabled = P.hle
        if hlEnabled and hlEnabled[eKey] == false then
            pcall(function() newHl.Enabled = false end)
        end
    end
end
function ApplyUnknownHighlight(model)
    local hl = R.esph.unknownMonsters[model]
    if hl and hl.Parent and hLKey.unknown[model] then return end
    hLKey.unknown[model] = true
    R.eh("unknownMonsters", model,
        Color3.fromRGB(255, 140, 0), gfx.white, 0.4,
        Enum.HighlightDepthMode.AlwaysOnTop)
    local newHl = R.esph.unknownMonsters[model]
    if newHl then
        local hlEnabled = P.hle
        if hlEnabled and hlEnabled["unknownMonsters"] == false then
            pcall(function() newHl.Enabled = false end)
        end
    end
end
function ApplyGenHighlight(model)
    if not R.espe.generators then return end
    local _, _, completed = GetCachedGenStats(model)
    local connie    = IsConnieGen(model)
    local isDual    = model.Name:match("^DualGen_%d+_%d+$") ~= nil
    local isTot     = model.Name:match("^TrickOrTreatGen") ~= nil
    local fillC
    if connie then        fillC = Color3.fromRGB(255, 80,  0)
    elseif completed then fillC = Color3.fromRGB(0,   255, 80)
    elseif isTot then     fillC = Color3.fromRGB(255, 140, 0)
    elseif isDual then    fillC = Color3.fromRGB(255, 200, 0)
    else                  fillC = Color3.fromRGB(0,   180, 255) end
    local colorKey = tostring(fillC)
    if Cache.genESPColorKey[model] == colorKey then
        local hl = R.esph.generators[model]
        if hl and hl.Parent then return end
    end
    Cache.genESPColorKey[model] = colorKey
    R.eh("generators", model, fillC, gfx.white, 0.45,
        Enum.HighlightDepthMode.AlwaysOnTop)
    local newHl = R.esph.generators[model]
    if newHl then
        local hlEnabled = P.hle
        if (hlEnabled and hlEnabled["generators"] == false)
            or (completed and S.espHideDone and S.espHideDone.generators) then
            pcall(function() newHl.Enabled = false end)
        end
    end
end
regSpawn(function()
    if R.isR then return end
