do
local avTriggerY    = -9
local avTwistedR    = 45
local avFront       = 0
local avCooldown    = 1.5
local avBrakeHold   = 0.15
local avLastSafePos = nil
local avBusy        = false
local avLastRun     = 0
local avBrake, avAtt = nil, nil

function avStopBrake()
    if avBrake then pcall(function() avBrake:Destroy() end); avBrake = nil end
    if avAtt   then pcall(function() avAtt:Destroy()   end); avAtt   = nil end
end

function avStartBrake(hrp)
    avStopBrake()
    local att = Instance.new("Attachment")
    att.Name   = "YattaAVAttachment"
    att.Parent = hrp
    local lv = Instance.new("LinearVelocity")
    lv.Name                    = "YattaAVBrake"
    lv.Attachment0             = att
    lv.RelativeTo              = Enum.ActuatorRelativeTo.World
    lv.VelocityConstraintMode  = Enum.VelocityConstraintMode.Vector
    lv.VectorVelocity          = Vector3.new(0, 0, 0)
    lv.MaxForce                = math.huge
    lv.Parent                  = hrp
    avBrake, avAtt = lv, att
end

function avPickBase()
    local mainBase = FindElevatorBasePart()
    if mainBase and mainBase.Parent
       and not IsCachedMonsterNearPosition(mainBase.Position, avTwistedR, false, true) then
        return mainBase
    end
    local okF, fakeBase = pcall(FindFakeElevatorBasePart)
    if okF and fakeBase and fakeBase.Parent then return fakeBase end
    return mainBase
end

function avLanding(base)
    local look = base.CFrame.LookVector
    local flat = Vector3.new(look.X, 0, look.Z)
    if flat.Magnitude > 0.001 then flat = flat.Unit else flat = Vector3.new(0, 0, 1) end
    local pos = base.Position + flat * avFront + Vector3.new(0, C.teleportHeight, 0)
    return BuildOrientedCFrame(pos, base.CFrame)
end

function avRescue(hrp)
    avBusy    = true
    avLastRun = tick()
    avStartBrake(hrp)
    task.wait()
    local char = plr.Character
    local hrp2 = char and char:FindFirstChild("HumanoidRootPart")
    if hrp2 then
        local cf = nil
        local base = avPickBase()
        if base and base.Parent then
            cf = avLanding(base)
        elseif avLastSafePos then
            cf = CFrame.new(avLastSafePos + Vector3.new(0, 5, 0))
        end
        if cf then
            pcall(function()
                WaitForSafeHideRelease()
                hrp2.AssemblyLinearVelocity  = Vector3.new(0, 0, 0)
                hrp2.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                hrp2.CFrame = cf
            end)
        end
    end
    task.wait(avBrakeHold)
    avStopBrake()
    avBusy = false
end

table.insert(_G.YattaConnections, rs.Heartbeat:Connect(function()
    if not S.antiVoid or R.isR then
        if avBrake and not avBusy then avStopBrake() end
        return
    end
    local char = plr.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then return end
    local pos = hrp.Position
    if pos.Y > avTriggerY + 15 then avLastSafePos = pos end
    if avBusy or S.shActive then return end
    if pos.Y <= avTriggerY and (tick() - avLastRun) > avCooldown then
        task.spawn(avRescue, hrp)
    end
end))
end
regSpawn(function()
