regSpawn(function()
    if R.isR then return end
    local RANGE = { Ginger = 24, Sprout = 60, Cosmo = 105 } 
    local lastTry = 0
    while true do
        task.wait(0.4)
        if not (S.autoHeal or S.autoUseAbilityGala) then continue end
        pcall(function()
            local info = workspace:FindFirstChild("Info")
            if not info then return end
            local eff, own, pend = _G.YattaEffToon()
            if pend then return end
            local me = ""
            if eff == own then
                if S.autoHeal then me = own end
            elseif eff == "Sprout" and S.autoUseAbilityGala then
                me = "Sprout"
            end
            local range = RANGE[me]
            if not range then return end
            local fa = info:FindFirstChild("FloorActive")
            if not (fa and fa.Value == true) then return end
            if tick() - lastTry < 1.2 then return end
            local char = plr.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not (hum and hrp and hum.Health > 0) then return end
            local igp = workspace:FindFirstChild(_G.YattaIGP)
            local pm  = igp and igp:FindFirstChild(plr.Name)
            local ab1 = pm and pm:FindFirstChild("Abilities") and pm.Abilities:FindFirstChild("Ability1")
            local cd  = ab1 and ab1:FindFirstChild("CurrentCooldown")
            if not cd or cd.Value > 0 then return end
            if me == "Cosmo" then
                if hum.Health <= 1 then return end
            else
                local costV = ab1:FindFirstChild("AbilityCost")
                local ps    = info:FindFirstChild("PlayerStats")
                local mine  = ps and ps:FindFirstChild(plr.Name)
                local tapes = mine and mine:FindFirstChild("SurvivalPoints")
                if not tapes or tapes.Value < ((costV and costV.Value) or 100) then return end
                if me == "Sprout" then
                    local gs = info:FindFirstChild("GameStats")
                    local hc = gs and gs:FindFirstChild("HealCooldown")
                    if hc and hc.Value == true then return end
                end
            end
            local players = workspace:FindFirstChild("InGamePlayers")
            if not players then return end
            local best, bestHp, bestDist
            for _, m in ipairs(players:GetChildren()) do
                if m ~= char and m:IsA("Model") then
                    local h = m:FindFirstChildOfClass("Humanoid")
                    local r = m:FindFirstChild("HumanoidRootPart")
                    if h and r and h.Health > 0 and h.Health < h.MaxHealth then
                        local d = (r.Position - hrp.Position).Magnitude
                        if d <= range and (not best or h.Health < bestHp
                            or (h.Health == bestHp and d < bestDist)) then
                            best, bestHp, bestDist = m, h.Health, d
                        end
                    end
                end
            end
            if not best then return end
            lastTry = tick()
            local Events = game:GetService("ReplicatedStorage").Events
