                local ch = Events:FindFirstChild("GingerHealChannel")
                if ch then ch:FireServer("MobileHealComplete", best) end
            else
                Events.AbilityEvent:InvokeServer(char, hrp.CFrame, best)
            end
        end)
    end
end)
