        if guardTarget then
            local tHum = guardTarget.Parent == igp and guardTarget:FindFirstChildOfClass("Humanoid") or nil
            if tHum and tHum.Health > 0 then
                if guardTarget:GetAttribute("GuardedBy") ~= nil then continue end
                if tick() - guardT < 3 then continue end
            end
            guardTarget = nil
        end
        local ab1 = pm and pm:FindFirstChild("Abilities") and pm.Abilities:FindFirstChild("Ability1")
