                selfMode = (selfMode % 3) + 1
            end
            task.wait(0.4)
        else
            if math.floor(hum.Health + 0.5) <= 1 then continue end
            if not best then continue end
            pcall(function() ae:InvokeServer(char, hrp.CFrame, best, nil) end)
            guardTarget, guardT = best, tick()
            task.wait(1)
        end
    end
