function FindBaseMachinePipe(gen)
    if not gen or not gen.Parent then return nil end
    local cached = cn.baseMachinePartCache[gen]
    if cached then
        for _, part in ipairs(cached) do
            if part.Parent and part.Name == "Pipe"
                and (part:IsA("BasePart") or part:IsA("MeshPart")) then
                return part
            end
        end
    end
    local bm = gen:FindFirstChild("BaseMachine")
    if bm then
        local pipe = bm:FindFirstChild("Pipe")
        if pipe and (pipe:IsA("BasePart") or pipe:IsA("MeshPart")) then return pipe end
        for _, desc in ipairs(bm:GetDescendants()) do
            if desc.Name == "Pipe" and (desc:IsA("BasePart") or desc:IsA("MeshPart")) then
                return desc
            end
        end
    end
    return R.FGPP2(gen)
end
function IsDualGen(name)
    return name:match("^DualGen_%d+_%d+$") ~= nil
end
function GetDualGenSlotForPlayer(gen)
    local st = gen:FindFirstChild("Stats"); if not st then return "primary" end
    local ap1Val = st:FindFirstChild("ActivePlayer")
    local ap2Val = st:FindFirstChild("ActivePlayer2")
    local ap1 = ap1Val and ap1Val.Value or nil
    local ap2 = ap2Val and ap2Val.Value or nil
    if ap1 == plr then return "primary" end
    if ap2 == plr then return "mirror"  end
    if ap1 == nil    then return "primary" end
    if ap2 == nil    then return "mirror"  end
    return nil
end
do
function IsGenSlotOccupied(gen)
    local st = gen:FindFirstChild("Stats"); if not st then return false end
    local ap = st:FindFirstChild("ActivePlayer"); if not ap then return false end
    local occupant = ap.Value
    return occupant ~= nil and occupant ~= plr
end
end
function IsDualGenFullyOccupied(gen)
    local st = gen:FindFirstChild("Stats"); if not st then return false end
    local ap1 = st:FindFirstChild("ActivePlayer")
    local ap2 = st:FindFirstChild("ActivePlayer2")
    local o1  = ap1 and ap1.Value or nil
    local o2  = ap2 and ap2.Value or nil
    return (o1 ~= nil and o1 ~= plr) and (o2 ~= nil and o2 ~= plr)
end
function IsGenOccupiedByOtherPlayer(gen)
    if not gen or not gen.Parent then return false end
    local st = gen:FindFirstChild("Stats")
    if not st then return false end
    local ap = st:FindFirstChild("ActivePlayer")
    if not ap then return false end
    local occupant = ap.Value
    return occupant ~= nil and occupant ~= plr and R.gag() ~= gen
end
function TeleportToElevOrEmergencyBase(hrp)
    if not hrp or not hrp.Parent then return end
    if S.safeHide then return end
    if not S.anyElevTpOn() then return end
    local floorVal = R.gfv()
    if not (floorVal and floorVal:IsA("BoolValue") and floorVal.Value == true) then return end
    if IsPanicActive() then return end
    local base = FindFakeElevatorBasePart()
    if base then
        local targetPos = base.Position + Vector3.new(0, 3, 0)
        if (hrp.Position - targetPos).Magnitude > 6 then
            WaitForSafeHideRelease()
            hrp.CFrame = CFrame.new(targetPos)
        end
    end
end
function FindGenInteractNode(gen, useMirror)
    if not gen then return nil end
    local pipe = FindBaseMachinePipe(gen)
    if pipe then return pipe end
    if useMirror then
        local tmFolder = gen:FindFirstChild("TreadmillTeleportPositions_Mirror", true)
        if tmFolder then
            local tp = tmFolder:FindFirstChild("TreadmillTeleportPosition")
            if tp and tp:IsA("BasePart") then return tp end
        end
        local mirrorFolder = gen:FindFirstChild("TeleportPositions_Mirror", true)
        if mirrorFolder then
            local tp = mirrorFolder:FindFirstChild("TeleportPosition")
                or mirrorFolder:FindFirstChildWhichIsA("BasePart", true)
            if tp then return tp end
        end
    end
    local tmStd = gen:FindFirstChild("TreadmillTeleportPositions", true)
    if tmStd then
        local tp = tmStd:FindFirstChild("TreadmillTeleportPosition")
        if tp and tp:IsA("BasePart") then return tp end
    end
    return gen:FindFirstChild("TreadmillTeleportPosition", true)
        or gen:FindFirstChild("TeleportPosition", true)
end
function safeSetCFrame(hrp, targetCF)
    if not hrp or not hrp.Parent then return end
    if S.shBusy and S.shBusy() then return end
    local d = hrp.Position - targetCF.Position
    if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= K.tpSkipDsq then return end
    WaitForSafeHideRelease()
    hrp.CFrame = targetCF
    if S.tpSettle then S.tpSettle(hrp) end
end
function TeleportToGenPipe(hrp, gen)
    if not hrp or not hrp.Parent then return end
    if S.shBusy and S.shBusy() then return end
    if not gen  or not gen.Parent  then return end
    local pipe = FindBaseMachinePipe(gen)
    if pipe then
        local pos    = Vector3.new(pipe.Position.X, pipe.Position.Y + 1.5, pipe.Position.Z)
        local target = BuildOrientedCFrame(pos, pipe.CFrame)
        safeSetCFrame(hrp, target)
    end
end
function TeleportToGenSimple(hrp, gen, useMirror)
    if not hrp or not gen then return end
    if S.shBusy and S.shBusy() then return end
    local pipe = FindBaseMachinePipe(gen)
    if pipe then
        local pos    = Vector3.new(pipe.Position.X, pipe.Position.Y + 1.5, pipe.Position.Z)
        local target = BuildOrientedCFrame(pos, pipe.CFrame)
        safeSetCFrame(hrp, target)
        return
    end
    local node = FindGenInteractNode(gen, useMirror)
    if node then
        local nodeCF = node:IsA("BasePart") and node.CFrame or nil
        local pos    = Vector3.new(node.Position.X, node.Position.Y + 1.5, node.Position.Z)
        local target = BuildOrientedCFrame(pos, nodeCF)
        safeSetCFrame(hrp, target)
        return
    end
    local prim = gen.PrimaryPart or gen:FindFirstChildWhichIsA("BasePart", true)
    if prim then
        local pos    = (prim.CFrame * CFrame.new(0, C.teleportHeight, 0)).Position
        local target = BuildOrientedCFrame(pos, prim.CFrame)
        safeSetCFrame(hrp, target)
    end
end
local baseTendrilNames = { BlotHand = true, blotHandL = true, blotHandR = true, BlotHand_L = true, BlotHand_R = true }
function LiveTendrilsNearBase(base, radius)
    local result = {}
    if not base or not base.Parent then return result end
    local ok, parts = pcall(function()
        local params = OverlapParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local char = plr.Character
        params.FilterDescendantsInstances = char and { char } or {}
        return workspace:GetPartBoundsInRadius(base.Position, radius, params)
    end)
    if not ok or not parts then return result end
    local seen = {}
    for _, part in ipairs(parts) do
        local model = part:FindFirstAncestorOfClass("Model")
        if model and not seen[model]
            and (R.TSet[model.Name] or baseTendrilNames[model.Name]) then
            seen[model] = true
            local tp = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart", true)
            if tp then
                result[#result+1] = { pos = tp.Position, obj = model }
            end
        elseif not seen[part] then
            local isHand = R.TSet[part.Name] or baseTendrilNames[part.Name]
            if not isHand then
                for _, ch in ipairs(part:GetChildren()) do
                    if R.TSet[ch.Name] or baseTendrilNames[ch.Name] then isHand = true; break end
                end
            end
            if isHand then
                seen[part] = true
                result[#result+1] = { pos = part.Position, obj = part }
            end
        end
    end
    return result
end
function GetSafeBaseCFrame(base)
    if not base or not base.Parent then return nil end
    local dodgeR = C.tendrilDodgeRange or 25
    local ten = LiveTendrilsNearBase(base, dodgeR + 20)
    if #ten == 0 then
        ten = Cache.tendrilPositions
    end
    local hasThreat = false
    if #ten > 0 then
        local halfX = base.Size.X / 2
        local halfZ = base.Size.Z / 2
        for i = 1, #ten do
            local lp = base.CFrame:PointToObjectSpace(ten[i].pos)
            if math.abs(lp.X) <= (halfX + dodgeR) and math.abs(lp.Z) <= (halfZ + dodgeR) then
                hasThreat = true; break
            end
        end
    end
    if hasThreat then
        local avoidList = {}
        for i = 1, #ten do avoidList[i] = ten[i].pos end
        local safeCF = R.fsbs(base, avoidList, dodgeR)
        if safeCF then
            local okP0, p0 = pcall(IsPanicActive)
            if okP0 and p0 then return S.elevFrontCF(base, safeCF.Position) end
            return safeCF
        end
    end
    local pos = (base.CFrame * CFrame.new(0, C.teleportHeight, 0)).Position
    local okPn, pn = pcall(IsPanicActive)
    if okPn and pn then return S.elevFrontCF(base, pos) end
    return BuildOrientedCFrame(pos, base.CFrame)
end
function TeleportToBaseWithRetry(hrp, currentBase, retries)
    if not hrp or not currentBase then return false end
    if S.safeHide then return false end
    if not S.anyElevTpOn() then return false end
    if S.shActive then
        while S.shActive do
            task.wait(0.05)
        end
        if not hrp.Parent or not currentBase.Parent then return false end
    end
    if S.pathfindMode and not S.pfEmergency then return false end
    if R.ibb(currentBase, hrp.Position) then return true end
    retries = retries or 3
    local targetCF = GetSafeBaseCFrame(currentBase)
    if not targetCF then return false end
    for i = 1, retries do
        if R.ibb(currentBase, hrp.Position) then return true end
        R.TpTo(hrp, targetCF)
        task.wait(0.15)
        if R.ibb(currentBase, hrp.Position) then return true end
    end
    return false
end
do
S.shActive = false
local SH_DEPTH_SEEN, SH_DEPTH_DECODE, SH_TEN_R = 8, 5, 14

function shTwistedY(pos)
    local me = plr.Name
    local mon = Cache.monsterPositions
    local chaseY, chaseD = nil, math.huge
    local nearY, nearD = nil, 80
    for i = 1, #mon do
        local e = mon[i]
        local part = e.livePart
        if part and part.Parent then
            local pp = part.Position
            local d = (pp - pos).Magnitude
            local chasing = false
            local m = e.model
            if m and m.Parent then
                local ch = plr.Character
                for _, cv in ipairs(m:GetDescendants()) do
                    if cv.Name == "ChasingValue" and cv:IsA("ObjectValue") then
                        local v = cv.Value
                        if v and (v == plr or v == ch or v.Name == me
                            or (ch ~= nil and v:IsDescendantOf(ch))) then
                            chasing = true
                            break
                        end
                    end
                end
            end
            if chasing and d < chaseD then chaseD = d; chaseY = pp.Y end
            if d < nearD then nearD = d; nearY = pp.Y end
        end
    end
    return chaseY or nearY
end

function shTendrilClear(x, z)
    local best = math.huge
    local ten = Cache.tendrilPositions
    for i = 1, #ten do
        local t = ten[i].pos
        local dx, dz = t.X - x, t.Z - z
        local d = math.sqrt(dx * dx + dz * dz)
        if d < best then best = d end
    end
    return best
end

function shPickXZ(x, z)
    if shTendrilClear(x, z) >= SH_TEN_R then return x, z end
    local bx, bz, bd = x, z, shTendrilClear(x, z)
    for _, r in ipairs({ 10, 18, 26 }) do
        for k = 0, 7 do
            local a = k * math.pi / 4
            local cx, cz = x + math.cos(a) * r, z + math.sin(a) * r
            local d = shTendrilClear(cx, cz)
            if d >= SH_TEN_R then return cx, cz end
            if d > bd then bd = d; bx = cx; bz = cz end
        end
    end
    return bx, bz
end

function shGetUp(hum, hrp)
    if not (hum and hrp and hrp.Parent) then return end
    pcall(function()
        hum.PlatformStand = false
        hum.Sit = false
        local ch = hrp.Parent
        for _, d in ipairs(ch:GetDescendants()) do
            if (d:IsA("LinearVelocity") or d:IsA("AngularVelocity")) and d.Name ~= "YattaSafeHideLV" and d.Name ~= "YattaFleeLV" then
                d:Destroy()
            end
        end
        local look = hrp.CFrame.LookVector
        local yaw  = math.atan2(-look.X, -look.Z)
        hrp.AssemblyAngularVelocity = Vector3.zero
        hrp.AssemblyLinearVelocity  = Vector3.new(0, math.min(0, hrp.AssemblyLinearVelocity.Y), 0)
        hrp.CFrame = CFrame.new(hrp.Position) * CFrame.Angles(0, yaw, 0)
        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
        hum:ChangeState(Enum.HumanoidStateType.Running)
    end)
end
function shIsDown(hum, hrp)
    local st = hum:GetState()
    if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.PlatformStanding
       or st == Enum.HumanoidStateType.FallingDown or st == Enum.HumanoidStateType.Ragdoll
       or hum.PlatformStand then
        return true
    end
    return hrp.CFrame.UpVector.Y < 0.85
end
function S.shWatchGetUp(seconds)
    local untilT = tick() + (seconds or 4)
    regSpawn(function()
        while tick() < untilT do
            task.wait(0.15)
            local ch = plr.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if not (hum and hrp and hum.Health > 0) then return end
            if S.shActive then return end
            if shIsDown(hum, hrp) then shGetUp(hum, hrp) end
        end
    end)
end

function shCleanup(hum)
    S.shAir = false
    pcall(function()
        local g = S.shGroundY
        local ch = plr.Character
        local h = ch and ch:FindFirstChild("HumanoidRootPart")
        if g and h and h.Position.Y < g - 2 and h.Position.Y > g - SH_DEPTH_SEEN - 4 then
            h.CFrame = CFrame.new(h.Position.X, g, h.Position.Z) * (h.CFrame - h.CFrame.Position)
            h.AssemblyLinearVelocity = Vector3.zero
        end
        S.shGroundY = nil
    end)
    if S.shLV   then pcall(function() S.shLV:Destroy()   end); S.shLV   = nil end
    if S.shAtt  then pcall(function() S.shAtt:Destroy()  end); S.shAtt  = nil end
    if S.shPlat then pcall(function() S.shPlat:Destroy() end); S.shPlat = nil end
    if hum then
        pcall(function()
            hum.PlatformStand = false
            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
        end)
    end
end

function shUpdatePlatform(hum, hrp, pos)
    if S.shAir then
        if S.shPlat then pcall(function() S.shPlat:Destroy() end); S.shPlat = nil end
        return
    end
    local plat = S.shPlat
    if not (plat and plat.Parent) then
        plat = Instance.new("Part")
        plat.Name = "YattaSafeHideFloor"
        plat.Size = Vector3.new(16, 1, 16)
        plat.Anchored = true
        plat.CanCollide = true
        plat.CanQuery = false
        plat.CanTouch = false
        plat.Transparency = 1
        plat.Parent = workspace
        S.shPlat = plat
    end
    local feet = hum.HipHeight + hrp.Size.Y / 2
    plat.CFrame = CFrame.new(pos.X, pos.Y - feet - 0.5, pos.Z)
end

function S.shIsGenOrGigi(d)
    local cur = d.Parent
    while cur and cur ~= workspace do
        local l = string.lower(cur.Name)
        if string.find(l, "generator", 1, true) or string.find(l, "dualgen", 1, true)
           or string.find(l, "trickortreatgen", 1, true) or string.find(l, "gigi", 1, true)
           or string.find(l, "claw", 1, true) or string.find(l, "trickortreatdoor", 1, true)
           or string.find(l, "holidaypickup", 1, true) or string.find(l, "collect", 1, true) then
            return true
        end
        cur = cur.Parent
    end
    return false
end
function S.shBigEnough(part)
    local sz, cf = part.Size, part.CFrame
    local vert, h1, h2
    if math.abs(cf.UpVector.Y) > 0.7 then vert, h1, h2 = sz.Y, sz.X, sz.Z
    elseif math.abs(cf.RightVector.Y) > 0.7 then vert, h1, h2 = sz.X, sz.Y, sz.Z
    else vert, h1, h2 = sz.Z, sz.X, sz.Y end
    if vert < 4 then return false end
    if math.min(h1, h2) < 2.5 then return false end
    return math.max(h1, h2) >= 4
end
function S.shIsNoclipType(d)
    if string.find(string.lower(d.Name), "noclip", 1, true) then return true end
    local pr = d.Parent
    return pr ~= nil and string.find(string.lower(pr.Name), "noclip", 1, true) ~= nil
end
function S.shIsWall(part)
    local sz, cf = part.Size, part.CFrame
    local vert, h1, h2
    if math.abs(cf.UpVector.Y) > 0.7 then vert, h1, h2 = sz.Y, sz.X, sz.Z
    elseif math.abs(cf.RightVector.Y) > 0.7 then vert, h1, h2 = sz.X, sz.Y, sz.Z
    else vert, h1, h2 = sz.Z, sz.X, sz.Y end
    if string.find(string.lower(part.Name), "wall", 1, true) then return vert >= 4 end
    return vert >= 7 and math.max(h1, h2) >= 6
end
function S.shSolid(d)
    if d.CanCollide == true then return true end
    return S.NcDisabled ~= nil and S.NcDisabled(d) == true
end
function S.shBlockedName(d)
    local l = string.lower(d.Name)
    if string.find(l, "cylindercollider", 1, true) then return true end
    if string.find(l, "noclip", 1, true) then
        if not S.shSolid(d) then return true end
        if d.Material == Enum.Material.Glass or d.Material == Enum.Material.ForceField then return true end
        return false
    end
    for _, w in ipairs({ "nocollide", "cylindercollider", "invis", "hitbox", "trigger", "barrier", "boundary", "killbrick" }) do
        if string.find(l, w, 1, true) then return true end
    end
    if not S.shSolid(d) then return true end
    if d.Transparency > 0.5 then return true end
    if d.Material == Enum.Material.Glass or d.Material == Enum.Material.ForceField then return true end
    return false
end
S.shExcludeFolders = { "Generators", "Items", "TrickOrTreatDoors", "Monsters", "HolidayPickups" }
function S.shExcludeRoots(room)
    local roots = {}
    if not room then return roots end
    local function addFrom(container)
        for _, nm in ipairs(S.shExcludeFolders) do
            local f = container:FindFirstChild(nm)
            if f then roots[#roots + 1] = f end
        end
    end
    addFrom(room)
    for _, rm in ipairs(room:GetChildren()) do
        addFrom(rm)
        if _G.YattaTotExtra then
            local okx, ex = pcall(_G.YattaTotExtra, rm, rm:FindFirstChild("Generators"))
            if okx and type(ex) == "table" then
                for _, g in ipairs(ex) do roots[#roots + 1] = g end
            end
        end
    end
    return roots
end
function S.shExcluded(d, roots)
    for k = 1, #roots do
        local r = roots[k]
        if d == r or d:IsDescendantOf(r) then return true end
    end
    return false
end
function S.shFloorSlab(part)
    if math.abs(part.CFrame.UpVector.Y) < 0.95 then return nil end
    local sz = part.Size
    if sz.Y < 2.9 or math.min(sz.X, sz.Z) < 3.5 then return nil end
    return sz.Y
end
function S.shBuildCover()
    if S.shCoverBusy then return end
    S.shCoverBusy = true
    task.spawn(function()
        local list, floors = {}, {}
        local room = workspace:FindFirstChild("CurrentRoom")
        local n = 0
        if room then
            local exRoots = S.shExcludeRoots(room)
            for _, d in ipairs(room:GetDescendants()) do
                n += 1
                if n % 600 == 0 then task.wait() end
                if d:IsA("BasePart") and S.shSolid(d) and d.Anchored
                   and not d:IsA("WedgePart") and not d:IsA("CornerWedgePart") and not d:IsA("TrussPart")
                   and not (d:IsA("Part") and d.Shape ~= Enum.PartType.Block)
                   and not string.find(string.lower(d.Name), "stair", 1, true)
                   and not (d:IsA("MeshPart") and d.CollisionFidelity ~= Enum.CollisionFidelity.Box
                            and not string.find(string.lower(d.Name), "collider", 1, true)
                            and not string.find(string.lower(d.Name), "invis", 1, true)
                            and not string.find(string.lower(d.Name), "noclip", 1, true))
                   and not S.shBlockedName(d) then
                    local ok = true
                    local cur = d.Parent
                    while cur and cur ~= room do
                        local l = string.lower(cur.Name)
                        if l == "monsters" or l == "items" or string.find(l, "elevator", 1, true)
                           or string.find(l, "trickortreatdoor", 1, true) or string.find(l, "stair", 1, true)
                           or l == "holidaypickups" or string.find(l, "collect", 1, true) then
                            ok = false; break
                        end
                        cur = cur.Parent
                    end
                    if ok and (S.shIsGenOrGigi(d) or S.shExcluded(d, exRoots)) then ok = false end
                    if ok then
                        if S.shBigEnough(d) and (S.shIsNoclipType(d) or S.shIsWall(d) or (d.Name == "Part" and S.shSolid(d))) then list[#list + 1] = d end
                        if S.shFloorSlab(d) then floors[#floors + 1] = d end
                    end
                end
            end
        end
        local cs, fs = {}, {}
        for _, x in ipairs(list) do cs[x] = true end
        for _, x in ipairs(floors) do fs[x] = true end
        S.shCoverSet, S.shFloorSet = cs, fs
        S.shCoverList = list
        S.shFloorList = floors
        S.shCoverT = tick()
        S.shCoverBusy = false
    end)
end
function S.shPumpkinOk(x, z)
    local l = S.rollingPumpkins()
    local need = (S.pumpkinRadius or 45) + 10
    for i = 1, #l do
        local e = l[i]
        local dx, dz = e.pos.X - x, e.pos.Z - z
        local d = math.sqrt(dx * dx + dz * dz)
        if d < need then return false end
        local sp = e.vel.Magnitude
        if sp > 6 and d < 200 then
            local ux, uz = e.vel.X / sp, e.vel.Z / sp
            local along   = dx * ux + dz * uz
            local lateral = math.abs(dx * uz - dz * ux)
            if along > 0 and lateral < 22 then return false end
        end
    end
    return true
end
function S.shTenOk(x, z)
    local ten = Cache.tendrilPositions
    for i = 1, #ten do
        local t = ten[i]
        local dx, dz = t.pos.X - x, t.pos.Z - z
        local d = math.sqrt(dx * dx + dz * dz)
        local nm = (t.obj and string.lower(t.obj.Name)) or ""
        local need = string.find(nm, "sprouttendril", 1, true) and 34 or SH_TEN_R
        if d < need then return false end
    end
    return true
end

function S.shSproutOk(x, z)
    local ten = Cache.tendrilPositions
    for i = 1, #ten do
        local t = ten[i]
        local nm = (t.obj and string.lower(t.obj.Name)) or ""
        if string.find(nm, "sprouttendril", 1, true) then
            local dx, dz = t.pos.X - x, t.pos.Z - z
            if math.sqrt(dx * dx + dz * dz) < 34 then return false end
        end
    end
    return true
end

function S.shBuildAvoid(canYield)
    local boxes, n = {}, 0
    local CAP = 6000
    local function addRoot(root, limit)
        if not root then return end
        local base = #boxes
        local function add(d)
            if #boxes >= CAP or #boxes - base >= limit then return end
            if d.CanCollide == false and not S.shSolid(d) and d.Transparency >= 0.5 then return end
            local sz = d.Size
            boxes[#boxes + 1] = { cf = d.CFrame, half = sz / 2, c = d.Position, r = sz.Magnitude / 2 }
        end
        if root:IsA("BasePart") then add(root) end
        for _, d in ipairs(root:GetDescendants()) do
            n += 1
            if canYield and n % 800 == 0 then task.wait() end
            if d:IsA("BasePart") then add(d) end
        end
    end
    local cr = workspace:FindFirstChild("CurrentRoom")
    if cr then
        local rooms = cr:GetChildren()
        for _, room in ipairs(rooms) do
            local gf = room:FindFirstChild("Generators")
            addRoot(gf, 4000)
            if _G.YattaTotExtra then
                for _, g in ipairs(_G.YattaTotExtra(room, gf)) do addRoot(g, 1000) end
            end
        end
        for _, room in ipairs(rooms) do
            addRoot(room:FindFirstChild("TrickOrTreatDoors"), 1000)
            addRoot(room:FindFirstChild("HolidayPickups"), 1000)
            addRoot(room:FindFirstChild("Items"), 2000)
        end
        for _, room in ipairs(rooms) do
            addRoot(room:FindFirstChild("Monsters"), 2000)
        end
    end
    return boxes
end
function S.shAvoidBoxes()
    local now = tick()
    if S._shAvoid then
        if now - (S._shAvoidT or 0) >= 1 and not S._shAvoidBusy then
            S._shAvoidBusy = true
            task.spawn(function()
                local ok, b = pcall(S.shBuildAvoid, true)
                if ok and b then S._shAvoid, S._shAvoidT = b, tick() end
                S._shAvoidBusy = false
            end)
        end
        return S._shAvoid
    end
    local b = S.shBuildAvoid(false)
    S._shAvoid, S._shAvoidT = b, now
    return b
end
function S.shInAvoid(pos, rh, rv)
    local boxes = S.shAvoidBoxes()
    rh = math.max((rh or 2.5) - 0.75, 0.5); rv = math.max((rv or 2.5) - 0.5, 0.5)
    local reach = math.max(rh, rv)
    for i = 1, #boxes do
        local b = boxes[i]
        local dx, dy, dz = b.c.X - pos.X, b.c.Y - pos.Y, b.c.Z - pos.Z
        local lim = b.r + reach
        if dx * dx + dy * dy + dz * dz <= lim * lim then
            local lp = b.cf:PointToObjectSpace(pos)
            if math.abs(lp.X) <= b.half.X + rh and math.abs(lp.Y) <= b.half.Y + rv and math.abs(lp.Z) <= b.half.Z + rh then
                return true
            end
        end
    end
    return false
end

function S.shGenPoints()
    local now = tick()
    if S._shGenPts and now - (S._shGenPtsT or 0) < 1 then return S._shGenPts end
    local pts = {}
    local cr = workspace:FindFirstChild("CurrentRoom")
    if cr then
        for _, room in ipairs(cr:GetChildren()) do
            local gf = room:FindFirstChild("Generators")
            if gf then
                for _, g in ipairs(gf:GetChildren()) do
                    local ok, pv = pcall(function() return g:GetPivot().Position end)
                    if ok then pts[#pts + 1] = pv end
                end
            end
            for _, g in ipairs(_G.YattaTotExtra(room, gf)) do
                local ok, pv = pcall(function() return g:GetPivot().Position end)
                if ok then pts[#pts + 1] = pv end
            end
            local items = room:FindFirstChild("Items")
            local gigi = items and items:FindFirstChild("GigiHoard")
            if gigi then
                local ok, pv = pcall(function() return gigi:GetPivot().Position end)
                if ok then pts[#pts + 1] = pv end
            end
        end
    end
    S._shGenPts, S._shGenPtsT = pts, now
    return pts
end
function S.shNearGen(x, z, r)
    local pts = S.shGenPoints()
    for i = 1, #pts do
        local dx, dz = pts[i].X - x, pts[i].Z - z
        if dx * dx + dz * dz < r * r then return true end
    end
    return false
end
function S.shAwayVec(p)
    local sx, sz, any = 0, 0, false
    local function add(pos)
        local dx, dz = p.X - pos.X, p.Z - pos.Z
        local d = math.sqrt(dx * dx + dz * dz)
        if d > 0.5 and d < 140 then
            local w = 1 / (d + 8)
            sx = sx + dx / d * w; sz = sz + dz / d * w; any = true
        end
    end
    local mon = Cache.monsterPositions
    if mon then
        for i = 1, #mon do
            if mon[i].farmEligible then
                local lp = mon[i].livePart
                add((lp and lp.Parent) and lp.Position or mon[i].pos)
            end
        end
    end
    for _, e in ipairs(S.rollingPumpkins()) do add(e.pos) end
    if not any then return nil end
    local m = math.sqrt(sx * sx + sz * sz)
    if m < 1e-6 then return nil end
    return Vector3.new(sx / m, 0, sz / m)
end

function S.shPickCover(p, radOverride, relaxed, excl)
    if not S.shCoverT or tick() - S.shCoverT > 20 then S.shBuildCover() end
    local list = S.shCoverList
    if not list then return nil end
    local mons = Cache.monsterPositions
    local pkNear = S.pumpkinThreat(p)
    local radius = radOverride or (pkNear and 80 or 30)
    local best, bestSc, bestPart = nil, math.huge, nil
    local fb, fbSc, fbPart = nil, math.huge, nil
    local away = S.shAwayVec(p)
    local chr  = plr.Character
    local hrpC = chr and chr:FindFirstChild("HumanoidRootPart")
    local hs   = hrpC and (hrpC.Size / 2) or Vector3.new(1, 1, 0.5)
    local hRot = hrpC and hrpC.CFrame.Rotation or CFrame.new()
    for i = 1, #list do
        local part = list[i]
        if part.Parent and not (excl and excl[part]) then   
            local pos, sz = part.Position, part.Size
            local rel = part.CFrame.Rotation:Inverse() * hRot
            local rr, ru, rl = rel.RightVector, rel.UpVector, rel.LookVector
            local hhx = math.abs(rr.X) * hs.X + math.abs(ru.X) * hs.Y + math.abs(rl.X) * hs.Z + 0.25
            local hhy = math.abs(rr.Y) * hs.X + math.abs(ru.Y) * hs.Y + math.abs(rl.Y) * hs.Z + 0.25
            local hhz = math.abs(rr.Z) * hs.X + math.abs(ru.Z) * hs.Y + math.abs(rl.Z) * hs.Z + 0.25
            if sz.X / 2 >= hhx and sz.Y / 2 >= hhy and sz.Z / 2 >= hhz
               and math.abs(pos.Y - p.Y) <= math.max(sz.X, sz.Y, sz.Z) / 2 + 3 then
                local lp = part.CFrame:PointToObjectSpace(p)
                local half = sz / 2
                local ix, iy, iz = hhx, hhy, hhz
                local tp = part.CFrame:PointToWorldSpace(Vector3.new(
                    0,
                    math.clamp(lp.Y, -(half.Y - iy), half.Y - iy),
                    0))
                local dx0, dz0 = tp.X - p.X, tp.Z - p.Z
                local d = math.sqrt(dx0 * dx0 + dz0 * dz0)
                if d < radius and math.abs(tp.Y - p.Y) <= 0.3 and S.shTenOk(tp.X, tp.Z) and S.shPumpkinOk(tp.X, tp.Z) then
                    local safe = true
                    for m = 1, (relaxed and 0 or #mons) do   
                        local lpart = mons[m].livePart
                        local mp = lpart and lpart.Parent and lpart.Position or mons[m].pos
                        if mp and mons[m].farmEligible then
                            local dx, dz = mp.X - tp.X, mp.Z - tp.Z
                            if dx * dx + dz * dz < 100 then safe = false; break end
                            local sx, sz2 = tp.X - p.X, tp.Z - p.Z
                            local sl = sx * sx + sz2 * sz2
                            local tt = sl > 0.01 and math.clamp(((mp.X - p.X) * sx + (mp.Z - p.Z) * sz2) / sl, 0, 1) or 0
                            local cx, cz = p.X + sx * tt - mp.X, p.Z + sz2 * tt - mp.Z
                            if cx * cx + cz * cz < 49 then safe = false; break end
                        end
                    end
                    if safe then
                        local sc = d
                        if away and d > 0.5 and not S.shNearestOn() then
                            if S.shNearGen(tp.X, tp.Z, 9) then
                                sc = d - 24
                            else
                                sc = d - (Vector3.new(dx0, 0, dz0).Unit:Dot(away)) * 24
                            end
                        end
                        if (sc < bestSc or sc < fbSc) and not S.shInAvoid(Vector3.new(tp.X, p.Y, tp.Z), math.max(hhx, hhz), hhy) then
                            local fit = true
                            if hrpC then
                                local okF, f = pcall(S.shFitsAtFloor, part, tp.X, tp.Z, p.Y, hrpC, chr and chr:FindFirstChildOfClass("Humanoid"))
                                if okF then fit = f end
                            end
                            if fit then
                                if sc < bestSc then bestSc = sc; best = Vector3.new(tp.X, p.Y, tp.Z); bestPart = part end
                            elseif sc < fbSc then
                                fbSc = sc; fb = Vector3.new(tp.X, p.Y, tp.Z); fbPart = part
                            end
                        end
                    end
                end
            end
        end
    end
    if best then return best, bestPart end
    return fb, fbPart
end

function S.shHrpHalf(part, hrpC)
    local hs   = hrpC and (hrpC.Size / 2) or Vector3.new(1, 1, 0.5)
    local hRot = hrpC and hrpC.CFrame.Rotation or CFrame.new()
    local rel = part.CFrame.Rotation:Inverse() * hRot
    local rr, ru, rl = rel.RightVector, rel.UpVector, rel.LookVector
    local hhx = math.abs(rr.X) * hs.X + math.abs(ru.X) * hs.Y + math.abs(rl.X) * hs.Z + 0.25
    local hhy = math.abs(rr.Y) * hs.X + math.abs(ru.Y) * hs.Y + math.abs(rl.Y) * hs.Z + 0.25
    local hhz = math.abs(rr.Z) * hs.X + math.abs(ru.Z) * hs.Y + math.abs(rl.Z) * hs.Z + 0.25
    return hhx, hhy, hhz
end
function S.shEncased(hrpC, part)
    if not (hrpC and part and part.Parent) then return false end
    local hs, cf, half = hrpC.Size / 2, hrpC.CFrame, part.Size / 2
    for sx = -1, 1, 2 do for sy = -1, 1, 2 do for sz = -1, 1, 2 do
        local lp = part.CFrame:PointToObjectSpace(cf:PointToWorldSpace(Vector3.new(hs.X * sx, hs.Y * sy, hs.Z * sz)))
        if math.abs(lp.X) > half.X - 0.05 or math.abs(lp.Y) > half.Y - 0.05 or math.abs(lp.Z) > half.Z - 0.05 then
            return false
        end
    end end end
    return true
end
function S.shEncasedAny(hrpC)
    if not hrpC then return nil end
    local cur = S.shPart
    if cur and cur.Parent and not S.shBlockedName(cur) and S.shEncased(hrpC, cur) then return cur end
    local list = S.shCoverList
    if list then
        for i = 1, #list do
            local part = list[i]
            if part.Parent and not S.shBlockedName(part) and S.shEncased(hrpC, part) then return part end
        end
    end
    return nil
end
function S.shInsidePoint(part, p, hrpC)
    local hhx, hhy, hhz = S.shHrpHalf(part, hrpC)
    local half = part.Size / 2
    local lp = part.CFrame:PointToObjectSpace(p)
    local function cl(v, h, ih) local m = math.max(h - ih, 0); return math.clamp(v, -m, m) end
    if S.shFloorGoal and S.shFloorGoal(part, hrpC) then
        local fp = part.CFrame:PointToWorldSpace(Vector3.new(cl(lp.X, half.X, hhx), lp.Y, cl(lp.Z, half.Z, hhz)))
        return Vector3.new(fp.X, p.Y, fp.Z)
    end
    local tp = part.CFrame:PointToWorldSpace(Vector3.new(0, cl(lp.Y, half.Y, hhy), 0))
    return Vector3.new(tp.X, p.Y, tp.Z)
end
S.regGame(function()
    local lastRoom
    while true do
        task.wait(1)
        local room = workspace:FindFirstChild("CurrentRoom")
        local cur  = room and room:GetChildren()[1]
        if cur ~= lastRoom then
            lastRoom = cur
            S.shCoverList = nil; S.shCoverT = nil
            S.shRebuild = { tick() + 1, tick() + 6 }
        end
        if S.shRebuild and S.shRebuild[1] and tick() >= S.shRebuild[1] then
            table.remove(S.shRebuild, 1)
            S.shBuildCover()
        end
        if S.safeHide and (not S.shCoverT or tick() - S.shCoverT > 15) then S.shBuildCover() end
    end
end)
function S.shPickSafe(p)
    local ch = plr.Character
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { ch }
    rp.RespectCanCollide = true
    local threats = {}
    local ten = Cache.tendrilPositions
    if ten then
        for i = 1, #ten do
            local nm = (ten[i].obj and string.lower(ten[i].obj.Name)) or ""
            threats[#threats + 1] = { pos = ten[i].pos, need = string.find(nm, "sprouttendril", 1, true) and 40 or (SH_TEN_R + 8) }
        end
    end
    local mon = Cache.monsterPositions
    if mon then
        for i = 1, #mon do
            if mon[i].farmEligible then
                local lp = mon[i].livePart
                local mp = (lp and lp.Parent) and lp.Position or mon[i].pos
                threats[#threats + 1] = { pos = mp, need = 38 }
            end
        end
    end
    local pkNeed = math.max(40, (S.pumpkinRadius or 45) + 10)
    for _, e in ipairs(S.rollingPumpkins()) do threats[#threats + 1] = { pos = e.pos, need = pkNeed } end
    local pkNear = S.pumpkinThreat(p)
    local best, bestScore = nil, -math.huge
    local eye = p + Vector3.new(0, 2, 0)
    local awayV = S.shAwayVec(p)
    for k = 0, 15 do
        local ang = k * math.pi / 8
        local dir = Vector3.new(math.cos(ang), 0, math.sin(ang))
        for _, r in ipairs(pkNear and { 14, 24, 36, 48, 60, 72 } or { 6, 10, 14, 20, 28, 36, 42 }) do
            local c = p + dir * r
            local blocked = workspace:Raycast(eye, dir * r, rp)
            if not blocked and not S.shNearGen(c.X, c.Z, 18) and not S.shInAvoid(Vector3.new(c.X, p.Y, c.Z), 3.5, 3.5) then
                local g = workspace:Raycast(c + Vector3.new(0, 4, 0), Vector3.new(0, -12, 0), rp)
                if g and math.abs(g.Position.Y - (p.Y - 3)) <= 6 then
                    local ok, minRatio = true, math.huge
                    for i = 1, #threats do
                        local dx, dz = threats[i].pos.X - c.X, threats[i].pos.Z - c.Z
                        local d = math.sqrt(dx * dx + dz * dz)
                        if d < threats[i].need then ok = false; break end
                        local ratio = d - threats[i].need
                        if ratio < minRatio then minRatio = ratio end
                    end
                    if ok then
                        local score = -r + math.min(minRatio, 40) * 0.05
                        if awayV then score = score + dir:Dot(awayV) * 16 end
                        if score > bestScore then bestScore = score; best = Vector3.new(c.X, p.Y, c.Z) end
                    end
                end
            end
        end
    end
    return best
end
S._shFoot = S._shFoot or setmetatable({}, { __mode = "k" })
function S.shGenFootprint(gen)
    local c = S._shFoot[gen]
    if c and c.n == #gen:GetChildren() then return c end
    local minx, maxx, minz, maxz = math.huge, -math.huge, math.huge, -math.huge
    local cnt = 0
    for _, d in ipairs(gen:GetDescendants()) do
        if d:IsA("BasePart") and (d.CanCollide or (d.Transparency < 0.9 and d.Size.Magnitude < 60)) then
            local cf, sz = d.CFrame, d.Size
            for sx = -1, 1, 2 do for sy = -1, 1, 2 do for sz2 = -1, 1, 2 do
                local w = cf:PointToWorldSpace(Vector3.new(sx * sz.X / 2, sy * sz.Y / 2, sz2 * sz.Z / 2))
                if w.X < minx then minx = w.X end
                if w.X > maxx then maxx = w.X end
                if w.Z < minz then minz = w.Z end
                if w.Z > maxz then maxz = w.Z end
            end end end
            cnt += 1
        end
    end
    if cnt == 0 then return nil end
    c = { cx = (minx + maxx) / 2, cz = (minz + maxz) / 2, hx = (maxx - minx) / 2, hz = (maxz - minz) / 2, n = #gen:GetChildren() }
    S._shFoot[gen] = c
    return c
end
function S.shAllGens()
    local gens = {}
    local cr = workspace:FindFirstChild("CurrentRoom")
    if not cr then return gens end
    for _, room in ipairs(cr:GetChildren()) do
        local gf = room:FindFirstChild("Generators")
        if gf then
            for _, g in ipairs(gf:GetChildren()) do
                if g:IsA("Model") then gens[#gens + 1] = g end
            end
        end
        if _G.YattaTotExtra then
            local okx, ex = pcall(_G.YattaTotExtra, room, gf)
            if okx and type(ex) == "table" then
                for _, g in ipairs(ex) do if typeof(g) == "Instance" and g:IsA("Model") then gens[#gens + 1] = g end end
            end
        end
    end
    return gens
end
function S.shSegNear(ax, az, bx, bz, px, pz, r)
    local sx, sz = bx - ax, bz - az
    local sl = sx * sx + sz * sz
    local t = sl > 0.01 and math.clamp(((px - ax) * sx + (pz - az) * sz) / sl, 0, 1) or 0
    local cx, cz = ax + sx * t - px, az + sz * t - pz
    return cx * cx + cz * cz < r * r
end
function S.shPickBehind(p, preferGen)
    local mons = Cache.monsterPositions
    if not mons or #mons == 0 then return nil end
    local T, td = nil, math.huge
    local tws = {}
    for i = 1, #mons do
        local e = mons[i]
        if e.farmEligible then
            local lp = e.livePart
            local mp = (lp and lp.Parent) and lp.Position or e.pos
            if mp then
                tws[#tws + 1] = mp
                local d = math.sqrt((mp.X - p.X) ^ 2 + (mp.Z - p.Z) ^ 2)
                if d < td then T, td = mp, d end
            end
        end
    end
    if not T then return nil end
    local ch  = plr.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not (hrp and hum) then return nil end
    local feet = hum.HipHeight + hrp.Size.Y / 2
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.RespectCanCollide = true
    local skip = { ch }
    for _, c in ipairs(workspace:GetChildren()) do
        if string.sub(c.Name, 1, 5) == "Yatta" then skip[#skip + 1] = c end
    end
    rp.FilterDescendantsInstances = skip
    local op = OverlapParams.new()
    op.FilterType = Enum.RaycastFilterType.Exclude
    op.FilterDescendantsInstances = skip
    op.RespectCanCollide = true
    local best, bestSc, bestGen
    for _, gen in ipairs(S.shAllGens()) do
        local fp = S.shGenFootprint(gen)
        if fp then
            local gx, gz = fp.cx - T.X, fp.cz - T.Z
            local gl = math.sqrt(gx * gx + gz * gz)
            if gl > 0.5 then
                local dx, dz = gx / gl, gz / gl
                local tExit = math.min(fp.hx / math.max(math.abs(dx), 1e-4), fp.hz / math.max(math.abs(dz), 1e-4))
                local sx, sz = fp.cx + dx * (tExit + 2.4), fp.cz + dz * (tExit + 2.4)
                local dpl = math.sqrt((sx - p.X) ^ 2 + (sz - p.Z) ^ 2)
                if dpl <= 45 then
                    local ok = S.shTenOk(sx, sz) and S.shPumpkinOk(sx, sz)
                    if ok then
                        for i = 1, #tws do
                            local m = tws[i]
                            if (m.X - sx) ^ 2 + (m.Z - sz) ^ 2 < 196 then ok = false; break end
                            if S.shSegNear(p.X, p.Z, sx, sz, m.X, m.Z, 7) and (m.X - p.X) ^ 2 + (m.Z - p.Z) ^ 2 > 49 then ok = false; break end
                        end
                    end
                    if ok and S.shInAvoid(Vector3.new(sx, p.Y, sz), 3.2, 3.2) then ok = false end
                    if ok then
                        local g = workspace:Raycast(Vector3.new(sx, p.Y + 3, sz), Vector3.new(0, -14, 0), rp)
                        if not g or math.abs(g.Position.Y - (p.Y - feet)) > 2 then ok = false end
                    end
                    if ok then
                        local hits = workspace:GetPartBoundsInBox(CFrame.new(sx, p.Y, sz), Vector3.new(2.6, 3.6, 2.6), op)
                        for _, h in ipairs(hits) do
                            if h.CanCollide then ok = false; break end
                        end
                    end
                    if ok then
                        local sc = dpl - ((gen == preferGen) and 8 or 0)
                        if not best or sc < bestSc then best, bestSc, bestGen = Vector3.new(sx, p.Y, sz), sc, gen end
                    end
                end
            end
        end
    end
    return best, bestGen
end

function S.shFloorGoal(part, hrp)
    if not (part and part.Parent and hrp) then return nil end
    local th = S.shFloorSlab(part)
    if not th then return nil end
    local top = part.Position.Y + th / 2
    local ground = S.shGroundY or hrp.Position.Y
    if top > ground - 1.0 then return nil end
    return top - hrp.Size.Y / 2 - 0.3
end
function S.shPickFloor(p, radius)
    local list = S.shFloorList
    if not list then return nil end
    local ch  = plr.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not (hrp and hum) then return nil end
    local feet = hum.HipHeight + hrp.Size.Y / 2
    local mons = Cache.monsterPositions or {}
    local best, bestD, bestPart
    for i = 1, #list do
        local part = list[i]
        if part.Parent then
            local th = S.shFloorSlab(part)
            if th then
                local top = part.Position.Y + th / 2
                if math.abs(top - (p.Y - feet)) <= 0.8 then
                    local hhx, hhy, hhz = S.shHrpHalf(part, hrp)
                    local half = part.Size / 2
                    if half.X > hhx and half.Z > hhz and th >= hrp.Size.Y + 0.7 then
                        local lp = part.CFrame:PointToObjectSpace(p)
                        local function cl(v, h, ih) local m = math.max(h - ih, 0); return math.clamp(v, -m, m) end
                        local tp = part.CFrame:PointToWorldSpace(Vector3.new(cl(lp.X, half.X, hhx), lp.Y, cl(lp.Z, half.Z, hhz)))
                        local d = math.sqrt((tp.X - p.X) ^ 2 + (tp.Z - p.Z) ^ 2)
                        if d < (radius or 40) and (not bestD or d < bestD)
                           and S.shTenOk(tp.X, tp.Z) and S.shPumpkinOk(tp.X, tp.Z)
                           and not S.shInAvoid(Vector3.new(tp.X, p.Y, tp.Z), math.max(hhx, hhz), hhy) then
                            local safe = true
                            for m = 1, #mons do
                                local lpart = mons[m].livePart
                                local mp = lpart and lpart.Parent and lpart.Position or mons[m].pos
                                if mp and ((mp.X - tp.X) ^ 2 + (mp.Z - tp.Z) ^ 2 < 64
                                    or (S.shSegNear(p.X, p.Z, tp.X, tp.Z, mp.X, mp.Z, 6) and (mp.X - p.X) ^ 2 + (mp.Z - p.Z) ^ 2 > 36)) then
                                    safe = false; break
                                end
                            end
                            if safe then best, bestD, bestPart = Vector3.new(tp.X, p.Y, tp.Z), d, part end
                        end
                    end
                end
            end
        end
    end
    return best, bestPart
end

function S.shPickSpot(p)
    if S.shActive and S.shGroundY and math.abs(p.Y - S.shGroundY) > 1 then
        p = Vector3.new(p.X, S.shGroundY, p.Z)
    end
    S.shBehindGen = nil
    if S.shNearestOn() then
        for _, r in ipairs({ false, 60 }) do
            local cp, part = S.shPickCover(p, r or nil)
            if cp then return cp, "cover", part, "wall" end
            cp, part = S.shPickCover(p, r or nil, true)
            if cp then return cp, "cover", part, "wall" end
        end
    end
    if S.shBehindOn == true then
        local okB, bp, bgen = pcall(S.shPickBehind, p, S.shBehindGenPrev)
        if okB and bp then
            S.shBehindGen, S.shBehindGenPrev = bgen, bgen
            return bp, "cover", nil, "behind"
        end
    end
    for _, r in ipairs({ false, 60 }) do
        local cp, part = S.shPickCover(p, r or nil)
        if cp then return cp, "cover", part, "wall" end
        cp, part = S.shPickCover(p, r or nil, true)
        if cp then return cp, "cover", part, "wall" end
    end
    if S.shFloorOn ~= false then
        local okF, fp, fpart = pcall(S.shPickFloor, p, 60)
        if okF and fp then return fp, "cover", fpart, "floor" end
    end
    local okN4, near4 = pcall(S.shNearNow)
    local dN4 = S.shNearestTwistedDist(p)
    if (okN4 and near4) or (dN4 and dN4 < 45) then
        for _, rlx in ipairs({ false, true }) do
            local cp, part = S.shPickCover(p, 140, rlx or nil)
            if cp then return cp, "cover", part, "wall" end
        end
        if S.shFloorOn ~= false then
            local okF, fp, fpart = pcall(S.shPickFloor, p, 140)
            if okF and fp then return fp, "cover", fpart, "floor" end
        end
    end
    return nil
end

function S.shNearestTwistedDist(pos)
    local mon = Cache.monsterPositions
    local best
    if mon then
        for i = 1, #mon do
            if mon[i].farmEligible then
                local lp = mon[i].livePart
                local mp = (lp and lp.Parent) and lp.Position or mon[i].pos
                if mp then
                    local d = (Vector3.new(mp.X, 0, mp.Z) - Vector3.new(pos.X, 0, pos.Z)).Magnitude
                    if not best or d < best then best = d end
                end
            end
        end
    end
    return best
end

function S.shVel(hrp, dir, speed)
    if not (hrp and hrp.Parent and dir) then return false end
    local existingLV = hrp:FindFirstChild("YattaFleeLV")
    if existingLV and existingLV.Parent then return false end
    local att = hrp:FindFirstChild("YattaFleeAtt")
    if not att then
        att = Instance.new("Attachment")
        att.Name = "YattaFleeAtt"
        att.Parent = hrp
    end
    if att.Parent ~= hrp then att.Parent = hrp end
    local lv = hrp:FindFirstChild("YattaFleeLV")
    if lv and (lv.Attachment0 ~= att or not lv.Enabled) then
        pcall(function() lv:Destroy() end)
        lv = nil
    end
    if not lv then
        lv = Instance.new("LinearVelocity")
        lv.Name = "YattaFleeLV"
        lv.Attachment0 = att
        lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
        lv.PrimaryTangentAxis = Vector3.xAxis
        lv.SecondaryTangentAxis = Vector3.zAxis
        lv.RelativeTo = Enum.ActuatorRelativeTo.World
        lv.MaxForce = math.huge
        lv.Parent = hrp
    end
    lv.PlaneVelocity = Vector2.new(dir.X * speed, dir.Z * speed)
    S.shVelActive = true
    pcall(function()
        hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + Vector3.new(dir.X, 0, dir.Z))
    end)
    return true
end

function S.shVelStop()
    S.shVelActive = false
    local ch = plr.Character
    local h = ch and ch:FindFirstChild("HumanoidRootPart")
    if h then
        local lv = h:FindFirstChild("YattaFleeLV")
        if lv then lv:Destroy() end
        local att = h:FindFirstChild("YattaFleeAtt")
        if att then att:Destroy() end
    end
end

function S.shFlee(hrp)
    S.shFleeing = false
end

function S.sprintReal()
    local spr = S.spr
    if spr and spr.on and spr.fake == true then return true end
    local ch = plr.Character
    local st = ch and ch:FindFirstChild("Stats")
    local sp = st and st:FindFirstChild("Sprinting")
    return sp ~= nil and sp:IsA("BoolValue") and sp.Value == true
end

function S.shSprintStop()
    if S.shSprintOwned then
        S.shSprintOwned = false
        if not S.autoSprint then pcall(R.FSprt, false) end
    end
end

function S.shSprintNow(hrp)
    local ch = hrp and hrp.Parent
    local stt = ch and ch:FindFirstChild("Stats")
    if S.sprintReal() then return end
    if tick() - (S.shSprintTry or 0) > 0.15 then
        S.shSprintTry = tick(); S.shSprintOwned = true
        pcall(R.FSprt, true)
    end
    local mark = tick(); S.shSprintMark = mark
    task.delay(3, function()
        if S.shSprintMark == mark and not S.shActive and not S.shTweening and not S.shFleeing then
            S.shSprintStop()
        end
    end)
end

function S.shSpeedRefresh()
    local ch = plr.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if hum and hum.WalkSpeed >= 1 then
        S.shSpeedBase = hum.WalkSpeed
        S.shTweenSpeed = math.max(hum.WalkSpeed * 0.85, 8)
    end
    return hum
end
function S.shSpeed()
    local now = tick()
    if now - (S.shSpeedT or 0) > 0.05 then S.shSpeedT = now; S.shSpeedRefresh() end
    if now - (S.shPkT or 0) > 0.15 then
        S.shPkT = now
        local okP, nearP = pcall(function()
            local c = plr.Character
            local h = c and c:FindFirstChild("HumanoidRootPart")
            return h and S.pumpkinThreat(h.Position)
        end)
        S.shPkNear = (okP and nearP) and true or false
    end
    local base = S.shSpeedBase
    if not base then
        local hum = S.shSpeedRefresh()
        base = (hum and hum.WalkSpeed >= 1 and hum.WalkSpeed) or 16
    end
    local mul = S.shPkNear and 1 or 0.85
    do
        local c = plr.Character
        local h = c and c:FindFirstChild("HumanoidRootPart")
        if h then
            local sz = h.Size.Y
            if S.shNormalChar ~= c then S.shNormalChar = c; S.shNormalSize = sz end
            if not S.shNormalSize or sz > S.shNormalSize then S.shNormalSize = sz end
            if sz < S.shNormalSize * 0.97 then mul = mul * 0.7 end
        end
    end
    return math.max(base * mul, 8)
end
regSpawn(function()
    local conn, lastHum
    local function hook(hum)
        if hum == lastHum then return end
        lastHum = hum
        if conn then pcall(function() conn:Disconnect() end) end
        local function upd()
            local ws = hum.WalkSpeed
            if ws >= 1 then
                S.shSpeedBase = ws
                S.shTweenSpeed = math.max(ws * 0.85, 8)
            end
        end
        upd()
        conn = hum:GetPropertyChangedSignal("WalkSpeed"):Connect(upd)
        table.insert(_G.YattaConnections, conn)
    end
    local function onChar(ch)
        local hum = ch:FindFirstChildOfClass("Humanoid") or ch:WaitForChild("Humanoid", 5)
        if hum then hook(hum) end
    end
    table.insert(_G.YattaConnections, plr.CharacterAdded:Connect(function(ch) task.spawn(onChar, ch) end))
    if plr.Character then task.spawn(onChar, plr.Character) end
    while true do
        local ch  = plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if hum then hook(hum) end
        task.wait(0.5)
    end
end)

