            unlocking = S.shUnlocking, noEnter = S.shNoEnterUntil and (S.shNoEnterUntil > tick()) or false,
        }
        if #dbg > 40 then table.remove(dbg, 1) end
    end)
end
function S.shDecodingGen()
    local ch  = plr.Character
    local dec = ch and ch:FindFirstChild("Decoding")
    local v = dec and dec:IsA("ObjectValue") and dec.Value
    return v or nil
end
function S.shReleaseLock(maxT)
    local t0 = tick()
    while tick() - t0 < (maxT or 1.5) do
        local g = S.shDecodingGen()
        if not g then return true end
        pcall(R.fsg, g)
        pcall(R.fsgcr, g)
        task.wait(0.15)
    end
    return S.shDecodingGen() == nil
end

function S.shGrounded(hrp, hum)
    local ch = hrp.Parent
    local now = tick()
    local rp = S.shRP
    if not rp then
        rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.RespectCanCollide = true
        S.shRP = rp
    end
    if now - (S.shRPT or 0) > 1 or S.shRPChar ~= ch then
        S.shRPT, S.shRPChar = now, ch
        local skip = { ch }
        for _, c in ipairs(workspace:GetChildren()) do
            if string.sub(c.Name, 1, 5) == "Yatta" then skip[#skip + 1] = c end
        end
        rp.FilterDescendantsInstances = skip
    end
    local reach = ((hum and hum.HipHeight) or 2) + hrp.Size.Y / 2 + 3
    return workspace:Raycast(hrp.Position, Vector3.new(0, -reach, 0), rp) ~= nil
end

S.shHipH = S.shHipH
regSpawn(function()
    local conn, lastHum
