function S.shIsDecor(d)
    if not d or not d:IsA("BasePart") then return false end
    if (S.shCoverSet and S.shCoverSet[d]) or (S.shFloorSet and S.shFloorSet[d]) then return false end
    if d:IsA("MeshPart") then return true end
    local m = d:FindFirstAncestorOfClass("Model")
    if not m then return false end
    local room = workspace:FindFirstChild("CurrentRoom")
    if m == room or m.Parent == room then return false end
    return true
end
function S.shRayIgnoreDecor(origin, dir, skip)
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.RespectCanCollide = true
    local ex = table.clone(skip or {})
    rp.FilterDescendantsInstances = ex
    for _ = 1, 12 do
        local hit = workspace:Raycast(origin, dir, rp)
        if not hit then return nil end
        if not S.shIsDecor(hit.Instance) then return hit end
        ex[#ex + 1] = hit.Instance
        rp.FilterDescendantsInstances = ex
    end
    return nil
end
function S.shStandOffset(hrp, hum)
    local hip = S.shHipH
    if not hip and hum then hip = hum.HipHeight end
    return (hip or 2) + ((hrp and hrp.Size.Y / 2) or 1)
end
function S.shStandY(x, z, refY, part, hrp, hum)
    if S.shAir or not (hrp and hrp.Parent) then return nil end
    local now = tick()
    local c = S.shStandCache
    if c and c.part == part and now - c.t < 0.2 and math.abs(c.x - x) < 0.5 and math.abs(c.z - z) < 0.5 then return c.y end
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.RespectCanCollide = true
    local skip = { hrp.Parent }
    if part then skip[#skip + 1] = part end
    for _, w in ipairs(workspace:GetChildren()) do
        if string.sub(w.Name, 1, 5) == "Yatta" then skip[#skip + 1] = w end
    end
    rp.FilterDescendantsInstances = skip
    local hit = S.shRayIgnoreDecor(Vector3.new(x, refY + 1.2, z), Vector3.new(0, -18, 0), skip)
    local y
    if hit then
        local cand = hit.Position.Y + S.shStandOffset(hrp, hum)
        if math.abs(cand - refY) <= 9 then y = cand end
    end
    S.shStandCache = { part = part, x = x, z = z, t = now, y = y }
    return y
end
function S.shFitsAtFloor(part, x, z, refY, hrp, hum)
    local y = S.shStandY(x, z, refY, nil, hrp, hum)
    if not y then return true end
    local _, hhy = S.shHrpHalf(part, hrp)
    local lp = part.CFrame:PointToObjectSpace(Vector3.new(x, y, z))
    return math.abs(lp.Y) <= part.Size.Y / 2 - hhy + 0.05
end

function S.shTweenTo(hrp, target)
    if S.shTween then pcall(function() S.shTween:Cancel() end); S.shTween = nil end
    S.shTweening = true
    local gen = (S.shTweenGen or 0) + 1
    S.shTweenGen = gen
    local cancelled = false
    S.shTween = { Cancel = function() cancelled = true end }
    S.shTweenBeat = tick()
    task.spawn(function()
      local okT = pcall(function()
        local t0 = tick()
        while not S.noclip and tick() - t0 < 0.15 and S.shActive and S.shTweenGen == gen do task.wait() end
        local hum = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
        local rsv = game:GetService("RunService")
        local function holdingSprint()
            return S.sprintReal()
        end
        local ground0 = (S.shActive and S.shGroundY) or hrp.Position.Y   
        local baseWs = (not holdingSprint()) and math.max((hum and hum.WalkSpeed) or 16, 4) or nil
        if S.shActive and not holdingSprint() then
            S.shSprintTry = tick(); S.shSprintOwned = true
            pcall(R.FSprt, true)
        end
        local entered, entPart, entT0 = false, nil, tick()   
        local lagExpect = nil   
        local winT, winD, winTgt, held = tick(), nil, nil, 0
        local winLeg = nil
        local natural, natT, natStart, lastMt = false, 0, 0, 0
        local airT = nil
        while not cancelled and S.shActive and S.shTweenGen == gen and hrp.Parent do
            local dt   = math.min(rsv.Heartbeat:Wait(), 0.05)   
            S.shTweenBeat = tick()
            local sprinting = holdingSprint()
            if not natural then
                local cy = hrp.Position.Y
                local onFloor = entered or (cy < ground0 - 1) or S.shGrounded(hrp, hum)
                if onFloor then
                    if S.shAir then
                        S.shAir = false
                        pcall(function()
                            if S.shLV and S.shLV.Parent then S.shLV.Enabled = true end
                            if hum then hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false) end
                        end)
                    end
                    airT = nil
                else
                    airT = airT or tick()
                    if tick() - airT < 0.4 then
                        if not S.shAir then
                            S.shAir = true
                            pcall(function()
                                if S.shLV and S.shLV.Parent then S.shLV.Enabled = false end
                                if hum then hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end
                            end)
                        end
                        lagExpect = nil
                        winT, winD, winTgt, held = tick(), nil, nil, 0
                        continue
                    elseif S.shAir then
                        S.shAir = false
                        pcall(function() if S.shLV and S.shLV.Parent then S.shLV.Enabled = true end end)
                    end
                end
            end
            if S.shActive and not sprinting and tick() - (S.shSprintTry or 0) > 0.15 then
                S.shSprintTry = tick()
                if not S.shSprintOwned then S.shSprintOwned = true end
                pcall(R.FSprt, true)
            end
            local cur  = hrp.Position
            if lagExpect then
                local lx, lz = cur.X - lagExpect.X, cur.Z - lagExpect.Z
                if lx * lx + lz * lz > 36 or math.abs(cur.Y - lagExpect.Y) > 8 then
                    S.shLagbackT = tick()
                    local okL, cpL, partL = pcall(S.shPickCover, cur, 30, true)
                    if not (okL and cpL) then okL, cpL, partL = pcall(S.shPickCover, cur, 60, true) end
                    if okL and cpL then S.shPos = cpL; S.shPart = partL end
                end
                lagExpect = nil
            end
            local tgt  = S.shPos or target          
            local mv = tgt
            local cpart = S.shPart
            if cpart ~= entPart then entPart = cpart; entered = false; entT0 = tick() end
            if cpart and cpart.Parent and not entered and tick() - entT0 < 10 then
                local okE, ex, ez, inside = pcall(function()
                    local hhx, hhy, hhz = S.shHrpHalf(cpart, hrp)
                    local half = cpart.Size / 2
                    local lp = cpart.CFrame:PointToObjectSpace(Vector3.new(cur.X, cur.Y, cur.Z))
                    local function cl(v, h, ih) local m = math.max(h - ih, 0); return math.clamp(v, -m, m) end
                    local e = cpart.CFrame:PointToWorldSpace(Vector3.new(cl(lp.X, half.X, hhx), cl(lp.Y, half.Y, hhy), cl(lp.Z, half.Z, hhz)))
                    local dd = math.sqrt((e.X - cur.X) ^ 2 + (e.Z - cur.Z) ^ 2)
                    return e.X, e.Z, dd < 0.3
                end)
                if okE then
                    if inside then entered = true
                    else mv = Vector3.new(ex, tgt.Y, ez) end
                end
            end
            local finalLeg = (mv == tgt)
            local cdist = math.sqrt((tgt.X - cur.X) ^ 2 + (tgt.Z - cur.Z) ^ 2)   
            do
                local wsW = S.shSpeed()
                local spW = S.shPos or target
                local wdist = math.sqrt((mv.X - cur.X) ^ 2 + (mv.Z - cur.Z) ^ 2)
                if winD == nil or winTgt == nil or winLeg ~= finalLeg or math.abs(spW.X - winTgt.X) > 0.05 or math.abs(spW.Z - winTgt.Z) > 0.05 then
                    winT, winD, winTgt, held, winLeg = tick(), wdist, spW, 0, finalLeg
                elseif tick() - winT >= 0.5 then
                    if wdist > 0.8 and (winD - wdist) < wsW * 0.5 * 0.3 then held = held + 1 else held = 0 end
                    winT, winD = tick(), wdist
                end
                if held >= 2 and not natural then
                    natural, natT, natStart = true, tick(), tick()
                    S.shLagbackT = tick()
                    pcall(function() if S.shLV and S.shLV.Parent then S.shLV.Enabled = false end end)
                    local okN, cpN, partN = pcall(S.shPickCover, cur, 14, true)
                    if not (okN and cpN) then okN, cpN, partN = pcall(S.shPickCover, cur, 30, true) end
                    if okN and cpN then S.shPos = cpN; S.shPart = partN end
                end
            end
            if natural then
                local hdist0 = math.sqrt((mv.X - cur.X) ^ 2 + (mv.Z - cur.Z) ^ 2)
                lagExpect = nil
                if tick() - lastMt > 0.2 then
                    lastMt = tick()
                    pcall(function() if hum then hum:MoveTo(Vector3.new(mv.X, cur.Y, mv.Z)) end end)
                end
                if cdist < 0.7 or (finalLeg and hdist0 and hdist0 < 0.7) then break end
                if tick() - natT > 1.5 then
                    natT = tick()
                    local ok2, cp2, part2 = pcall(S.shPickCover, cur, 12, true)
                    if ok2 and cp2 and S.shPos and (cp2 - S.shPos).Magnitude > 1 then S.shPos = cp2; S.shPart = part2 end
                end
                if tick() - natStart > 3.5 then break end   
                continue
            end
            local hdiff = Vector3.new(mv.X - cur.X, 0, mv.Z - cur.Z)
            local hdist = hdiff.Magnitude
            local ws   = S.shSpeed()
            if cur.Y < ground0 - 1 and S.shFloorGoal(cpart, hrp) then ws = math.min(ws, 10) end
            local hstep = ws * dt
            local keep = hrp.CFrame - hrp.CFrame.Position
            local underway = false   
            local wantY = (cur.Y < ground0 - 1.5) and ground0 or cur.Y
            do
                if cpart and cpart.Parent then
                    local sy = S.shStandY(tgt.X, tgt.Z, cur.Y, cpart, hrp, hum)
                    if sy then wantY = sy end
                end
            end
            do
                local fy = S.shFloorGoal(cpart, hrp)
                if fy and (entered or hdist <= 1.2) then wantY = fy end
            end
            local dyv = wantY - cur.Y
            local curSpd = (hum and hum.WalkSpeed) or 16
            local diveV = math.max(math.min(curSpd, 14), 5)
            local riseV = diveV
            local newY = cur.Y + math.clamp(dyv, -diveV * dt, riseV * dt)
            local nx, nz = cur.X, cur.Z
            if hdist <= hstep then
                nx, nz = mv.X, mv.Z
            elseif not (underway and cur.Y > ground0 - 3) then      
                local u = hdiff.Unit
                nx, nz = cur.X + u.X * hstep, cur.Z + u.Z * hstep
            end
            if finalLeg and hdist <= hstep and math.abs(newY - wantY) < 0.05 then
                hrp.CFrame = CFrame.new(tgt.X, wantY, tgt.Z) * keep
                break
            end
            hrp.CFrame = CFrame.new(nx, newY, nz) * keep
            hrp.AssemblyLinearVelocity = Vector3.zero
            lagExpect = Vector3.new(nx, newY, nz)
        end
        if natural then pcall(function() if S.shLV and S.shLV.Parent then S.shLV.Enabled = true end end) end
        if S.shAir then
            S.shAir = false
            pcall(function() if S.shLV and S.shLV.Parent then S.shLV.Enabled = true end end)
        end
        if S.shTweenGen == gen then
            S.shTween = nil; S.shTweening = false
            pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero end)
            S.shSprintStop()
        end
      end)
      if not okT then
        S.shAir = false
        pcall(function() if S.shLV and S.shLV.Parent then S.shLV.Enabled = true end end)
        if S.shTweenGen == gen then S.shTween = nil; S.shTweening = false end
      end
    end)
end


regSpawn(function()
    local since
