                if tick() - since >= 2 then
                    since = nil
                    pcall(function()
                        local top = S.shRayIgnoreDecor(Vector3.new(pos.X, up.Position.Y + 30, pos.Z), Vector3.new(0, -60, 0), skip)
                        local y = (top and top.Position.Y or up.Position.Y) + 3.5
                        local keep = hrp.CFrame - hrp.CFrame.Position
                        hrp.AssemblyLinearVelocity = Vector3.zero
                        hrp.CFrame = CFrame.new(pos.X, y, pos.Z) * keep
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    end)
                end
            else
                since = nil
            end
        end
    end
end)

function S.safeHideEnter(hrp, hold, depth, kind)
    if not S.safeHide and not S.shByPathfind then return false end
    if IsPanicActive() then return false end
    if kind ~= "decode" then pcall(S.shSprintNow, hrp) end
    if S.encounterActive then return false end
    if S.shFleeing then return false end
    if kind == "decode" then return false end
    if tick() < (S.shHurtUntil or 0) then return false end
    if S.shDecodingGen() then
        if not S.shUnlocking then
            S.shUnlocking = true
            S.shLog("decodeHide")
            regSpawn(function()
                pcall(S.shReleaseLock, 2)
                S.shUnlocking = false
            end)
        end
    end
    pcall(S.shSprintNow, hrp)
    pcall(S.shSpeedRefresh)
    local now = tick()
    depth = depth or SH_DEPTH_SEEN
    local isDecode = (kind == "decode")
    if S.shActive then
        if isDecode then S.shDecodeUntil = math.max(S.shDecodeUntil or 0, now + (hold or 3))
        else S.shSeenUntil = math.max(S.shSeenUntil or 0, now + (hold or 3)) end
        if now - (S.shRevT or 0) > 0.25 then
            S.shRevT = now
            pcall(S.shRepick, hrp)
        end
        return true
    end
    if not (hrp and hrp.Parent) then return false end
    local hum = hrp.Parent:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    local p = hrp.Position
    if S.shNoEnterUntil and now < S.shNoEnterUntil then return false end
    local cpEarly, spotKind, coverPart = nil, nil, nil
    if S.shSearching and now - (S.shSearchT or 0) > 12 then S.shSearching = false end
    if not isDecode and S.shSearching then return false end
    if not isDecode then cpEarly, spotKind, coverPart = S.shPickSpot(p) end
    if not cpEarly or spotKind ~= "cover" then
        if not isDecode and not S.shSearching then
            S.shSearching = true
            S.shSearchT = now
            regSpawn(function()
              pcall(function()
                local untilT = tick() + math.max(hold or 3, 3) + 2
                while tick() < untilT and (S.safeHide or S.shByPathfind) and not S.shActive do
                    task.wait(0.2)
                    local ch2 = plr.Character
                    local h2 = ch2 and ch2:FindFirstChild("HumanoidRootPart")
                    if not h2 then break end
                    pcall(S.shSprintNow, h2)
                    local nearT = false
                    local okT, clearT = pcall(S.shDetClear, h2.Position)
                    if okT and clearT == false then nearT = true end
                    if not nearT then local okN, nn = pcall(S.shNearNow); if okN and nn then nearT = true end end
                    if not nearT then local okDn, dN = pcall(S.shNearestTwistedDist, h2.Position); if okDn and dN and dN < 45 then nearT = true end end
                    if nearT then
                        untilT = math.max(untilT, tick() + 3)
                        pcall(S.shNoSpotFlee, h2)
                    end
                    local okS, sp2, sk2 = pcall(S.shPickSpot, h2.Position)
                    if okS and sp2 and sk2 == "cover" then
                        S.shSearching = false
                        S.safeHideEnter(h2, hold, depth, kind)
                        return
                    end
                end
              end)
              S.shSearching = false
            end)
        end
        return false
    end
    S.shEnterT = now
    S.shNeedSpot = false
    S.shSpotKind = spotKind
    local hx, hz = shPickXZ(p.X, p.Z)
    S.shRet      = hrp.CFrame
    S.shBaseY    = p.Y
    S.shGroundY  = p.Y
    S.shTwY      = shTwistedY(p)
    local y0
    if isDecode then y0 = p.Y - SH_DEPTH_DECODE
    else y0 = math.min((S.shTwY or p.Y) - SH_DEPTH_SEEN, p.Y - 3) end
    S.shPos  = cpEarly
    S.shPart = coverPart
    S.shMode = "cover"
    S.shDodgeSpeedUntil = now + 1.5
    S.shSeenUntil   = isDecode and 0 or (now + (hold or 3))
    S.shDecodeUntil = isDecode and (now + (hold or 3)) or 0
    S.shMaxUntil = math.huge
    S.shNextDodge = 0
    S.shHops = 0
    S.shActive = true
    pcall(function()
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
        hum:ChangeState(Enum.HumanoidStateType.Running)
        if spotKind == "cover" then
            shUpdatePlatform(hum, hrp, S.shPos)
            local att = Instance.new("Attachment")
            att.Name = "YattaSafeHideAtt"
            att.Parent = hrp
            local lv = Instance.new("LinearVelocity")
            lv.Name = "YattaSafeHideLV"
            lv.Attachment0 = att
            lv.RelativeTo = Enum.ActuatorRelativeTo.World
            lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
            lv.MaxForce = math.huge
            lv.VectorVelocity = Vector3.zero
            lv.Parent = hrp
            S.shAtt, S.shLV = att, lv
        end
        hrp.AssemblyLinearVelocity = Vector3.zero
        S.shTweenTo(hrp, S.shPos)
    end)
    return true
end


do
    local RS = game:GetService("RunService")
    local qCh, qIds, qIdsT, qNonQ = nil, {}, 0, {}
    local hookedAn, hookConn = nil, nil
    local function refreshIds(ch)
        local now = os.clock()
        if qCh == ch and now - qIdsT < 2 then return end
        qCh, qIdsT, qIds, qNonQ = ch, now, {}, {}
        local cfg = ch:FindFirstChild("Animations")
        if cfg then
            local hitIds = {}
            for _, d in ipairs(cfg:GetDescendants()) do
                if d:IsA("Animation") and d.AnimationId ~= "" then
                    local hit, cur = false, d
                    while cur and cur ~= cfg do
                        if string.find(string.lower(cur.Name), "quirk", 1, true) then hit = true; break end
                        cur = cur.Parent
                    end
                    if hit then hitIds[d.AnimationId] = true else qNonQ[d.AnimationId] = true end
                end
            end
            for id in pairs(hitIds) do
                if not qNonQ[id] then qIds[id] = true end
            end
        end
    end
    local function isQuirk(t)
        local a = t.Animation
        local id = a and a.AnimationId
        if id and id ~= "" and qIds[id] then return true end
        if id and id ~= "" and qNonQ[id] then return false end
        return string.find(string.lower(t.Name .. " " .. (a and a.Name or "")), "quirk", 1, true) ~= nil
    end
    function _G.YattaQuirkSet(ch)
        refreshIds(ch)
        return qIds
    end
    function _G.YattaIsQuirkTrack(t) return isQuirk(t) end
    local mvCache = setmetatable({}, { __mode = "k" })
    local mvT, mvIdleSince, mvStartT, mvGrace = 0, nil, nil, 0
    function S.scriptWalkNow()
        if S.buyWalking == true then return true end
        local pf = _G.yattaPF
        return S.pathfindMode == true and S.autoEnabled == true and pf ~= nil and pf.active == true
    end
    function S.animFeatureOn()
        if R.isR then return (S.autoRunSolo or S.autoJoinRun or S.autoJoinMatch) and true or false end
        return S.scriptWalkNow()
    end
    local mvActive = false
    local function strictMoving(hum, hrp)
        if not (hum and hrp) or hum.Sit or hum.PlatformStand or hum.Health <= 0 then return false end
        if not R.isR then
            if not S.scriptWalkNow() then return false end
            return hum.MoveDirection.Magnitude > 0.05
        end
        if hum.MoveDirection.Magnitude > 0.05 then return true end
        if S.shVelActive or S.shTweening or S.wasteWalkActive or S.buyWalking == true then return true end
        local v = hrp.AssemblyLinearVelocity
        return (v.X * v.X + v.Z * v.Z) > 64
    end
    local function releaseMoveAnim()
        for _, tr in pairs(mvCache) do
            if tr.IsPlaying then pcall(function() tr:Stop(0.1) end) end
        end
    end
    local function ensureMoveAnim(ch, hum, hrp)
        if not R.isR then return end
        if not strictMoving(hum, hrp) then return end
        local an = hum and hum:FindFirstChildOfClass("Animator")
        if not an then return end
        local stats = ch:FindFirstChild("Stats")
        local hs = stats and stats:FindFirstChild("HoldingSprint")
        local running = S.sprintReal()
        local name = _G.YattaMoveAnimName(ch, running)
        local cfgF = ch:FindFirstChild("Animations")
        local anim = cfgF and cfgF:FindFirstChild(name)
        if not (anim and anim:IsA("Animation")) then return end
        for a2, tr2 in pairs(mvCache) do
            if a2 ~= anim and tr2.IsPlaying then pcall(function() tr2:Stop(0.15) end) end
        end
        local mine = mvCache[anim]
        if mine and mine.IsPlaying then return end
        for _, t in ipairs(an:GetPlayingAnimationTracks()) do
            if t ~= mine and t.Animation and t.Animation.AnimationId == anim.AnimationId and t.WeightCurrent > 0.2 then return end
        end
        local tr = mvCache[anim]
        if not tr then
            local ok, lt = pcall(function() return an:LoadAnimation(anim) end)
            if not (ok and lt) then return end
            lt.Priority = Enum.AnimationPriority.Movement
            lt.Looped = true
            mvCache[anim] = lt
            tr = lt
        end
        if not tr.IsPlaying then pcall(function() tr:Play(0.1); tr:AdjustSpeed(1) end) end
    end
    local function walkingNow(hum, hrp)
        if hum.Sit or hum.PlatformStand then return false end
        if hum.MoveDirection.Magnitude > 0.05 then return true end
        if S.shVelActive or S.shTweening or S.wasteWalkActive then return true end
        if S.buyWalking == true then return true end
        local v = hrp.AssemblyLinearVelocity
        if v.X * v.X + v.Z * v.Z > 4 then
            local st = hum:GetState()
            if st ~= Enum.HumanoidStateType.Freefall and st ~= Enum.HumanoidStateType.Jumping then return true end
        end
        return false
    end
    regC(RS.Heartbeat, function()
        local ch  = plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        local an  = hum and hum:FindFirstChildOfClass("Animator")
        if not (an and hrp and hum.Health > 0) then return end
        if an ~= hookedAn then
            hookedAn = an
            if hookConn then pcall(function() hookConn:Disconnect() end) end
            hookConn = an.AnimationPlayed:Connect(function(t)
                if not S.animFeatureOn() then return end
                local c2 = plr.Character
                local h2 = c2 and c2:FindFirstChildOfClass("Humanoid")
                local r2 = c2 and c2:FindFirstChild("HumanoidRootPart")
                if h2 and r2 and walkingNow(h2, r2) then
                    refreshIds(c2)
                    if isQuirk(t) then
                        pcall(function() t:Stop(0) end)
                        ensureMoveAnim(c2, h2, r2)
                    end
                end
            end)
            table.insert(_G.YattaConnections, hookConn)
        end
        if not S.animFeatureOn() then
            if mvActive then mvActive = false; releaseMoveAnim() end
            mvIdleSince, mvStartT = nil, nil
            return
        end
        mvActive = true
        local nowM = os.clock()
        if not strictMoving(hum, hrp) then
            if not mvIdleSince then
                mvIdleSince = nowM
                mvGrace = (R.isR and mvStartT and (nowM - mvStartT) < 0.5) and 0.12 or 0
                mvStartT = nil
            end
            if nowM - mvIdleSince >= mvGrace then releaseMoveAnim() end
        else
            mvIdleSince = nil
            mvStartT = mvStartT or nowM
            if nowM - mvT > 0.05 then mvT = nowM; ensureMoveAnim(ch, hum, hrp) end
        end
        if not walkingNow(hum, hrp) then return end
        refreshIds(ch)
        local stoppedQuirk = false
        for _, t in ipairs(an:GetPlayingAnimationTracks()) do
            if isQuirk(t) then pcall(function() t:Stop(0) end); stoppedQuirk = true end
        end
        if stoppedQuirk then ensureMoveAnim(ch, hum, hrp) end
    end)
end

do
    local function animActive()
        if R.isR then return (S.autoRunSolo or S.autoJoinRun or S.autoJoinMatch) and true or false end
        return S.scriptWalkNow and S.scriptWalkNow() or false
    end
    local tracks, animChar = {}, nil
    local function lobbyTrack(ch, hum, name)
        if animChar ~= ch then
            for _, t in pairs(tracks) do pcall(function() t:Stop(0) end) end
            animChar, tracks = ch, {}
        end
        local t = tracks[name]
        if t then return t end
        local an = hum:FindFirstChildOfClass("Animator")
        if not an then an = Instance.new("Animator"); an.Parent = hum end
        local cfg  = ch:FindFirstChild("Animations")
        local anim = cfg and cfg:FindFirstChild(name)
        if not (anim and anim:IsA("Animation")) then return nil end
        local ok, tr = pcall(function() return an:LoadAnimation(anim) end)
        if not ok or not tr then return nil end
        tr.Priority = Enum.AnimationPriority.Action
        tr.Looped   = true
        tracks[name] = tr
        return tr
    end
    local function lobbyStopAll()
        for _, t in pairs(tracks) do
            if t.IsPlaying then pcall(function() t:Stop(0.15) end) end
        end
    end
    local quirkT = 0
    regC(game:GetService("RunService").Heartbeat, function()
        if not animActive() then return end
        local nowQ = os.clock()
        if nowQ - quirkT < 0.1 then return end
        quirkT = nowQ
        local ch  = plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        local an  = hum and hum:FindFirstChildOfClass("Animator")
        if not (an and hrp) then return end
        local v = hrp.AssemblyLinearVelocity
        if not (hum.MoveDirection.Magnitude > 0.1 or (v.X * v.X + v.Z * v.Z) > 4) then return end
        local qset = _G.YattaQuirkSet and _G.YattaQuirkSet(ch) or {}
        for _, t in ipairs(an:GetPlayingAnimationTracks()) do
            local a = t.Animation
            local nm = string.lower(t.Name .. " " .. (a and a.Name or ""))
            if _G.YattaIsQuirkTrack(t) then
                pcall(function() t:Stop(0) end)
            end
        end
    end)
    regSpawn(function()
        while true do
            task.wait(0.1)
            if not animActive() then
                if next(tracks) ~= nil then lobbyStopAll(); table.clear(tracks) end
                if R.isR then task.wait(0.4) end
                continue
            end
            local ch  = plr.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if not (hum and hrp and hum.Health > 0) then lobbyStopAll(); continue end
            local v  = hrp.AssemblyLinearVelocity
            local sp = math.sqrt(v.X * v.X + v.Z * v.Z)
            if not (hum.MoveDirection.Magnitude > 0.1 or sp > 2) or hum.Sit or hum.PlatformStand then
                lobbyStopAll(); continue
            end
            local stats = ch:FindFirstChild("Stats")
            local hs = stats and stats:FindFirstChild("HoldingSprint")
            local running = S.sprintReal()
            local want = _G.YattaMoveAnimName(ch, running)
            for nm, tO in pairs(tracks) do
                if nm ~= want and tO.IsPlaying then pcall(function() tO:Stop(0.15) end) end
            end
            local tr = lobbyTrack(ch, hum, want)
            if tr and not tr.IsPlaying then
                pcall(function() tr:Play(0.15); tr:AdjustSpeed(1) end)
            end
        end
    end)
end

function shMonsterDetectorClear(pos, margin, exact)
    margin = margin or 0
    local monsT = R.mons or P.mons
    if type(monsT) ~= "table" then return true end
    do
        local okPk, nearPk = pcall(S.pumpkinThreat, pos)
        if okPk and nearPk then return false, "RollingPumpkin", 0, S.pumpkinRadius or 45 end
    end
    local function counts(m, cfg)
        return cfg and not cfg.isGrab and not _G.YattaRZ.ignored(m, cfg) and m ~= S.wasteTarget
            and not (m.Name == "GourdyMonster" and not S.gourdyThreat(m))
            and not (m.Name == "GlistenMonster" and not (m:GetAttribute("GlistenActivated") == true and m:GetAttribute("GlistenInitialized") == true))
    end
    local seenM = {}
    local function check(m, mpos)
        if not mpos then return false end
        local cfg = monsT[m.Name]
        if not counts(m, cfg) then return false end
        local radius = (cfg.detRadius or C.detectorRadius or 40) + margin
        if S.safeHide and S.autoEnabled and not exact then radius = math.min(radius, 25) end
        local d = (mpos - pos).Magnitude
        if d <= radius then return true, m.Name, d, radius end
        return false
    end
    for obj in pairs(S.extraMons or {}) do
        if obj.Parent and obj:IsA("Model") and not seenM[obj] then
            seenM[obj] = true
            local part = obj.PrimaryPart or obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChildWhichIsA("BasePart", true)
            local hit, nm, dd, rr = check(obj, part and part.Position)
            if hit then return false, nm, dd, rr end
        end
    end
    if exact or tick() - (Cache.lastWorldScanTime or 0) > 1.5 then
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return true end
        for _, room in ipairs(cr:GetChildren()) do
            local mf = room:FindFirstChild("Monsters")
            if mf then
                for _, m in ipairs(mf:GetChildren()) do
                    if m:IsA("Model") and not seenM[m] then
                        seenM[m] = true
                        local part = m.PrimaryPart or m:FindFirstChild("HumanoidRootPart") or m:FindFirstChildWhichIsA("BasePart")
                        local hit, nm, dd, rr = check(m, part and part.Position)
                        if hit then return false, nm, dd, rr end
                    end
                end
            end
        end
        return true
    end
    local mon = Cache.monsterPositions
    if not mon then return true end
    for i = 1, #mon do
        local e = mon[i]
        local model = e and e.model
        if model and model.Parent and not seenM[model] then
            local part = e.livePart
            local mpos = (part and part.Parent) and part.Position or e.pos
            local hit, nm, dd, rr = check(model, mpos)
            if hit then return false, nm, dd, rr end
        end
    end
    return true
end

S.shDetClear = shMonsterDetectorClear
function shTwistedNear(pos, margin, exact)
    if not pos then return false end
    local ok, clear = pcall(shMonsterDetectorClear, pos, margin, exact)
    return ok and clear == false
end
S.shTwistedNear = shTwistedNear

function shExitInner(noReturn)
    if not S.shActive then return end
    if S.shExiting then return end
    S.shExiting = true

    local fleeAfter = false
    if not noReturn then
        local waitT0 = tick()
        while S.shActive do
            if not S.safeHide and not S.shByPathfind then break end
            local nearNow = false
            do
                local ch00 = plr.Character
                local hrp00 = ch00 and ch00:FindFirstChild("HumanoidRootPart")
                nearNow = (hrp00 and shTwistedNear(hrp00.Position, 5)) or false   
            end
            if not nearNow then
                local okS, sn = pcall(S.seenNow)
                if okS and sn then nearNow = true end
            end
            if not nearNow then
                local okN, nn = pcall(S.shNearNow)
                if okN and nn then nearNow = true end
            end
            if tick() - waitT0 > 8 and not nearNow then
                break
            end
            if nearNow then
                S.shMaxUntil = tick()
            elseif tick() - waitT0 > 4 then
                break
            end
            local ch0 = plr.Character
            local hrp0 = ch0 and ch0:FindFirstChild("HumanoidRootPart")
            local hum0 = ch0 and ch0:FindFirstChildOfClass("Humanoid")
            if not (hrp0 and hum0 and hum0.Health > 0) then break end
            if S.encounterActive or IsPanicActive() then break end
            if nearNow then
                S.shLastThreat = tick()
                S.shClearSince = nil
                S.shExiting = false
                return
            end
            local returnPos = hrp0.Position   
            local okC, clear = pcall(shMonsterDetectorClear, returnPos, 5)
            if not okC then clear = true end
            if clear and S.shPos then
                local okC2, c2 = pcall(shMonsterDetectorClear, S.shPos, 5)
                clear = (not okC2) or c2
            end
            if clear and not nearNow then break end
            task.wait(0.10)
        end
    end

    S.shActive = false
    S.shLastExit = tick()
    S.shTweenGen = (S.shTweenGen or 0) + 1
    if S.shTween then pcall(function() S.shTween:Cancel() end); S.shTween = nil end
    S.shTweening = false
    local ch = plr.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if hrp and S.shGroundY and hrp.Position.Y < S.shGroundY - 1 and not noReturn then
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            local cur = hrp.Position
            local keep = hrp.CFrame - cur
            S.shTeleporting = true
            R.TpTo(hrp, CFrame.new(cur.X, S.shGroundY, cur.Z) * keep)
            S.shTeleporting = false
        end)
    end
    shCleanup(hum)
    if hrp and hum then
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
        end)
        S.shWatchGetUp(4)
    end
    S.shRet = nil
    S.shExiting = false
end

function S.safeHideExit(noReturn)
    S.shSprintStop()
    local ok, err = pcall(shExitInner, noReturn)
    if not ok then
        local ch = plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        pcall(shCleanup, hum)
        S.shTeleporting = false
        S.shActive = false
        S.shRet = nil
        S.shExiting = false
    end
end

S.regGame(function()
    local strayT, lastHp
    while true do
        task.wait(0.2)
        pcall(function()
            local ch  = plr.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if not (hum and hrp and hum.Health > 0) then strayT = nil; lastHp = nil; return end
            if lastHp and S.shActive and hum.Health < lastHp - 0.5 then
                S.shLastThreat = tick() + 1.5
                S.shSeenUntil = math.max(S.shSeenUntil or 0, tick() + 3)
                if tick() - (S.shHitRepickT or 0) >= 2.5 and tick() - (S.shSpotT or 0) >= 1.0 then
                    S.shHitRepickT = tick()
                    local sp, sk, spPart = S.shPickSpot(hrp.Position)
                    if sp and sk == "cover" then
                        if not (S.shPos and S.shPart and S.shPart.Parent) or S.shSwitchOk(hrp, sp) then
                            S.shPos, S.shPart, S.shSpotKind = sp, spPart, sk
                            S.shSpotT = tick()
                            S.shDodgeSpeedUntil = tick() + 1.5
                            S.shNextDodge = tick() + 1.5
                        end
                    else
                        S.shNeedSpot = true
                    end
                end
            end
            lastHp = hum.Health
            if (S.shActive or S.shTweening) and S.shGroundY and S.shRet
               and hrp.Position.Y < S.shGroundY - (SH_DEPTH_SEEN + 6) then
                S.shTeleporting = true
                pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero; R.TpTo(hrp, S.shRet) end)
                S.shTeleporting = false
                pcall(S.safeHideExit, true)
                return
            end
            local legit = S.shActive or S.shExiting or S.shTeleporting or S.shTweening or S.shFleeing
                or S.pickingUp or S.collectBusy or S.encounterActive or avBusy or (fs and fs.flying)
            if legit then strayT = nil; return end
            local stray = (S.shLV and S.shLV.Parent) ~= nil
                or hrp:FindFirstChild("YattaSafeHideLV") ~= nil or hrp:FindFirstChild("YattaSafeHideAtt") ~= nil
                or hrp:FindFirstChild("YattaFleeLV") ~= nil or hrp:FindFirstChild("YattaAVBrake") ~= nil
            if not stray and hum.PlatformStand then
                local near = false
                for _, m in ipairs(Cache.monsterPositions or {}) do
                    local mp = m.livePart and m.livePart.Parent and m.livePart.Position or m.pos
                    if mp and (mp - hrp.Position).Magnitude < 12 then near = true; break end
                end
                stray = not near
            end
            if not stray then strayT = nil; return end
            strayT = strayT or tick()
            if tick() - strayT < 1.2 then return end
            strayT = nil
            pcall(S.shVelStop)
            shCleanup(hum)
            for _, n in ipairs({ "YattaSafeHideLV", "YattaSafeHideAtt", "YattaFleeLV", "YattaFleeAtt", "YattaAVBrake", "YattaAVAttachment" }) do
                local o = hrp:FindFirstChild(n)
                if o then pcall(function() o:Destroy() end) end
            end
            shGetUp(hum, hrp)
        end)
    end
end)

function S.shSpotOk(hrp)
    local part, pos = S.shPart, S.shPos
    if not (hrp and part and part.Parent and pos) then return false end
    if S.shBlockedName(part) then return false end
    if not (S.shTenOk(pos.X, pos.Z) and S.shPumpkinOk(pos.X, pos.Z) and S.shSproutOk(pos.X, pos.Z)) then return false end
    local p = hrp.Position
    local mons = Cache.monsterPositions
    if mons then
        for m = 1, #mons do
            local e = mons[m]
            if e.farmEligible then
                local lpart = e.livePart
                local mp = (lpart and lpart.Parent and lpart.Position) or e.pos
                if mp then
                    local dx, dz = mp.X - pos.X, mp.Z - pos.Z
                    if dx * dx + dz * dz < 100 then return false end
                    local sx, sz2 = pos.X - p.X, pos.Z - p.Z
                    local sl = sx * sx + sz2 * sz2
                    if sl > 2.25 then
                        local tt = math.clamp(((mp.X - p.X) * sx + (mp.Z - p.Z) * sz2) / sl, 0, 1)
                        local cx, cz = p.X + sx * tt - mp.X, p.Z + sz2 * tt - mp.Z
                        if cx * cx + cz * cz < 49 then return false end
                    end
                end
            end
        end
    end
    return true
end

S.shBigHit = { DyleMonster = true, DandyMonster = true, GourdyMonster = true }
S.SH_COMMIT = 2.0
function S.shSpotHard(hrp)
    local part, pos = S.shPart, S.shPos
    if not (hrp and part and part.Parent and pos) then return true end
    if S.shBlockedName(part) then return true end
    if not (S.shTenOk(pos.X, pos.Z) and S.shPumpkinOk(pos.X, pos.Z) and S.shSproutOk(pos.X, pos.Z)) then return true end
    local mons = Cache.monsterPositions
    if mons then
        for m = 1, #mons do
            local e = mons[m]
            if e.farmEligible then
                local lpart = e.livePart
                local mp = (lpart and lpart.Parent and lpart.Position) or e.pos
                if mp then
                    local r = (e.model and S.shBigHit[e.model.Name]) and 9 or 5
                    local dx, dz = mp.X - pos.X, mp.Z - pos.Z
                    if dx * dx + dz * dz < r * r then return true end
                end
            end
        end
    end
    return false
end

function S.shSwitchOk(hrp, sp)
    local p = hrp.Position
    local mons = Cache.monsterPositions
    if not mons then return true end
    local hard
    for m = 1, #mons do
        local e = mons[m]
        if e.farmEligible then
            local lpart = e.livePart
            local mp = (lpart and lpart.Parent and lpart.Position) or e.pos
            if mp then
                local dx, dz = mp.X - p.X, mp.Z - p.Z
                local d = math.sqrt(dx * dx + dz * dz)
                if d < 22 then
                    if d < 12 then
                        if hard == nil then hard = S.shSpotHard(hrp) end
                        if not hard then return false end
                    end
                    local sx, sz = sp.X - p.X, sp.Z - p.Z
                    local sl = math.sqrt(sx * sx + sz * sz)
                    if sl > 1.5 then
                        local dot = (sx * dx + sz * dz) / (sl * math.max(d, 0.01))
                        if dot > 0.35 then return false end
                        local tt = math.clamp((dx * sx + dz * sz) / (sl * sl), 0, 1)
                        local cx, cz = sx * tt - dx, sz * tt - dz
                        local r = (e.model and S.shBigHit[e.model.Name]) and 12 or 9
                        if cx * cx + cz * cz < r * r then return false end
                    end
                end
            end
        end
    end
    return true
end

function S.shRepick(hrp, force)
    if not (S.shActive and hrp and hrp.Parent) then return false end
    if not force then
        if S.shSpotOk(hrp) then S.shNeedSpot = false; return true end
        if S.shPos and S.shPart and tick() - (S.shSpotT or 0) < S.SH_COMMIT and not S.shSpotHard(hrp) then
            return true
        end
    end
    local sp, sk, part = S.shPickSpot(hrp.Position)
    if sp and sk == "cover" then
        local changed = force or (not S.shPos)
            or Vector3.new(sp.X - S.shPos.X, 0, sp.Z - S.shPos.Z).Magnitude > 1.0 or part ~= S.shPart
        if changed and S.shPos and not force and S.shPart and S.shPart.Parent and not S.shSwitchOk(hrp, sp) then
            return true
        end
        if changed then
            S.shPos, S.shPart, S.shSpotKind = sp, part, sk
            S.shNeedSpot = false
            S.shNextDodge = tick() + 0.3
            S.shSpotT = tick()
        end
        return true
    end
    S.shNeedSpot = true
    return false
end

