function S.hideAway(hrp, base, hold)
    if S.safeHide then return S.safeHideEnter(hrp, hold or 3, SH_DEPTH_SEEN, "seen") end
    return TeleportToBaseWithRetry(hrp, base)
end

if R.isR then
regSpawn(function()
    local PFS = game:GetService("PathfindingService")
    local blockedUntil = {}
    local getElevators, directMove
    local wantC, wantT, wantG = false, 0, nil
    local lastCompute = 0
    local lastChar
    local respawnConn = plr.CharacterAdded:Connect(function()
        table.clear(blockedUntil)
        wantG = nil; wantT = 0; wantC = false; lastCompute = 0
    end)
    local function gateParts(g)
        local gate = g:FindFirstChild("Gate")
        local el   = g:FindFirstChild("Elevator")
        local base = el and el:FindFirstChild("Base")
        if not (gate and gate:IsA("BasePart") and base and base:IsA("BasePart")) then return nil end
        local d = Vector3.new(base.Position.X - gate.Position.X, 0, base.Position.Z - gate.Position.Z)
        if d.Magnitude < 0.1 then return nil end
        return gate, base, d.Unit
    end
    local function gateCount(g)
        local bp  = g:FindFirstChild("billboardPart")
        local gui = bp and bp:FindFirstChild("billboardGui")
        local fr  = gui and gui:FindFirstChild("Frame")
        local lb  = fr and fr:FindFirstChild("players")
        local t = (lb and lb:IsA("TextLabel")) and lb.Text or ""
        return tonumber(t:match("(%d+)%s*/%s*%d+"))
    end
    local function gateMax(g)
        local bp  = g:FindFirstChild("billboardPart")
        local gui = bp and bp:FindFirstChild("billboardGui")
        local fr  = gui and gui:FindFirstChild("Frame")
        local lb  = fr and fr:FindFirstChild("players")
        local t = (lb and lb:IsA("TextLabel")) and lb.Text or ""
        return tonumber(t:match("%d+%s*/%s*(%d+)"))
    end
    local friendCache, friendBusy = {}, {}
    local function isFriend(p)
        local v = friendCache[p.UserId]
        if v ~= nil then return v end
        if not friendBusy[p.UserId] then
            friendBusy[p.UserId] = true
            task.spawn(function()
                local ok, r = pcall(function() return plr:IsFriendsWith(p.UserId) end)
                if ok then friendCache[p.UserId] = (r == true) end
                friendBusy[p.UserId] = nil
            end)
        end
        return false
    end
    local function friendsIn(g)
        if not S.autoRunAllowFriends then return 0 end
        local _, base = gateParts(g)
        if not base then return 0 end
        local n = 0
        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
            if p ~= plr and isFriend(p) then
                local hrp = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                if hrp and p:GetAttribute("InLobby") == true then
                    local rel = base.CFrame:PointToObjectSpace(hrp.Position)
                    local sz  = base.Size
                    if math.abs(rel.X) <= sz.X / 2 + 4 and math.abs(rel.Z) <= sz.Z / 2 + 4 and math.abs(rel.Y) <= 20 then
                        n = n + 1
                    end
                end
            end
        end
        return n
    end
    local function strangers(g, inside)
        local c = math.max((gateCount(g) or 0) - (inside and 1 or 0), 0)
        if S.autoRunAllowFriends then c = math.max(c - friendsIn(g), 0) end
        return c
    end
    local function joinOk(g)
        local c, m = gateCount(g) or 0, gateMax(g)
        return not (m and c >= m)
    end
    local function gateUsable(g)
        if g:GetAttribute("Disabled") == true then return false end
        local el = g:FindFirstChild("Elevator")
        local op = el and el:FindFirstChild("Opened")
        if op and op:IsA("BoolValue") and op.Value == false then return false end
        return true
    end
    local function inElevator() return plr:GetAttribute("InLobby") == true end
    local function leaveGate()
        local ok = false
        if S.isXeno then
            local Net = S.gcModule and S.gcModule("Post", "Network")
            if Net then ok = pcall(function() Net:Post("LeaveGate") end) end
        else
            local eL
            ok, eL = pcall(function()
                require(game:GetService("ReplicatedStorage").SharedUtils.Network):Post("LeaveGate")
            end)
            if not ok then S.requireFailed(eL) end
        end
        if not ok then
            pcall(function()
                local b = plr.PlayerGui.MainGui.leaveButton
                if firesignal then firesignal(b.MouseButton1Down) end
            end)
        end
    end
    local function voteMatch()
        local ok = false
        if S.isXeno then
            local Net = S.gcModule and S.gcModule("Post", "Network")
            if Net then ok = pcall(function() Net:Post("VoteMatch") end) end
        else
            local eL
            ok, eL = pcall(function()
                require(game:GetService("ReplicatedStorage").SharedUtils.Network):Post("VoteMatch")
            end)
            if not ok then S.requireFailed(eL) end
        end
        if not ok then
            pcall(function()
                local b = plr.PlayerGui.MainGui.fillParty
                if firesignal then firesignal(b.MouseButton1Down) end
            end)
        end
    end
    local mmVoted, mmWarned = false, false
    local function matchVote()
        if mmVoted then return end
        if game:GetService("ReplicatedStorage"):GetAttribute("MatchmakingEnabled") ~= true then
            if not mmWarned then
                mmWarned = true
                pcall(ui.Notify, "Matchmaking is turned off in the game right now, waiting in the elevator.")
            end
            return
        end
        local mg = plr.PlayerGui:FindFirstChild("MainGui")
        local fp = mg and mg:FindFirstChild("fillParty")
        if not (fp and fp.Visible) then return end
        mmVoted = true
        voteMatch()
    end
    local function nearestGate(pos)
        local elevs = getElevators()
        if not elevs or #elevs == 0 then return nil end
        local best, bd
        for _, g in ipairs(elevs) do
            local _, base = gateParts(g)
            if base then
                local d = (base.Position - pos).Magnitude
                if not bd or d < bd then best, bd = g, d end
            end
        end
        return best
    end
    local function pickGate(pos)
        local elevs = getElevators()
        if not elevs or #elevs == 0 then return nil end
        local best, bd
        for _, g in ipairs(elevs) do
            local gate = gateParts(g)
            local solo = S.autoRunSolo
            if gate and gateUsable(g) and tick() >= (blockedUntil[g] or 0)
               and ((solo and strangers(g, false) == 0) or (not solo and joinOk(g))) then
                local d = (gate.Position - pos).Magnitude
                if not solo then d = d - (gateCount(g) or 0) * 1000 end
                if solo and S.autoRunAllowFriends then
                    local fi = friendsIn(g)
                    if fi > 0 then
                        if not joinOk(g) then d = nil else d = d - fi * 100000 end
                    end
                end
                if d then
                if not bd or d < bd then best, bd = g, d end
                end
            end
        end
        return best
    end
    local function stillWanted(g)
        local now = os.clock()
        if wantG == g and now - wantT < 0.2 then return wantC end
        local r
        if inElevator() or not gateUsable(g) then r = false
        elseif S.autoRunSolo then
            r = strangers(g, false) == 0
            if r and S.autoRunAllowFriends and friendsIn(g) == 0 then
                local elevs = workspace:FindFirstChild("Elevators")
                for _, o in ipairs(elevs and elevs:GetChildren() or {}) do
                    if o ~= g and gateUsable(o) and joinOk(o) and strangers(o, false) == 0 and friendsIn(o) > 0 then
                        r = false; break
                    end
                end
            end
        else r = (S.autoJoinRun == true or S.autoJoinMatch == true) and joinOk(g) end
        wantG, wantT, wantC = g, now, r
        return r
    end
    local function flat(a, b)
        local dx, dz = a.X - b.X, a.Z - b.Z
        return math.sqrt(dx * dx + dz * dz)
    end
    local function followPath(g, path, hum, hrp)
        local wps = path:GetWaypoints()
        local n = #wps
        if n == 0 then return "done" end
        local JUMP = Enum.PathWaypointAction.Jump
        local blockedAt = 0
        local conn = path.Blocked:Connect(function(i) blockedAt = i end)
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.RespectCanCollide = true
        rp.FilterDescendantsInstances = { plr.Character }

        local function segDist(p, a, b)
            local abx, abz = b.X - a.X, b.Z - a.Z
            local l2 = abx * abx + abz * abz
            local t = 0
            if l2 > 0 then t = math.clamp(((p.X - a.X) * abx + (p.Z - a.Z) * abz) / l2, 0, 1) end
            local dx, dz = p.X - (a.X + abx * t), p.Z - (a.Z + abz * t)
            return math.sqrt(dx * dx + dz * dz)
        end

        local function clear(pos, target)
            local d = Vector3.new(target.X - pos.X, 0, target.Z - pos.Z)
            local dist = d.Magnitude
            if dist < 0.5 then return true end
            local dir = d.Unit
            if workspace:Raycast(pos - Vector3.new(0, 2.5, 0), dir * dist, rp) then return false end
            return true
        end

        local function carrot(pos, idx, look)
            local remaining, from, j = look, pos, idx
            while true do
                local to = wps[j].Position
                if wps[j].Action == JUMP or j >= n then return to, j end
                local seg = flat(from, to)
                if seg >= remaining then
                    return from:Lerp(to, remaining / math.max(seg, 0.01)), j
                end
                remaining = remaining - seg
                from = to
                j = j + 1
            end
        end

        local function hugsPath(pos, target, idx, j)
            for k = idx, j - 1 do
                if segDist(wps[k].Position, pos, target) > 1.2 then return false end
            end
            return true
        end

        local result = "done"
        local idx = 1
        local jumpedAt = 0
        local t0 = os.clock()
        local total = 0
        for k = 2, n do total = total + flat(wps[k].Position, wps[k - 1].Position) end
        local limit = total / math.max(hum.WalkSpeed, 8) + 8
        local lastPos, lastCheck, stalls = hrp.Position, os.clock(), 0
        local lastRecompute = 0

        hum:MoveTo(wps[math.min(2, n)].Position)

        while true do
            if not stillWanted(g) or hum.Health <= 0 then result = "cancel"; break end
            local pos = hrp.Position
            local now = os.clock()

            while idx < n and wps[idx].Action ~= JUMP
                  and (flat(pos, wps[idx].Position) < 3
                       or (flat(pos, wps[idx + 1].Position) < flat(wps[idx].Position, wps[idx + 1].Position)
                           and math.abs(wps[idx + 1].Position.Y - wps[idx].Position.Y) < 2.5
                           and segDist(wps[idx].Position, pos, wps[idx + 1].Position) <= 1.2
                           and clear(pos, wps[idx + 1].Position))) do
                idx = idx + 1
            end

            if idx >= n and flat(pos, wps[n].Position) < 3.2 and math.abs(pos.Y - wps[n].Position.Y) < 7 then break end

            if blockedAt > 0 and blockedAt >= idx and now - lastRecompute > 1 then
                conn:Disconnect()
                return "recompute"
            end

            if now - t0 > limit then result = "stuck"; break end

            if wps[idx].Action == JUMP and jumpedAt ~= idx and flat(pos, wps[idx].Position) < 4.5 then
                jumpedAt = idx
                hum.Jump = true
            end
            if wps[idx].Action == JUMP and flat(pos, wps[idx].Position) < 2 and jumpedAt == idx then
                idx = math.min(idx + 1, n)
            end

            local target = wps[idx].Position
            for _, look in ipairs({ 7, 4.5, 2.5 }) do
                local c, j = carrot(pos, idx, look)
                if hugsPath(pos, c, idx, j) and clear(pos, c) then target = c; break end
            end

            hum:MoveTo(target)

            if now - lastCheck > 0.5 then
                if (pos - lastPos).Magnitude < 1 then
                    stalls = stalls + 1
                    hum.Jump = true
                    if stalls >= 3 and now - lastRecompute > 2 then
                        conn:Disconnect()
                        return "recompute"
                    end
                else
                    stalls = 0
                end
                lastPos, lastCheck = pos, now
            end

            task.wait(0.05)
        end

        conn:Disconnect()
        return result
    end
    local function walkStraight(g, dest, hum, hrp)
        local t0 = os.clock()
        local lastPos, lastCheck = hrp.Position, os.clock()
        local stuckCount = 0
        hum:MoveTo(dest)
        while os.clock() - t0 < 10 do
            if not stillWanted(g) or hum.Health <= 0 then return false end
            if flat(hrp.Position, dest) < 3.5 then return true end
            local now = os.clock()
            if now - lastCheck > 0.4 then
                local moved = (hrp.Position - lastPos).Magnitude
                if moved < 0.8 then
                    stuckCount = stuckCount + 1
                    hum.Jump = true
                    hum:MoveTo(dest)
                    if stuckCount >= 3 then
                        local offset = Vector3.new(math.random(-3, 3), 0, math.random(-3, 3))
                        hum:MoveTo(dest + offset)
                    end
                else
                    stuckCount = 0
                end
                lastPos, lastCheck = hrp.Position, now
            end
            task.wait(0.03)
        end
        return false
    end
    local function walkTo(g, dest, hum, hrp)
        if flat(hrp.Position, dest) < 3.5 then return true end
        local gate, _, inside = gateParts(g)
        local dests = { dest }
        if gate and inside then
            dests[#dests + 1] = gate.Position - inside * 4
            dests[#dests + 1] = gate.Position - inside * 14
        end
        local radii = { 2.5, 1.6, 0.9 }
        local fails = 0
        local recomputeCount = 0
        for _ = 1, 7 do
            if not stillWanted(g) or hum.Health <= 0 then return false end
            local gap = 0.3 - (os.clock() - lastCompute)
            if gap > 0 then task.wait(gap) end
            if not stillWanted(g) or hum.Health <= 0 then return false end
            lastCompute = os.clock()
            local radius = radii[math.min(fails + 1, #radii)]
            local target = dests[(fails % #dests) + 1]
            local path = PFS:CreatePath({ AgentRadius = radius, AgentHeight = 5.5, AgentCanJump = true, WaypointSpacing = 6 })
            local okP = pcall(function() path:ComputeAsync(hrp.Position, target) end)
            if okP and path.Status == Enum.PathStatus.Success then
                local r = followPath(g, path, hum, hrp)
                if r == "done" then return true end
                if r == "cancel" then return false end
                if r == "recompute" then
                    recomputeCount = recomputeCount + 1
                    if recomputeCount >= 3 then
                        fails = fails + 1
                        recomputeCount = 0
                        if fails >= 3 then break end
                    end
                    continue
                end
                if r == "stuck" then
                    fails = fails + 1
                    if fails >= 3 then break end
                    continue
                end
            else
                fails = fails + 1
                if fails >= 3 then break end
            end
        end
        return directMove(g, dest, hum, hrp)
    end

    function directMove(g, dest, hum, hrp)
        local t0 = os.clock()
        local lastPos, lastCheck = hrp.Position, os.clock()
        local stuckCount = 0
        hum:MoveTo(dest)
        while os.clock() - t0 < 12 do
            if not stillWanted(g) or hum.Health <= 0 then return false end
            if flat(hrp.Position, dest) < 3.5 then return true end
            local now = os.clock()
            if now - lastCheck > 0.3 then
                local moved = (hrp.Position - lastPos).Magnitude
                if moved < 0.5 then
                    stuckCount = stuckCount + 1
                    hum.Jump = true
                    hum:MoveTo(dest)
                    if stuckCount >= 2 then
                        local offset = Vector3.new(math.random(-2, 2), 0, math.random(-2, 2))
                        hum:MoveTo(dest + offset)
                    end
                else
                    stuckCount = 0
                end
                lastPos, lastCheck = hrp.Position, now
            end
            task.wait(0.02)
        end
        return false
    end
    local elevatorsCache, elevatorsCacheT = nil, 0
    function getElevators()
        local now = tick()
        if elevatorsCache and now - elevatorsCacheT < 2 and #elevatorsCache > 0 then return elevatorsCache end
        elevatorsCache = workspace:FindFirstChild("Elevators") and workspace.Elevators:GetChildren() or {}
        if #elevatorsCache > 0 then elevatorsCacheT = now end
        return elevatorsCache
    end
    local function step()
        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not (hrp and hum and hum.Health > 0) then return end
        if ch ~= lastChar then
            lastChar = ch
            table.clear(blockedUntil)
            wantC, wantT, wantG = false, 0, nil
            lastCompute = 0
            task.wait(0.5)
            return
        end
        if inElevator() then
            local g = nearestGate(hrp.Position)
            if S.autoRunSolo and g and strangers(g, true) > 0 then
                blockedUntil[g] = tick() + 20
                pcall(ui.Notify, "Someone joined the elevator, leaving it.")
                leaveGate()
                local t0 = tick()
                while inElevator() and tick() - t0 < 5 do task.wait(0.1) end
                task.wait(1)
            end
            if S.autoJoinMatch then pcall(matchVote) end
            return
        end
        mmVoted, mmWarned = false, false
        local g = pickGate(hrp.Position)
        if not g then task.wait(1); return end
        local gate, _, inside = gateParts(g)
        if not gate then blockedUntil[g] = tick() + 2; return end
        local reached = walkTo(g, gate.Position - inside * 8, hum, hrp)
        if plr.Character ~= ch or hum.Health <= 0 then return end
        if reached and stillWanted(g) then
            hum:MoveTo(gate.Position + inside * 4)
            local t0 = tick()
            while (S.autoRunSolo or S.autoJoinRun or S.autoJoinMatch) and not inElevator() and plr.Character == ch and hum.Health > 0
                  and tick() - t0 < 6 do task.wait(0.1) end
            if plr.Character == ch and hum.Health > 0 and not inElevator() then blockedUntil[g] = tick() + 8 end
        elseif not inElevator() then
            blockedUntil[g] = tick() + (((gateCount(g) or 0) > 0) and 20 or 5)
        end
    end
    while true do
        task.wait(0.25)
        if S.autoRunSolo or S.autoJoinRun or S.autoJoinMatch then
            local okStep = pcall(step)
            if not okStep then task.wait(1) end
        end
    end
end)
end

if not R.isR then
regSpawn(function()
    local RunSvc = game:GetService("RunService")
    local PFSvc  = game:GetService("PathfindingService")
    local curInst, enterT = nil, 0
