            return require(game:GetService("ReplicatedStorage").Modules.GenArcade.SwimmyBarnaby)
        end)
        if not okMod then S.requireFailed(GA) end
    end
    local hookOk = okMod and type(GA) == "table"
    if okMod and type(GA) == "table" then
        GA.__yattaBarnSeen = function(self)
            if rawget(self, "Fish") ~= nil and rawget(self, "Disconnected") ~= true and curInst ~= self then
                curInst = self; enterT = tick()
            end
        end
        if not GA.__yattaBarnWrapped then
            GA.__yattaBarnWrapped = true
            local names = {}
            for k, v in pairs(GA) do
                if type(k) == "string" and type(v) == "function" and k:sub(1, 2) ~= "__" and k ~= "new" and k ~= "Bootup" then
                    names[#names + 1] = k
                end
            end
            for _, k in ipairs(names) do
                local orig = rawget(GA, k)
                if type(orig) == "function" then
                    GA[k] = function(self, ...)
                        if self ~= GA and type(self) == "table" then
                            local seenFn = GA.__yattaBarnSeen
                            if seenFn then pcall(seenFn, self) end
                        end
                        return orig(self, ...)
                    end
                end
            end
        end
        GA.__yattaBarnCb = function(self) curInst = self; enterT = tick() end
        if not GA.__yattaBarnHook then
            GA.__yattaBarnHook = true
            local origBoot = GA.Bootup
            GA.Bootup = function(self, ...)
                local cb = GA.__yattaBarnCb
                if cb then pcall(cb, self) end
                return origBoot(self, ...)
            end
        end
    end

    local geo = setmetatable({}, {__mode = "k"})
    local function bounds(m)
        local c = geo[m]
        if not c then
            local maxx, lo, hi = -math.huge, -math.huge, math.huge
            local px = m:GetPivot().Position.X
            for _, p in ipairs(m:GetDescendants()) do
                if p:IsA("BasePart") and p.CanQuery then
                    local cf, sz = p.CFrame, p.Size
                    local hy = (math.abs(cf.RightVector.Y) * sz.X + math.abs(cf.UpVector.Y) * sz.Y + math.abs(cf.LookVector.Y) * sz.Z) / 2
                    local hx = (math.abs(cf.RightVector.X) * sz.X + math.abs(cf.UpVector.X) * sz.Y + math.abs(cf.LookVector.X) * sz.Z) / 2
                    local pos = cf.Position
                    maxx = math.max(maxx, pos.X + hx)
                    if pos.Y < 0 then lo = math.max(lo, pos.Y + hy) else hi = math.min(hi, pos.Y - hy) end
                end
            end
            c = {dx = maxx - px, lo = lo, hi = hi}
            geo[m] = c
        end
        return m:GetPivot().Position.X + c.dx, c.lo, c.hi
    end
    local tuneAt, tuneG, tuneFl = 0, 0.75, 0.01
    local function barnOn() return S.autoBarnaby or S.autoBarnabyGlide end

    local coinCache = setmetatable({}, {__mode = "k"})
    local function coinParts(m)
        local c = coinCache[m]
        if c and (#c > 0 or tick() - c.t > 1) then return c end
        if not c then c = {t = tick()}; coinCache[m] = c end
        for _, d in ipairs(m:GetDescendants()) do
            if d:IsA("BasePart") and string.find(string.lower(d.Name), "coin", 1, true) then c[#c + 1] = d end
        end
        return c
    end
    local function findCoin(inst, fx)
        local bestC, bestX, bestP
        for _, o in ipairs(inst._objects) do
            local m = o.Model
            if m and not o.Destroyed and m.Parent then
                local nm = string.lower(m.Name)
                if string.find(nm, "coin", 1, true) or string.find(nm, "gold", 1, true) then
                    local okP, pos = pcall(function() return m:GetPivot().Position end)
                    if okP and pos.X > fx - 0.6 and (not bestX or pos.X < bestX) then bestC, bestX, bestP = pos, pos.X, nil end
                elseif nm == "obstacleset" then
                    for _, p in ipairs(coinParts(m)) do
                        if p.Parent then
                            local pos = p.Position
                            if pos.X > fx - 0.6 and (not bestX or pos.X < bestX) then bestC, bestX, bestP = pos, pos.X, p end
                        end
                    end
                end
            end
        end
        return bestC, bestP
    end

    local G_PMAX = math.rad(50)    
    local G_WN   = 10              
    local G_ZETA = 1.0             
    local G_TAU  = 0.28            

    local function glideTarget(inst, f, vx)
        local fx, y = f.Part.Position.X, f.Part.Position.Y
        local best, lo, hi = math.huge, -15, 15
        for _, o in ipairs(inst._objects) do
            local m = o.Model
            if m and m.Name == "ObstacleSet" and not o.Destroyed then
                local b, l, h = bounds(m)
                if b > fx - 0.6 and b < best then best, lo, hi = b, l, h end
            end
        end
        local safeLo, safeHi = lo + 1.2, hi - 1.0
        if safeHi < safeLo then safeLo = (lo + hi) / 2; safeHi = safeLo end
        local tgt = math.clamp((lo + hi) / 2, safeLo, safeHi)
        local coin, coinPart = findCoin(inst, fx)
        local useCoin = false
        if coin and (best == math.huge or coin.X <= best) and coin.Y >= safeLo and coin.Y <= safeHi then
            tgt = coin.Y; useCoin = true
        end
        local tau = G_TAU
        if useCoin then tau = math.clamp((coin.X - fx) / vx * 0.5, 0.12, G_TAU) end
        return tgt, tau, useCoin and coin or nil, useCoin and coinPart or nil
    end

    local function glideControl(inst, f, dt)
        dt = math.clamp(dt, 0, 1 / 20)
        if dt <= 0 then return end
        local cfg = inst.GAME_CONFIG
        local vx = (cfg and cfg.SCREEN_WIDTH) or 30
        local y = f.Part.Position.Y
        if tick() - tuneAt > 1 then
            tuneAt = tick()
            local info = workspace:FindFirstChild("Info")
            local g  = info and info:GetAttribute("BarnabyGravity");    tuneG  = type(g)  == "number" and g  or 0.75
            local fl = info and info:GetAttribute("BarnabyIntroFloat"); tuneFl = type(fl) == "number" and fl or 0.01
        end
        local gs = rawget(f, "__yG")
        if not gs or gs.sid ~= inst.SessionId then
            gs = { sid = inst.SessionId, pitch = math.atan2(f.Velocity_Y * 60, vx), rate = 0 }
            rawset(f, "__yG", gs)
        end
        local tgt, tau, coin, coinPart = glideTarget(inst, f, vx)
        local want = math.clamp(math.atan2((tgt - y) / tau, vx), -G_PMAX, G_PMAX)
        local n = math.max(1, math.ceil(dt / (1 / 120)))
        local h = dt / n
        for _ = 1, n do
            local acc = G_WN * G_WN * (want - gs.pitch) - 2 * G_ZETA * G_WN * gs.rate
            gs.rate  = gs.rate + acc * h
            gs.pitch = gs.pitch + gs.rate * h
        end
        gs.pitch = math.clamp(gs.pitch, -G_PMAX * 1.1, G_PMAX * 1.1)
        local grav = f.Acceleration_Y * tuneG * (f.Weightless and tuneFl or 1) * dt
        f.Velocity_Y = vx * math.tan(gs.pitch) / 60 - grav
        gs.coin, gs.coinPart = coin, coinPart
    end

    local function glideFace(inst, f)
        local gs = rawget(f, "__yG")
        if not gs then return end
        local part = f.Part
        part:PivotTo(CFrame.new(part.Position) * CFrame.Angles(0, 0, gs.pitch) * CFrame.Angles(0, math.pi, 0))
        local coin, coinPart = gs.coin, gs.coinPart
        if coin and coinPart and coinPart.Parent then
            local fp = part.Position
            if math.abs(coin.X - fp.X) < 1.6 and math.abs(coin.Y - fp.Y) < 1.8 then
                pcall(function() coinPart:PivotTo(part:GetPivot()) end)
            end
        end
    end

    local function installGlide(inst)
        local f = rawget(inst, "Fish")
        if not f or rawget(f, "__yHook") then return end
        rawset(f, "__yHook", true)
        local origTick = f.tick
        rawset(f, "tick", function(self, dt, ...)
            if not S.autoBarnabyGlide or self.Destroyed or self.IsSpinning or inst ~= curInst
               or inst.Disconnected ~= false or inst._countingDown or not rawget(inst, "SessionId") then
                rawset(self, "__yG", nil)
                return origTick(self, dt, ...)
            end
            pcall(glideControl, inst, self, dt)
            local r = origTick(self, dt, ...)
            if not self.Destroyed then pcall(glideFace, inst, self) end
            return r
        end)
    end

    local function flyTick(dt)
        if not S.autoBarnaby or S.autoBarnabyGlide then return end
        local inst = curInst
        if not inst then return end
        local f = rawget(inst, "Fish")
        if not f or f.Destroyed or not rawget(inst, "SessionId") or inst.Disconnected ~= false or inst._countingDown then return end
        local fx, y, v = f.Part.Position.X, f.Part.Position.Y, f.Velocity_Y
        local best, lo, hi = math.huge, -15, 15
        for _, o in ipairs(inst._objects) do
            local m = o.Model
            if m and m.Name == "ObstacleSet" and not o.Destroyed then
                local b, l, h = bounds(m)
                if b > fx - 0.6 and b < best then best, lo, hi = b, l, h end
            end
        end
        if tick() - tuneAt > 1 then
            tuneAt = tick()
            local info = workspace:FindFirstChild("Info")
            local g  = info and info:GetAttribute("BarnabyGravity");    tuneG  = type(g)  == "number" and g  or 0.75
            local fl = info and info:GetAttribute("BarnabyIntroFloat"); tuneFl = type(fl) == "number" and fl or 0.01
        end
        local g, fl = tuneG, tuneFl
        local a  = f.Acceleration_Y * g * (f.Weightless and fl or 1)
        local yn = y + math.max(-2, v + a * dt) * 60 * dt
        local rise = 60 / (2 * math.abs(f.Acceleration_Y * g))
        local ylow = math.min((lo + hi) / 2 - rise / 2, hi - 1.0 - rise)
        ylow = math.max(ylow, lo + 1.2)
        if v <= 0.2 and yn < ylow and S.autoBarnaby then
            f:Jump()
            pcall(inst.PlaySoundOneShot, inst, "Jump")
        end
    end
    flyTick = _G.YattaProf("flyTick", flyTick)
    regC(RunSvc.RenderStepped, function(dt)
        if curInst then
            if S.autoBarnabyGlide then pcall(installGlide, curInst)
            elseif S.autoBarnaby then pcall(flyTick, dt) end
        end
    end)
    regSpawn(function()
        while true do
            task.wait(0.2)
            local inst = curInst
            if barnOn() and inst and inst._objects then
                for _, o in ipairs(inst._objects) do
                    local m = o.Model
                    if m and m.Name == "ObstacleSet" and not o.Destroyed and not geo[m] then
                        pcall(bounds, m)
                        task.wait()
                    end
                end
            end
        end
    end)

    local function machineOf(gen)
        local pr = gen:FindFirstChild("Prompt")
        local att = pr and pr:FindFirstChild("Attachment")
        local pp = att and att:FindFirstChildOfClass("ProximityPrompt")
        if not (pp and pp.Enabled) then return nil end
        local st = gen:FindFirstChild("Stats")
        local done = st and st:FindFirstChild("Completed")
        if done and done.Value == true then return nil end
        local occ = st and st:FindFirstChild("ActivePlayer")
        if occ and occ.Value ~= nil and occ.Value ~= plr then return nil end
        return pp, pr
    end
    local function seated()
        local okG, g = pcall(R.gag)
        if okG and g and g.Parent and g:FindFirstChild("SwimmyBarnaby") then return true end
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return false end
        for _, rm in ipairs(cr:GetChildren()) do
            local gf = rm:IsA("Model") and rm:FindFirstChild("Generators")
            if gf then
                for _, gen in ipairs(gf:GetChildren()) do
                    if gen:IsA("Model") and gen:FindFirstChild("SwimmyBarnaby") then
                        local st  = gen:FindFirstChild("Stats")
                        local occ = st and st:FindFirstChild("ActivePlayer")
                        if occ and occ.Value == plr then return true end
                    end
                end
            end
        end
        return false
    end
    local lastGc, gcTries = 0, 0
    local function nfy(m, e) if _G.YattaNotify then pcall(_G.YattaNotify, m, e) end end
    local function giveUpBarn(why)
        gcTries = 0
        S.autoBarnaby = false; S.autoBarnabyGlide = false
        for _, tg in ipairs({ ui.autoBarnabyTog, ui.autoBarnabyGlideTog }) do
            if tg and tg.SetState then pcall(tg.SetState, false) end
        end
        nfy("Auto Barnaby: " .. why, true)
    end
    local function tryCapture()
        if curInst then return true end
        if tick() - lastGc < 1.5 then return false end
        lastGc = tick()
        gcTries = gcTries + 1
        if type(getgc) ~= "function" then
            if hookOk then gcTries = 0; return false end
            giveUpBarn("this executor can't read the game's Barnaby state.")
            return false
        end
        local okG, list = pcall(getgc, true)
        if okG and type(list) == "table" then
            for i = 1, #list do
                local t = list[i]
                if type(t) == "table" then
                    local okT, f = pcall(function()
                        if hookOk and t ~= GA then
                            local mt = getmetatable(t)
                            if type(mt) == "table" and (mt == GA or rawget(mt, "__index") == GA)
                               and rawget(t, "Fish") ~= nil and rawget(t, "Disconnected") ~= true then
                                return rawget(t, "Fish")
                            end
                        end
                        if rawget(t, "SessionId") == nil then return nil end
                        local fish = rawget(t, "Fish")
                        if type(fish) ~= "table" then return nil end
                        local part = rawget(fish, "Part")
                        if typeof(part) ~= "Instance" or not part.Parent or rawget(fish, "Destroyed") then return nil end
                        if rawget(t, "Disconnected") == true then return nil end
                        return fish
                    end)
                    if okT and f then
                        curInst = t; enterT = tick(); gcTries = 0
                        nfy("Auto Barnaby attached.", false)
                        return true
                    end
                end
            end
        end
        if gcTries >= (S.isXeno and 12 or 6) then
            if hookOk then
                gcTries = 0; lastGc = tick() + 3
                if tick() - (S.barnTryMsgT or 0) > 60 then
                    S.barnTryMsgT = tick()
                    nfy("Auto Barnaby: still attaching to the machine…", false)
                end
            else
                giveUpBarn("couldn't attach to the game (executor limitation).")
            end
        end
        return false
    end
    local function pickMachine(hrp)
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return nil end
        local best, bd
        for _, roomModel in ipairs(cr:GetChildren()) do
            local gf = roomModel:IsA("Model") and roomModel:FindFirstChild("Generators")
            if gf then
                for _, gen in ipairs(gf:GetChildren()) do
                    if gen:IsA("Model") and gen:FindFirstChild("SwimmyBarnaby") then
                        local pp, pr = machineOf(gen)
                        if pp then
                            local d = (pr.Position - hrp.Position).Magnitude
                            if not bd or d < bd then best, bd = {pp = pp, pr = pr}, d end
                        end
                    end
                end
            end
        end
        return best, bd
    end
    local function frontOf(pr, hrp)
        local off = hrp.Position - pr.Position
        local flat = Vector3.new(off.X, 0, off.Z)
        if flat.Magnitude < 0.01 then flat = Vector3.new(0, 0, 1) end
        return pr.Position + flat.Unit * 3
    end
    local function walkTo(hum, hrp, dest)
        for _ = 1, 3 do
            if not barnOn() or hum.Health <= 0 or (S.aeRunning and S.aeRunning()) then return false end
            local path = PFSvc:CreatePath({ AgentRadius = 2.5, AgentHeight = 5, AgentCanJump = true })
            local okP = pcall(function() path:ComputeAsync(hrp.Position, dest) end)
            if okP and path.Status == Enum.PathStatus.Success then
                local stuck = false
                for _, wp in ipairs(path:GetWaypoints()) do
                    if not barnOn() or hum.Health <= 0 or (S.aeRunning and S.aeRunning()) then return false end
                    if wp.Action == Enum.PathWaypointAction.Jump then hum.Jump = true end
                    hum:MoveTo(wp.Position)
                    local t0 = tick()
                    while true do
                        if not barnOn() or hum.Health <= 0 or (S.aeRunning and S.aeRunning()) then return false end
                        local dx, dz = hrp.Position.X - wp.Position.X, hrp.Position.Z - wp.Position.Z
                        if math.sqrt(dx * dx + dz * dz) < 3.5 then break end
                        if tick() - t0 > 3 then stuck = true; break end
                        task.wait(0.05)
                    end
                    if stuck then break end
                end
                local dx, dz = hrp.Position.X - dest.X, hrp.Position.Z - dest.Z
                if not stuck and math.sqrt(dx * dx + dz * dz) < 6 then return true end
            else
                task.wait(0.5)
            end
        end
        return false
    end

    while true do
        task.wait(0.3)
        if not barnOn() then continue end
        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not (hrp and hum and hum.Health > 0) then continue end

        if curInst then
            local f = rawget(curInst, "Fish")
            if curInst.Disconnected == false and f and not f.Destroyed then continue end
            if curInst.Disconnected == false and seated() then continue end
            if tick() - enterT < 10 then continue end
            curInst = nil
            task.wait(1.5)
            continue
        end

        if S.shBusy and S.shBusy() then continue end
        if IsPanicActive() then continue end
        if S.pickingUp or S.gigiBusy or S.collectBusy or S.totBusy then continue end
        if S.aeRunning and S.aeRunning() then continue end
        local okG, curGen = pcall(R.gag)
        if okG and curGen and curGen.Parent and not curGen:FindFirstChild("SwimmyBarnaby") then continue end

        if seated() then
            tryCapture()
            continue
        end
        gcTries = 0
        local okFa, faV = pcall(R.gfv)
        if okFa and faV and faV:IsA("BoolValue") and faV.Value == true then continue end
        if S.autoEnabled ~= true then continue end
        if S.pathfindMode then continue end
        local cab, d = pickMachine(hrp)
        if not cab then task.wait(2); continue end
        if d > 6 then
            local front = frontOf(cab.pr, hrp)
            pcall(function()
                hrp.AssemblyLinearVelocity = Vector3.zero
                R.TpTo(hrp, CFrame.new(front + Vector3.new(0, 3, 0)))
            end)
            task.wait(0.4)
        end
        local hd = cab.pp.HoldDuration
        cab.pp.HoldDuration = 0
        enterT = tick()
        pcall(fireproximityprompt, cab.pp)
        task.wait(0.2)
        cab.pp.HoldDuration = hd
        local t0 = tick()
        while barnOn() and not curInst and tick() - t0 < 5 do
            if S.isXeno and seated() then tryCapture() end
            task.wait(0.1)
        end
        if curInst then
            local t1 = tick()
            while barnOn() and curInst and curInst.Disconnected ~= false and tick() - t1 < 8 do task.wait(0.2) end
            if curInst and curInst.Disconnected ~= false then curInst = nil end
        end
    end
end)
end

regSpawn(function()
    local function syncTog(tg, v)
        if tg and tg.SetState and tg.GetState and tg.GetState() ~= v then pcall(tg.SetState, v) end
    end
    local prevFarm = S.autoEnabled == true
    while true do
        task.wait(0.3)
        local farm = S.autoEnabled == true
        if farm ~= prevFarm then
            prevFarm = farm
            if farm then
                if not isR and not S.isXeno and not S.autoBarnaby then syncTog(ui.autoBarnabyGlideTog, true); S.autoBarnabyGlide = true end
                if not S.pathfindMode then syncTog(ui.encounterTog, true); S.autoEncounter = true end
            else
                if not isR then
                    syncTog(ui.autoBarnabyTog, false); S.autoBarnaby = false
                    syncTog(ui.autoBarnabyGlideTog, false); S.autoBarnabyGlide = false
                end
                syncTog(ui.encounterTog, false);   S.autoEncounter = false
            end
        end
    end
end)

