function shFleeNoSpot(hrp, hum)
    do local okPn, pn = pcall(IsPanicActive); if okPn and pn then return end end
    local okD, dir = pcall(S.shEscapeDir, hrp)
    local nowF = tick()
    if okD and dir and dir.Magnitude > 0.01 then
        S.shFleeDir, S.shFleeDirT = dir, nowF
    elseif S.shFleeDir and nowF - (S.shFleeDirT or 0) < 3 then
        dir = S.shFleeDir
    else
        dir = nil
    end
    if not (S.shLV and S.shLV.Parent) then
        if dir then pcall(function() hum:MoveTo(hrp.Position + Vector3.new(dir.X, 0, dir.Z).Unit * 30) end) end
        return
    end
    if dir then
        local ws = math.max((hum and hum.WalkSpeed) or 16, 14)
        pcall(function() S.shLV.Enabled = true; S.shLV.VectorVelocity = Vector3.new(dir.X, 0, dir.Z).Unit * ws end)
    else
        pcall(function() S.shLV.VectorVelocity = Vector3.zero end)
    end
end
regSpawn(function()
    if R.isR then return end
    while true do
        task.wait(0.1)
        if not S.shActive then S.shLastDanger = nil; S.shLastPos = nil; S.shDangerPrev = false; continue end
        local ch = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not (hrp and hum and hum.Health > 0) then
            shCleanup(hum); S.shActive = false; S.shRet = nil
            continue
        end
        local now = tick()
        do
            local lp, lt = S.shLastPos, S.shLastPosT
            S.shLastPos, S.shLastPosT = hrp.Position, now
            if lp and lt and not S.shTeleporting and S.shMode == "cover" then
                local moved = (hrp.Position - lp).Magnitude
                if moved > 50 * (now - lt) + 8 then
                    local sp, sk, spPart = S.shPickSpot(hrp.Position)
                    if sp and sk == "cover" then
                        S.shPos, S.shPart, S.shSpotKind = sp, spPart, sk
                        S.shDodgeSpeedUntil = now + 1.5
                        S.shNextDodge = now + 1.5
                    end
                end
            end
        end
        local okP, pan = pcall(IsPanicActive)
        if S.encounterActive then
            S.safeHideExit(true)
            continue
        end
        local SH_CLEAR_HOLD = 0.8
        local threat = false
        do
            local okD, anyDanger = pcall(GetDangerState)
            if okD and anyDanger then
                S.shDangerPrev = true
                S.shLastDanger = now
                S.shSeenUntil  = math.max(S.shSeenUntil or 0, now + 2.5)
                threat = true
            else
                S.shDangerPrev = false
                S.shLastDanger = S.shLastDanger or now
            end
        end
        if not threat then
            local okS, sn = pcall(S.seenNow)
            if okS and sn then threat = true end
        end
        if not threat then
            local okS, sn = pcall(S.shNearNow)
            if okS and sn then threat = true end
        end
        if not threat then
            local okN, nearNow = pcall(shTwistedNear, hrp.Position, 5)
            if okN and nearNow then threat = true end
        end
        if threat then
            S.shLastThreat = now
            S.shClearSince = nil
            pcall(S.shSprintNow, hrp)
        elseif not S.shLastThreat or S.shLastThreat < (S.shEnterT or 0) then
            S.shLastThreat = S.shEnterT or now
        end
        if (not S.safeHide and not S.shByPathfind) or (okP and pan) then
            S.safeHideExit()
            continue
        end
        if not threat then
            if now - S.shLastThreat >= SH_CLEAR_HOLD then
                S.shClearSince = nil
                S.safeHideExit()
                continue
            end
            S.shClearSince = S.shClearSince or now
            if S.shTweening then
                S.shTweenGen = (S.shTweenGen or 0) + 1
                if S.shTween then pcall(function() S.shTween:Cancel() end); S.shTween = nil end
                S.shTweening = false
                pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero end)
            end
            pcall(S.shSprintStop)
            if S.shLV then pcall(function() S.shLV.VectorVelocity = Vector3.zero end) end
            continue
        end
        local seen = true
        local targetY
        if seen then
            local ty = shTwistedY(hrp.Position)
            if ty then S.shTwY = ty end
            targetY = math.min((S.shTwY or S.shBaseY) - SH_DEPTH_SEEN, S.shBaseY - 3)
        else
            targetY = S.shBaseY - SH_DEPTH_DECODE
        end
        if S.shPos then S.shPos = Vector3.new(S.shPos.X, hrp.Position.Y, S.shPos.Z) end
        if S.shMode == "cover" and S.shPart and S.shPart.Parent and S.shPos and not S.shTweening and not S.shAir
           and not (S.shFloorGoal and S.shFloorGoal(S.shPart, hrp)) and (S.shLevelNow or now - (S.shLevelT or 0) > 0.3) then
            S.shLevelNow = false; S.shLevelT = now
            local hp0 = hrp.Position
            local sy = S.shStandY(hp0.X, hp0.Z, hp0.Y, S.shPart, hrp, hum)
            if sy and math.abs(sy - hp0.Y) > 0.12 then
                local ny = hp0.Y + math.clamp(sy - hp0.Y, -0.5, 0.5)
                pcall(function()
                    local keepL = hrp.CFrame - hrp.CFrame.Position
                    hrp.CFrame = CFrame.new(hp0.X, ny, hp0.Z) * keepL
                    hrp.AssemblyLinearVelocity = Vector3.zero
                end)
                S.shPos = Vector3.new(S.shPos.X, ny, S.shPos.Z)
            end
        end
        if S.shMode == "cover" and S.shPart and (not S.shPart.Parent or S.shBlockedName(S.shPart)) then
            S.shCoverT = 0
            local sp0, sk0, spPart0 = S.shPickSpot(hrp.Position)
            if sp0 and sk0 == "cover" then
                S.shPos, S.shPart, S.shSpotKind = sp0, spPart0, sk0
            else
                S.shNeedSpot = true          
                S.shSeenUntil = math.max(S.shSeenUntil or 0, now + 1)
                shFleeNoSpot(hrp, hum)
                continue
            end
        end
        if S.shMode == "cover" and now >= (S.shRepickT or 0) then
            S.shRepickT = now + 0.15
            pcall(S.shRepick, hrp)
        end
        if S.shNeedSpot and S.shMode == "cover" and now >= (S.shSpotRetryT or 0) then   
            S.shSpotRetryT = now + 0.25
            local spN, skN, partN = S.shPickSpot(hrp.Position)
            if spN and skN == "cover" then
                S.shPos, S.shPart, S.shSpotKind = spN, partN, skN
                S.shNeedSpot = false
                S.shDodgeSpeedUntil = now + 1.5
                S.shNextDodge = now + 1.5
            end
        end
        if S.shNeedSpot and S.shMode == "cover" then
            if S.shTweening then
                S.shTweenGen = (S.shTweenGen or 0) + 1
                if S.shTween then pcall(function() S.shTween:Cancel() end); S.shTween = nil end
                S.shTweening = false
            end
            shFleeNoSpot(hrp, hum)
            continue
        end
        if S.shMode == "cover" and S.shPos and now >= (S.shNextDodge or 0)
           and (not S.shSproutOk(S.shPos.X, S.shPos.Z) or not S.shPumpkinOk(S.shPos.X, S.shPos.Z)) then
            S.shNextDodge = now + 1.5
            local sp, sk, spPart = S.shPickSpot(hrp.Position)
            if sp and sk == "cover" then
                S.shPos = sp
                S.shPart = spPart
                S.shSpotKind = sk
                S.shDodgeSpeedUntil = now + 1.5
            end
        end
        if S.shPos and S.shMode ~= "cover" then
            local cur = S.shPos
            local x, z = cur.X, cur.Z
            local dodgingTendril = false
            if now >= (S.shNextDodge or 0) and shTendrilClear(x, z) < SH_TEN_R - 2 then
                x, z = shPickXZ(x, z)
                S.shNextDodge = now + 0.4
                S.shDodgeSpeedUntil = now + 0.8
                dodgingTendril = true
            end
            local newY = cur.Y
            if math.abs(targetY - cur.Y) > 2.5 then newY = targetY end
            S.shPos = Vector3.new(x, newY, z)
        end
        local off = S.shPos - hrp.Position
        if S.shSpotKind == "cover" and not (S.shLV and S.shLV.Parent) then
            pcall(function()
                local att = Instance.new("Attachment"); att.Name = "YattaSafeHideAtt"; att.Parent = hrp
                local lv = Instance.new("LinearVelocity")
                lv.Name = "YattaSafeHideLV"; lv.Attachment0 = att
                lv.RelativeTo = Enum.ActuatorRelativeTo.World
                lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
                lv.MaxForce = math.huge; lv.VectorVelocity = Vector3.zero; lv.Parent = hrp
                S.shAtt, S.shLV = att, lv
            end)
        end
        pcall(function()
            local flat = Vector3.new(off.X, 0, off.Z).Magnitude
            if S.shTweening then
                shUpdatePlatform(hum, hrp, S.shPos)
            elseif S.shLagUntil and now < S.shLagUntil then
                shUpdatePlatform(hum, hrp, S.shPos)
            elseif flat > 1.2 then
                shUpdatePlatform(hum, hrp, S.shPos)
                S.shTweenTo(hrp, S.shPos)
            else
                shUpdatePlatform(hum, hrp, S.shPos)
                if S.shSpotKind == "cover" and S.shPart and S.shPart.Parent and now - (S.shEncaseT or 0) > 0.3
                   and not S.shEncased(hrp, S.shPart) then
                    S.shEncaseT = now
                    S.shPos = S.shInsidePoint(S.shPart, hrp.Position, hrp)
                    S.shTweenTo(hrp, S.shPos)
                end
            end
            if shIsDown(hum, hrp) then shGetUp(hum, hrp) end
            if S.shLV then S.shLV.VectorVelocity = Vector3.zero end
        end)
    end
end)
function S.shSidestep(hrp)
    do local okPn, pn = pcall(IsPanicActive); if okPn and pn then return end end
    local now = tick()
    if S.shSideT and now - S.shSideT < 0.25 then return end
    S.shSideT = now
    local hum = hrp.Parent and hrp.Parent:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local okEd, dir = pcall(S.shEscapeDir, hrp)
    if not okEd then dir = nil end
    if dir then
        S.shFleeDir, S.shFleeDirT = dir, now
    elseif S.shFleeDir and now - (S.shFleeDirT or 0) < 3 then
        dir = S.shFleeDir
    end
    if dir then
        local ws = hum.WalkSpeed
        if S.shFleeing then
            S.shVel(hrp, dir, ws)
        else
            if not S.shVel(hrp, dir, ws) then
                pcall(function() hum:MoveTo(hrp.Position + dir * 15) end)
                return
            end
            S.shVelStamp = (S.shVelStamp or 0) + 1
            local stamp = S.shVelStamp
            task.delay(0.35, function()
                if S.shVelStamp == stamp and not S.shFleeing then S.shVelStop() end
            end)
        end
    end
end

function S.shEscapeDir(hrp)
    local pos = hrp.Position
    local dir
    local okPk, hit, e = pcall(S.pumpkinThreat, pos, 45)
    if okPk and hit and type(e) == "table" then
        local rel = Vector3.new(pos.X - e.pos.X, 0, pos.Z - e.pos.Z)
        local v = e.vel
        if v.Magnitude > 3 then
            local perp = Vector3.new(-v.Z, 0, v.X).Unit
            if rel:Dot(perp) < 0 then perp = -perp end
            dir = perp
        elseif rel.Magnitude > 0.1 then
            dir = rel.Unit
        end
    else
        local mon = Cache.monsterPositions
        local rx, rz, bd, bp = 0, 0, math.huge, nil
        for i = 1, #mon do
            local mp = mon[i].livePart and mon[i].livePart.Parent and mon[i].livePart.Position or mon[i].pos
            local dx, dz, d = 0, 0, math.huge
            if mp then
                dx, dz = pos.X - mp.X, pos.Z - mp.Z
                d = math.sqrt(dx * dx + dz * dz)
            end
            if d < 70 and d > 0.1 then
                local w = 1 / (d * d)
                rx = rx + dx / d * w; rz = rz + dz / d * w
                if d < bd then bd = d; bp = mp end
            end
        end
        local rep = Vector3.new(rx, 0, rz)
        if rep.Magnitude > 1e-6 then
            dir = rep.Unit
        elseif bp then
            local away = Vector3.new(pos.X - bp.X, 0, pos.Z - bp.Z)
            if away.Magnitude > 0.1 then dir = away.Unit end
        end
    end
    return dir
end

table.insert(_G.YattaConnections, rs.Heartbeat:Connect(function()
    if not S.shActive or not S.shPos or S.encounterActive or S.shTweening then return end
    local ch  = plr.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local off = S.shPos - hrp.Position
    if false and math.abs(off.Y) > 3 and Vector3.new(off.X, 0, off.Z).Magnitude < 40 then
        local now = tick()
        if S.shLagUntil and now < S.shLagUntil then
            S.shSidestep(hrp)
            return
        end
        local sn = S.shSnaps or {}
        S.shSnaps = sn
        sn[#sn + 1] = now
        while #sn > 0 and now - sn[1] > 1.5 do table.remove(sn, 1) end
        if #sn >= 3 then
            S.shLagUntil = now + 3
            S.shSnaps = {}
            S.shSidestep(hrp)
            return
        end
        pcall(function()
            local keep = hrp.CFrame - hrp.CFrame.Position
            S.shTeleporting = true
            R.TpTo(hrp, CFrame.new(S.shPos) * keep)
            S.shTeleporting = false
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end))
end
function TriggerForceHide()
    if S.forceHideActive then return end
    if S.safeHide or S.shByPathfind or S.shActive then return end
    if not S.autoEnabled then return end
    S.forceHideActive = true
    local minW, maxW = C.seenHideMin or 10, C.seenHideMax or 15
    S.forceHideUntil = tick() + minW + math.random() * (maxW - minW)
    regSpawn(function()
        if S.safeHide then
            local hc0   = plr.Character
            local hhrp0 = hc0 and hc0.PrimaryPart
            if hhrp0 then
                S.safeHideEnter(hhrp0, math.max(0.5, S.forceHideUntil - tick()), 15, "seen")
                while tick() < S.forceHideUntil and S.safeHide do task.wait(0.3) end
            end
            S.forceHideActive = false
            return
        end
        for _ = 1, 3 do
            if S.safeHide or S.shByPathfind or not S.autoEnabled then break end
            local hc   = plr.Character
            local hhrp = hc and hc.PrimaryPart
            local base = R.fb()
            if hhrp and base and not S.pathfindMode then
                pcall(function() TeleportToBaseWithRetry(hhrp, base) end)
                if R.ibb(base, hhrp.Position) then break end
            end
            task.wait(0.3)
        end
        while tick() < S.forceHideUntil do
            task.wait(0.5)
            if S.safeHide or S.shByPathfind or not S.autoEnabled then break end
            local c2    = plr.Character
            local hrp2  = c2 and c2.PrimaryPart
            local base2 = R.fb()
            if hrp2 and base2 and not S.pathfindMode and not R.ibb(base2, hrp2.Position) then
                pcall(function() TeleportToBaseWithRetry(hrp2, base2) end)
            end
        end
        S.forceHideActive = false
    end)
end
do
function GetCurrentFloorNumber()
    local info = workspace:FindFirstChild("Info")
    local fv   = info and info:FindFirstChild("Floor")
    if fv and fv:IsA("IntValue") then return fv.Value end
    return nil
end
regSpawn(function()
    if R.isR then return end
    while true do
        task.wait(0.5)
        if not S.autoStopFloorEnabled then
            S.floorStopActive = false
            continue
        end
        local floorNum = GetCurrentFloorNumber()
        if not floorNum or floorNum < (S.autoStopFloor or 0) then
            S.floorStopActive = false
            continue
        end
        S.floorStopActive = true
        local fa = R.gfv()
        if not (fa and fa:IsA("BoolValue") and fa.Value == true) then
            continue
        end
        local char = plr.Character
        local hrp  = char and char.PrimaryPart
        local base = R.fb()
        if hrp and S.safeHide and not S.pathfindMode then
            pcall(S.safeHideEnter, hrp, 3, 15, "seen")
        elseif hrp and base and not S.pathfindMode then
            pcall(function() TeleportToBaseWithRetry(hrp, base) end)
        end
    end
end)
end
function TryTeleportToBaseIfIdle(hrp, currentBase)
    if not currentBase then return end
    if R.ibb(currentBase, hrp.Position) then return end
    local d = hrp.Position - currentBase.Position
    if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) < (K.baseSkip * K.baseSkip) then return end
    if tick() - (S.lastBaseTP or 0) >= C.baseTpLoopCd then
        S.lastBaseTP = tick()
        TeleportToBaseWithRetry(hrp, currentBase)
    end
end
function UpdateInventoryUI(invStats)
    local now = tick()
    local hc  = invStats.healingCount
    local tc  = R.gtc()
    local stam = Prev.cuStamina
    local stamFloor = (stam == math.huge) and -1 or math.floor(stam)
    local invChanged = (hc ~= Prev.lastInvHC) or (invStats.isFull ~= Prev.lastInvFull)
                    or (tc ~= Prev.invTapes)   or (stamFloor ~= Prev.invStam)
    local elapsed    = now - Prev.invUILastUpdate
    if not invChanged and elapsed < K.invuiInt then return hc end
    Prev.invUILastUpdate = now
    Prev.lastInvHC       = hc
    Prev.lastInvFull     = invStats.isFull
    if not ui.SlotLabels or #ui.SlotLabels == 0 then return hc end
    if invStats.noSlots then
        SetLabelVisible(ui.SlotLabels[1], true)
        SetLabelText(ui.SlotLabels[1], "No slots found.")
        SetLabelColor(ui.SlotLabels[1], Th.red)
        for i = 2, 4 do SetLabelVisible(ui.SlotLabels[i], false) end
    else
        for i = 1, 4 do
            local lbl = ui.SlotLabels[i]; local val = invStats.slotData[i]
            if val then
                SetLabelVisible(lbl, true)
                SetLabelText(lbl, "Slot "..i..": "..val)
                if val == "None" then SetLabelColor(lbl, Th.mgray)
                elseif val == "HealthKit" or val == "Bandage" then SetLabelColor(lbl, Th.green)
                else SetLabelColor(lbl, Th.lgray) end
            else SetLabelVisible(lbl, false) end
        end
    end
    if ui.healCountLbl and hc ~= Prev.invHc then
        Prev.invHc = hc
        local maxH = C.maxHeals or 2
        if hc >= maxH then
            SetLabelText(ui.healCountLbl,  "Heals: "..hc.." (Max)")
            SetLabelColor(ui.healCountLbl, Th.red)
        else
            SetLabelText(ui.healCountLbl,  "Heals: "..hc)
            SetLabelColor(ui.healCountLbl, Th.green)
        end
    end
    if ui.spLbl and tc ~= Prev.invTapes then
        Prev.invTapes = tc
        SetLabelText(ui.spLbl,  "Tapes: "..tc)
        SetLabelColor(ui.spLbl, tc > 0 and Th.yellow or Th.mgray)
    end
    if ui.staminaLbl and stamFloor ~= Prev.invStam then
        Prev.invStam = stamFloor
        if stam == math.huge then
            SetLabelText(ui.staminaLbl,  "Stamina: N/A")
            SetLabelColor(ui.staminaLbl, Th.mgray)
        else
            SetLabelText(ui.staminaLbl,  "Stamina: "..stamFloor)
            SetLabelColor(ui.staminaLbl, stamFloor <= C.staminaStopThreshold and Th.red or Th.purple)
        end
    end
    return hc
end
function applyGenUINA()
    SetLabelText(ui.genHalfLbl,  "Gen Progress: N/A"); SetLabelColor(ui.genHalfLbl, Th.mgray)
    if ui.genRestrictLbl then SetLabelText(ui.genRestrictLbl, "Valve/JumperCable: N/A");  SetLabelColor(ui.genRestrictLbl, Th.mgray) end
    if ui.valveLbl       then SetLabelText(ui.valveLbl,  "Valve: N/A");       SetLabelColor(ui.valveLbl,  Th.mgray) end
    if ui.jumperLbl      then SetLabelText(ui.jumperLbl, "JumperCable: N/A"); SetLabelColor(ui.jumperLbl, Th.mgray) end
    if ui.progActiveGenLbl   then SetLabelText(ui.progActiveGenLbl,   "Active Gen: None");     SetLabelColor(ui.progActiveGenLbl,   Th.mgray) end
    if ui.progGenProgressLbl then SetLabelText(ui.progGenProgressLbl, "Progress: N/A");        SetLabelColor(ui.progGenProgressLbl, Th.mgray) end
    if ui.progValveStatLbl   then SetLabelText(ui.progValveStatLbl,   "Valve: waiting");       SetLabelColor(ui.progValveStatLbl,   Th.mgray) end
    if ui.progJumperStatLbl  then SetLabelText(ui.progJumperStatLbl,  "JumperCable: waiting"); SetLabelColor(ui.progJumperStatLbl,  Th.mgray) end
    if ui.progGenSafeLbl     then SetLabelText(ui.progGenSafeLbl,     "Gen Safe: N/A");        SetLabelColor(ui.progGenSafeLbl,     Th.mgray) end
end
function UpdateGenUI(activeGen)
    if not ui.genHalfLbl then return false, false end
    if not activeGen then
        if Prev.genPct ~= "" or Prev.genSafe ~= nil then
            applyGenUINA(); Prev.genPct = ""; Prev.genSafe = nil
            Prev.genUILastUpdate = tick()
        end
        return false, false
    end
    local now = tick()
    if (now - Prev.genUILastUpdate) < K.genuiInt then
        local genCur2, genReq2, _ = GetCachedGenStats(activeGen)
        if genReq2 > 0 then
            local bh = genCur2 < (genReq2 / 2)
            return bh, not bh
        end
        return false, false
    end
    Prev.genUILastUpdate = now
    local genCur, genReq, _ = GetCachedGenStats(activeGen)
    local belowHalf, halfOrMore = false, false
    if genReq > 0 then
        halfOrMore = (genCur >= (genReq/2))
        belowHalf  = (genCur <  (genReq/2))
    end
    local pctStr = string.format("%d / %d (%.0f%%)", genCur, genReq,
        genReq > 0 and (genCur/genReq*100) or 0)
    local connFlag   = IsConnieGen(activeGen) and " [CONNIE]" or ""
    local displayStr = pctStr..connFlag
    if displayStr ~= Prev.genPct then
        Prev.genPct = displayStr
        SetLabelText(ui.genHalfLbl,
            IsConnieGen(activeGen) and ("Gen Progress: "..pctStr.." ⚠ CONNIE")
            or ("Gen Progress: "..pctStr))
        SetLabelColor(ui.genHalfLbl,
            IsConnieGen(activeGen) and Th.red
            or (halfOrMore and Th.green or Th.orange))
        local firing = belowHalf and "FIRING (< 50%)" or "WAITING (>= 50%)"
        if ui.genRestrictLbl then SetLabelText(ui.genRestrictLbl,"Valve/JumperCable: "..firing); SetLabelColor(ui.genRestrictLbl, belowHalf and Th.green or Th.mgray) end
        if ui.valveLbl  then SetLabelText(ui.valveLbl,  "Valve: "..(belowHalf and "FIRING (< 50%)" or "waiting")); SetLabelColor(ui.valveLbl,  belowHalf and Th.green or Th.mgray) end
        if ui.jumperLbl then SetLabelText(ui.jumperLbl, "JumperCable: "..(belowHalf and "FIRING (< 50%)" or "waiting")); SetLabelColor(ui.jumperLbl, belowHalf and Th.green or Th.mgray) end
        if ui.progActiveGenLbl   then SetLabelText(ui.progActiveGenLbl,   "Active Gen: "..activeGen.Name..connFlag); SetLabelColor(ui.progActiveGenLbl, IsConnieGen(activeGen) and Th.red or Th.green) end
        if ui.progGenProgressLbl then SetLabelText(ui.progGenProgressLbl, "Progress: "..pctStr); SetLabelColor(ui.progGenProgressLbl, halfOrMore and Th.green or Th.orange) end
        if ui.progValveStatLbl   then SetLabelText(ui.progValveStatLbl,   "Valve: "..(belowHalf and "FIRING" or "waiting")); SetLabelColor(ui.progValveStatLbl,  belowHalf and Th.green or Th.mgray) end
        if ui.progJumperStatLbl  then SetLabelText(ui.progJumperStatLbl,  "JumperCable: "..(belowHalf and "FIRING" or "waiting")); SetLabelColor(ui.progJumperStatLbl, belowHalf and Th.green or Th.mgray) end
    end
    local genSafe = R.igs(activeGen) and not IsConnieGen(activeGen)
    if genSafe ~= Prev.genSafe then
        Prev.genSafe = genSafe
        if ui.progGenSafeLbl then
            SetLabelText(ui.progGenSafeLbl,  "Gen Safe: "..(genSafe and "Yes" or (IsConnieGen(activeGen) and "No (CONNIE)" or "No")))
            SetLabelColor(ui.progGenSafeLbl, genSafe and Th.green or Th.red)
        end
    end
    return belowHalf, halfOrMore
end
function UpdateDecodingUI(activeGen, hrp, currentBase, isDanger)
    if not ui.decGenLbl then return end
    if not activeGen then
        if Prev.decLastGen ~= nil then
            SetLabelText(ui.decGenLbl,  "Decoding: None"); SetLabelColor(ui.decGenLbl, Th.mgray)
            if ui.decMonLbl  then SetLabelText(ui.decMonLbl,  "Twisteds Nearby: No (0)");   SetLabelColor(ui.decMonLbl,  Th.mgray) end
            if ui.decTenLbl  then SetLabelText(ui.decTenLbl,  "Tendrils Nearby: No (0)");   SetLabelColor(ui.decTenLbl,  Th.mgray) end
            if ui.decBlotLbl then SetLabelText(ui.decBlotLbl, "Blot Hands Nearby: No (0)"); SetLabelColor(ui.decBlotLbl, Th.mgray) end
            Prev.decLastGen=nil; Prev.decLastMc=-1; Prev.decLastTc=-1; Prev.decLastBc=-1
        end
        return
    end
    local genPos     = activeGen:GetPivot().Position
    local mc, tc, bc = R.ggt(genPos)
    local genChanged = (activeGen ~= Prev.decLastGen)
    local cntChanged = (mc ~= Prev.decLastMc) or (tc ~= Prev.decLastTc) or (bc ~= Prev.decLastBc)
    if genChanged then
        SetLabelText(ui.decGenLbl,  "Decoding: "..activeGen.Name..(IsConnieGen(activeGen) and " ⚠" or ""))
        SetLabelColor(ui.decGenLbl, IsConnieGen(activeGen) and Th.red or Th.green)
    end
    if cntChanged or genChanged then
        Prev.decLastGen=activeGen; Prev.decLastMc=mc; Prev.decLastTc=tc; Prev.decLastBc=bc
        local function tt(cnt) return (cnt>0 and "Yes ( " or "No ( ")..cnt.." )" end
        if ui.decMonLbl  then SetLabelText(ui.decMonLbl,  "Twisteds Nearby: "..tt(mc));   SetLabelColor(ui.decMonLbl,  mc>0 and Th.red    or Th.mgray) end
        if ui.decTenLbl  then SetLabelText(ui.decTenLbl,  "Tendrils Nearby: "..tt(tc));   SetLabelColor(ui.decTenLbl,  tc>0 and Th.purple or Th.mgray) end
        if ui.decBlotLbl then SetLabelText(ui.decBlotLbl, "Blot Hands Nearby: "..tt(bc)); SetLabelColor(ui.decBlotLbl, bc>0 and Th.pink   or Th.mgray) end
    end
    local shouldGoToBase = false
    if isDanger then
        shouldGoToBase = true
    elseif IsConnieGen(activeGen) then
        shouldGoToBase = true
    elseif (mc + tc + bc) > 0 then
        local approachBlocked = IsCachedMonsterNearPosition(genPos, C.genApproachClearRadius, true, false)
        local hasTen, hasBlot = IsTendrilNearGen(genPos)
        if approachBlocked or hasTen or hasBlot then shouldGoToBase = true end
    end
    if shouldGoToBase and hrp and currentBase and (S.autoEnabled or S.safeTp) then
        if not R.ibb(currentBase, hrp.Position) then
            if tick() - (S.lastBaseTP or 0) >= C.baseTpLoopCd then
                S.lastBaseTP = tick()
                TeleportToBaseWithRetry(hrp, currentBase)
            end
        end
    end
end
function DoAutoUseItems(activeGen, genIsBelowHalfUI, isFullDanger, char)
    if not S.autoUseItems then return end
    local igp         = workspace:FindFirstChild(_G.YattaIGP)
    local pm          = igp and igp:FindFirstChild(plr.Name)
    local statsFolder = pm and pm:FindFirstChild("Stats")
    local humanoid    = char:FindFirstChildWhichIsA("Humanoid")
    local used        = nil
    local humHp       = humanoid and humanoid.Health or nil
    local humMaxHp    = humanoid and humanoid.MaxHealth or nil
    local halfHp    = humHp and humMaxHp and (humMaxHp / 2) or nil
    local isDamaged     = humHp and humMaxHp and (humHp < humMaxHp) or false
    local isCrit        = humHp and halfHp and (humHp <= halfHp) or false
    local missingOne    = humHp and humMaxHp and (humMaxHp - humHp <= 1) or false
    local missingTwo    = humHp and humMaxHp and (humMaxHp - humHp <= 2) or false
    local healEnabled = true
    if healEnabled and isDamaged and (tick() - S.lastHealUse >= C.healCooldown) then
        local sl
        if humHp ~= nil and humHp <= 1 then
            sl = R.swi("HealthKit") or R.swi("Bandage")
        else
            sl = R.swi("Bandage")
        end
        if sl then
            R.fis(sl)
            S.lastItemUse = tick()
            S.lastHealUse = tick()
            used = sl.Value
        end
    end
    if not used then
        for _, iname in ipairs({"ProteinBar", "SpeedCandy"}) do
            local sl = R.swi(iname)
            if sl then
                R.fis(sl)
                S.lastItemUse = tick()
                used = iname
                break
            end
        end
    end
    if not used and (tick() - S.lastItemUse >= C.itemUseCooldown) then
        local stam       = Prev.cuStamina
        local staminaLow = (stam ~= math.huge) and (stam <= C.staminaStopThreshold)
        local stamina30  = (stam ~= math.huge) and (stam <= C.itemUseStaminaThreshold)
        local genIsBelowHalfLive = activeGen and GetGenBelowHalfDirect(activeGen) or false
        local activeGenIsTreadmill = false
        if activeGen and activeGen.Parent then
            local mt = activeGen:GetAttribute("MinigameType")
            if mt == "MovementTreadmill" then
                activeGenIsTreadmill = true
            else
                local mts = activeGen:GetAttribute("MinigameTypes")
                if type(mts) == "string" then
                    for part in mts:gmatch("[^,]+") do
                        if part:match("^%s*MovementTreadmill%s*$") then
                            activeGenIsTreadmill = true; break
                        end
                    end
                end
            end
        end
        for _, cfg in ipairs(R.ic) do
            if cfg.ignore then continue end
            if cfg.heal and not cfg.always then continue end
            local wantsExtract = cfg.extracting or (cfg.always and R.ghr[cfg.name])
            if wantsExtract and R.ghr[cfg.name] then
                local faVal = Prev.cuFloorVal
                if not (faVal and faVal:IsA("BoolValue") and faVal.Value == true) then continue end
                if not activeGen then continue end
                if not genIsBelowHalfLive then continue end
                if tick() - S.lastDecodingUse < C.decodingUseDelay then continue end
                local trinketsFolder = pm and pm:FindFirstChild("Trinkets")
                if trinketsFolder then
                    local veeActive = false
                    for _, trinket in ipairs({"Trinket1", "Trinket2"}) do
                        local tv = trinketsFolder:FindFirstChild(trinket)
                        if tv and tv:IsA("StringValue") and tv.Value == "VeeRemote" then
                            local ab = tv:FindFirstChild("Active")
                            if ab and ab:IsA("BoolValue") and ab.Value == true then
                                veeActive = true; break
                            end
                        end
                    end
                    if veeActive then continue end
                end
            end
            local fire = false
            if cfg.always then
                fire = true
            else
                if cfg.extracting and (activeGen ~= nil) then fire = true end
                if cfg.seen      and isFullDanger         then fire = true end
                if cfg.stamina   and stamina30             then fire = true end
                if cfg.treadmillExtracting and activeGenIsTreadmill then fire = true end
            end
            if fire then
                local sl = R.swi(cfg.name)
                if sl then
                    R.fis(sl); S.lastItemUse = tick()
                    if R.ghr[cfg.name] then S.lastDecodingUse = tick() end
                    used = cfg.name; break
                end
            end
        end
    end
    if ui.autoUseLbl then
        if used then SetLabelText(ui.autoUseLbl,"- Item Used: "..used); SetLabelColor(ui.autoUseLbl, Th.green)
        else         SetLabelText(ui.autoUseLbl,"- Item Used: None");   SetLabelColor(ui.autoUseLbl, Th.mgray) end
    end
    if ui.progLastItemUsedLbl then
        SetLabelText(ui.progLastItemUsedLbl, "Last Item Used: "..(used or "None"))
        SetLabelColor(ui.progLastItemUsedLbl, used and Th.green or Th.mgray)
    end
end
function IsItemInsideDyleMap(item)
    local currentRoom = workspace:FindFirstChild("CurrentRoom"); if not currentRoom then return false end
    local ancestor = item.Parent
    while ancestor and ancestor ~= currentRoom and ancestor ~= workspace do
        if ancestor.Parent == currentRoom and ancestor.Name == "DyleMap" then return true end
        ancestor = ancestor.Parent
    end
    return false
end
function IsPickupBlocked()
    if IsInChaseClearWait() then return true end
    if not IsPanicActive() and tick() - S.lastGenT < K.postCompW then return true end
    if S.pickupFloorBlocked() then return true end   
    return false
end
local pad = { pad = nil, suppressed = {} }
function restoreWorldParts()
    for part, orig in pairs(pad.suppressed) do
        pcall(function()
            if part and part.Parent then part.CanCollide = orig end
        end)
    end
    table.clear(pad.suppressed)
end
function suppressGeometryUnderItem(itemPos, padY)
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    local char = plr.Character
    local excludeList = char and {char} or {}
    if pad.pad and pad.pad.Parent then excludeList[#excludeList+1] = pad.pad end
    for _, plr in ipairs(Plrs:GetPlayers()) do
        if plr.Character then excludeList[#excludeList+1] = plr.Character end
    end
    local elevs = workspace:FindFirstChild("Elevators")
    if elevs then
        local fakeElev = elevs:FindFirstChild("FakeElevator")
        if fakeElev then excludeList[#excludeList+1] = fakeElev end
        excludeList[#excludeList+1] = elevs
    end
    local fakeElevDirect = workspace:FindFirstChild("FakeElevator")
    if fakeElevDirect then excludeList[#excludeList+1] = fakeElevDirect end
    local currentRoom = workspace:FindFirstChild("CurrentRoom")
    if currentRoom then
        for _, child in ipairs(currentRoom:GetChildren()) do
            local n = child.Name
            if n == "Bases" or n == "Spawns" or n == "PlayerSpawns" then
                excludeList[#excludeList+1] = child
            end
        end
    end
    local igp = workspace:FindFirstChild(_G.YattaIGP)
    if igp then excludeList[#excludeList+1] = igp end
    rayParams.FilterDescendantsInstances = excludeList
    local origin    = Vector3.new(itemPos.X, itemPos.Y - 0.1, itemPos.Z)
    local direction = Vector3.new(0, padY - itemPos.Y, 0)
    local result = workspace:Raycast(origin, direction, rayParams)
    if result and result.Instance and result.Instance:IsA("BasePart") then
        local part = result.Instance
        local isPlayerPart = false
        for _, plr in ipairs(Plrs:GetPlayers()) do
            if plr.Character and part:IsDescendantOf(plr.Character) then
                isPlayerPart = true; break
            end
        end
        if not isPlayerPart and part.CanCollide and pad.suppressed[part] == nil then
            pad.suppressed[part] = true
            part.CanCollide = false
        end
    end
end
function DestroyPickupPad()
    if pad.pad then
        if pad.pad.Parent then pad.pad:Destroy() end
        pad.pad = nil
    end
end
function SpawnOrMovePad(itemPos)
    local padY = itemPos.Y - K.padBelow
    if pad.pad and pad.pad.Parent then
        pad.pad.CFrame = CFrame.new(itemPos.X, padY, itemPos.Z); return padY
    end
    DestroyPickupPad()
    local newPad = Instance.new("Part")
    newPad.Name=K.padName; newPad.Size=Vector3.new(8,0.5,8)
    newPad.CFrame=CFrame.new(itemPos.X,padY,itemPos.Z)
    newPad.Anchored=true; newPad.CanCollide=true; newPad.CastShadow=false
    newPad.Transparency=1; newPad.Material=Enum.Material.SmoothPlastic
    newPad.Color=Color3.fromRGB(100,210,255); newPad.Parent=workspace
    game:GetService("Debris"):AddItem(newPad, 10)
    pad.pad = newPad; return padY
end
function DoPickupItem(hrp, item)
    if IsInventoryFull() and item.Name ~= "Tape" and item.Name ~= "ResearchCapsule" then return false end
    local handle = item:IsA("BasePart") and item or item:FindFirstChildWhichIsA("BasePart", true)
    if not handle or not handle.Parent then return false end
    local itemPos = handle.Position
    local pkMargin = (IsPanicActive and IsPanicActive()) and 6 or 4
    do local okT, nearT = pcall(function() return S.shTwistedNear and S.shTwistedNear(itemPos, pkMargin, true) end); if okT and nearT then S.pickupThreatSkipT = tick(); return false, "threat" end end
    if IsItemInsideDyleMap(item) then
        local itemName = item.Name or ""
        if not K.dylemapAllowedItems[itemName] then return false end
    end
    local padY         = SpawnOrMovePad(itemPos)
    suppressGeometryUnderItem(itemPos, padY)
    local playerStandY = padY + 0.25 + 1.5
    local holdPos       = Vector3.new(itemPos.X, playerStandY, itemPos.Z)
    do local okT, nearT = pcall(function() return S.shTwistedNear and S.shTwistedNear(holdPos, pkMargin, true) end); if okT and nearT then S.pickupThreatSkipT = tick(); return false, "threat" end end
    WaitForSafeHideRelease()
    hrp.CFrame = CFrame.new(holdPos)
    local char = plr.Character
    local hum  = char and char:FindFirstChildWhichIsA("Humanoid")
    local usingHold = not fs.flying and hum ~= nil
    local holdAttach, holdLV, holdAV, wasPlatformStand
    if usingHold then
        wasPlatformStand = hum.PlatformStand
        holdAttach = Instance.new("Attachment", hrp)
        holdLV = Instance.new("LinearVelocity", hrp)
        holdLV.MaxForce               = 9e10
        holdLV.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
        holdLV.VectorVelocity         = Vector3.zero
        holdLV.Attachment0            = holdAttach
        holdAV = Instance.new("AngularVelocity", hrp)
        holdAV.MaxTorque       = 9e10
        holdAV.AngularVelocity = Vector3.zero
        holdAV.Attachment0     = holdAttach
        hum.PlatformStand = true
        hum:ChangeState(Enum.HumanoidStateType.Physics)
    end
    task.wait(K.settleT)
    restoreWorldParts()
    local result = false
    if handle.Parent and not (function() local okT, nearT = pcall(function() return S.shTwistedNear and S.shTwistedNear(itemPos, pkMargin, true) end); return okT and nearT end)() then
        local deadline = tick() + (K.pickupRetryBudget or 0.3)
        repeat
            local firedAny = false
            for _, p in ipairs(item:GetDescendants()) do
                if p:IsA("ProximityPrompt") and p.Parent and p.Enabled ~= false then
                    fireOnePrompt(p)
                    firedAny = true
                    break
                end
            end
            if not firedAny then break end
            task.wait(K.postfireT)
            if not item.Parent or not handle.Parent then
                result = true
                break
            end
        until tick() >= deadline
        if not result then
            result = not (item.Parent and handle.Parent)
        end
    end
    if usingHold then
        pcall(function() holdLV:Destroy() end)
        pcall(function() holdAV:Destroy() end)
        pcall(function() holdAttach:Destroy() end)
        pcall(function()
            if hum and hum.Parent then
                hum.PlatformStand = wasPlatformStand
                if not wasPlatformStand then
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end
            end
        end)
    end
    return result
end
function RunPickupBatch(hrp)
    local items = R.gai()
    if not items or #items == 0 then
        if nc.enabled and nc.pickupOwned then
            S.ncPickupOff()
        end
        return
    end
    S.pickingUp = true; DisableCharacterCollision()
    if not nc.enabled then
        nc.enabled = true; nc.pickupOwned = true; S.noclip = true
        if plr.Character then pcall(task.spawn, nCBypass, plr.Character) end
    end
    local pickedCount = 0
    for _, item in ipairs(items) do
        if not S.pickupEnabled then break end
        if not S.autoEnabled then break end
        if R.gag() then break end
        local isDanger, _, _ = GetDangerState()
        if isDanger then break end
        if IsPickupBlocked() then break end
        if IsInventoryFull() and item.Name ~= "Tape" and item.Name ~= "ResearchCapsule" then continue end
        local ok, why = DoPickupItem(hrp, item)
        if ok then pickedCount = pickedCount + 1 end
        if why ~= "threat" then task.wait(K.pickupItemGap) end
    end
    local remaining = R.gai()
    if nc.pickupOwned and (not S.pickupEnabled or not S.autoEnabled or not remaining or #remaining == 0) then
        S.ncPickupOff()
    end
    DestroyPickupPad(); restoreWorldParts(); RestoreCharacterCollision(); S.pickingUp = false
    do
        local cleanChar = plr.Character
        if cleanChar then
            local hrpC = cleanChar:FindFirstChild("HumanoidRootPart")
            if hrpC then
                for _, obj in ipairs(hrpC:GetJoints()) do
                    if obj:IsA("Weld") or obj:IsA("WeldConstraint") then
                        local p0ok = pcall(function() return obj.Part0 end)
                        local p1ok = pcall(function() return obj.Part1 end)
                        if p0ok and p1ok then
                            if obj.Parent and not obj.Parent:IsDescendantOf(cleanChar) then
                                pcall(function() obj:Destroy() end)
                            end
                        end
                    end
                end
            end
        end
        if not S.pickupEnabled or not S.autoEnabled then
            local tpChar = plr.Character
            local tpHrp = tpChar and tpChar:FindFirstChild("HumanoidRootPart")
            if tpHrp then
                WaitForSafeHideRelease()
                local elevBase = nil
                local elevs = workspace:FindFirstChild("Elevators")
                if elevs then
                    local elev = elevs:FindFirstChild("Elevator")
                    if elev then elevBase = elev:FindFirstChild("Base", true) end
                end
                if elevBase and elevBase:IsA("BasePart") then
                    WaitForSafeHideRelease()
                    tpHrp.CFrame = CFrame.new(elevBase.Position + Vector3.new(0, 3, 0))
                else
                    local farPad = workspace:FindFirstChild("YattaFarPad")
