                    WaitForSafeHideRelease()
                    tpHrp.CFrame = CFrame.new(99999, 104, 99999)
                end
            end
        end
    end
    local remainingItems = R.gai()
    local pickedLastItem = pickedCount > 0 and (not remainingItems or #remainingItems == 0)
    S.puStart  = tick()
    S.puActive = true
    if pickedLastItem then
        S.puStart = tick() - K.pickupDur + 10
