do
local dodgeLastFire = 0
function StartAutoDodgeLoop()
    S.regGame(function()
        while true do
            task.wait(0.1)
            if not S.autoDodgeTendrils or not S.autoEnabled then continue end
            if S.pathfindMode then continue end
            if S.safeHide then continue end
            local cache = _G.YattaTendrilCache
            if not cache or #cache == 0 then continue end
            local char = plr.Character
            local hrp  = char and char.PrimaryPart
            if not hrp then continue end
            if tick() - dodgeLastFire < 0.35 then continue end
            local myPos = hrp.Position
            local nearestDist, nearestPos = math.huge, nil
            for i = 1, #cache do
                local entry = cache[i]
                if entry.pos then
                    local d = (entry.pos - myPos).Magnitude
                    if d < nearestDist then
                        nearestDist = d
                        nearestPos  = entry.pos
                    end
                end
            end
            if nearestPos and nearestDist < (K.tenGenR or 25) then
                if S.shActive and not S.shTeleporting then continue end
                dodgeLastFire = tick()
                local away = (myPos - nearestPos)
                if away.Magnitude < 0.1 then away = Vector3.new(1, 0, 0) end
                away = away.Unit
                local pushTo = myPos + away * 14 + Vector3.new(0, 2, 0)
                pcall(function()
                    if S.shActive and not S.shTeleporting then return end
                    hrp.CFrame = CFrame.new(pushTo, pushTo + hrp.CFrame.LookVector)
                end)
            end
        end
    end)
end
StartAutoDodgeLoop()
do
end
function StartPickupLoop()
    if S.pickupLoopRunning then return end
    S.pickupLoopRunning = true
    regSpawn(function()
        while S.pickupLoopRunning do
            local faL = R.gfv()
            local floorL = faL and faL:IsA("BoolValue") and faL.Value == true
            do
                local waitT, w0 = floorL and (C.pickupLoopInterval or 1.5) or 0.3, tick()
                repeat
                    task.wait(0.05)
                    if floorL and IsPanicActive() then break end
                until tick() - w0 >= waitT
            end
            if not S.pickupEnabled or not S.autoEnabled then
                S.pickingUp=false
                if (not S.pickupEnabled or not S.autoEnabled) and nc.enabled and nc.pickupOwned then
                    S.ncPickupOff()
                    pcall(RestoreCharacterCollision)
                end
                continue
            end
            if S.autoEncounter and S.trigOk("encounter") then
                local ae = _G.yattaAE
                local panicFirst = false
                if ae and not ae.allDone and not panicFirst then
                    S.pickingUp=false; continue
                end
            end
            if S.gigiBusy or S.collectBusy or S.totBusy then S.pickingUp=false; continue end
            if S.totPending and S.totPending() then S.pickingUp=false; continue end
            if S.pathfindMode then S.pickingUp=false; continue end
            local char = plr.Character; local hrp = char and char.PrimaryPart
            if not hrp then S.pickingUp=false; continue end
            if R.gag() then S.pickingUp=false; continue end
            local isDanger, _, _ = GetDangerState()
            if isDanger then S.pickingUp=false; continue end
            if IsPickupBlocked() then S.pickingUp=false; continue end
            if IsInventoryFull() then S.pickingUp=false; continue end
            RunPickupBatch(hrp)
        end
        S.pickingUp = false
    end)
end
StartPickupLoop()
end
function S.panicPickupFirst()
    do return false end
    if not (S.pickupEnabled and S.autoEnabled) or S.pathfindMode then return false end
    if not IsPanicActive() then return false end
    if S.panicStartT and tick() - S.panicStartT > 8 then return false end
    if S.pickupFloorBlocked() then return false end
    if S.pickingUp then return true end
    if IsInventoryFull() then return false end
    local ok, items = pcall(R.gai)
    return ok and items ~= nil and #items > 0
end
S.regGame(function()
