function IsGenCompleted(gen)
    if not gen or not gen.Parent then return false end
    local _, _, comp = GetCachedGenStats(gen)
    return comp
end
function IsGenBlockedForEggson(gen)
    if not gen or not gen.Parent then return false end
    if IsConnieGen(gen) then return true end
    if not IsGenSafeFromBalls(gen) then return true end
    local genPos = gen:GetPivot().Position
    local hasTen, hasBlot = IsTendrilNearGen(genPos)
    if hasTen or hasBlot then return true end
    return IsCachedMonsterNearGen(genPos, K.eggClrR, true)
end
function AllRoomGensHavePlayerValue(roomGens)
    for _, entry in ipairs(roomGens) do
        local gen = entry.gen
        local _, _, comp = GetCachedGenStats(gen)
        if comp then continue end
        local nv = R.gegpnv(gen)
        if not nv or nv.Value < 6 then return false end
    end
    return true
end
function EggsonMonsterNearby(checkPos, secondPos)
    local r2  = K.eggStopRsq
    local mon = Cache.monsterPositions
    for i = 1, #mon do
        local entry = mon[i]
        if entry.eggsonEligible then
            local livePos = entry.livePart and entry.livePart.Parent and entry.livePart.Position
            local pos = livePos or entry.pos
            local d = pos - checkPos
            if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= r2 then return true end
            if secondPos then
                local d2 = pos - secondPos
                if (d2.X*d2.X + d2.Y*d2.Y + d2.Z*d2.Z) <= r2 then return true end
            end
        end
    end
    local ten = Cache.tendrilPositions
    for i = 1, #ten do
        local d = ten[i].pos - checkPos
        if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= r2 then return true end
        if secondPos then
            local d2 = ten[i].pos - secondPos
            if (d2.X*d2.X + d2.Y*d2.Y + d2.Z*d2.Z) <= r2 then return true end
        end
    end
    return false
end
function EggsonTeleportAndInteract(hrp, gen, pipe)
    local isNewGen = (gen ~= Cache.lastPositionedGen)
    if isNewGen then Cache.lastPositionedGen = gen end
    local useMirror = false
    if IsDualGen(gen.Name) then
        local slot = GetDualGenSlotForPlayer(gen)
        useMirror = (slot == "mirror")
    end
    TeleportToGenSimple(hrp, gen, useMirror)
    if gen and gen.Parent then FireGenProximityPrompts(gen) end
end
function eggsonLowPlayerPath(hrp, currentBase, serverCount, roomGens)
    if AllRoomGensHavePlayerValue(roomGens) then return false end
    local unseededGens = {}
    for _, entry in ipairs(roomGens) do
        local gen = entry.gen
        if IsConnieGen(gen) then continue end
        local _, _, comp = GetCachedGenStats(gen)
        if comp then continue end
        if IsGenBlockedForEggson(gen) then continue end
        local nv = R.gegpnv(gen)
        if not nv then
            local st    = gen:FindFirstChild("Stats")
            local apVal = st and st:FindFirstChild("ActivePlayer")
            local apOcc = apVal and apVal.Value or nil
            if apOcc ~= nil and apOcc ~= plr then continue end
            unseededGens[#unseededGens+1] = gen
        end
    end
    local activeGen = R.gag()
    if #unseededGens == 0 then return true end
    if activeGen then
        if IsConnieGen(activeGen) then
            pcall(function() R.fsgcr(activeGen) end)
            pcall(function() R.fsg(activeGen) end)
            stopEggsonDecodeFireLoop()
            ClearPositionedGen(); TryTeleportToBaseIfIdle(hrp, currentBase); return true
        end
        if IsGenBlockedForEggson(activeGen) then
            pcall(function() R.fsgcr(activeGen) end)
            pcall(function() R.fsg(activeGen) end)
            stopEggsonDecodeFireLoop()
            ClearPositionedGen(); TryTeleportToBaseIfIdle(hrp, currentBase); return true
        end
        local nv     = R.gegpnv(activeGen)
        local hasVal = (nv ~= nil and nv.Value >= 6)
        if not hasVal then
            if tick() - S.lastEggsonTeleport >= K.eggCd then
                S.lastEggsonTeleport = tick()
                EggsonTeleportAndInteract(hrp, activeGen, R.FGPP2(activeGen))
                startEggsonDecodeFireLoop(activeGen)
            end
            return true
        end
        local genKey = tostring(activeGen)
        if not S.eggsonCompletionWaitStart[genKey] then
            S.eggsonCompletionWaitStart[genKey] = tick()
        end
        if tick() - S.eggsonCompletionWaitStart[genKey] >= K.eggWait then
            pcall(function() R.fsgcr(activeGen) end)
            stopEggsonDecodeFireLoop()
        end
        return true
    end
    if tick() - S.lastEggsonTeleport < K.eggCd then return true end
    S.lastEggsonTeleport = tick()
    local targetGen, closestDist = nil, math.huge
    for _, gen in ipairs(unseededGens) do
        local prim = gen.PrimaryPart or gen:FindFirstChildWhichIsA("BasePart", true)
        if prim then
            local d = (hrp.Position - prim.Position).Magnitude
            if d < closestDist then closestDist = d; targetGen = gen end
        end
    end
    if targetGen then
        if IsGenBlockedForEggson(targetGen) then stopEggsonDecodeFireLoop(); ClearPositionedGen(); return true end
        EggsonTeleportAndInteract(hrp, targetGen, R.FGPP2(targetGen))
        startEggsonDecodeFireLoop(targetGen)
    else
        TryTeleportToBaseIfIdle(hrp, currentBase)
    end
    return true
end
function startEggsonStopSpam(activeGen)
    if S.eggsonStopSpamActive and S.eggsonStopSpamGen == activeGen then return end
    S.eggsonStopSpamActive = true; S.eggsonStopSpamGen = activeGen
    local capturedGen = activeGen
    regSpawn(function()
        while S.eggsonMode and S.autoEnabled
            and S.eggsonStopSpamActive and S.eggsonStopSpamGen == capturedGen do
            if R.gag() ~= capturedGen then
                S.eggsonStopSpamActive = false; S.eggsonStopSpamGen = nil; return
            end
            pcall(function() R.fsgcr(capturedGen) end)
            task.wait(0.1)
        end
        if S.eggsonStopSpamGen == capturedGen then
            S.eggsonStopSpamActive = false; S.eggsonStopSpamGen = nil
        end
    end)
end
function DoEggsonFarm(hrp, currentBase, isPanicChecked, floorActiveValue)
    if not S.autoEnabled or not S.eggsonMode then
        stopEggsonDecodeFireLoop(); loop.eggsonChaseStop = false; return false
    end
    local function setStatus(mainText, mainColor, actionText, actionColor)
        if ui.progEggsonActionLbl then SetLabelText(ui.progEggsonActionLbl, actionText or mainText); SetLabelColor(ui.progEggsonActionLbl, actionColor or mainColor) end
    end
    if S.pickingUp then
        stopEggsonDecodeFireLoop()
        setStatus("- Eggson: Waiting for pickup...", Th.mgray, "Action: waiting for pickup...", Th.mgray); return true
    end
    if not R.ipe() then
        stopEggsonDecodeFireLoop()
        setStatus("- Eggson: Need Eggson character!", Th.red, "Action: wrong character!", Th.red); return false
    end
    if isPanicChecked then
        local activeGenPanic = R.gag()
        if activeGenPanic and activeGenPanic.Parent then
            pcall(function() R.fsg(activeGenPanic) end)
            pcall(function() R.fsgcr(activeGenPanic) end)
        end
        stopEggsonDecodeFireLoop()
        setStatus("- Eggson: PANIC (waiting)", Th.red, "Action: PANIC - waiting", Th.red)
        ClearPositionedGen(); return false
    end
    local isDangerNow, _, chaseCount = GetDangerState()
    if isDangerNow then
        local activeGenChase = R.gag()
        if activeGenChase and activeGenChase.Parent then
            pcall(function() R.fsg(activeGenChase) end)
            pcall(function() R.fsgcr(activeGenChase) end)
        end
        stopEggsonDecodeFireLoop()
        startEggsonChaseStopLoop()
        TryTeleportToBaseIfIdle(hrp, currentBase)
        ClearPositionedGen()
        setStatus("- Eggson: CHASED! Stopping & fleeing. (x"..chaseCount..")", Th.red, "Action: chased - fled to base", Th.red)
        return true
    else
        loop.eggsonChaseStop = false
    end
    if IsInChaseClearWait() then
        local activeGenCCW = R.gag()
        if activeGenCCW and activeGenCCW.Parent then
            pcall(function() R.fsg(activeGenCCW) end)
            pcall(function() R.fsgcr(activeGenCCW) end)
        end
        stopEggsonDecodeFireLoop()
        setStatus("- Eggson: Chase cleared, waiting...", Th.yellow, "Action: chase-clear cooldown", Th.yellow)
        TryTeleportToBaseIfIdle(hrp, currentBase); ClearPositionedGen(); return true
    end
    if EggsonMonsterNearby(hrp.Position) then
        local activeGenNow = R.gag()
        if activeGenNow then
            pcall(function() R.fsgcr(activeGenNow) end)
            pcall(function() R.fsg(activeGenNow) end)
        end
        stopEggsonDecodeFireLoop()
        TryTeleportToBaseIfIdle(hrp, currentBase); ClearPositionedGen()
        setStatus("- Eggson: MONSTER/TENDRIL NEARBY! Stopping.", Th.red, "Action: threat nearby - stopped", Th.red)
        return true
    end
    if S.autoUseItems then
        local hc   = R.gis().healingCount
        local maxH = C.maxHeals or 2
        if hc < maxH then
            if S.autoBuy then DoAutoBuyV15(hrp) end
        end
    elseif S.autoBuy then DoAutoBuyV15(hrp) end
    local roomGens = R.gcrg()
    if #roomGens == 0 then
        stopEggsonDecodeFireLoop()
        setStatus("- Eggson: No gens in CurrentRoom", Th.mgray, "Action: no gens in room", Th.mgray)
        if ui.progEggsonGenLbl then SetLabelText(ui.progEggsonGenLbl,"Pending Gens: 0"); SetLabelColor(ui.progEggsonGenLbl, Th.mgray) end
        TryTeleportToBaseIfIdle(hrp, currentBase); return false
    end
    local pendingCount = 0
    for _, entry in ipairs(roomGens) do
        if IsConnieGen(entry.gen) then continue end
        local _, _, comp = GetCachedGenStats(entry.gen)
        if comp then continue end
        if not R.eghpnv(entry.gen) then pendingCount += 1 end
    end
    if ui.progEggsonGenLbl then
        SetLabelText(ui.progEggsonGenLbl, "Pending Gens: "..pendingCount)
        SetLabelColor(ui.progEggsonGenLbl, pendingCount > 0 and Th.yellow or Th.green)
    end
    local serverCount = #Plrs:GetPlayers()
    if serverCount < 5 then
        local handled = eggsonLowPlayerPath(hrp, currentBase, serverCount, roomGens)
        if handled then setStatus("- Eggson: Seeding gen ("..serverCount.." players)", Th.blue, "Action: seeding gen", Th.blue); return true end
        return false
    end
    local pendingGens = {}
    local activeGen = R.gag()
    for _, entry in ipairs(roomGens) do
        local gen = entry.gen
        if IsConnieGen(gen) then continue end
        local _, _, comp = GetCachedGenStats(gen)
        if comp then continue end
        if IsGenBlockedForEggson(gen) then continue end
        if gen == activeGen then continue end
        if not R.eghpnv(gen) then
            local st    = gen:FindFirstChild("Stats")
            local apVal = st and st:FindFirstChild("ActivePlayer")
            local apOcc = apVal and apVal.Value or nil
            if apOcc ~= nil and apOcc ~= plr then continue end
            pendingGens[#pendingGens+1] = entry
        end
    end
    if activeGen and IsConnieGen(activeGen) then
        pcall(function() R.fsgcr(activeGen) end)
        pcall(function() R.fsg(activeGen) end)
        stopEggsonDecodeFireLoop(); ClearPositionedGen()
        TryTeleportToBaseIfIdle(hrp, currentBase)
        setStatus("- Eggson: Gen is CONNIE! Stopping.", Th.red, "Action: CONNIE - stopped", Th.red); return true
    end
    if activeGen and IsGenBlockedForEggson(activeGen) then
        pcall(function() R.fsgcr(activeGen) end)
        pcall(function() R.fsg(activeGen) end)
        stopEggsonDecodeFireLoop(); ClearPositionedGen()
        TryTeleportToBaseIfIdle(hrp, currentBase)
        setStatus("- Eggson: Threat near active gen! Stopping.", Th.red, "Action: threat near gen - stopped", Th.red); return true
    end
    if #pendingGens == 0 then
        if activeGen then
            if IsGenCompleted(activeGen) then S.lastGenT = tick() end
            stopEggsonDecodeFireLoop(); startEggsonStopSpam(activeGen)
            setStatus("- Eggson: All done, firing Stop", Th.yellow, "Action: all done, firing stop", Th.yellow)
        else
            S.eggsonStopSpamActive = false; S.eggsonStopSpamGen = nil
            stopEggsonDecodeFireLoop()
            TryTeleportToBaseIfIdle(hrp, currentBase)
            setStatus("- Eggson: All gens done! Waiting.", Th.green, "Action: all gens done, waiting", Th.green)
        end
        return true
    end
    if activeGen then
        if IsGenCompleted(activeGen) then
            S.lastGenT = tick(); stopEggsonDecodeFireLoop(); startEggsonStopSpam(activeGen)
            setStatus("- Eggson: Gen Completed! Stopping.", Th.yellow, "Action: completed - firing stop", Th.yellow); return true
        end
        local nv            = R.gegpnv(activeGen)
        local hasCompletion = (nv ~= nil and nv.Value >= 6)
        if hasCompletion then
            local genKey = tostring(activeGen)
            if not S.eggsonCompletionWaitStart[genKey] then S.eggsonCompletionWaitStart[genKey] = tick() end
            if tick() - S.eggsonCompletionWaitStart[genKey] >= K.eggWait then
                stopEggsonDecodeFireLoop(); startEggsonStopSpam(activeGen)
                setStatus("- Eggson: Firing Stop! (>= 6)", Th.yellow, "Action: firing stop (>= 6)", Th.yellow)
            else
                setStatus("- Eggson: Waiting before stop...", Th.orange, "Action: waiting before stop...", Th.orange)
            end
            return true
        else
            S.eggsonCompletionWaitStart[tostring(activeGen)] = nil
            if IsGenBlockedForEggson(activeGen) then
                pcall(function() R.fsgcr(activeGen) end)
                pcall(function() R.fsg(activeGen) end)
                stopEggsonDecodeFireLoop()
                TryTeleportToBaseIfIdle(hrp, currentBase); ClearPositionedGen()
                setStatus("- Eggson: Threat arrived at gen! Stopped.", Th.red, "Action: threat at gen - stopped", Th.red); return true
            end
            if tick() - S.lastEggsonTeleport >= K.eggCd then
                S.lastEggsonTeleport = tick()
                local pipe = R.FGPP2(activeGen)
                EggsonTeleportAndInteract(hrp, activeGen, pipe)
                startEggsonDecodeFireLoop(activeGen)
                local txt = pipe and "- Eggson: Decoding (at Pipe)" or "- Eggson: Decoding (no pipe)"
                setStatus(txt, Th.blue, pipe and "Action: decoding (at pipe)" or "Action: decoding (no pipe)", Th.blue)
            else
                setStatus("- Eggson: Decoding...", Th.blue, "Action: decoding...", Th.blue)
            end
            return true
        end
    end
    if tick() - S.lastEggsonTeleport < K.eggCd then return true end
    S.lastEggsonTeleport = tick()
    S.eggsonStopSpamActive = false; S.eggsonStopSpamGen = nil; stopEggsonDecodeFireLoop()
    local targetGen, closestDist = nil, math.huge
    for _, entry in ipairs(pendingGens) do
        local prim = entry.gen.PrimaryPart or entry.gen:FindFirstChildWhichIsA("BasePart", true)
        if prim then
            local d = (hrp.Position - prim.Position).Magnitude
            if d < closestDist then closestDist = d; targetGen = entry.gen end
        end
    end
    if not targetGen then
        TryTeleportToBaseIfIdle(hrp, currentBase)
        setStatus("- Eggson: Waiting for gens...", Th.mgray, "Action: waiting for gens...", Th.mgray); return true
    end
    if IsGenBlockedForEggson(targetGen) then
        ClearPositionedGen()
        setStatus("- Eggson: Threat near target gen! Skipping.", Th.red, "Action: threat at target - skipping", Th.red); return true
    end
    EggsonTeleportAndInteract(hrp, targetGen, R.FGPP2(targetGen))
    startEggsonDecodeFireLoop(targetGen)
    setStatus("- Eggson: Going to gen...", Th.orange, "Action: going to gen...", Th.orange)
    return true
end
function DualGenSlotUsable(gen)
    local slot = GetDualGenSlotForPlayer(gen)
    if slot == nil then return nil end
    return slot == "mirror"
end
function S.shBusy()
    return (S.shActive == true) or (S.shFleeing == true) or (S.shTweening == true) or (S.shExiting == true)
end
function schedulePipeTP(hrp, gen)
    if S.ptpGen == gen and S.ptpPend then return end
    S.ptpPend       = true
    S.ptpGen           = gen
    S.ptpTime = tick()
    S.ptpDone          = false
    local capturedGen = gen
    task.defer(function()
        if S.ptpGen ~= capturedGen then return end
        if not S.ptpPend then return end
        local char2 = plr.Character
        local hrp2  = char2 and char2.PrimaryPart
        if not hrp2 then return end
        if R.gag() == capturedGen and capturedGen.Parent and not S.shBusy()
           and not S.twistedNearGen(capturedGen:GetPivot().Position, C.genApproachClearRadius, false, true) then
            TeleportToGenPipe(hrp2, capturedGen)
        end
        S.ptpPend = false
        S.ptpDone    = true
    end)
end
function IsValidGenModel(gen)
    if not gen or not gen.Parent then return false end
    return gen.Name == "Generator" or IsDualGen(gen.Name) or gen.Name:match("^TrickOrTreatGen") ~= nil
end
do
    local A = {}
    _G.YattaAdditionals = A
    local busy = false
    local function notify(msg, snd, col) if _G.YattaNotify then _G.YattaNotify(msg, snd, col) end end
    local function collectItems(kind)
        local out = {}
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return out end
        for _, room in ipairs(cr:GetChildren()) do
            local f = room:FindFirstChild("Items")
            if f then
                for _, it in ipairs(f:GetChildren()) do
                    local n = it.Name
                    if n == "GigiHoard" then continue end
                    if kind == "tapes" and n ~= "Tape" then continue end
                    if kind == "capsules" and n ~= "ResearchCapsule" then continue end
                    if not it:FindFirstChildWhichIsA("ProximityPrompt", true) then continue end
                    if not (it:IsA("BasePart") or it:FindFirstChildWhichIsA("BasePart", true)) then continue end
                    out[#out + 1] = it
                end
            end
        end
        return out
    end
    local function runPickup(kind)
        local items = collectItems(kind)
        if #items == 0 then notify("No items found", true); return end
        local char = plr.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local origCF   = hrp.CFrame
        local deadline = tick() + 5
        local picked   = 0
        table.sort(items, function(a, b)
            local pa = a:IsA("BasePart") and a or a:FindFirstChildWhichIsA("BasePart", true)
            local pb = b:IsA("BasePart") and b or b:FindFirstChildWhichIsA("BasePart", true)
            return (pa.Position - origCF.Position).Magnitude < (pb.Position - origCF.Position).Magnitude
        end)
        S.pickingUp = true; DisableCharacterCollision()
        local ownNc = false
        if not nc.enabled then
            nc.enabled = true; nc.pickupOwned = true; S.noclip = true; ownNc = true
            if plr.Character then pcall(task.spawn, nCBypass, plr.Character) end
        end
        for _, item in ipairs(items) do
            if tick() >= deadline then break end
            if not item.Parent then continue end
            local ch = plr.Character
            local h  = ch and ch:FindFirstChild("HumanoidRootPart")
            if not h then break end
            local okp, gotIt = pcall(DoPickupItem, h, item)
            if okp and gotIt then picked = picked + 1 end
            task.wait(K.pickupItemGap)
        end
        DestroyPickupPad(); restoreWorldParts(); RestoreCharacterCollision(); S.pickingUp = false
        if ownNc and nc.pickupOwned then
            S.ncPickupOff()
        end
        local ch2 = plr.Character
        local h2  = ch2 and ch2:FindFirstChild("HumanoidRootPart")
        if h2 then
            WaitForSafeHideRelease()
            h2.CFrame = origCF
        end
        if picked > 0 then
            notify("Picked up " .. picked .. (picked == 1 and " item." or " items."), false, Color3.fromRGB(120, 255, 140))
        else
            notify("Couldn't pick anything up.", true)
        end
    end
    local function collectibles()
        local out = {}
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return out end
        for _, room in ipairs(cr:GetChildren()) do
            local f = room:FindFirstChild("HolidayPickups")
            if f then
                for _, c in ipairs(f:GetChildren()) do
                    if c:IsA("BasePart") or c:IsA("Model") then out[#out + 1] = c end
                end
            end
        end
        return out
    end
    local function pieceTarget(piece)
        if piece:IsA("BasePart") then return piece end
        return piece.PrimaryPart or piece:FindFirstChildWhichIsA("BasePart", true)
    end
    local function nearestCollectible(skip)
        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local best, bd = nil, math.huge
        for _, c in ipairs(collectibles()) do
            if skip and skip[c] and tick() - skip[c] < 5 then continue end
            local t = pieceTarget(c)
            if t then
                local d = (t.Position - hrp.Position).Magnitude
                if d < bd then bd = d; best = c end
            end
        end
        return best
    end
    local function collectPiece(piece)
        local target = pieceTarget(piece)
        if not target then return false end
        local pos = target.Position
        if IsCachedMonsterNearPosition(pos, K.monSkipR, false, true) then return false end
        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        WaitForSafeHideRelease()
        hrp.CFrame = CFrame.new(pos)
        for _ = 1, 6 do
            if not piece.Parent then return true end
            local ch2 = plr.Character
            local h   = ch2 and ch2:FindFirstChild("HumanoidRootPart")
            if not h then return false end
            if (h.Position - pos).Magnitude > 6 then
                WaitForSafeHideRelease()
                h.CFrame = CFrame.new(pos)
            end
            if firetouchinterest then
                local parts = {}
                if piece:IsA("BasePart") then
                    parts[1] = piece
                else
                    for _, d in ipairs(piece:GetDescendants()) do
                        if d:IsA("BasePart") then
                            parts[#parts + 1] = d
                            if #parts >= 6 then break end
                        end
                    end
                end
                for _, bp in ipairs(parts) do
                    pcall(function() firetouchinterest(h, bp, 0); firetouchinterest(h, bp, 1) end)
                end
            end
            task.wait(0.05)
        end
        return not piece.Parent
    end
    local function runCollect()
        if #collectibles() == 0 then notify("No items found", true); return end
        local char = plr.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local origCF   = hrp.CFrame
        local deadline = tick() + 5
        local tried    = {}
        local got      = 0
        S.collectBusy = true
        while tick() < deadline do
            local piece = nearestCollectible(tried)
            if not piece then break end
            tried[piece] = tick()
            local ok, res = pcall(collectPiece, piece)
            if ok and res then got = got + 1 end
        end
        local ch2 = plr.Character
        local h2  = ch2 and ch2:FindFirstChild("HumanoidRootPart")
        if h2 then
            WaitForSafeHideRelease()
            h2.CFrame = origCF
        end
        S.collectBusy = false
        if got > 0 then
            notify("Collected " .. got .. (got == 1 and " collectible." or " collectibles."), false, Color3.fromRGB(120, 255, 140))
        else
            notify("Couldn't collect anything.", true)
        end
    end
    regSpawn(function()
        local tried = setmetatable({}, { __mode = "k" })
        while true do
            task.wait(0.4)
            if R.isR or not (S.autoCollect and S.autoEnabled and S.trigOk("collect")) or S.pathfindMode then S.collectBusy = false; continue end
            if busy then continue end
            local fa = R.gfv()
            if not (fa and fa:IsA("BoolValue") and fa.Value == true) then S.collectBusy = false; continue end
            local colTrig = S.autoTrig and S.autoTrig.collect
            local panicBlocks = IsPanicActive() and not (colTrig and (colTrig.always or colTrig.panic))
            if S.pickupFloorBlocked(true) then continue end   
            if S.pickingUp or S.gigiBusy or R.gag() or panicBlocks or IsInChaseClearWait() then continue end
            if GetDangerState() then continue end
            if R.idso() or R.icv() then continue end
            local piece = nearestCollectible(tried)
            if not piece then continue end
            local ch  = plr.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if not hrp then continue end
            local origCF = hrp.CFrame
            tried[piece] = tick()
            S.collectBusy = true
            pcall(collectPiece, piece)
            local ch2 = plr.Character
            local h2  = ch2 and ch2:FindFirstChild("HumanoidRootPart")
            if h2 then
                WaitForSafeHideRelease()
                h2.CFrame = origCF
            end
            S.collectBusy = false
        end
    end)
    local function tpToMachine(wantCompleted)
        local char = plr.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local best, bd = nil, math.huge
        for _, e in ipairs(R.gcrg()) do
            local g = e.gen
            if g and g.Parent and IsValidGenModel(g) and (IsGenCompleted(g) == wantCompleted) then
                local d = (g:GetPivot().Position - hrp.Position).Magnitude
                if d < bd then bd = d; best = g end
            end
        end
        if not best then
            notify(wantCompleted and "No Completed machines found." or "No Incomplete machines found.", true)
            return
        end
        TeleportToGenSimple(hrp, best, false)
    end
    local function tpMachineFar(wantCompleted)
        local char = plr.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local best, bd = nil, -1
        for _, e in ipairs(R.gcrg()) do
            local g = e.gen
            if g and g.Parent and IsValidGenModel(g) and (IsGenCompleted(g) == wantCompleted) then
                local d = (g:GetPivot().Position - hrp.Position).Magnitude
                if d > bd then bd = d; best = g end
            end
        end
        if not best then
            notify(wantCompleted and "No Completed machines found." or "No Incomplete machines found.", true)
            return
        end
        TeleportToGenSimple(hrp, best, false)
    end
    local function tpMachineRandom()
        local char = plr.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local list = {}
        for _, e in ipairs(R.gcrg()) do
            local g = e.gen
            if g and g.Parent and IsValidGenModel(g) then list[#list + 1] = g end
        end
        if #list > 1 then
            local far = {}
            for _, g in ipairs(list) do
                if (g:GetPivot().Position - hrp.Position).Magnitude > 8 then far[#far + 1] = g end
            end
            if #far > 0 then list = far end
        end
        if #list == 0 then
            notify("No machines found.", true)
            return
        end
        TeleportToGenSimple(hrp, list[math.random(#list)], false)
    end
    local totTries = setmetatable({}, { __mode = "k" })

    local function findAllTot()
        local out = {}
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return out end
        for _, room in ipairs(cr:GetChildren()) do
            local folder = room:FindFirstChild("TrickOrTreatDoors")
            if folder then
                for _, d in ipairs(folder:GetDescendants()) do
                    if d.Name == "Ground" and d:IsA("BasePart") then
                        local att = d:FindFirstChild("Attachment")
                        local pp = att and att:IsA("Attachment") and att:FindFirstChildWhichIsA("ProximityPrompt")
                        if pp then
                            out[#out + 1] = { pp = pp, ground = d, att = att,
                                              door = d:FindFirstAncestorOfClass("Model") or d }
                        end
                    end
                end
            end
        end
        return out
    end
    A.findAllTot = findAllTot

    local function totOk(e)
        if not (e.pp and e.pp.Parent) or e.pp.Enabled == false then return false end
        local rec = totTries[e.pp]
        if rec then
            if S.pathfindMode and S.autoEnabled and rec.n < 99 then
                if tick() - rec.t < 8 then return false end
            elseif rec.n >= 3 or tick() - rec.t < 8 then
                return false
            end
        end
        return true
    end

    A.totMark = function(pp, done)
        local rec = totTries[pp]
        totTries[pp] = { n = done and 99 or (((rec and rec.n) or 0) + 1), t = tick() }
    end

    function A.totUnsafe()
        if S.seenNow then
            local okS, seen = pcall(S.seenNow)
            if okS and seen then return true end
        end
        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if hrp and IsCachedMonsterNearPosition(hrp.Position, K.totNearMeR or 60, false, true) then return true end
        return false
    end

    local function findTot(filter)
        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        local best, bd = nil, math.huge
        for _, e in ipairs(findAllTot()) do
            if totOk(e) and (not filter or filter(e)) then
                local d = hrp and (e.att.WorldPosition - hrp.Position).Magnitude or 0
                if d < bd then bd = d; best = e end
            end
        end
        if best then return best.pp, best.ground, best.att, best.door end
        return nil
    end
    A.findTot = findTot

    local function runTrick(manual)
        local all = findAllTot()
        if #all == 0 then
            if manual then notify("No Trick or Treat door found", true) end
            return false
        end
        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        local origCF = hrp.CFrame
        local list = {}
        for _, e in ipairs(all) do
            if e.pp.Parent and e.pp.Enabled ~= false and (manual or totOk(e)) then list[#list + 1] = e end
        end
        if #list == 0 then
            if manual then notify("Trick or Treat already used", true) end
            return false
        end
        table.sort(list, function(a, b)
            return (a.att.WorldPosition - origCF.Position).Magnitude < (b.att.WorldPosition - origCF.Position).Magnitude
        end)
        S.totBusy = true
        local doneN, skipped = 0, 0
        for _, e in ipairs(list) do
            if not manual and A.totUnsafe() then break end
            local pp, pos = e.pp, e.att.WorldPosition
            local okDet, detClear = pcall(shMonsterDetectorClear, pos)
            if IsCachedMonsterNearPosition(pos, K.monSkipR, false, true) or (okDet and not detClear) then
                skipped = skipped + 1
            else
                local done = false
                for _ = 1, 6 do
                    local ch2 = plr.Character
                    local h   = ch2 and ch2:FindFirstChild("HumanoidRootPart")
                    if not h then break end
                    if not pp.Parent then done = true; break end
                    if (h.Position - pos).Magnitude > 6 then
                        local okD2, clear2 = pcall(shMonsterDetectorClear, pos)
                        if okD2 and not clear2 then break end
                        WaitForSafeHideRelease()
                        h.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))
                    end
                    fireOnePrompt(pp)
                    for _ = 1, 6 do
                        if not pp.Parent or pp.Enabled == false then break end
                        task.wait(0.05)
                    end
                    if not pp.Parent or pp.Enabled == false then done = true; break end
                end
                A.totMark(pp, done)
                if done then doneN = doneN + 1 end
            end
            if not manual and GetDangerState() then break end
        end
        local ch3 = plr.Character
        local h3  = ch3 and ch3:FindFirstChild("HumanoidRootPart")
        if h3 then
            local tw = tick()
            while tick() - tw < 3 do
                local okD3, clear3 = pcall(shMonsterDetectorClear, origCF.Position)
                if not okD3 or clear3 then break end
                task.wait(0.2)
            end
            WaitForSafeHideRelease()
            h3.CFrame = origCF
        end
        S.totBusy = false
        if manual then
            if doneN > 0 then
                notify("Trick or Treat done (" .. doneN .. " of " .. #all .. ").", false, Color3.fromRGB(120, 255, 140))
            elseif skipped > 0 then
                notify("A twisted is near the door", true)
            else
                notify("Trick or Treat didn't register.", true)
            end
        end
        return doneN > 0
    end

    function S.totPending()
        if R.isR or not (S.autoTrickTreat and S.autoEnabled and S.trigOk("trick")) then return false end
        if S.totBusy then return true end
        if IsPanicActive() or GetDangerState() then return false end
        if A.totUnsafe() then return false end
        return findTot() ~= nil
    end
    regSpawn(function()
        while true do
            task.wait(0.3)
            if R.isR or not (S.autoTrickTreat and S.autoEnabled and S.trigOk("trick")) then continue end
            if busy then continue end
            if S.pathfindMode and S.autoEnabled then continue end
            if S.pickingUp or S.gigiBusy or S.collectBusy or S.totBusy or R.gag() then continue end
            if IsPanicActive() or IsInChaseClearWait() or GetDangerState() then continue end
            if R.idso() or R.icv() then continue end
            if A.totUnsafe() then continue end
            if findTot() then pcall(runTrick, false) end
        end
    end)

    A.collectibles = collectibles
    A.pieceTarget  = pieceTarget
    A.run = function(kind)
        if busy then return end
        if S.autoEnabled then notify("Turn off AutoFarm first!", true); return end
        if kind == "tpIncomplete" then tpToMachine(false)
        elseif kind == "tpComplete" then tpToMachine(true)
        elseif kind == "tpRandom" then tpMachineRandom()
        elseif kind == "tpFarIncomplete" then tpMachineFar(false)
        elseif kind == "tpFarComplete" then tpMachineFar(true)
        elseif kind == "encounter" then
            if A.encounter then A.encounter() end
        elseif kind == "trickortreat" then
            busy = true
            regSpawn(function()
                pcall(runTrick, true)
                busy = false
            end)
        elseif kind == "collectibles" then
            if S.pathfindMode then
                notify("Pathfind Mode is on - collectibles are walked to during autofarm.", true)
                return
            end
            busy = true
            regSpawn(function()
                pcall(runCollect)
                busy = false
            end)
        else
            busy = true
            regSpawn(function()
                pcall(runPickup, kind)
                busy = false
            end)
        end
    end
end
S.gigiBusy = false
do
local gg = { giveUpUntil = 0 }
function ggWhitelistSet()
    local set, any = {}, false
    for _, g in ipairs(R.gigiWL or {}) do
        if g.whitelisted then set[g.name] = true; any = true end
    end
    return set, any
end
function ggFindHoard()
    local cr = workspace:FindFirstChild("CurrentRoom")
    if not cr then return nil end
    for _, room in ipairs(cr:GetChildren()) do
        local items = room:FindFirstChild("Items")
        local h = items and items:FindFirstChild("GigiHoard")
        if h then return h, items end
    end
    return nil
end
function ggGetPrompt(hoard)
    local part = hoard:FindFirstChild("Prompt")
    if not part then return nil, nil end
    if part:IsA("ProximityPrompt") then return part, part.Parent end
    return part:FindFirstChildWhichIsA("ProximityPrompt", true), part
end
function ggTargetBalls(hoard, wl)
    local out = {}
    local vis = hoard:FindFirstChild("ItemVisuals")
    if not vis then return out end
    for _, b in ipairs(vis:GetChildren()) do
        if b.Name:match("^GlassBall%d+$") then
            local nm = b:GetAttribute("ItemName")
            if type(nm) == "string" and wl[nm] then out[#out + 1] = b end
        end
    end
    return out
end
function ggPendingReleased(itemsFolder, wl)
    for _, c in ipairs(itemsFolder:GetChildren()) do
        if wl[c.Name] and c:FindFirstChild("Capsule") then return true end
    end
    return false
end
gg.HOARD_MAX = 30
function gg.hoardFull(hoard)
    local c = hoard and hoard:GetAttribute("HoardCount")
    return type(c) == "number" and c >= gg.HOARD_MAX
end
function gg.razzleRange(pos)
    local r  = S.razzleRadius or 60
    local r2 = r * r
    local cr = workspace:FindFirstChild("CurrentRoom")
    if not cr then return false end
    for _, room in ipairs(cr:GetChildren()) do
        local mf = room:FindFirstChild("Monsters")
        if mf then
            for _, m in ipairs(mf:GetChildren()) do
                if m.Name == "RazzleDazzleMonster" and m:GetAttribute("Awake") == true then
                    local prim = m.PrimaryPart or m:FindFirstChild("HumanoidRootPart")
                              or m:FindFirstChildWhichIsA("BasePart", true)
                    if prim then
                        local d = prim.Position - pos
                        if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= r2 then return true end
                    end
                end
            end
        end
    end
    return false
end
function gg.unsafe(hoard)
    local ok, pos = pcall(function() return hoard:GetPivot().Position end)
    if not ok or not pos then return false end
    local hasTen, hasBlot = IsTendrilNearGen(pos)
    if hasTen or hasBlot then return true end
    return gg.razzleRange(pos)
end
function ggStandCFrame(hoard, promptPart)
    local tpf = hoard:FindFirstChild("TeleportPositions")
    local tp  = tpf and (tpf:FindFirstChild("TeleportPosition") or tpf:FindFirstChildWhichIsA("BasePart", true))
    if tp and tp:IsA("BasePart") then
        return tp.CFrame * CFrame.new(0, C.teleportHeight or 3, 0)
    end
    if promptPart and promptPart:IsA("BasePart") then
        return CFrame.new(promptPart.Position + Vector3.new(0, 3, 0))
    end
    return nil
end
S.regGame(function()
    while true do
        task.wait(0.25)
        if R.isR or not S.autoGigiClaw or not S.autoEnabled then S.gigiBusy = false; continue end
        local fa = R.gfv()
        if not (fa and fa:IsA("BoolValue") and fa.Value == true) then S.gigiBusy = false; continue end
        local hoard, itemsFolder = ggFindHoard()
        if not hoard then S.gigiBusy = false; continue end
        if gg.hoardFull(hoard) then S.gigiBusy = false; continue end
        local pp, promptPart = ggGetPrompt(hoard)
        if not pp then continue end
        pcall(function() pp.HoldDuration = 0 end)
        if tick() < gg.giveUpUntil then continue end
        local wl, any = ggWhitelistSet()
        if not any then continue end
        local char = plr.Character
        local hrp  = char and char.PrimaryPart
        if not hrp then continue end
        if S.pickingUp or R.gag() or IsPanicActive() or IsInChaseClearWait() then continue end
        if GetDangerState() then continue end
        if R.idso() or R.icv() then continue end
        if IsInventoryFull() then continue end
        if S.autoEncounter and S.trigOk("encounter") then
            local ae = _G.yattaAE
            if ae and not ae.allDone then continue end
        end
        if ggPendingReleased(itemsFolder, wl) then continue end
        if #ggTargetBalls(hoard, wl) == 0 then continue end
        local standCF = ggStandCFrame(hoard, promptPart)
        if not standCF then continue end
        if gg.unsafe(hoard) then continue end
        if promptPart and promptPart:IsA("BasePart")
           and IsCachedMonsterNearPosition(promptPart.Position, K.monSkipR, false, true) then continue end

        S.gigiBusy = true
        local before = {}
        for _, c in ipairs(itemsFolder:GetChildren()) do before[c] = true end
        local clicks, startT = 0, tick()
        local gotName = nil
        while S.autoGigiClaw and S.autoEnabled do
            if not (hoard.Parent and pp.Parent) then break end
            local fa2 = R.gfv()
            if not (fa2 and fa2:IsA("BoolValue") and fa2.Value == true) then break end
            if R.gag() or IsPanicActive() or GetDangerState() then break end
            if IsInventoryFull() then break end
            if gg.hoardFull(hoard) or gg.unsafe(hoard) then break end
            if promptPart and promptPart:IsA("BasePart")
               and IsCachedMonsterNearPosition(promptPart.Position, K.monSkipR, false, true) then
                gg.giveUpUntil = tick() + 5
                break
            end
            local released = false
            for _, c in ipairs(itemsFolder:GetChildren()) do
                if not before[c] and wl[c.Name] and c:FindFirstChild("Capsule") then
                    released = true; gotName = c.Name; break
                end
            end
            if released then break end
            if #ggTargetBalls(hoard, wl) == 0 then break end
            local hrp2 = plr.Character and plr.Character.PrimaryPart
            if not hrp2 then break end
            if (hrp2.Position - standCF.Position).Magnitude > 6 then
                WaitForSafeHideRelease()
                hrp2.CFrame = standCF
                hrp2.AssemblyLinearVelocity = Vector3.zero
            end
            pcall(function() pp.HoldDuration = 0 end)
            if pp.Enabled then
                clicks = clicks + 1
                if fireproximityprompt then
                    pcall(fireproximityprompt, pp)
                else
                    pcall(function() pp:InputHoldBegin(); task.wait(); pp:InputHoldEnd() end)
                end
            end
            if clicks >= 80 or (tick() - startT) > 60 then
                gg.giveUpUntil = tick() + 20
                break
            end
            task.wait(0.1)
        end
        S.gigiBusy = false
        if gotName and _G.YattaNotify then
            _G.YattaNotify("Got " .. gotName .. " from Gigi!", false, Color3.fromRGB(120, 255, 140))
        end
    end
end)
do
local ggEsp = { hoard = nil, hl = nil, bb = nil, lbl = nil, text = nil }
function ggEspClear()
    if ggEsp.hl then pcall(function() ggEsp.hl:Destroy() end) end
    if ggEsp.bb then pcall(function() ggEsp.bb:Destroy() end) end
    ggEsp.hoard, ggEsp.hl, ggEsp.bb, ggEsp.lbl, ggEsp.text = nil, nil, nil, nil, nil
end
function ggItemNames(hoard)
    local balls = {}
    local vis = hoard:FindFirstChild("ItemVisuals")
    if vis then
        for _, b in ipairs(vis:GetChildren()) do
            local n = b.Name:match("^GlassBall(%d+)$")
            if n then balls[#balls + 1] = { idx = tonumber(n), ball = b } end
        end
    end
    table.sort(balls, function(a, b) return a.idx < b.idx end)
    local names = {}
    for _, e in ipairs(balls) do
        local nm = e.ball:GetAttribute("ItemName")
        if type(nm) == "string" and nm ~= "" then names[#names + 1] = nm end
    end
    return names
end
function ggJoinNames(names)
    local n = #names
    if n == 0 then return "none" end
    if n == 1 then return names[1] end
    if n == 2 then return names[1] .. " and " .. names[2] end
    return table.concat(names, ", ", 1, n - 1) .. ", and " .. names[n]
end
regSpawn(function()
    while true do
        task.wait(0.5)
        if R.isR or not R.espe.gigiMachine then
            if ggEsp.hoard then ggEspClear() end
            continue
        end
        local hoard = ggFindHoard()
        if not hoard then
            if ggEsp.hoard then ggEspClear() end
            continue
        end
        if ggEsp.hoard ~= hoard or not (ggEsp.hl and ggEsp.hl.Parent) or not (ggEsp.bb and ggEsp.bb.Parent) then
            ggEspClear()
            local prim = hoard:IsA("BasePart") and hoard
                      or (hoard:IsA("Model") and (hoard.PrimaryPart or hoard:FindFirstChildWhichIsA("BasePart", true)))
            if not prim then continue end
            local hl = Instance.new("Highlight")
            hl.Name                = "YattaGigiESP"
            hl.Adornee             = hoard
            hl.FillColor           = Color3.fromRGB(139, 0, 0)
            hl.FillTransparency    = 0.5
            hl.OutlineColor        = Color3.fromRGB(255, 0, 0)
            hl.OutlineTransparency = 0
            hl.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
            hl.Parent              = R.vf or workspace
            local bb = Instance.new("BillboardGui")
            bb.Name         = "YattaGigiESPLabel"
            bb.Adornee      = prim
            bb.AlwaysOnTop  = true
            bb.Size         = UDim2.new(0, 260, 0, 54)
            bb.StudsOffset  = Vector3.new(0, 5, 0)
            bb.ResetOnSpawn = false
            bb:SetAttribute("YattaGUI_Billboard", true)
            local lbl = Instance.new("TextLabel", bb)
            lbl.Size                   = UDim2.new(1, 0, 1, 0)
            lbl.BackgroundTransparency = 1
            lbl.TextColor3             = Color3.fromRGB(255, 60, 60)
            lbl.TextStrokeTransparency = 0
            lbl.TextStrokeColor3       = Color3.new(0, 0, 0)
            lbl.Font                   = Enum.Font.GothamBold
            lbl.TextSize               = 14
            lbl.TextWrapped            = true
            lbl.Text                   = ""
            bb.Parent = R.vf or workspace
            ggEsp.hoard, ggEsp.hl, ggEsp.bb, ggEsp.lbl = hoard, hl, bb, lbl
        end
        local hlOn = not (P.hle and P.hle.gigiMachine == false)
        if ggEsp.hl.Enabled ~= hlOn then ggEsp.hl.Enabled = hlOn end
        local infoOn = S.gigiEspInfo ~= false
        if ggEsp.bb.Enabled ~= infoOn then ggEsp.bb.Enabled = infoOn end
        local text = "Gigi Machine\nitems: " .. ggJoinNames(ggItemNames(hoard))
        if text ~= ggEsp.text and ggEsp.lbl then
            ggEsp.lbl.Text = text
            ggEsp.text = text
        end
    end
end)
end
end
do
    local function firstPart(m)
        if m:IsA("BasePart") then return m end
        return m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart", true)
    end
    local function doorPrompt(door)
        for _, d in ipairs(door:GetDescendants()) do
            if d:IsA("ProximityPrompt") then return d end
        end
        return nil
    end
    local function collectDoors()
        local out = {}
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return out end
        for _, room in ipairs(cr:GetChildren()) do
            local f = room:FindFirstChild("TrickOrTreatDoors")
            if f then
                for _, door in ipairs(f:GetChildren()) do
                    if door:IsA("Model") then out[#out + 1] = door end
                end
            end
        end
        table.sort(out, function(a, b) return a.Name < b.Name end)
        return out
    end
    local function collectPieces()
        local out = {}
        local cr = workspace:FindFirstChild("CurrentRoom")
        if not cr then return out end
        for _, room in ipairs(cr:GetChildren()) do
            local f = room:FindFirstChild("HolidayPickups")
            if f then
                for _, c in ipairs(f:GetChildren()) do
                    if c:IsA("Model") or c:IsA("BasePart") then out[#out + 1] = c end
                end
            end
        end
        return out
    end
    local function doorText(door, idx, total)
        local pp = doorPrompt(door)
        local status = "no prompt"
        if pp then status = (pp.Enabled ~= false) and "ready" or "done" end
        local title = (total > 1) and ("Trick or Treat Door " .. idx .. "/" .. total) or "Trick or Treat Door"
        return title .. "\n<font color=\"#FFFFFF\">" .. status .. "</font>"
    end
    local function pieceText(piece, idx, total)
        return "Collectable Piece"
    end
    local function runEsp(key, fillC, textFn, collect, doneFn, offY, lblC)
        local labels = setmetatable({}, { __mode = "k" })
        local function update()
            local set = R.esph[key]
            if R.isR or not R.espe[key] then
                for m, hl in pairs(set) do pcall(function() hl:Destroy() end); set[m] = nil end
                for m, bb in pairs(labels) do pcall(function() bb:Destroy() end); labels[m] = nil end
                return
            end
            local targets = collect()
            local hlOn   = not (P.hle and P.hle[key] == false)
            local infoOn = not (S.espInfo and S.espInfo[key] == false)
            for idx, tgt in ipairs(targets) do
                local hl = set[tgt]
                if not (hl and hl.Parent) then
                    hl = Instance.new("Highlight")
                    hl.Name                = "Yatta" .. key .. "ESP"
                    hl.Adornee             = tgt
                    hl.FillColor           = fillC
                    hl.FillTransparency    = 0.5
                    hl.OutlineColor        = Color3.fromRGB(255, 255, 255)
                    hl.OutlineTransparency = 0
                    hl.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
                    hl.Parent              = R.vf or workspace
                    set[tgt] = hl
                end
                local hlWant = hlOn
                if hlWant and doneFn and S.espHideDone and S.espHideDone[key] then
                    local okD, isDone = pcall(doneFn, tgt)
                    if okD and isDone then hlWant = false end
                end
                if hl.Enabled ~= hlWant then hl.Enabled = hlWant end
                local bb = labels[tgt]
                if not (bb and bb.Parent) then
                    local prim = firstPart(tgt)
                    if prim then
                        bb = Instance.new("BillboardGui")
                        bb.Name         = "Yatta" .. key .. "Label"
                        bb.Adornee      = prim
                        bb.AlwaysOnTop  = true
                        bb.Size         = UDim2.new(0, 220, 0, 40)
                        bb.StudsOffset  = Vector3.new(0, offY or 4, 0)
                        bb.ResetOnSpawn = false
                        bb:SetAttribute("YattaGUI_Billboard", true)
                        local lbl = Instance.new("TextLabel", bb)
                        lbl.Name                   = "Text"
                        lbl.Size                   = UDim2.new(1, 0, 1, 0)
                        lbl.BackgroundTransparency = 1
                        lbl.TextColor3             = lblC or fillC
                        lbl.TextStrokeTransparency = 0
                        lbl.Font                   = Enum.Font.GothamBold
                        lbl.TextSize               = 14
                        lbl.TextWrapped            = true
                        lbl.RichText               = true
                        bb.Parent = R.vf or workspace
                        labels[tgt] = bb
                    end
                end
                if bb and bb.Parent then
                    if bb.Enabled ~= infoOn then bb.Enabled = infoOn end
                    local lbl = bb:FindFirstChild("Text")
                    if lbl then
                        local txt = textFn(tgt, idx, #targets)
                        if lbl.Text ~= txt then lbl.Text = txt end
                    end
                end
            end
            for m, hl in pairs(set) do
                if not (m and m.Parent) then
                    pcall(function() hl:Destroy() end); set[m] = nil
                    if labels[m] then pcall(function() labels[m]:Destroy() end); labels[m] = nil end
                end
            end
        end
        S.espRefresh = S.espRefresh or {}
        S.espRefresh[key] = update
        regSpawn(function()
            while true do
                task.wait(0.7)
                pcall(update)
            end
        end)
    end
    runEsp("totDoors",      Color3.fromRGB(255, 140, 0), doorText,  collectDoors, function(door)
        local pp = doorPrompt(door)
        return pp ~= nil and pp.Enabled == false
    end)
    runEsp("collectibles",  Color3.fromRGB(255, 215, 0), pieceText, collectPieces)
    local fakeCache
    local function findRealElev()
        local es = workspace:FindFirstChild("Elevators")
        local m = es and es:FindFirstChild("Elevator") or workspace:FindFirstChild("Elevator")
        if m and m:IsA("Model") then
            local inner = m:FindFirstChild("Elevator")
            return (inner and inner:IsA("Model")) and inner or m
        end
        return nil
    end
    local function findFakeElev()
        if fakeCache and fakeCache.Parent then return fakeCache end
        fakeCache = nil
        local es = workspace:FindFirstChild("Elevators")
        local m = es and es:FindFirstChild("FakeElevator") or workspace:FindFirstChild("FakeElevator")
        if not m then
            local cr = workspace:FindFirstChild("CurrentRoom")
            m = cr and cr:FindFirstChild("FakeElevator", true)
        end
        if m and m:IsA("Model") then fakeCache = m end
        return fakeCache
    end
    local function doorsOf(m)
        local out = {}
        if not m then return out end
        for _, n in ipairs({ "ElevatorDoor", "Door" }) do
            local d = m:FindFirstChild(n)
            if d and (d:IsA("Model") or d:IsA("BasePart")) then out[1] = d; break end
        end
        return out
    end
    local white = Color3.fromRGB(255, 255, 255)
    runEsp("elevator",      Color3.fromRGB(80, 200, 255), function() return "Elevator" end,
        function() return doorsOf(findRealElev()) end, nil, 12, white)
    runEsp("fakeElevator",  Color3.fromRGB(190, 120, 255), function() return "Fake Elevator" end,
        function() return doorsOf(findFakeElev()) end, nil, 12, white)
end
K.dyleFarDist = K.dyleFarDist or 80
function S.dyleApproach(hrp, targetPos)
    if true then return false end
    if R.isR or not S.safeHide or not S.safeHideEnter or not S.isDyleFloor() then return false end
    if not (hrp and hrp.Parent and targetPos) then return false end
    if S.dyleWalking then
        S.dyleTarget = targetPos
        return true
    end
    local p0 = hrp.Position
    local flat0 = math.sqrt((targetPos.X - p0.X) ^ 2 + (targetPos.Z - p0.Z) ^ 2)
    if flat0 <= 35 or flat0 < K.dyleFarDist then return false end
    S.dyleWalking = true
    S.dyleTarget = targetPos
    local walkGen = (S.dyleWalkGen or 0) + 1
    S.dyleWalkGen = walkGen
    task.spawn(function()
        local rsv = game:GetService("RunService")
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.RespectCanCollide = true
        local skipT = 0
        local function refreshSkip(ch)
            local skip = { ch }
            for _, c in ipairs(workspace:GetChildren()) do
                if string.sub(c.Name, 1, 5) == "Yatta" then skip[#skip + 1] = c end
            end
            rp.FilterDescendantsInstances = skip
        end
        local function groundAt(x, y, z)
            local hit = workspace:Raycast(Vector3.new(x, y + 4, z), Vector3.new(0, -24, 0), rp)
            return hit and hit.Position.Y or nil
        end
        while S.dyleWalkGen == walkGen do
            local ch  = plr.Character
            local h   = ch and ch:FindFirstChild("HumanoidRootPart")
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            local fa  = R.gfv()
            if not (h and hum and hum.Health > 0) or not S.autoEnabled or not S.safeHide
               or not (fa and fa:IsA("BoolValue") and fa.Value == true) or IsPanicActive() then break end
            local tp = S.dyleTarget
            if not tp then break end
            local pos = h.Position
            local dx, dz = tp.X - pos.X, tp.Z - pos.Z
            local dist = math.sqrt(dx * dx + dz * dz)
            if dist <= 35 then break end
            local okD, clear = pcall(S.shDetClear, pos)
            local seen = false
            if S.seenNow then
                local okS, sn = pcall(S.seenNow)
                seen = okS and sn and true or false
            end
            if (okD and clear == false) or seen then
                pcall(function() h.AssemblyLinearVelocity = Vector3.zero end)
                if not S.shActive then pcall(S.safeHideEnter, h, 3, 15, "seen") end
                task.wait(0.15)
            elseif S.shActive or S.shTweening or (S.shBusy and S.shBusy()) or S.pickingUp or S.collectBusy or S.gigiBusy or S.totBusy then
                task.wait(0.15)
            else
                local dt = math.min(rsv.Heartbeat:Wait(), 0.05)
                pcall(S.shSprintNow, h)
                if tick() - skipT > 1 then skipT = tick(); refreshSkip(ch) end
                local ws = math.max(math.min(hum.WalkSpeed, 16), 4)
                local step = ws * dt
                local ux, uz = dx / dist, dz / dist
                local nx, nz = pos.X + ux * step, pos.Z + uz * step
                local ny = pos.Y
                local g0 = groundAt(pos.X, pos.Y, pos.Z)
                local g1 = groundAt(nx, pos.Y, nz)
                if g0 and g1 and math.abs(g1 - g0) < 6 then ny = pos.Y + (g1 - g0) end
                h.CFrame = CFrame.lookAt(Vector3.new(nx, ny, nz), Vector3.new(nx + ux, ny, nz + uz))
                h.AssemblyLinearVelocity = Vector3.zero
            end
        end
        if S.dyleWalkGen == walkGen then S.dyleWalking = false end
        pcall(S.shSprintStop)
    end)
    return true
end
do
function DoNormalAutoFarm(hrp, currentBase, isDanger, isPanicChecked, floorActive, activeGen, pumpkinDanger)
    if not S.autoEnabled then
        if S.FarmBall then S.FarmBall.Transparency=1 end; return
    end
    if S.shLastExit and tick() - S.shLastExit < 6 and hrp then
        local okX, clearX = false, true
        if S.shDetClear then okX, clearX = pcall(S.shDetClear, hrp.Position) end
        if okX and clearX == false then
            if S.FarmBall then S.FarmBall.Transparency=1 end
            Cache.lastPositionedFarm = nil
            return
        end
    end
    if S.shBusy and S.shBusy() then
        if S.FarmBall then S.FarmBall.Transparency=1 end
        Cache.lastPositionedFarm = nil
        return
    end
    if S.gigiBusy or S.collectBusy or S.totBusy or (S.totPending and S.totPending()) then
        if S.FarmBall then S.FarmBall.Transparency=1 end; return
    end
    if not isPanicChecked and tick() < (S.autoFarmWarnUntil or 0) then
        if activeGen then
            pcall(function() R.fsg(activeGen) end)
            pcall(function() R.fsgcr(activeGen) end)
        end
        if S.FarmBall then S.FarmBall.Transparency=1 end
        Cache.lastPositionedFarm = nil
        S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
        return
    end
    if not isPanicChecked and #S.rollingPumpkins() > 0 then
        if S.safeHide and S.safeHideEnter and not S.shActive and pumpkinDanger then
            S.safeHideEnter(hrp, 3, 15, "pumpkin")
        end
        if activeGen then
            pcall(function() R.fsg(activeGen) end)
            pcall(function() R.fsgcr(activeGen) end)
        end
        if S.FarmBall then S.FarmBall.Transparency=1 end
        Cache.lastPositionedFarm = nil
        S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
        return
    end
    if (isDanger and not pumpkinDanger) or isPanicChecked then
        if S.FarmBall then S.FarmBall.Transparency=1 end
        Cache.lastPositionedFarm = nil
        S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
        return
    end
    if R.idso() or R.icv() then
        if S.FarmBall then S.FarmBall.Transparency=1 end; return
    end
    if S.pickingUp then
        S.pendWaitSince = nil
        if S.FarmBall then S.FarmBall.Transparency=1 end; return
    end
    if S.pickupEnabled and not activeGen and not IsPickupBlocked() and tick() - (S.pickupThreatSkipT or -10) > 3 then
        local ok, pendingItems = pcall(function() return R.gai() end)
        if ok and pendingItems and #pendingItems > 0 then
            S.pendWaitSince = S.pendWaitSince or tick()
            if tick() - S.pendWaitSince < 10 then
                if S.FarmBall then S.FarmBall.Transparency=1 end
                return
            end
        else
            S.pendWaitSince = nil
        end
    end
    if IsInChaseClearWait() then
        if S.FarmBall then S.FarmBall.Transparency=1 end
        TryTeleportToBaseIfIdle(hrp, currentBase); Cache.lastPositionedFarm = nil; return
    end
    if tick() - (S.lastFarmTeleport or 0) < K.farmTpCooldown then return end
    S.lastFarmTeleport = tick()
    if activeGen then
        if IsConnieGen(activeGen) then
            pcall(function() R.fsg(activeGen) end)
            pcall(function() R.fsgcr(activeGen) end)
            Cache.lastPositionedFarm = nil
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
            TryTeleportToBaseIfIdle(hrp, currentBase); return
        end
        if S.ptpGen ~= activeGen then
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
        end
        if IsGenCompleted(activeGen) then
            S.lastGenT = tick()
            pcall(function() R.fsg(activeGen) end)
            pcall(function() R.fsgcr(activeGen) end)
            Cache.lastPositionedFarm = nil
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
            TryTeleportToBaseIfIdle(hrp, currentBase); return
        end
        if IsDualGen(activeGen.Name) then
            if IsDualGenFullyOccupied(activeGen) then
                Cache.lastPositionedFarm = nil; S.ptpPend = false; S.ptpGen = nil
                TeleportToElevOrEmergencyBase(hrp); return
            end
            local slot = GetDualGenSlotForPlayer(activeGen)
            if slot == nil then
                Cache.lastPositionedFarm = nil; S.ptpPend = false; S.ptpGen = nil
                TryTeleportToBaseIfIdle(hrp, currentBase); return
            end
        else
            if IsGenOccupiedByOtherPlayer(activeGen) then
                Cache.lastPositionedFarm = nil; S.ptpPend = false; S.ptpGen = nil
                TeleportToElevOrEmergencyBase(hrp); return
            end
        end
        local genPos   = activeGen:GetPivot().Position
        local hasTen, hasBlot = IsTendrilNearGen(genPos)
        if hasTen or hasBlot then
            pcall(function() R.fsg(activeGen) end)
            pcall(function() R.fsgcr(activeGen) end)
            Cache.lastPositionedFarm = nil
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
            if S.safeTp and currentBase and not R.ibb(currentBase, hrp.Position) then
                if tick() - (S.lastFarmBaseTP or 0) >= C.baseTpCooldown then
                    S.lastFarmBaseTP = tick(); S.hideAway(hrp, currentBase, 6)
                end
            end
            return
        end
        local blockedByRealMonster = IsCachedMonsterNearPosition(genPos, C.genActiveMonsterRadius or 40, false, true)
        if not R.igs(activeGen) and blockedByRealMonster then
            Cache.lastPositionedFarm = nil
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
            if S.safeTp and currentBase and not R.ibb(currentBase, hrp.Position) then
                S.hideAway(hrp, currentBase, 6)
            end
            return
        end
        if not IsGenSafeFromBalls(activeGen) then
            Cache.lastPositionedFarm = nil
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
            if S.safeTp and currentBase and not R.ibb(currentBase, hrp.Position) then
                if tick() - (S.lastFarmBaseTP or 0) >= C.baseTpCooldown then
                    S.lastFarmBaseTP = tick(); S.hideAway(hrp, currentBase, 6)
                end
            end
            return
        end
        if IsCachedMonsterNearGen(genPos, C.genApproachClearRadius, false) then
            Cache.lastPositionedFarm = nil
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
            if S.safeTp and currentBase and not R.ibb(currentBase, hrp.Position) then
                if tick() - (S.lastFarmBaseTP or 0) >= C.baseTpCooldown then
                    S.lastFarmBaseTP = tick(); S.hideAway(hrp, currentBase, 6)
                end
            end
            return
        end
        local isNewGen = (activeGen ~= Cache.lastPositionedFarm)
        if isNewGen then
            local okDC, clearDC = pcall(S.shDetClear, genPos)
            if okDC and clearDC == false then
                Cache.lastPositionedFarm = nil
                S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
                if S.safeTp and currentBase and not R.ibb(currentBase, hrp.Position) then
                    if tick() - (S.lastFarmBaseTP or 0) >= C.baseTpCooldown then
                        S.lastFarmBaseTP = tick(); S.hideAway(hrp, currentBase, 6)
                    end
                end
                return
            end
        end
        if isNewGen and S.dyleApproach(hrp, genPos) then return end   
        if isNewGen then
            Cache.lastPositionedFarm = activeGen
            S.farmPromptFiredForGen = nil
            local useMirror = false
            if IsDualGen(activeGen.Name) then
                local m = DualGenSlotUsable(activeGen)
                if m == nil then Cache.lastPositionedFarm = nil; return end
                useMirror = m
            end
            TeleportToGenSimple(hrp, activeGen, useMirror)
            local alreadyDecoding = (R.gag() == activeGen)
            if activeGen and activeGen.Parent and not alreadyDecoding then
                FireGenProximityPrompts(activeGen)
                S.farmPromptFiredForGen = activeGen
            end
            schedulePipeTP(hrp, activeGen)
        else
            local stillDecoding = (R.gag() == activeGen)
            if not stillDecoding and S.ptpDone and activeGen and activeGen.Parent then
                if S.farmPromptFiredForGen ~= activeGen then
                    FireGenProximityPrompts(activeGen)
                    S.farmPromptFiredForGen = activeGen
                end
            elseif S.ptpDone and activeGen and activeGen.Parent then
                local pipe = FindBaseMachinePipe(activeGen)
                if pipe then
                    local dv = hrp.Position - pipe.Position
                    local distSq = dv.X*dv.X + dv.Y*dv.Y + dv.Z*dv.Z
                    if distSq > K.pipeDsq then TeleportToGenPipe(hrp, activeGen) end
                end
            end
        end
        return
    end
    Cache.lastPositionedFarm = nil
    S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
    if tick() - (S.lastGenT or 0) < K.postCompW then
        TryTeleportToBaseIfIdle(hrp, currentBase); return
    end
    if S.autoUseAbilitySquirm and _G.YattaEffToon() == "Squirm" then
        local igp2 = workspace:FindFirstChild(_G.YattaIGP)
        local pm2  = igp2 and igp2:FindFirstChild(plr.Name)
        local ab1  = pm2 and pm2:FindFirstChild("Abilities") and pm2.Abilities:FindFirstChild("Ability1")
        local cd2  = ab1 and ab1:FindFirstChild("CurrentCooldown")
        if cd2 and cd2.Value == 0 then
            TeleportToElevOrEmergencyBase(hrp)
            return
        end
    end
    local safeCached = {}
    for _, gen in ipairs(Cache.genList) do
        if not gen.Parent then continue end
        if IsConnieGen(gen) then continue end
        local genPos2 = Cache.genPivotCache[gen] or gen:GetPivot().Position
        local hasTen2, hasBlot2 = IsTendrilNearGen(genPos2)
        if hasTen2 or hasBlot2 then continue end
        if IsDualGen(gen.Name) then
            if IsDualGenFullyOccupied(gen) then continue end
            if DualGenSlotUsable(gen) == nil then continue end
        else
            if IsGenOccupiedByOtherPlayer(gen) then continue end
        end
        if R.igs(gen) and IsGenSafeFromBalls(gen)
           and not S.twistedNearGen(genPos2, C.genApproachClearRadius, false) then safeCached[#safeCached+1] = gen end
    end
    if #safeCached == 0 then
        if S.FarmBall then S.FarmBall.Transparency=1 end
        if tick() - (S.lastFarmBaseTP or 0) >= C.baseTpCooldown then
            S.lastFarmBaseTP = tick()
            TeleportToElevOrEmergencyBase(hrp)
        end
        S.noGenTPd = true
        return
    end
    S.noGenTPd = false
    local function IsTreadmillGen(gen)
        if not gen or not gen.Parent then return false end
        local mt = gen:GetAttribute("MinigameType")
        if mt == "MovementTreadmill" then return true end
        local mts = gen:GetAttribute("MinigameTypes")
        if type(mts) == "string" then
            for part in mts:gmatch("[^,]+") do
                if part:match("^%s*MovementTreadmill%s*$") then return true end
            end
        end
        return false
    end
    local function SelectUsableGen(list)
        local sorted = {}
        for _, gen in ipairs(list) do sorted[#sorted + 1] = gen end
        table.sort(sorted, function(a, b)
            local aa = ((S.genAvoid[a] or 0) > tick()) and true or false
            local ab = ((S.genAvoid[b] or 0) > tick()) and true or false
            if aa ~= ab then return ab end
            local pa = Cache.genPivotCache[a] or a:GetPivot().Position
            local pb = Cache.genPivotCache[b] or b:GetPivot().Position
            return (hrp.Position - pa).Magnitude < (hrp.Position - pb).Magnitude
        end)
        for _, gen in ipairs(sorted) do
            if IsDualGen(gen.Name) then
                local m = DualGenSlotUsable(gen)
                if m ~= nil then return gen, m end
            else
                return gen, false
            end
        end
        return nil, false
    end
    local closestGen, useMirrorSelected = nil, false
    if S.extractTreadmillsFirst then
        local treadmillSafe = {}
        for _, gen in ipairs(safeCached) do
            if IsTreadmillGen(gen) and not IsGenCompleted(gen) then
                treadmillSafe[#treadmillSafe + 1] = gen
            end
        end
        closestGen, useMirrorSelected = SelectUsableGen(treadmillSafe)
    end
    if not closestGen then
        closestGen, useMirrorSelected = SelectUsableGen(safeCached)
    end
    if not closestGen then TryTeleportToBaseIfIdle(hrp, currentBase); return end
    local closestGenPos = Cache.genPivotCache[closestGen] or closestGen:GetPivot().Position
    if IsCachedMonsterNearGen(closestGenPos, C.genApproachClearRadius, false) or not IsGenSafeFromBalls(closestGen)
       or S.twistedNearGen(closestGenPos, C.genApproachClearRadius, false, true) then
        if S.FarmBall then S.FarmBall.Transparency=1 end
        if S.safeTp and currentBase and not R.ibb(currentBase, hrp.Position) then
            if tick() - (S.lastFarmBaseTP or 0) >= C.baseTpCooldown then
                S.lastFarmBaseTP = tick(); S.hideAway(hrp, currentBase, 6)
            end
        else TryTeleportToBaseIfIdle(hrp, currentBase) end
        return
    end
    if not S.FarmBall then
        S.FarmBall = R.cb(C.farmBallRadius, Color3.fromRGB(0,255,100))
    end
    S.FarmBall.CFrame = closestGen:GetPivot(); S.FarmBall.Transparency = 1
    local isNewGen2 = (closestGen ~= Cache.lastPositionedFarm)
    if isNewGen2 and S.dyleApproach(hrp, closestGenPos) then return end   
    if isNewGen2 then
        Cache.lastPositionedFarm = closestGen
        S.farmPromptFiredForGen = nil
        TeleportToGenSimple(hrp, closestGen, useMirrorSelected)
        local alreadyDecoding2 = (R.gag() == closestGen)
        if closestGen and closestGen.Parent and not alreadyDecoding2 then
            FireGenProximityPrompts(closestGen)
            S.farmPromptFiredForGen = closestGen
        end
        schedulePipeTP(hrp, closestGen)
    else
        local stillDecoding2 = (R.gag() == closestGen)
        if not stillDecoding2 and S.ptpDone and closestGen and closestGen.Parent then
            if S.farmPromptFiredForGen ~= closestGen then
                FireGenProximityPrompts(closestGen)
                S.farmPromptFiredForGen = closestGen
            end
        elseif S.ptpDone and closestGen and closestGen.Parent then
            local pipe2 = FindBaseMachinePipe(closestGen)
            if pipe2 then
                local dv2 = hrp.Position - pipe2.Position
                local distSq2 = dv2.X*dv2.X + dv2.Y*dv2.Y + dv2.Z*dv2.Z
                if distSq2 > K.pipeDsq then TeleportToGenPipe(hrp, closestGen) end
            end
        end
    end
    if not closestGen.Parent then
        if S.FarmBall then S.FarmBall.Transparency=1 end
    end
end
S.drainHealCooldown = S.drainHealCooldown or 0
function TryWasteHeal(char)
    local maxH = C.maxHeals or 2
    local inv  = R.gis(); if inv.healingCount <= maxH then return end
    local hum = char and char:FindFirstChildWhichIsA("Humanoid")
    local isDamaged = hum and (hum.Health < hum.MaxHealth)
    if not isDamaged and tick() - S.drainHealCooldown < K.drainCd then return end
    local sl = R.swi("Bandage") or R.swi("HealthKit")
    if sl then
        R.fis(sl); S.drainHealCooldown = tick()
        if isDamaged then S.wasteHealT = tick() end
    end
end
function UpdateMachineLocatorEmpty() end
function doInstantTendrilReact(spawnedObj)
    if S.tendrilDodgeHandled[spawnedObj] then return end
    S.tendrilDodgeHandled[spawnedObj] = true
    Cache.tendrilScanDirty = true
    Cache.espDirty         = true
    pcall(function()
        local tp = spawnedObj.PrimaryPart or spawnedObj:FindFirstChildWhichIsA("BasePart", true)
        if tp then
            local isBlot = (spawnedObj.Name ~= "SproutTendril")
            local already = false
            for _, entry in ipairs(Cache.tendrilPositions) do
                if entry.obj == spawnedObj then already = true; break end
            end
            if not already then
                Cache.tendrilPositions[#Cache.tendrilPositions+1] = {
                    pos = tp.Position, isBlot = isBlot, obj = spawnedObj,
                }
            end
            ApplyTendrilHighlight(spawnedObj)
            local ballColor = isBlot and Color3.fromRGB(255,78,178) or Color3.fromRGB(150,0,255)
            EnsureTendrilBall(spawnedObj, tp, K.tenGenR, ballColor)
        end
    end)
    spawnedObj.AncestryChanged:Connect(function()
        if not spawnedObj.Parent then
            S.tendrilDodgeHandled[spawnedObj] = nil
            for gen in pairs(S.genUnsafeByTendril) do
                if not gen.Parent then S.genUnsafeByTendril[gen] = nil end
            end
        end
    end)
    local char = plr.Character
    local hrp  = char and char.PrimaryPart
    if not hrp then return end
    local spawnPart = spawnedObj.PrimaryPart or spawnedObj:FindFirstChildWhichIsA("BasePart", true)
    if not spawnPart then return end
    local spawnPos = spawnPart.Position
    local activeGen = R.gag() or S.activeGen
    if activeGen and activeGen.Parent then
        local genPos = activeGen:GetPivot().Position
        local d      = spawnPos - genPos
        if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= K.tenGenRsq then
            S.genUnsafeByTendril[activeGen] = true
            R.fsg(activeGen)
            R.fsgcr(activeGen)
            if S.eggsonMode then stopEggsonDecodeFireLoop() end
            ClearPositionedGen()
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
        end
    end
    for _, gen in ipairs(Cache.genList) do
        if gen and gen.Parent then
            local gp = Cache.genPivotCache[gen] or gen:GetPivot().Position
            local d  = spawnPos - gp
            if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= K.tenGenRsq then
                S.genUnsafeByTendril[gen] = true
            end
        end
    end
    if not S.autoEnabled or S.safeHide then return end
    if S.pathfindMode and S.autoEnabled then return end
    local dodgeR  = C.tendrilDodgeRange or 25
    local dodgeR2 = dodgeR * dodgeR
    local dPlayer = hrp.Position - spawnPos
    if (dPlayer.X*dPlayer.X + dPlayer.Y*dPlayer.Y + dPlayer.Z*dPlayer.Z) > dodgeR2 then return end
    local currentBase = R.fb()
    local userInBase  = currentBase and R.ibb(currentBase, hrp.Position)
    if userInBase and currentBase then
        local alreadySafe = true
        for _, entry in ipairs(Cache.tendrilPositions) do
            local dv = hrp.Position - entry.pos
            if (dv.X*dv.X + dv.Y*dv.Y + dv.Z*dv.Z) <= dodgeR2 then
                alreadySafe = false; break
            end
        end
        if alreadySafe then
            local dv2 = hrp.Position - spawnPos
            if (dv2.X*dv2.X + dv2.Y*dv2.Y + dv2.Z*dv2.Z) <= dodgeR2 then
                alreadySafe = false
            end
        end
        if not alreadySafe then
            local avoidList = {}
            for _, entry in ipairs(Cache.tendrilPositions) do avoidList[#avoidList+1] = entry.pos end
            if not table.find(avoidList, spawnPos) then
                avoidList[#avoidList+1] = spawnPos
            end
            local safeCF = R.fsbs(currentBase, avoidList, dodgeR)
            if safeCF then
                WaitForSafeHideRelease()
                hrp.CFrame = safeCF
            end
            S.safeSptOk = true
        end
    else
        local hrpPos  = hrp.Position
        local ten     = Cache.tendrilPositions
        local bestPos = hrpPos
        local maxDist = 0
        for angle = 0, 315, 45 do
            local dir  = Vector3.new(math.cos(math.rad(angle)), 0, math.sin(math.rad(angle)))
            local cp   = hrpPos + (dir * 15)
            local minD = math.huge
            for i = 1, #ten do
                local dv = cp - ten[i].pos
                local dm = math.sqrt(dv.X*dv.X + dv.Y*dv.Y + dv.Z*dv.Z)
                if dm < minD then minD = dm end
            end
            if minD > maxDist then maxDist = minD; bestPos = cp end
        end
        WaitForSafeHideRelease()
        hrp.CFrame = CFrame.new(bestPos.X, hrpPos.Y, bestPos.Z)
    end
end
function teardownInstantReactConns()
    for _, conn in ipairs(Cache.instantReactConns) do
        pcall(function() conn:Disconnect() end)
    end
    table.clear(Cache.instantReactConns)
end
function setupInstantReactForFolder(monstersFolder)
    local conn = monstersFolder.ChildAdded:Connect(function(child)
        if not child:IsA("Model") then return end
        if K.instantReactSet[child.Name] then
            if child.Parent then
                doInstantTendrilReact(child)
            end
        else
            local cfg = R.mons[child.Name]
            if cfg and not cfg.isGrab and R.espe.monsters then
                ApplyMonsterHighlight(child, cfg, false)
            elseif R.iumo(child) then
                if R.espe.unknownMonsters then
                    ApplyUnknownHighlight(child)
                    local prim = child.PrimaryPart or child:FindFirstChildWhichIsA("BasePart", true)
                    if prim then EnsureUnknownBall(child, prim) end
                end
            end
        end
        if child:IsA("Model") and child.Name == "RazzleDazzleMonster" then
            task.defer(function()
                if child.Parent then setupRazzleAttributeWatch(child) end
            end)
        end
        Cache.espDirty = true
    end)
    Cache.instantReactConns[#Cache.instantReactConns+1] = conn
    local connDesc = monstersFolder.DescendantAdded:Connect(function(desc)
        if not desc:IsA("Model") then return end
        if not K.instantReactSet[desc.Name] then return end
        if desc.Parent == monstersFolder then return end
        if desc.Parent then
            doInstantTendrilReact(desc)
        end
    end)
    Cache.instantReactConns[#Cache.instantReactConns+1] = connDesc
    local conn2 = monstersFolder.ChildRemoved:Connect(function(child)
        Cache.espDirty = true
        if child and K.instantReactSet[child.Name] then
            S.tendrilDodgeHandled[child] = nil
            for gen in pairs(S.genUnsafeByTendril) do
                S.genUnsafeByTendril[gen] = nil
            end
        end
    end)
    Cache.instantReactConns[#Cache.instantReactConns+1] = conn2
    local connDescR = monstersFolder.DescendantRemoving:Connect(function(desc)
        if not desc:IsA("Model") then return end
        if not K.instantReactSet[desc.Name] then return end
        if desc.Parent == monstersFolder then return end
        S.tendrilDodgeHandled[desc] = nil
        for gen in pairs(S.genUnsafeByTendril) do
            S.genUnsafeByTendril[gen] = nil
        end
        Cache.espDirty = true
    end)
    Cache.instantReactConns[#Cache.instantReactConns+1] = connDescR
end
function setupInstantESPForGensFolder(gensFolder)
    local conn = gensFolder.ChildAdded:Connect(function(child)
        InvalidateGenPPCache(child)
        cn.baseMachinePartCache[child] = nil
        if child:IsA("Model") then
            task.defer(function()
                if child.Parent then ApplyGenHighlight(child) end
            end)
        end
        Cache.espDirty = true
    end)
    Cache.instantReactConns[#Cache.instantReactConns+1] = conn
    local conn2 = gensFolder.ChildRemoved:Connect(function(child)
        Cache.espDirty = true
        if child then
            Cache.genESPColorKey[child]     = nil
            Cache.genPivotCache[child]      = nil
            cn.baseMachinePartCache[child] = nil
            ppc.cache[child] = nil
            cn.statsCache[child]           = nil
            cn.statsWatched[child]         = nil
        end
    end)
    Cache.instantReactConns[#Cache.instantReactConns+1] = conn2
end
function setupInstantESPForItemsFolder(itemsFolder)
    local conn = itemsFolder.ChildAdded:Connect(function(child)
        Cache.espDirty = true
    end)
    Cache.instantReactConns[#Cache.instantReactConns+1] = conn
    local conn2 = itemsFolder.ChildRemoved:Connect(function(child)
        Cache.espDirty = true
    end)
    Cache.instantReactConns[#Cache.instantReactConns+1] = conn2
end
function teardownRoomWatch()
    for _, conn in ipairs(Cache.roomWatchConns) do pcall(function() conn:Disconnect() end) end
    table.clear(Cache.roomWatchConns)
    teardownInstantReactConns()
end
function setupRoomWatch()
    teardownRoomWatch()
    local currentRoom = workspace:FindFirstChild("CurrentRoom")
    if not currentRoom then return end
    local rw = Cache.roomWatchConns
    local function watchFolder(folder)
        rw[#rw+1] = folder.ChildAdded:Connect(function()   Cache.scanDirty = true; Cache.espDirty = true end)
        rw[#rw+1] = folder.ChildRemoved:Connect(function() Cache.scanDirty = true; Cache.espDirty = true end)
    end
    for _, roomModel in ipairs(currentRoom:GetChildren()) do
        if roomModel:IsA("Model") then
            local mf = roomModel:FindFirstChild("Monsters")
            if mf then
                watchFolder(mf)
                setupInstantReactForFolder(mf)
                for _, child in ipairs(mf:GetChildren()) do
                    if child:IsA("Model") then
                        local cfg = R.mons[child.Name]
                        if R.TSet[child.Name] then
                            local prim = child.PrimaryPart or child:FindFirstChildWhichIsA("BasePart", true)
                            ApplyTendrilHighlight(child)
                            if prim then
                                local isBlot = child.Name ~= "SproutTendril"
                                local bc = isBlot and Color3.fromRGB(255,78,178) or Color3.fromRGB(150,0,255)
                                EnsureTendrilBall(child, prim, K.tenGenR, bc)
                            end
                        elseif cfg and not cfg.isGrab then
                            if R.espe.monsters then
                                ApplyMonsterHighlight(child, cfg, false)
                                if not cfg.farmIgnore then
                                    local prim = child.PrimaryPart or child:FindFirstChild("HumanoidRootPart")
                                    if prim then
                                        local r = cfg.detRadius or C.detectorRadius or 40
                                        EnsureMonsterBall(child, prim, r, Color3.fromRGB(0,255,255))
                                    end
                                end
                            end
                        elseif cfg and cfg.isGrab then
                            if R.espe.monsters then
                                local prim = child.PrimaryPart or child:FindFirstChildWhichIsA("BasePart", true)
                                if prim then EnsureGrabBall(child, prim, C.grabDodgeRange, Color3.fromRGB(255,0,150)) end
                            end
                        elseif R.iumo(child) then
                            if R.espe.unknownMonsters then
                                ApplyUnknownHighlight(child)
                                local prim = child.PrimaryPart or child:FindFirstChildWhichIsA("BasePart", true)
                                if prim then EnsureUnknownBall(child, prim) end
                            end
                        end
                        if child.Name == "RazzleDazzleMonster" then
                            task.defer(function()
                                if child.Parent then setupRazzleAttributeWatch(child) end
                            end)
                        end
                    end
                end
            end
            local gf = roomModel:FindFirstChild("Generators")
            if gf then
                setupInstantESPForGensFolder(gf)
                rw[#rw+1] = gf.ChildAdded:Connect(function(child)
                    Cache.scanDirty = true; Cache.espDirty = true
                    if child:IsA("Model") then
                        regSpawn(function()
                            task.wait(0.1)
                            watchConnieForGen(child)
                            watchGenStats(child)
                        end)
                    end
                end)
                rw[#rw+1] = gf.ChildRemoved:Connect(function(child)
                    Cache.scanDirty = true; Cache.espDirty = true
                    cn.connieCache[child]             = nil
                    cn.watchedGens[child]       = nil
                    cn.baseMachinePartCache[child] = nil
                    ppc.cache[child] = nil
                    cn.statsCache[child]           = nil
                    cn.statsWatched[child]         = nil
                    Cache.genESPColorKey[child]     = nil
                    Cache.genPivotCache[child]      = nil
                end)
                for _, gen in ipairs(gf:GetChildren()) do
                    if gen:IsA("Model") then
                        watchConnieForGen(gen)
                        watchGenStats(gen)
                        task.defer(function()
                            if gen.Parent then ApplyGenHighlight(gen) end
                        end)
                    end
                end
            end
            local itf = roomModel:FindFirstChild("Items")
            if itf then
                setupInstantESPForItemsFolder(itf)
                Cache.espDirty = true
            end
        end
    end
    rw[#rw+1] = currentRoom.ChildAdded:Connect(function(child)
        Cache.scanDirty = true; Cache.tendrilScanDirty = true; Cache.espDirty = true
        if child:IsA("Model") then
            regSpawn(function()
                local mf = child:WaitForChild("Monsters", 2)
                if mf then
                    watchFolder(mf)
                    setupInstantReactForFolder(mf)
                    for _, mc in ipairs(mf:GetChildren()) do
                        if mc:IsA("Model") then
                            if R.TSet[mc.Name] then
                                local prim = mc.PrimaryPart or mc:FindFirstChildWhichIsA("BasePart", true)
                                ApplyTendrilHighlight(mc)
                                if prim then
                                    local isBlot = mc.Name ~= "SproutTendril"
                                    EnsureTendrilBall(mc, prim, K.tenGenR,
                                        isBlot and Color3.fromRGB(255,78,178) or Color3.fromRGB(150,0,255))
                                end
                            else
                                local cfg = R.mons[mc.Name]
                                if cfg and not cfg.isGrab then
                                    if R.espe.monsters then
                                        ApplyMonsterHighlight(mc, cfg, false)
                                        if not cfg.farmIgnore then
                                            local prim = mc.PrimaryPart or mc:FindFirstChild("HumanoidRootPart")
                                            if prim then EnsureMonsterBall(mc, prim, cfg.detRadius or 40, Color3.fromRGB(0,255,255)) end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                local gf = child:WaitForChild("Generators", 2)
                if gf then
                    setupInstantESPForGensFolder(gf)
                    for _, gen in ipairs(gf:GetChildren()) do
                        if gen:IsA("Model") then
                            watchConnieForGen(gen)
                            watchGenStats(gen)
                            ApplyGenHighlight(gen)
                        end
                    end
                end
                local itf = child:WaitForChild("Items", 2)
                if itf then
                    setupInstantESPForItemsFolder(itf)
                    Cache.espDirty = true
                end
            end)
        end
    end)
    rw[#rw+1] = currentRoom.ChildRemoved:Connect(function()
        Cache.scanDirty = true; Cache.tendrilScanDirty = true; Cache.espDirty = true
    end)
end
