function clearESPTable(tbl)
    for obj, hl in pairs(tbl) do
        pcall(function() hl:Destroy() end); tbl[obj] = nil
    end
end
function cleanupESPTable(tbl)
    for obj, hl in pairs(tbl) do
        if not obj or not obj.Parent then
            pcall(function() hl:Destroy() end); tbl[obj] = nil
        end
    end
end
P.uae = function()
    local ESPh  = R.esph
    local ESPen = R.espe
    if ESPen.players then
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p == plr then continue end
            local char = p.Character
            if char and char:FindFirstChild("HumanoidRootPart") then
                R.eh("players", char,
                    Color3.fromRGB(0,200,255), gfx.white, 0.5,
                    Enum.HighlightDepthMode.AlwaysOnTop)
                local newHl = R.esph.players[char]
                if newHl then
                    local hlEnabled = P.hle
                    if hlEnabled and hlEnabled["players"] == false then
                        pcall(function() newHl.Enabled = false end)
                    end
                end
            end
        end
    else clearESPTable(ESPh.players) end
    local currentRoom = workspace:FindFirstChild("CurrentRoom")
    if currentRoom then
        for _, roomModel in ipairs(currentRoom:GetChildren()) do
            if not roomModel:IsA("Model") then continue end
            local mf = roomModel:FindFirstChild("Monsters")
            if mf then
                for _, obj in ipairs(mf:GetChildren()) do
                    if not obj:IsA("Model") then continue end
                    if R.TSet[obj.Name] then
                        if obj.Name == "SproutTendril" then
                            if ESPen.tendrils then ApplyTendrilHighlight(obj)
                            else
                                local hl = ESPh.tendrils[obj]
                                if hl then pcall(function() hl:Destroy() end); ESPh.tendrils[obj] = nil end
                            end
                        end
                        continue
                    end
                    local cfg = R.mons[obj.Name]
                    if cfg then
                        if not cfg.isGrab then
                            if ESPen.monsters then ApplyMonsterHighlight(obj, cfg, false)
                            else
                                local hl = ESPh.monsters[obj]
                                if hl then pcall(function() hl:Destroy() end); ESPh.monsters[obj] = nil end
                            end
                        end
                    else
                        if not R.iumo(obj) then continue end
                        if ESPen.unknownMonsters or ESPen.monsters then
                            ApplyUnknownHighlight(obj)
                            local prim = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true)
                            if prim then EnsureUnknownBall(obj, prim) end
                        else
                            local hl = ESPh.unknownMonsters[obj]
                            if hl then pcall(function() hl:Destroy() end); ESPh.unknownMonsters[obj] = nil end
                            RemoveBall(ba.u, ba.uP, obj)
                        end
                    end
                end
            end
            local gf = roomModel:FindFirstChild("Generators")
            if gf then
                for _, gen in ipairs(gf:GetChildren()) do
                    if not gen:IsA("Model") then continue end
                    if gen.Name ~= "Generator" and not IsDualGen(gen.Name) and not gen.Name:match("^TrickOrTreatGen") then continue end
                    if ESPen.generators then
                        ApplyGenHighlight(gen)
                    else
                        local hl = ESPh.generators[gen]
                        if hl then pcall(function() hl:Destroy() end); ESPh.generators[gen] = nil end
                        Cache.genESPColorKey[gen] = nil
                    end
                end
            end
        end
    end
    if not ESPen.monsters        then clearESPTable(ESPh.monsters)   end
    if not ESPen.tendrils        then clearESPTable(ESPh.tendrils)   end
    if not ESPen.generators      then
        clearESPTable(ESPh.generators); table.clear(Cache.genESPColorKey)
    end
    if not ESPen.unknownMonsters and not ESPen.monsters then
        clearESPTable(ESPh.unknownMonsters)
        for obj in pairs(ba.u) do RemoveBall(ba.u, ba.uP, obj) end
    end
end
function S.seenNow(strict)
    if gcc() >= C.chaseCountThreshold then return true, "chase" end
    local ch  = plr.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    local mon = Cache.monsterPositions
    for i = 1, #mon do
        local e = mon[i]
        local m = e.model
        if m and m.Parent and e.farmEligible and m:GetAttribute("LostInterest") ~= true then
            local lpS = e.livePart
            local mpS = (lpS and lpS.Parent) and lpS.Position or e.pos
            local capS = S.shSeenCap or 60
            if strict then capS = (e.decodeEligible and (e.detRadius or C.detectorRadius or 40)) or -1 end
            local closeS = (not hrp) or (not mpS) or (mpS - hrp.Position).Magnitude <= capS
            if m:GetAttribute("Chasing") == true then
                local cv = m:FindFirstChild("ChasingValue")
                if not (cv and cv:IsA("ObjectValue") and cv.Value ~= nil) then
                    if closeS then return true, "seen" end
                else
                    local v = cv.Value
                    if v == plr or v == ch or v.Name == plr.Name then return true, "seen" end
                end
            elseif m:GetAttribute("Alerted") == true then
                if closeS then return true, "seen" end
            end
        end
    end
    if hrp and S.pumpkinNear(hrp.Position, strict and (S.pumpkinRadius or 45) or 60) then return true, "pumpkin" end
    return false
end

function S.monInDetector(pos)
    local mon = Cache.monsterPositions
    if not (pos and mon) then return false end
    for i = 1, #mon do
        local e = mon[i]
        if e.farmEligible and e.decodeEligible then
            local lp = e.livePart
            local mp = (lp and lp.Parent) and lp.Position or e.pos
            if mp then
                local r = e.detRadius or C.detectorRadius or 40
                if (mp - pos).Magnitude <= r then return true, e end
            end
        end
    end
    return false
end
function S.shNearNow()
    local ch  = plr.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    local mon = Cache.monsterPositions
    if not (hrp and mon) then return false end
    for i = 1, #mon do
        local e = mon[i]
        if e.farmEligible then
            local lp = e.livePart
            local mp = (lp and lp.Parent) and lp.Position or e.pos
            local r = S.shNearTrigger or 20
            if e.decodeEligible then r = e.detRadius or C.detectorRadius or 40 end
            if mp and (mp - hrp.Position).Magnitude < r
               and not (e.model and e.model.Parent and e.model:GetAttribute("LostInterest") == true) then
                return true, "near"
            end
        end
    end
    return false
end
function S.shStopGen()
    pcall(function()
        local g = R.gag and R.gag()
        if g then
            pcall(R.fsg, g)
            pcall(R.fsgcr, g)
        end
    end)
end
function S.shNoSpotFlee(hrp)
    do
        local okPn, pn = pcall(IsPanicActive)
        if okPn and pn then return end
    end
    local d = S.shNearestTwistedDist(hrp.Position)
    local okN, nearN = pcall(S.shNearNow)
    local okC, clearC = pcall(S.shDetClear, hrp.Position)
    if (d and d < 50) or (okN and nearN) or (okC and clearC == false) then
        if tick() - (S.shNoSpotLogT or 0) > 3 then S.shNoSpotLogT = tick(); S.shLog("noSpot", d) end
        S.shSidestep(hrp)
    end
end
function S.shStopActions()
    pcall(function()
        local ch  = plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if hum and hrp then hum:MoveTo(hrp.Position); hum:Move(Vector3.zero) end
    end)
    pcall(function()
        local g = R.gag and R.gag()
        if g then
            pcall(R.fsg, g)
            pcall(R.fsgcr, g)
        end
    end)
end
regSpawn(function()
    local RS = game:GetService("RunService")
    local lastTry, lastStop = 0, 0
    if R.isR then return end
    while true do
        RS.Heartbeat:Wait()
        if not S.safeHide or S.pathfindMode or S.shActive or S.shFleeing or S.encounterActive or S.wasteWalkActive then continue end
        do local okPn, pn = pcall(IsPanicActive); if okPn and pn then continue end end
        local now = tick()
        if now - lastTry < 0.04 then continue end
        if S.shNoEnterUntil and now < S.shNoEnterUntil then continue end
        local ch  = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not (hrp and hum and hum.Health > 0) then continue end
        local okS, seen = pcall(S.seenNow)
        if not (okS and seen) then okS, seen = pcall(S.shNearNow) end
        if not (okS and seen) then
            local okD, clr = pcall(S.shDetClear, hrp.Position)
            seen = okD and clr == false
        end
        if not seen then continue end
        lastTry = now
        local okB, base = pcall(R.fb)
        if okB and base and R.ibb(base, hrp.Position) then continue end
        local okE, entered = pcall(S.safeHideEnter, hrp, 3, 15, "seen")
        if okE and entered then
            if now - lastStop > 0.5 then lastStop = now; S.shStopActions() end
        else
            if now - lastStop > 0.5 then lastStop = now; S.shStopGen() end
            pcall(S.shNoSpotFlee, hrp)
        end
    end
end)
local sf = { loopActive = false, currentGen = nil, chaseDanger = false }
function sfDoStop(activeGen, goBase)
    sf.currentGen = activeGen
    pcall(function() R.fsg(activeGen) end)
    pcall(function() R.fsgcr(activeGen) end)
    if goBase then
        local char        = plr.Character
        local hrp         = char and char.PrimaryPart
        local currentBase = R.fb()
        if hrp and currentBase and not R.ibb(currentBase, hrp.Position) then
            if tick() - (S.lastBaseTP or 0) >= C.baseTpLoopCd then
                S.lastBaseTP = tick()
                TeleportToBaseWithRetry(hrp, currentBase)
            end
        end
    end
    S.ptpPend = false; S.ptpGen = nil
end
function sfGetValidActiveGen()
    if not S.fireStop or S.eggsonMode then return nil end
    local activeGen = R.gag()
    if activeGen and activeGen.Parent and IsValidGenModel(activeGen) then
        return activeGen
    end
    return nil
end
function sfRefreshChase()
    sf.chaseDanger = gcc() >= C.chaseCountThreshold
end
sfRefreshChase()
regC(plr:GetAttributeChangedSignal("ChaseCount"), function()
    sfRefreshChase()
    if not sf.chaseDanger then return end
    local activeGen = sfGetValidActiveGen()
