end)
function ssfl()
    if sf.loopActive then return end
    sf.loopActive = true
    regSpawn(function()
        while sf.loopActive do
            task.wait(K.stopInt)
            if not S.fireStop or S.eggsonMode then
                sf.currentGen = nil; continue
            end
            local activeGen = R.gag()
            if activeGen and IsValidGenModel(activeGen) then
                S.activeGen     = activeGen
                S.activeGenT = tick()
            end
            if not activeGen or not activeGen.Parent then
                sf.currentGen = nil
                local cacheAge = tick() - (S.activeGenT or 0)
                if cacheAge >= 1.5 then S.activeGen = nil end
                continue
            end
            if not IsValidGenModel(activeGen) then
                sf.currentGen = nil; continue
            end
            if type(plr:GetAttribute("ChaseCount")) ~= "number" then sfRefreshChase() end
            local isDanger = sf.chaseDanger
            local seenNow  = S.seenNow(true)
            local isConnie = IsConnieGen(activeGen)
            local genPos   = activeGen:GetPivot().Position
            local hasTen, hasBlot = IsTendrilNearGen(genPos)
            local hasMonster = false
            do
                local monL = Cache.monsterPositions
                for mi = 1, #monL do
                    local en = monL[mi]
                    if en.decodeEligible and en.farmEligible then
                        local lv = en.livePart and en.livePart.Parent and en.livePart.Position
                        local cp = lv or en.pos
                        if cp then
                            local dd = cp - genPos
                            if (dd.X*dd.X + dd.Y*dd.Y + dd.Z*dd.Z) <= K.monStopRsq then hasMonster = true; break end
                        end
                    end
                end
            end
            local pkHrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not hasMonster and pkHrp and S.pumpkinThreat(pkHrp.Position, 45) then hasMonster = true end
            if not hasMonster and S.pumpkinThreat(genPos, 45) then hasMonster = true end
            local hasDet = S.monInDetector(genPos) or (pkHrp and S.monInDetector(pkHrp.Position)) or false
            local shouldStop = isDanger or seenNow or isConnie or hasTen or hasBlot or hasMonster or hasDet
            if shouldStop then
                sfDoStop(activeGen, isDanger or hasTen or hasBlot or hasMonster)
            else
                sf.currentGen = nil
            end
        end
    end)
end
if not R.isR then ssfl() end
regSpawn(function()
