        end
    end
end)
function ProcessMonsterObject(obj, hrpPos, isDanger, tCount, gCount, blotCount, monsterCount)
    local objName = obj.Name
    local cfg     = R.mons[objName]
    if not cfg then return tCount, gCount, blotCount, monsterCount end
    if cfg.isGrab then
        gCount += 1
        local gp = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true)
        if gp then
            if R.espe.monsters then
                EnsureGrabBall(obj, gp, C.grabDodgeRange, Color3.fromRGB(255,0,150))
            end
            local char2        = plr.Character; local hrp2 = char2 and char2.PrimaryPart
            local currentBase2 = R.fb()
            local userInBase2  = hrp2 and currentBase2 and R.ibb(currentBase2, hrp2.Position)
            if S.autoEnabled and hrp2 and not userInBase2 and (hrpPos - gp.Position).Magnitude < C.grabDodgeRange then
                if tick() - S.lastTeleport > C.teleportCooldown then
                    S.lastTeleport = tick()
                    if currentBase2 then
                        local pos = (currentBase2.CFrame * CFrame.new(0, C.teleportHeight, 0)).Position
                        local targetCF = BuildOrientedCFrame(pos, currentBase2.CFrame)
                        R.TpTo(hrp2, targetCF)
                    end
                end
            end
        end
    else
        monsterCount += 1
        local prim = obj.PrimaryPart or obj:FindFirstChild("HumanoidRootPart")
            or obj:FindFirstChildWhichIsA("BasePart", true)
        if prim then
            local ballRadius = cfg.detRadius  or C.detectorRadius or 40
            local stopRadius = cfg.stopRadius or K.defaultStopRadius
            local effectiveFarmIgnore = cfg.farmIgnore
            if objName == "RazzleDazzleMonster" then
                effectiveFarmIgnore = not _G.YattaRZ.razzleThreat(obj)
                stopRadius = 60
            elseif objName == "RodgerMonster" then
                effectiveFarmIgnore = not _G.YattaRZ.rodgerThreat(obj)
            end
            if objName == "GourdyMonster" and not S.gourdyThreat(obj) then
                effectiveFarmIgnore = true
            end
            if objName == "GlistenMonster" then
                local gActivated   = obj:GetAttribute("GlistenActivated")
                local gInitialized = obj:GetAttribute("GlistenInitialized")
                if not (gActivated == true and gInitialized == true) then
                    effectiveFarmIgnore = true
                end
            end
            if S.safeHide and S.autoEnabled then
                ballRadius = math.min(ballRadius, 25)
                stopRadius = math.min(stopRadius, 25)
            end
            local nmc = Cache.newMonsterCache
            nmc[#nmc+1] = {
                pos            = prim.Position,
                livePart       = prim,
                model          = obj,
                decodeEligible = (not effectiveFarmIgnore) and (not cfg.decodeIgnore),
                eggsonEligible = (not cfg.eggsonIgnore),
                farmEligible   = (not effectiveFarmIgnore),
                threatEligible = (cfg.isThreat == true) and (not cfg.isGrab),
                isAny          = true,
                stopRadius     = stopRadius,
                detRadius      = ballRadius,
            }
            local wantColor = isDanger and Th.red or getMonsterBallColor(cfg)
            if effectiveFarmIgnore and not isDanger then
                wantColor = Color3.fromRGB(110, 110, 110)
            end
            if R.espe.monsters then
                ApplyMonsterHighlight(obj, cfg, isDanger)
                if not effectiveFarmIgnore then
                    local ballRadius = cfg.detRadius or C.detectorRadius or 40
                    local ball = EnsureMonsterBall(obj, prim, ballRadius, wantColor)
                    local cat2 = cfg and cfg.espCategory
                    if cfg and cfg.isEvent and ball then
                        rb.balls[obj] = ball
                        pl.balls[obj] = nil
                        pm.balls[obj] = nil
                    elseif cat2 == "lethal" and ball then
                        pl.balls[obj] = ball
                        rb.balls[obj] = nil
                        pm.balls[obj] = nil
                    elseif cat2 == "main" and ball then
                        pm.balls[obj] = ball
                        rb.balls[obj] = nil
                        pl.balls[obj] = nil
                    else
                        rb.balls[obj] = nil
                        pl.balls[obj] = nil
                        pm.balls[obj] = nil
                    end
                else
                    rb.balls[obj] = nil
                    pl.balls[obj] = nil
                    pm.balls[obj] = nil
                    if ba.m[obj] then
                        pcall(function() ba.m[obj]:Destroy() end)
                        ba.m[obj]    = nil
                        ba.mP[obj] = nil
                    end
                end
            end
        end
    end
    return tCount, gCount, blotCount, monsterCount
end
local RunTendrilScan
do
local blotHandNames = {
    BlotHand = true,
    BlotHand_L = true,
    BlotHand_R = true,
    blotHandL = true,
    blotHandR = true,
}
local trackedTendrils = {}
local trackedSet = {}
local trackedPart = {}
local refreshQueued = false

function ClearTendrilCache()
    table.clear(Cache.tendrilPositions)
    table.clear(Cache.activeTendrils)
    Cache.scanBlotCount = 0
    S.cachedBlotCount = 0
    S.cachedTendrilLen = 0
    _G.YattaTendrilCache = Cache.tendrilPositions
end

function TendrilUntrack(obj)
    if not trackedSet[obj] then return false end
    trackedSet[obj] = nil
    trackedPart[obj] = nil
    Cache.trackedBlot[obj] = nil
    for i = #trackedTendrils, 1, -1 do
        if trackedTendrils[i] == obj then
            table.remove(trackedTendrils, i)
            break
        end
    end
    return true
end

local RefreshTrackedTendrils

function QueueTendrilRefresh()
    if refreshQueued then return end
    refreshQueued = true
    task.defer(function()
        refreshQueued = false
        if #trackedTendrils > 0 then
            RefreshTrackedTendrils()
        else
            ClearTendrilCache()
        end
    end)
end

Cache.trackedBlot = {}
Cache.blotSource  = {}
function FindTendrilPart(obj)
    if obj:IsA("BasePart") then return obj end
    local part = obj.PrimaryPart
    if part and part:IsA("BasePart") then
        return part
    end
    return obj:FindFirstChildWhichIsA("BasePart", true)
end

function TendrilTrack(obj)
    local name = obj.Name
    local isBlot = blotHandNames[name] == true
    local isTen = R.TSet[name] == true
    if not isBlot and not isTen then return false end
    if isBlot and R.isR then return false end

    local target = obj
    if isBlot then
        if not (obj:IsA("Model") or obj:IsA("BasePart")) then
            target = obj:FindFirstAncestorWhichIsA("BasePart")
                or obj:FindFirstChildWhichIsA("BasePart", true)
        end
        if not target then return false end
    elseif not obj:IsA("Model") then
        return false
    end
    if trackedSet[target] then return false end

    trackedSet[target] = true
    trackedTendrils[#trackedTendrils + 1] = target
    trackedPart[target] = FindTendrilPart(target)
    if isBlot then
        Cache.trackedBlot[target] = true
        if target ~= obj then Cache.blotSource[obj] = target end
    end
    return true
end

RefreshTrackedTendrils = function()
    local newTendrilCache = {}
    local newActiveTendrils = {}
    local blotCount = 0
    local refreshBudget = 0

    for i = #trackedTendrils, 1, -1 do
        local obj = trackedTendrils[i]
        if not obj.Parent then
            TendrilUntrack(obj)
            continue
        end

        local tp = trackedPart[obj]
        if not tp or not tp.Parent then
            tp = FindTendrilPart(obj)
            trackedPart[obj] = tp
        end
        if not tp then continue end

        local isBlot = Cache.trackedBlot[obj] == true or blotHandNames[obj.Name] == true
        if isBlot then blotCount += 1 end

        local pos = tp.Position
        newActiveTendrils[#newActiveTendrils + 1] = tp
        newTendrilCache[#newTendrilCache + 1] = {
            pos = pos,
            isBlot = isBlot,
            obj = obj,
        }

        if not isBlot and R.espe.tendrils then
            local ballNeedsCreate = not (ba.t[obj] and ba.t[obj].Parent)
            local ballColor = isBlot
                and Color3.fromRGB(255, 78, 178)
                or Color3.fromRGB(150, 0, 255)
            EnsureTendrilBall(obj, tp, K.tenGenR, ballColor)
            ApplyTendrilHighlight(obj)
            if ballNeedsCreate then
                refreshBudget = refreshBudget + 1
                if refreshBudget >= 3 then
                    refreshBudget = 0
                    task.wait()
                end
            end
        end
    end

    Cache.tendrilPositions = newTendrilCache
    _G.YattaTendrilCache = newTendrilCache
    Cache.activeTendrils = newActiveTendrils
    Cache.scanBlotCount = blotCount
    S.cachedBlotCount = blotCount
    S.cachedTendrilLen = #newActiveTendrils
end

function S.trackTotGen(obj)
    if obj:IsA("Model") and (obj.Name:match("^TrickOrTreatGen")
        or (obj.Parent and obj.Parent:IsA("Folder") and obj.Parent.Name:match("^TrickOrTreatGen"))) then
        Cache.totGens = Cache.totGens or {}
        if not Cache.totGens[obj] then
            Cache.totGens[obj] = true
            Cache.scanDirty = true; Cache.espDirty = true
            task.defer(function()
                if obj.Parent then
                    pcall(watchConnieForGen, obj); pcall(watchGenStats, obj)
                end
            end)
        end
    end
end
if not R.isR then regC(workspace.DescendantAdded, function(obj) S.trackTotGen(obj) end) end
task.defer(function()
    local cr = workspace:FindFirstChild("CurrentRoom")
    if cr then for _, d in ipairs(cr:GetDescendants()) do S.trackTotGen(d) end end
end)
RunTendrilScan = function(forceFull)
    Cache.lastTendrilScanTime = tick()
    Cache.tendrilScanDirty = false
    local nowT = tick()
    if (forceFull or not Cache.tendrilFullDone or nowT - (Cache.tendrilFullT or 0) > 30)
       and not Cache.tendrilScanBusy then
        Cache.tendrilScanBusy = true
        Cache.tendrilFullDone = true
        Cache.tendrilFullT    = nowT
        local scanBudget = 0
        local okScan = pcall(function()
            for _, obj in ipairs(workspace:GetDescendants()) do
                scanBudget += 1
                if scanBudget >= 300 then
                    scanBudget = 0
                    task.wait()
                end
                TendrilTrack(obj)
                S.trackTotGen(obj)
            end
        end)
        Cache.tendrilScanBusy = false
    end
    RefreshTrackedTendrils()
end

if not R.isR then
RunTendrilScan()

regC(workspace.DescendantAdded, function(obj)
    local name = obj.Name
    local isBlot = blotHandNames[name] == true
    if not isBlot and not R.TSet[name] then return end
    if not isBlot and not obj:IsA("Model") then return end
    if isBlot and R.isR then return end

    if obj.Parent and TendrilTrack(obj) then
        QueueTendrilRefresh()
    end
end)

regC(workspace.DescendantRemoving, function(obj)
    local t = Cache.blotSource[obj]
    if t then
        Cache.blotSource[obj] = nil
        if TendrilUntrack(t) then QueueTendrilRefresh() end
    end
    if TendrilUntrack(obj) then
        QueueTendrilRefresh()
    end
end)

regC(workspace.DescendantAdded, function(obj)
    if not obj:IsA("BasePart") then return end
    local model = obj:FindFirstAncestorOfClass("Model")
    if not model or not trackedSet[model] then return end
    if not trackedPart[model] or not trackedPart[model].Parent then
        trackedPart[model] = model.PrimaryPart or obj
        QueueTendrilRefresh()
    end
end)

regSpawn(function()
    while true do
        task.wait(0.05)
        if #trackedTendrils > 0 then
            RefreshTrackedTendrils()
        end
    end
end)
end
end
function RunWorldScan(hrp, isDanger, currentBase, userInBase)
    Cache.lastWorldScanTime = tick()
    Cache.scanDirty         = false
    table.clear(Cache.seenThisScan)
    table.clear(Cache.newMonsterCache)
    table.clear(Cache.newGenList)
    table.clear(Cache.genPivotCache)
    local monsterCount = 0
    local tCount    = Cache.scanTCount
    local gCount    = 0
    local blotCount = Cache.scanBlotCount
    local hrpPos    = hrp.Position
    local currentRoom = workspace:FindFirstChild("CurrentRoom")
    if currentRoom then
        for _, roomModel in ipairs(currentRoom:GetChildren()) do
            if not roomModel:IsA("Model") then continue end
            local monstersFolder = roomModel:FindFirstChild("Monsters")
            if monstersFolder then
                for _, obj in ipairs(monstersFolder:GetChildren()) do
                    if not obj:IsA("Model") then continue end
                    if Cache.seenThisScan[obj] then continue end
                    Cache.seenThisScan[obj] = true
                    if R.TSet[obj.Name] then continue end
                    if R.mons[obj.Name] then
                        tCount, gCount, blotCount, monsterCount =
                            ProcessMonsterObject(obj, hrpPos, isDanger, tCount, gCount, blotCount, monsterCount)
                    elseif R.iumo(obj) then
                        if R.espe.unknownMonsters then
                            ApplyUnknownHighlight(obj)
                            local prim = obj.PrimaryPart or obj:FindFirstChild("HumanoidRootPart")
                                or obj:FindFirstChildWhichIsA("BasePart", true)
                            if prim then EnsureUnknownBall(obj, prim) end
                        end
                    end
                end
            end
            local gensFolder = roomModel:FindFirstChild("Generators")
            local totExtra
            if Cache.totGens and next(Cache.totGens) then
                for g in pairs(Cache.totGens) do
                    if not g.Parent then Cache.totGens[g] = nil
                    elseif g.Parent ~= gensFolder and g:IsDescendantOf(roomModel) then
                        totExtra = totExtra or {}
                        totExtra[#totExtra + 1] = g
                    end
                end
            end
            if gensFolder or totExtra then
                local genObjs = _G.YattaFlatGens(gensFolder and gensFolder:GetChildren() or {})
                if totExtra then for _, g in ipairs(totExtra) do genObjs[#genObjs + 1] = g end end
                for _, g in ipairs(_G.YattaTotExtra(roomModel, gensFolder)) do genObjs[#genObjs + 1] = g end
                do
                    local seenG, uniq = {}, {}
                    for _, g in ipairs(genObjs) do
                        if not seenG[g] then seenG[g] = true; uniq[#uniq + 1] = g end
                    end
                    genObjs = uniq
                end
                for _, obj in ipairs(genObjs) do
                    if not obj:IsA("Model") then continue end
                    local isGenerator = (obj.Name == "Generator" or obj.Name:match("^TrickOrTreatGen") ~= nil or _G.YattaTotSet[obj] == true)
                    local isDual      = IsDualGen(obj.Name)
                    if not isGenerator and not isDual then continue end
                    local st = obj:FindFirstChild("Stats")
                    if not st then
                        if isGenerator then ApplyGenHighlight(obj) end
                        continue
                    end
                    local genCur, genReq, comp = GetCachedGenStats(obj)
                    if comp then
                        if not Cache.genNumberMap[obj] then
                            local usedNums = {}
                            for _, n in pairs(Cache.genNumberMap) do usedNums[n] = true end
                            local nextNum = 1
                            while usedNums[nextNum] do nextNum = nextNum + 1 end
                            Cache.genNumberMap[obj] = nextNum
                        end
                        if ui.MachineList then
                            if not R.ml[obj] or not R.ml[obj].Parent then
                                local l = Instance.new("TextLabel", ui.MachineList)
                                l.Size=UDim2.new(1,0,0,16); l.BackgroundTransparency=1
                                l.TextColor3 = Color3.fromRGB(130, 130, 130)
                                l.Font=Th.Font; l.TextSize=12
                                l.TextXAlignment=Enum.TextXAlignment.Left; l.ZIndex=204
                                R.ml[obj] = l
                            end
                            local genNum = Cache.genNumberMap[obj]
                            local isDual2 = IsDualGen(obj.Name)
                            local compName = isDual2 and "DualGen (Completed)" or "Generator (Completed)"
                            SetLabelText(R.ml[obj], genNum .. ". " .. compName)
                            R.ml[obj].TextColor3 = Color3.fromRGB(130, 130, 130)
                        end
                        continue
                    end
                    if not cn.watchedGens[obj] then task.defer(function() if obj and obj.Parent then watchConnieForGen(obj) end end) end
                    if not cn.statsWatched[obj]   then task.defer(function() if obj and obj.Parent then watchGenStats(obj) end end) end
                    local genPivotPos = obj:GetPivot().Position
                    Cache.genPivotCache[obj] = genPivotPos
                    local isConnie = IsConnieGen(obj)
                    ApplyGenHighlight(obj)
                    if not isConnie then
                        if isDual then
                            if not IsDualGenFullyOccupied(obj) and DualGenSlotUsable(obj) ~= nil then
                                Cache.newGenList[#Cache.newGenList+1] = obj
                            end
                        else
                            Cache.newGenList[#Cache.newGenList+1] = obj
                        end
                    end
                    local p = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true)
                    if p and ui.MachineList then
                        local currentDist = (hrpPos - genPivotPos).Magnitude
                        local lastDist    = Cache.genLabelLastDist[obj]
                        local distDelta   = lastDist and math.abs(currentDist - lastDist) or math.huge
                        if not Cache.genNumberMap[obj] then
                            local usedNums = {}
                            for _, n in pairs(Cache.genNumberMap) do
                                usedNums[n] = true
                            end
                            local nextNum = 1
                            while usedNums[nextNum] do nextNum = nextNum + 1 end
                            Cache.genNumberMap[obj] = nextNum
                        end
                        local genNum   = Cache.genNumberMap[obj]
                        local baseName = isDual and "Generator (Dual)" or "Generator"
                        local slotTxt = ""
                        if isDual then
                            local slot2 = GetDualGenSlotForPlayer(obj)
                            slotTxt = slot2 == "mirror" and " [S2]" or " [S1]"
                        end
                        local connieTxt = isConnie and " ⚠ CONNIE" or ""
                        local occupiedTxt = ""
                        do
                            local igp2 = workspace:FindFirstChild(_G.YattaIGP)
                            if igp2 then
                                for _, plr2 in ipairs(Plrs:GetPlayers()) do
                                    local pm2 = igp2:FindFirstChild(plr2.Name)
                                    local dv2 = pm2 and pm2:FindFirstChild("Decoding")
                                    if dv2 and dv2.Value == obj then
                                        occupiedTxt = " [Generator Occupied]"
                                        break
                                    end
                                end
                            end
                        end
                        local stateStr    = slotTxt..connieTxt..occupiedTxt
                        local needsUpdate = (distDelta >= K.lblDist)
                                         or (Cache.genLabelLastState[obj] ~= stateStr)
                        if needsUpdate then
                            Cache.genLabelLastDist[obj]  = currentDist
                            Cache.genLabelLastState[obj] = stateStr
                            if not R.ml[obj] or not R.ml[obj].Parent then
                                local l = Instance.new("TextLabel", ui.MachineList)
                                l.Size=UDim2.new(1,0,0,16); l.BackgroundTransparency=1
                                l.TextColor3 = isConnie and Th.red or Th.white
                                l.Font=Th.Font; l.TextSize=12
                                l.TextXAlignment=Enum.TextXAlignment.Left; l.ZIndex=204
                                R.ml[obj] = l
                            end
                            SetLabelText(R.ml[obj],
                                genNum..". "..baseName..slotTxt..occupiedTxt..connieTxt)
                            R.ml[obj].TextColor3 = isConnie and Th.red or Th.white
                        end
                    end
                end
            end
        end
    end
    for obj in pairs(S.extraMons) do
        if not obj.Parent then
            S.extraMons[obj] = nil
        elseif not Cache.seenThisScan[obj] then
            Cache.seenThisScan[obj] = true
            tCount, gCount, blotCount, monsterCount =
                ProcessMonsterObject(obj, hrpPos, isDanger, tCount, gCount, blotCount, monsterCount)
        end
    end
    Cache.monsterPositions = Cache.newMonsterCache
    Cache.genList          = Cache.newGenList
    UpdateMachineLocatorEmpty()
    Cache.scanTCount = tCount
    Cache.scanGCount = gCount
    S.cachedTCount       = tCount
    S.cachedGCount       = gCount
    S.cachedMonsterCount = monsterCount
end
function cleanupBalls()
    local db  = ba.m
    local tb  = ba.t
    local gb  = ba.g
    local umb = ba.u
    for o in pairs(db)  do if not o.Parent then RemoveBall(db,  ba.mP,  o) end end
    for o in pairs(tb)  do if not o.Parent then RemoveBall(tb,  ba.tP,  o) end end
    for o in pairs(gb)  do if not o.Parent then RemoveBall(gb,  ba.gP,     o) end end
    for o in pairs(umb) do if not o.Parent then RemoveBall(umb, ba.uP,  o) end end
    for model, prim in pairs(ba.mP)  do if not prim or not prim.Parent then ba.mP[model]  = nil end end
    for model, prim in pairs(ba.gP)     do if not prim or not prim.Parent then ba.gP[model]     = nil end end
    for model, prim in pairs(ba.tP)  do if not prim or not prim.Parent then ba.tP[model]  = nil end end
    for model, prim in pairs(ba.uP)  do if not prim or not prim.Parent then ba.uP[model]  = nil end end
    if R.espb and R.espb.items then
        local itemBalls = R.espb.items
        for obj, b in pairs(itemBalls) do
            if not obj or not obj.Parent then pcall(function() b:Destroy() end); itemBalls[obj] = nil end
        end
    end
end
function cleanupESP()
    local ESPh = R.esph
    cleanupESPTable(ESPh.players)
    cleanupESPTable(ESPh.monsters)
    cleanupESPTable(ESPh.generators)
    cleanupESPTable(ESPh.tendrils)
    if ESPh.items          then cleanupESPTable(ESPh.items)          end
    if ESPh.unknownMonsters then cleanupESPTable(ESPh.unknownMonsters) end
end
function cleanupGenData(o)
    Cache.genLabelLastDist[o]    = nil
    Cache.genLabelLastState[o]   = nil
    Cache.genPivotCache[o]       = nil
    Cache.genESPColorKey[o]      = nil
    Cache.genNumberMap[o]        = nil
    cn.connieCache[o]              = nil
    cn.watchedGens[o]        = nil
    cn.baseMachinePartCache[o]  = nil
    InvalidateGenPPCache(o)
    cn.statsCache[o]            = nil
    cn.statsWatched[o]          = nil
    if cn.watchConns[o] then
        for _, c in ipairs(cn.watchConns[o]) do pcall(function() c:Disconnect() end) end
        cn.watchConns[o] = nil
    end
    if cn.statsConns[o] then
        for _, c in ipairs(cn.statsConns[o]) do pcall(function() c:Disconnect() end) end
        cn.statsConns[o] = nil
    end
end
function cleanupMachineLabels()
    local ml = R.ml
    for o, l in pairs(ml) do
        local isGone = not o.Parent
        local isCompleted = false
        if not isGone then
            local _, _, comp = GetCachedGenStats(o)
            if comp then isCompleted = true end
        end
        if isGone then
            pcall(function() l:Destroy() end)
            ml[o] = nil
            Cache.genNumberMap[o] = nil
            cleanupGenData(o)
        elseif isCompleted then
            local isDual2 = IsDualGen(o.Name)
            local baseName2 = isDual2 and "DualGen (Completed)" or "Generator (Completed)"
            local genNum = Cache.genNumberMap[o] or 0
            if l and l.Parent then
                SetLabelText(l, genNum .. ". " .. baseName2)
                l.TextColor3 = Color3.fromRGB(130, 130, 130)
            end
        end
    end
    UpdateMachineLocatorEmpty()
    for gen in pairs(cn.connieCache) do
        if not gen or not gen.Parent then cleanupGenData(gen) end
    end
end
function cleanupCacheRefs()
    if Cache.lastPositionedGen and not Cache.lastPositionedGen.Parent then
        if S.ptpGen == Cache.lastPositionedGen then
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
        end
        Cache.lastPositionedGen = nil
    end
    if Cache.lastPositionedFarm and not Cache.lastPositionedFarm.Parent then Cache.lastPositionedFarm = nil end
    if S.activeGen   and not S.activeGen.Parent   then S.activeGen = nil end
    if S.eggFireG  and not S.eggFireG.Parent  then stopEggsonDecodeFireLoop() end
    local roomGensNow = R.gcrg()
    local liveGenKeys = {}
    for _, entry in ipairs(roomGensNow) do
        if entry.gen.Parent then liveGenKeys[tostring(entry.gen)] = true end
    end
    for k in pairs(S.eggsonCompletionWaitStart) do
        if not liveGenKeys[k] then S.eggsonCompletionWaitStart[k] = nil end
    end
    if S.ptpGen and not S.ptpGen.Parent then
        S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
    end
end
function cleanupMisc()
    local pb = R.playerBillboards
    for plr, bb in pairs(pb) do
        if not plr or not plr.Parent then pcall(function() bb:Destroy() end); pb[plr] = nil end
    end
    local at = Cache.activeTendrils
    local newLen = 0
    for i = 1, #at do
        local tp = at[i]
        if tp and tp.Parent then newLen += 1; at[newLen] = tp end
    end
    for i = newLen + 1, #at do at[i] = nil end
    S.cachedTendrilLen = newLen
    if pad.pad and not pad.pad.Parent then pad.pad = nil end
    for obj in pairs(S.tendrilDodgeHandled) do
        if not obj or not obj.Parent then S.tendrilDodgeHandled[obj] = nil end
    end
    for gen in pairs(S.genUnsafeByTendril) do
        if not gen or not gen.Parent then S.genUnsafeByTendril[gen] = nil end
    end
    if col.count > 0 and not S.pickingUp then
        col.count = 0
        table.clear(col.orig)
        local char2 = plr.Character
        if char2 and not S.NoclipLocked() then
            for _, part in ipairs(char2:GetDescendants()) do
                if part:IsA("BasePart") then part.CanCollide = true end
            end
        end
    end
    local ltc = Prev.labelText
    local lcc = Prev.labelColor
    for lbl in pairs(ltc) do
        if not lbl or not lbl.Parent then ltc[lbl] = nil; lcc[lbl] = nil end
    end
    local mon = Cache.monsterPositions
    local newMonLen = 0
    for i = 1, #mon do
        local entry = mon[i]
        if entry.livePart and entry.livePart.Parent then newMonLen += 1; mon[newMonLen] = entry end
    end
    for i = newMonLen + 1, #mon do mon[i] = nil end
    local ten = Cache.tendrilPositions
    local newTenLen = 0
    for i = 1, #ten do
        local entry = ten[i]
        if entry.obj and entry.obj.Parent then newTenLen += 1; ten[newTenLen] = entry end
    end
    for i = newTenLen + 1, #ten do ten[i] = nil end
end
function RunPeriodicCleanup()
    cleanupBalls()
    cleanupESP()
    cleanupMachineLabels()
    cleanupCacheRefs()
    cleanupMisc()
end
regSpawn(function()
    while true do task.wait(K.cleanS); pcall(RunPeriodicCleanup) end
end)
regSpawn(function()
_G.yattaABW = _G.yattaABW or { active = false, storeConn = nil, wasOpen = false }
local abw = _G.yattaABW
function stopBuyWalk() abw.active = false end
