S.wasteLethalFar   = S.wasteLethalFar   or 90
S.wasteLethalRoute = S.wasteLethalRoute or 45
function S.shNearestOn() return tick() < (S.shNearestUntil or 0) end
local WASTE_LETHAL = { DyleMonster = true, GourdyMonster = true, DandyMonster = true }
function S.wasteIsLethal(model)
    if not model then return false end
    if WASTE_LETHAL[model.Name] then return true end
    local monsT = R.mons
    local cfg = type(monsT) == "table" and monsT[model.Name] or nil
    return cfg ~= nil and cfg.espCategory == "lethal"
end
function S.wasteFarFromLethal(pos)
    local mon = Cache.monsterPositions
    if not mon then return true end
    for i = 1, #mon do
        local e = mon[i]
        if e.model and S.wasteIsLethal(e.model) then
            local lp = e.livePart
            local mp = (lp and lp.Parent) and lp.Position or e.pos
            if mp and Vector3.new(mp.X - pos.X, 0, mp.Z - pos.Z).Magnitude < S.wasteLethalFar then return false end
        end
    end
    return true
end
function S.wasteFindTarget(hrp)
    local mon = Cache.monsterPositions
    local monsT = R.mons
    if not (mon and type(monsT) == "table") then return nil end
    local lethal = {}
    for i = 1, #mon do
        local e = mon[i]
        if e.model and S.wasteIsLethal(e.model) then
            local lp = e.livePart
            lethal[#lethal + 1] = (lp and lp.Parent) and lp.Position or e.pos
        end
    end
    local a = hrp.Position
    local function routeMin(b)
        local best = math.huge
        local sx, sz = b.X - a.X, b.Z - a.Z
        local sl = sx * sx + sz * sz
        for _, lp in ipairs(lethal) do
            local tt = sl > 0.01 and math.clamp(((lp.X - a.X) * sx + (lp.Z - a.Z) * sz) / sl, 0, 1) or 0
            local cx, cz = a.X + sx * tt - lp.X, a.Z + sz * tt - lp.Z
            local d = math.sqrt(cx * cx + cz * cz)
            if d < best then best = d end
        end
        return best
    end
    local best, bestScore
    for i = 1, #mon do
        local e = mon[i]
        local m = e.model
        local cfg = m and monsT[m.Name]
        if m and m.Parent and cfg and not cfg.isGrab and not S.wasteIsLethal(m)
           and m:GetAttribute("LostInterest") ~= true
           and not (m.Name == "GlistenMonster" and not (m:GetAttribute("GlistenActivated") == true and m:GetAttribute("GlistenInitialized") == true)) then
            local lp = e.livePart
            local mp = (lp and lp.Parent) and lp.Position or e.pos
            if mp and S.wasteFarFromLethal(mp) and routeMin(mp) >= S.wasteLethalRoute then
                local sc = Vector3.new(mp.X - a.X, 0, mp.Z - a.Z).Magnitude + (cfg.isThreat and 40 or 0)
                if not bestScore or sc < bestScore then best, bestScore = m, sc end
            end
        end
    end
    return best
end
function S.wasteWalkStart(hrp)
    if S.wasteWalkActive then return true end
    local tgt = S.wasteFindTarget(hrp)
    if not tgt then return false end
    S.wasteWalkActive = true
    S.wasteTarget = tgt
    S.wasteHealT = nil
    local startT = tick()
    local gen = (S.wasteGen or 0) + 1
    S.wasteGen = gen
    regSpawn(function()
        local lastMt, lastSprint, lastPos, lastProg, reachedT = 0, 0, nil, tick(), nil
        local result = "abort"
        local ch0 = plr.Character
        local h, hum
        while S.wasteWalkActive and S.wasteGen == gen do
            task.wait(0.05)
            local ch = plr.Character
            h = ch and ch:FindFirstChild("HumanoidRootPart")
            hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if not (h and hum and hum.Health > 0) then break end
            if S.wasteHealT and S.wasteHealT >= startT and S.safeHide and not S.shActive then result = "healed"; break end
            local okP, pan = pcall(IsPanicActive)
            if not S.autoWasteHeals or not S.drainHunt or not S.safeHide or S.shActive or S.encounterActive or (okP and pan) then break end
            local now = tick()
            if now - startT > 25 then result = "timeout"; break end
            local tm = S.wasteTarget
            local prim = tm and tm.Parent and (tm.PrimaryPart or tm:FindFirstChild("HumanoidRootPart") or tm:FindFirstChildWhichIsA("BasePart", true))
            if not prim then result = "lost"; break end
            local danger = false
            local mon = Cache.monsterPositions
            if mon then
                for i = 1, #mon do
                    local e = mon[i]
                    if e.model and S.wasteIsLethal(e.model) then
                        local lp = e.livePart
                        local mp = (lp and lp.Parent) and lp.Position or e.pos
                        if mp then
                            if (mp - h.Position).Magnitude < (e.detRadius or 75) + 10
                               or Vector3.new(mp.X - prim.Position.X, 0, mp.Z - prim.Position.Z).Magnitude < 60 then
                                danger = true; break
                            end
                        end
                    end
                end
            end
            if danger then result = "danger"; break end
            local d = Vector3.new(prim.Position.X - h.Position.X, 0, prim.Position.Z - h.Position.Z).Magnitude
            if d < 3 then
                reachedT = reachedT or now
                if now - lastMt > 0.3 then lastMt = now; pcall(function() hum:MoveTo(h.Position) end) end
                if now - reachedT > 10 then result = "nohit"; break end
            else
                reachedT = nil
                if now - lastMt > 0.2 then
                    lastMt = now
                    pcall(function() hum:MoveTo(Vector3.new(prim.Position.X, h.Position.Y, prim.Position.Z)) end)
                end
                local st = ch:FindFirstChild("Stats")
                local hs = st and st:FindFirstChild("HoldingSprint")
                if not S.sprintReal() and now - lastSprint > 0.15 then
                    lastSprint = now; S.shSprintOwned = true
                    pcall(R.FSprt, true)
                end
                if not lastPos or (h.Position - lastPos).Magnitude > 1.5 then lastPos, lastProg = h.Position, now
                elseif now - lastProg > 3 then result = "blocked"; break end
            end
        end
        S.wasteWalkActive = false
        S.wasteTarget = nil
        local hh = (plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")) or h
        local hm = (plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")) or hum
        if hh and hm then pcall(function() hm:MoveTo(hh.Position) end) end
        if result == "blocked" or result == "timeout" or result == "lost" or result == "nohit" then
            S.wasteWalkFailT = tick()
        end
        if (result == "healed" or result == "danger") and hh and S.safeHide and not S.shActive then
            S.shNearestUntil = tick() + 12
            S.shEarlyUntil = tick() + 1.2
            S.shNoEnterUntil = nil
            pcall(S.safeHideEnter, hh, 3, 15, "seen")
        elseif not S.shActive then
            pcall(S.shSprintStop)
        end
    end)
    return true
end
function UpdateDrainHunt(hrp, currentBase, userInBase, isPanicChecked, hc)
    local maxH = C.maxHeals or 2
    if S.autoWasteHeals and not S.autoEnabled then
        S.drainHunt = false; S.drainOn = false
        if ui.drainLbl then
            SetLabelText(ui.drainLbl, "- Auto Waste Heals: waiting for Auto Farm")
            SetLabelColor(ui.drainLbl, Th.mgray)
        end
        return false
    end
    if S.autoWasteHeals then
        if hc > maxH  then S.drainHunt = true  end
        if hc <= maxH then S.drainHunt = false  end
    else
        S.drainHunt = false
    end
    S.drainOn = S.drainHunt
    if not S.drainHunt then
        if ui.drainLbl then
            SetLabelText(ui.drainLbl, not S.autoWasteHeals
                and "- Auto Waste Heals: Off (toggle disabled)"
                or  "- Auto Waste Heals: Inactive")
            SetLabelColor(ui.drainLbl, Th.mgray)
        end
        return false
    end
    if ui.drainLbl then
        SetLabelText(ui.drainLbl,  "- Auto Waste Heals: ACTIVE ( heals: "..hc.." )")
        SetLabelColor(ui.drainLbl, Th.orange)
    end
    local char = plr.Character
    if char then TryWasteHeal(char) end
    local floorActive = R.gfv()
    if not (floorActive and floorActive:IsA("BoolValue") and floorActive.Value == true) then
        return true
    end
    if tick() - (S.drainHuntLastTP or 0) < (C.drainHuntDelay or 1.0) then
        return true
    end
    if S.safeHide and not S.pathfindMode and not R.isR and tick() - (S.wasteWalkFailT or 0) > 10 then
        if S.wasteWalkActive or S.shActive or S.shExiting or S.shTweening then return true end
        if S.wasteWalkStart(hrp) then
            if ui.drainLbl then
                SetLabelText(ui.drainLbl, "- Auto Waste Heals: Walking to a twisted (Safe Hide)")
                SetLabelColor(ui.drainLbl, Th.orange)
            end
            return true
        end
    end
    local tgt = R.fsm(hrp)
    if tgt and not S.wasteFarFromLethal(tgt.Position) then tgt = nil end
    if tgt then
        S.drainHuntLastTP = tick()
        local pos      = (tgt.CFrame * CFrame.new(0, 2, 0)).Position
        local targetCF = BuildOrientedCFrame(pos, tgt.CFrame)
        R.TpTo(hrp, targetCF)
        if ui.drainLbl then
            SetLabelText(ui.drainLbl, "- Auto Waste Heals: Teleporting to safe monster")
            SetLabelColor(ui.drainLbl, Th.orange)
        end
    else
        S.drainHunt        = false
        S.drainOn = false
        S.drainHuntLastTP   = tick() + K.drainNmCd - (C.drainHuntDelay or 1.0)
        if ui.drainLbl then
            SetLabelText(ui.drainLbl, "- Auto Waste Heals: No safe monster, farming...")
            SetLabelColor(ui.drainLbl, Th.yellow)
        end
        return false
    end
    return true
end
function RunTendrilDodge(hrp, currentBase, userInBase)
    if not S.autoEnabled then return end
    if S.safeHide then return end
    if S.pathfindMode and S.autoEnabled then return end
    local ten = Cache.tendrilPositions
    local tendrilPosCount = #ten
    if tendrilPosCount == 0 then return end
    local hrpPos   = hrp.Position
    local dodgeR   = C.tendrilDodgeRange
    local dodgeR2  = dodgeR * dodgeR
    local nearbyTendril = false
    for i = 1, tendrilPosCount do
        local d = hrpPos - ten[i].pos
        if (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= dodgeR2 then nearbyTendril = true; break end
    end
    if not nearbyTendril then return end
    if userInBase and currentBase then
        local avoidList = {}
        for i = 1, tendrilPosCount do avoidList[i] = ten[i].pos end
        if not S.safeSptOk then
            local safeCF = R.fsbs(currentBase, avoidList, dodgeR)
            if safeCF then
                WaitForSafeHideRelease()
                hrp.CFrame = safeCF
            end
        end
        S.safeSptOk = false
        return
    end
    if S.shActive and not S.shTeleporting then return end
    local ch0 = hrp.Parent
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.RespectCanCollide = true
    local excl = { ch0 }
    local cr0 = workspace:FindFirstChild("CurrentRoom")
    if cr0 then
        for _, room in ipairs(cr0:GetChildren()) do
            local mf = room:FindFirstChild("Monsters")
            if mf then excl[#excl+1] = mf end
        end
    end
    rp.FilterDescendantsInstances = excl
    local op = OverlapParams.new()
    op.FilterType = Enum.RaycastFilterType.Exclude
    op.FilterDescendantsInstances = excl
    op.RespectCanCollide = true
    op.MaxParts = 1
    local function tendrilMinD(p)
        local minD = math.huge
        for i = 1, tendrilPosCount do
            local dv = p - ten[i].pos
            local dm = math.sqrt(dv.X*dv.X + dv.Y*dv.Y + dv.Z*dv.Z)
            if dm < minD then minD = dm end
        end
        return minD
    end
    local bestPos, bestD = nil, -1
    local startD = tendrilMinD(hrpPos)
    local radii = { 15, 11, 8 }
    for _, rad in ipairs(radii) do
        for angle = 0, 315, 30 do
            local dir = Vector3.new(math.cos(math.rad(angle)), 0, math.sin(math.rad(angle)))
            local reach = rad
            local hit = workspace:Raycast(hrpPos, dir * (rad + 2.5), rp)
            if hit then reach = math.min(rad, (hit.Position - hrpPos):Dot(dir) - 2.5) end
            if reach >= 5 then
                local cp = hrpPos + dir * reach
                local gh = workspace:Raycast(cp + Vector3.new(0, 2, 0), Vector3.new(0, -12, 0), rp)
                if gh then
                    local tight = workspace:GetPartBoundsInRadius(Vector3.new(cp.X, hrpPos.Y, cp.Z), 2, op)
                    if #tight == 0 then
                        local d = tendrilMinD(Vector3.new(cp.X, hrpPos.Y, cp.Z))
                        if d > bestD then bestD = d; bestPos = Vector3.new(cp.X, hrpPos.Y, cp.Z) end
                    end
                end
            end
        end
        if bestPos and bestD >= dodgeR then break end
    end
    if not bestPos or bestD <= startD then return end
    hrp.CFrame = CFrame.new(bestPos.X, hrpPos.Y, bestPos.Z)
end
function IsSproutTendrilInBase(base)
    if not base or not base.Parent then return false end
    local halfX = base.Size.X / 2
    local halfZ = base.Size.Z / 2
    local function isInsideXZ(worldPos)
        local localPos = base.CFrame:PointToObjectSpace(worldPos)
        return math.abs(localPos.X) <= halfX and math.abs(localPos.Z) <= halfZ
    end
    local ten = Cache.tendrilPositions
    for i = 1, #ten do
        if not ten[i].isBlot then
            if isInsideXZ(ten[i].pos) then return true end
        end
    end
    if #ten == 0 then
        local nowF = tick()
        if nowF - (Cache.sproutFallbackT or 0) < 5 then return Cache.sproutFallbackRes == true end
        Cache.sproutFallbackT = nowF
        if not Cache.sproutFallbackBusy then
            Cache.sproutFallbackBusy = true
            task.spawn(function()
                local found, budget = false, 0
                for _, child in ipairs(workspace:GetChildren()) do
                    for _, obj in ipairs(child:GetDescendants()) do
                        budget += 1
                        if budget >= 400 then budget = 0; task.wait() end
                        if not found and obj:IsA("Model") and obj.Name == "SproutTendril" then
                            local tp = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true)
                            if tp and isInsideXZ(tp.Position) then found = true end
                        end
                    end
                    if found then break end
                end
                Cache.sproutFallbackRes = found
                Cache.sproutFallbackBusy = false
            end)
        end
        return Cache.sproutFallbackRes == true
    end
    return false
end
function RunBaseTendrilDodge(hrp, currentBase, userInBase)
    if not S.autoEnabled then S.safeSptOk = false; return end
    if S.safeHide then S.safeSptOk = false; return end
    if not userInBase or not currentBase then
        S.safeSptOk = false; return
    end
    if not IsSproutTendrilInBase(currentBase) then
        S.safeSptOk = false; return
    end
    local halfX = currentBase.Size.X / 2
    local halfZ = currentBase.Size.Z / 2
    local function isInsideBaseXZ(worldPos)
        local lp = currentBase.CFrame:PointToObjectSpace(worldPos)
        return math.abs(lp.X) <= halfX and math.abs(lp.Z) <= halfZ
    end
    local avoidList = {}
    local ten = Cache.tendrilPositions
    for i = 1, #ten do
        if isInsideBaseXZ(ten[i].pos) then avoidList[#avoidList+1] = ten[i].pos end
    end
    if #avoidList == 0 then return end
    local dodgeR2 = K.tenDodgeRsq
    local hrpPos  = hrp.Position
    local stillDangerous = false
    for i = 1, #avoidList do
        local dv = hrpPos - avoidList[i]
        if (dv.X*dv.X + dv.Y*dv.Y + dv.Z*dv.Z) <= dodgeR2 then
            stillDangerous = true; break
        end
    end
    if not stillDangerous then
        S.safeSptOk = true
        return
    end
    local safeCF = R.fsbs(currentBase, avoidList, K.tenDodgeR)
    if safeCF then
        S.safeSptOk = true
        WaitForSafeHideRelease()
        hrp.CFrame = safeCF
    end
end
function Update()
    local char = plr.Character
    if not char or not char.PrimaryPart then return end
    local hrp = char.PrimaryPart
    Prev.cuActiveGen   = R.gag()
    Prev.cuCurrentBase = R.fb()
    Prev.cuInvStats    = R.gis()
    Prev.cuStamina     = R.gcs()
    local activeGen        = Prev.cuActiveGen
    local currentBase      = Prev.cuCurrentBase
    local invStats         = Prev.cuInvStats
    if activeGen and IsValidGenModel(activeGen) then
        S.activeGen     = activeGen
        S.activeGenT = tick()
    end
    if activeGen ~= Prev.activeGen then
        Prev.activeGen = activeGen
        Cache.espDirty       = true
        Prev.genUILastUpdate = 0
        if Cache.lastPositionedGen ~= nil and activeGen ~= Cache.lastPositionedGen then
            Cache.lastPositionedGen = nil
        end
        if activeGen ~= S.ptpGen then
            S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
        end
        if S.eggFireG ~= activeGen then stopEggsonDecodeFireLoop() end
        if activeGen then
            startStopRadiusLoop()
        else
            stopStopRadiusLoop()
        end
    end
    if activeGen then S.noGenTPd = false end
    local isDanger, isFullDanger, chaseCount, pumpkinDanger = GetDangerState()
    UpdateChaseClearState(chaseCount)
    if S.forceHideActive and (S.safeHide or S.shByPathfind or S.shActive) then
        S.forceHideActive = false; S.forceHideUntil = 0; S.seenTimestamps = {}
    end
    if isDanger ~= Prev.lastIsDanger then
        Prev.lastIsDanger = isDanger; Cache.espDirty = true
        if isDanger and not S.forceHideActive and not S.safeHide and not S.shByPathfind and not S.shActive then
            local now = tick()
            local window = C.seenHideWindow or 10
            local kept = {}
            for _, t in ipairs(S.seenTimestamps or {}) do
                if now - t <= window then kept[#kept+1] = t end
            end
            kept[#kept+1] = now
            S.seenTimestamps = kept
            if #S.seenTimestamps >= (C.seenHideCount or 3) then
                S.seenTimestamps = {}
                TriggerForceHide()
            end
        end
    end
    if R.isR then return end
    local panicBase      = FindPanicBaseCached()
    local userInBase     = R.ibb(currentBase, hrp.Position)
    local isPanicChecked = IsPanicActive()
    if not Cache.firstFrameScanDone then
        Cache.firstFrameScanDone = true
        pcall(function() RunWorldScan(hrp, isDanger, currentBase, userInBase) end)
        pcall(function() RunTendrilScan() end)
    end
    local now = tick()
    local scanMinCD = 0.3
    if (Cache.scanDirty and (now - Cache.lastWorldScanTime) >= scanMinCD)
        or (now - Cache.lastWorldScanTime >= K.worldScanSecs) then
        pcall(function() RunWorldScan(hrp, isDanger, currentBase, userInBase) end)
    end
    if Cache.tendrilScanDirty or (now - Cache.lastTendrilScanTime >= K.tscanS) then
        pcall(function() RunTendrilScan() end)
    end
    Prev.cuFloorVal         = R.gfv()
    local floorActive       = Prev.cuFloorVal
    local floorActiveValue  = floorActive and floorActive:IsA("BoolValue") and floorActive.Value == true
    local floorJustOpened = floorActiveValue and not Prev.lastFloorActive
    Prev.lastFloorActive = floorActiveValue
    if floorJustOpened then
        pcall(function() RunWorldScan(hrp, isDanger, currentBase, userInBase) end)
        pcall(function() RunTendrilScan(true) end)
        Cache.lastPositionedFarm = nil
        S.lastFarmTeleport       = 0
        if S.pickupEnabled and not S.pathfindMode and not S.pickingUp and not activeGen and not S.pickupFloorBlocked() then
            local encounterActiveNow = false
            if S.autoEncounter and S.trigOk("encounter") then
                local ae = _G.yattaAE
                if ae and not ae.allDone then encounterActiveNow = true end
            end
            if not encounterActiveNow then
                local ok, pendingItems = pcall(function() return R.gai() end)
                if ok and pendingItems and #pendingItems > 0 then
                    regSpawn(function()
                        local c2 = plr.Character
                        local hrp2 = c2 and c2.PrimaryPart
                        if hrp2 then pcall(function() RunPickupBatch(hrp2) end) end
                    end)
                end
            end
        end
    end
    local genIsBelowHalfUI = UpdateGenUI(activeGen)
    local hc               = UpdateInventoryUI(invStats)
    UpdateDecodingUI(activeGen, hrp, currentBase, isDanger)
    do
        local isTreadmillActive = false
        if activeGen and activeGen.Parent then
            local mt = activeGen:GetAttribute("MinigameType")
            if mt == "MovementTreadmill" then isTreadmillActive = true end
            if not isTreadmillActive then
                local mts = activeGen:GetAttribute("MinigameTypes")
                if type(mts) == "string" then
                    for p in mts:gmatch("[^,]+") do
                        if p:match("^%s*MovementTreadmill%s*$") then isTreadmillActive = true; break end
                    end
                end
            end
        end
        local shouldSprint = S.autoSprint and (isTreadmillActive or (not floorActiveValue))
        if shouldSprint and not S.sprintLoopActive then
            R.StrSL()
        elseif not shouldSprint and S.sprintLoopActive then
            R.StSL()
            if S.isSprinting then pcall(function() R.FSprt(false) end) end
        end
    end
    local drainHandled = UpdateDrainHunt(hrp, currentBase, userInBase, isPanicChecked, hc)
    if ui.panicLbl then
        SetLabelText(ui.panicLbl,  "- Panic: "..(isPanicChecked and "ACTIVE" or "waiting"))
        SetLabelColor(ui.panicLbl, isPanicChecked and Th.red or Th.mgray)
    end
    if ui.elevLbl then
        SetLabelText(ui.elevLbl, currentBase
            and ("- Fake Elevator ("..math.floor((hrp.Position-currentBase.Position).Magnitude).." studs)")
            or  "- Fake Elevator: SEARCHING...")
        SetLabelColor(ui.elevLbl, currentBase and Th.lgray or Th.orange)
    end
    if drainHandled then
        RunTendrilDodge(hrp, currentBase, userInBase)
        RunBaseTendrilDodge(hrp, currentBase, userInBase)
        aDDestroyPad(); aDSetInactive()
        UpdateProgressPanel(invStats, chaseCount, isDanger, activeGen, hc)
        return
    end
    if S.autoBuy then
        DoAutoBuyV15(hrp)
        Prev.lastAutoBuy = true
    elseif Prev.lastAutoBuy then
        Prev.lastAutoBuy = false
        stopBuyWalk()
        updateDandyInvisWallCollision(false)
        abw.wasOpen = false
    end
    DoAutoUseItems(activeGen, genIsBelowHalfUI, isFullDanger, char)
    if (S.safeTp or S.safeHide) and isDanger and not isPanicChecked then
        if S.safeHide then
            if not S.shActive and S.pumpkinThreat(hrp.Position, 45) then S.shPumpkinUntil = tick() + 2 end
            if not S.shActive then
                local mons = Cache.monsterPositions
                for i = 1, #mons do
                    local lp = mons[i].livePart
                    local mp = lp and lp.Parent and lp.Position or mons[i].pos
                    if mp and (mp - hrp.Position).Magnitude < 35 then S.shDodgeSpeedUntil = tick() + 1.5; break end
                end
            end
            local pkCause = (S.shPumpkinUntil and tick() < S.shPumpkinUntil) or #S.rollingPumpkins() > 0
            S.safeHideEnter(hrp, 3, 15, pkCause and "pumpkin" or "seen")
        elseif tick() - (S.lastIconTeleport or 0) >= C.iconLoopDelay then
            S.lastIconTeleport = tick()
            if currentBase and not userInBase then TeleportToBaseWithRetry(hrp, currentBase) end
        end
        if ui.hideLbl then SetLabelText(ui.hideLbl,"- Seen: Yes"); SetLabelColor(ui.hideLbl, Th.red) end
    else
        if ui.hideLbl then SetLabelText(ui.hideLbl,"- Seen: No");  SetLabelColor(ui.hideLbl, Th.mgray) end
    end
    local aePanicBusy = false
    if S.autoEncounter and S.autoEnabled and S.trigOk("encounter") then
        local aeP = _G.yattaAE
        if aeP and not aeP.allDone then aePanicBusy = true end
    end
    local abw = abw or _G.yattaABW
    if S.autoPanicTp and isPanicChecked and panicBase and not S.pathfindMode
        and not S.pickingUp and not aePanicBusy
        and abw and not (abw.active or abw.storeConn ~= nil) then
        local inPanicBase = R.ibb(panicBase, hrp.Position)
        if not inPanicBase then
            if tick() - (S.lastPanicTeleport or 0) >= C.panicCooldown then
                S.lastPanicTeleport = tick()
                local pos      = (panicBase.CFrame * CFrame.new(0, C.teleportHeight, 0)).Position
                local targetCF = S.elevFrontCF(panicBase, pos)
                R.TpTo(hrp, targetCF)
            end
        end
    end
    if S.autoPanicTp and S.autoEnabled and isPanicChecked and not S.pathfindMode and not S.pickingUp and not aePanicBusy then
        local elevBase = nil
        local elevs = workspace:FindFirstChild("Elevators")
        if elevs then
            local elev = elevs:FindFirstChild("Elevator")
            if elev then elevBase = elev:FindFirstChild("Base", true) end
        end
        if not elevBase then
            local cr = workspace:FindFirstChild("CurrentRoom")
            if cr then
                local elev2 = cr:FindFirstChild("Elevator", true)
                if elev2 then elevBase = elev2:FindFirstChild("Base", true) end
            end
        end
        if elevBase and elevBase:IsA("BasePart") then
            local primary = char and char.PrimaryPart
            if primary and primary.Position.Y < elevBase.Position.Y then
                if tick() - (S.lastElevBelowPanicTP or 0) >= (C.panicCooldown or 1) then
                    S.lastElevBelowPanicTP = tick()
                    local didPickupBeforeElev = false
                    if S.pickupEnabled and not S.pickingUp and not S.pickupFloorBlocked() then
                        local panicPickupItems = R.gai()
                        if #panicPickupItems > 0 then
                            didPickupBeforeElev = true
                            local panicPickupDeadline = tick() + 6
                            regSpawn(function()
                                while tick() < panicPickupDeadline do
                                    local ppItems2 = R.gai()
                                    if #ppItems2 == 0 then break end
                                    task.wait(0.1)
                                end
                                local hrp2 = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                                if hrp2 and elevBase and elevBase.Parent then
                                    WaitForSafeHideRelease()
                                    hrp2.CFrame = S.elevFrontCF(elevBase, elevBase.Position + Vector3.new(0, 4, 0))
                                end
                            end)
                        end
                    end
                    if not didPickupBeforeElev then
                        WaitForSafeHideRelease()
                        hrp.CFrame = S.elevFrontCF(elevBase, elevBase.Position + Vector3.new(0, 4, 0))
                    end
                end
            end
        end
    end
    local buyWalkBusy = abw and (abw.active or (abw.storeConn ~= nil))
    local encounterBlocking = false
    if S.autoEncounter and S.autoEnabled and S.trigOk("encounter") then
        local ae = _G.yattaAE
        local aeDone = not ae or ae.allDone
        if not aeDone then
            encounterBlocking = true
        end
        if not encounterBlocking then
            S.encounterStartTime = nil
            S.encounterActive    = false
        end
    else
        S.encounterStartTime = nil
    end
    local eggsonHandled = false
    local shHiding = S.shBusy()
    if not shHiding and S.safeHide and S.autoEnabled then
        if tick() - (S.shLastExit or 0) < 1.5 then
            shHiding = true
        else
            local inB = false
            if currentBase then
                local okB, r = pcall(R.ibb, currentBase, hrp.Position)
                inB = okB and r or false
            end
            if not inB then
                local okD, clearD = pcall(S.shDetClear, hrp.Position)
                if okD and not clearD then shHiding = true end
            end
        end
    end
    if shHiding then
        Cache.lastPositionedFarm = nil
        S.ptpPend = false; S.ptpGen = nil; S.ptpDone = false
        if S.FarmBall then S.FarmBall.Transparency = 1 end
        if S.eggFire then stopEggsonDecodeFireLoop() end
    end
    if not shHiding and not buyWalkBusy and not encounterBlocking then
        if S.autoEnabled and S.eggsonMode then
            eggsonHandled = DoEggsonFarm(hrp, currentBase, isPanicChecked, floorActiveValue)
        else
            if S.eggFire then stopEggsonDecodeFireLoop() end
            if loop.eggsonChaseStop then loop.eggsonChaseStop = false end
        end
    end
    if not shHiding and not eggsonHandled and not buyWalkBusy and not encounterBlocking and not S.forceHideActive and not S.floorStopActive and not S.pathfindMode then
        DoNormalAutoFarm(hrp, currentBase, isDanger, isPanicChecked, floorActive, activeGen, pumpkinDanger)
    end
    if S.autoBuy or R.idso() then
        updateDandyInvisWallCollision(true)
    else
        updateDandyInvisWallCollision(false)
    end
    if ui.eyeLbl then
        SetLabelText(ui.eyeLbl, "Chase Count: "..chaseCount)
        SetLabelColor(ui.eyeLbl, isDanger and Th.red or Th.lgray)
    end
    if ui.chaseLbl and not IsInChaseClearWait() then
        SetLabelText(ui.chaseLbl, "- Chase Count: "..chaseCount)
        SetLabelColor(ui.chaseLbl, isDanger and Th.red or Th.mgray)
    end
    if ui.interactLbl then
        local shouldFire = (sf.currentGen ~= nil and sf.currentGen == activeGen)
        SetLabelText(ui.interactLbl, "Auto stop Extracting: "..(shouldFire and "ACTIVE" or "READY"))
        SetLabelColor(ui.interactLbl, shouldFire and Th.red or Th.yellow)
    end
    RunTendrilDodge(hrp, currentBase, userInBase)
    RunBaseTendrilDodge(hrp, currentBase, userInBase)
    local tCount    = S.cachedTCount    or 0
    local blotCount = S.cachedBlotCount or 0
    local gCount    = S.cachedGCount    or 0
    if ui.tendrilLbl then SetLabelText(ui.tendrilLbl, "Tendrils: "..(tCount-blotCount).."   Blot Hands: "..blotCount) end
    if ui.grabLbl    then SetLabelText(ui.grabLbl,    "Active Grabs: "..gCount) end
    if ui.healUsedCountLbl and Prev.healUsedCount ~= S.healUsedCount then
        SetLabelText(ui.healUsedCountLbl, "Heals Used: "..S.healUsedCount)
        Prev.healUsedCount = S.healUsedCount
    end
    if ui.droppedStolenLbl and Prev.droppedStolenCount ~= S.droppedStolenCount then
        SetLabelText(ui.droppedStolenLbl, "Healing Items Dropped/Stolen: "..S.droppedStolenCount)
        Prev.droppedStolenCount = S.droppedStolenCount
    end
    if ui.hitsTakenLbl and Prev.hitsTakenCount ~= S.hitsTakenCount then
        SetLabelText(ui.hitsTakenLbl, "Hits Taken: "..S.hitsTakenCount)
        Prev.hitsTakenCount = S.hitsTakenCount
    end
    UpdateProgressPanel(invStats, chaseCount, isDanger, activeGen, hc)
end
