_G.yattaLoopToken      = (_G.yattaLoopToken or 0) + 1
local myToken          = _G.yattaLoopToken
_G.yattaLoopAlive      = true
_G.yattaMainUpdateTask = true
regSpawn(function()
    while _G.yattaLoopAlive and _G.yattaMainUpdateTask
        and _G.yattaLoopToken == myToken do
        local stepW = K.updateStep
        if S.autoEnabled then
            local okG, ag = pcall(R.gag)
            if (okG and ag ~= nil) or (tick() - (S.lastGenT or 0)) < 2 then stepW = 0.09 end
        end
        task.wait(stepW)
        if _G.yattaLoopToken ~= myToken then break end
        local ok, err = pcall(Update)
        if not ok then
            task.wait(0.25)
        end
    end
