function collect()
    local now = tick()
    if (now - collectCacheTime) < collectTtl and #collectCache > 0 then
        return collectCache
    end
    collectCacheTime = now
    local out   = collectCache
    local n     = 0
    local ESPen = R.espe
    local room  = workspace:FindFirstChild("CurrentRoom")
    if ESPen.players then
        for _, p in ipairs(tPlayers:GetPlayers()) do
            if p == tPlayer then continue end
