                                    col = espColors.tendrils, cat = "tendrils" }
                            end
                        end
                    else
                        local cached = objCatCache[obj]
                        if not cached then
                            if R.mons and R.mons[obj.Name] then
                                local mcfg = R.mons[obj.Name]
                                local isIgnored = _G.YattaRZ.ignored(obj, mcfg)
                                if obj.Name == "GlistenMonster" then
                                    local gA = obj:GetAttribute("GlistenActivated")
                                    local gI = obj:GetAttribute("GlistenInitialized")
                                    isIgnored = not (gA == true and gI == true)
                                    if isIgnored then
                                        cached = { cat = "ignoredMonsters", col = espColors.ignoredMonsters }
                                    else
                                        cached = { cat = "monsters", col = espColors.monsters }
                                    end
                                elseif isIgnored then
                                    cached = { cat = "ignoredMonsters", col = espColors.ignoredMonsters }
                                else
                                    cached = { cat = "monsters",        col = espColors.monsters }
                                end
                            elseif R.iumo and R.iumo(obj) then
                                cached = { cat = "unknownMonsters", col = espColors.unknownMonsters }
                            end
                            if cached and obj.Name ~= "GlistenMonster" and obj.Name ~= "GourdyMonster" then objCatCache[obj] = cached end
                        end
                        if cached and (ESPen[cached.cat]
                            or (cached.cat == "ignoredMonsters"  and ESPen.monsters)
                            or (cached.cat == "unknownMonsters"  and ESPen.monsters)) then
                            n += 1
                            out[n] = { obj = obj, prim = prim,
                                col = cached.col, cat = cached.cat }
                        end
                    end
                end
            end
            if ESPen.generators then
                if Cache.totGens then
                    for g in pairs(Cache.totGens) do
                        if g.Parent and g.Parent.Name ~= "Generators" and g:IsDescendantOf(roomModel) then
                            local prim = getPrimary(g)
                            if prim then
                                n += 1
                                out[n] = { obj = g, prim = prim, col = espColors.generators, cat = "generators" }
                            end
                        end
                    end
                end
                local gf = roomModel:FindFirstChild("Generators")
                if gf then
                    for _, gen in ipairs(gf:GetChildren()) do
                        if not gen:IsA("Model") then continue end
                        local prim = getPrimary(gen)
                        if prim then
                            n += 1
                            out[n] = { obj = gen, prim = prim,
                                col = espColors.generators, cat = "generators" }
                        end
                    end
                end
            end
            if ESPen.items then
                local itf = roomModel:FindFirstChild("Items")
                if itf then
                    for _, item in ipairs(itf:GetChildren()) do
                        if not item:IsA("Model") then continue end
                        if item.Name == "GigiHoard" and ESPen.gigiMachine then continue end
                        local prim = getPrimary(item)
                        if prim then
                            local isRC = (item.Name == "ResearchCapsule")
                            n += 1
                            out[n] = { obj = item, prim = prim,
                                col = espColors.items,
                                cat = isRC and "researchCapsule" or "items" }
                        end
                    end
                end
            end
        end
    end
    for i = n + 1, #out do out[i] = nil end
    return out
end
