function setInfoText(obj, text)
    local lbl = infoLbls[obj]
    if lbl and lbl.Parent and lbl.Text ~= text then lbl.Text = text end
end
function genInfo(gen)
    local st   = gen:FindFirstChild("Stats")
    local cur, req, comp, connie = 0, 0, false, false
    if st then
        local cv  = st:FindFirstChild("CurrentAmount")
        local rv  = st:FindFirstChild("RequiredAmount")
        local cpv = st:FindFirstChild("Completed")
        local cnv = st:FindFirstChild("Connie")
        cur    = cv  and cv.Value  or 0
        req    = rv  and rv.Value  or 0
        comp   = cpv and cpv:IsA("BoolValue") and cpv.Value == true
        connie = cnv and cnv:IsA("BoolValue") and cnv.Value == true
    end
    local safe = false
    if R.igs then pcall(function() safe = R.igs(gen) end) end
    return string.format(
        "Completed: (%s)\n%d/%d\nSafe: (%s)\nConnie: (%s)\nName: (%s)",
        comp   and "True" or "False",
        cur, req,
        safe   and "True" or "False",
        connie and "True" or "False",
        gen.Name or "?"
    )
end
function playerInfo(p, char)
    local lines = {}
    local tag = getPlayerTag(p)
    if tag then lines[#lines+1] = tag end
    lines[#lines+1] = string.format("User: (%s, %s)", p.DisplayName or p.Name, p.Name)
    if tIsFullPlace then
        local ok, val = pcall(function() return p:GetAttribute("SelectedCharacter") end)
        local sc = ok and val or nil
        if sc and sc ~= "" then
            lines[#lines+1] = string.format("Toon: (%s)", tostring(sc))
        end
        local igp = workspace:FindFirstChild(_G.YattaIGP)
        local pm  = igp and igp:FindFirstChild(p.Name)
        local inv = pm and (pm:FindFirstChild("Inventory") or pm:FindFirstChild("Items"))
        if inv then
            local slots = {}
            for i = 1, 4 do
                local s = inv:FindFirstChild("Slot"..i) or inv:FindFirstChild("Item"..i)
                local v = s and s:IsA("StringValue") and s.Value ~= "" and s.Value ~= "None" and s.Value
                if v then slots[#slots+1] = v
                elseif i <= 3 then slots[#slots+1] = "Empty" end
            end
            if #slots > 0 then
                lines[#lines+1] = "Items: (" .. table.concat(slots, " - ") .. ")"
            end
        end
        local hum = char and char:FindFirstChildWhichIsA("Humanoid")
        if hum then
            lines[#lines+1] = string.format("Health: %.0f/%.0f", hum.Health, hum.MaxHealth)
        end
        local trinketsF = pm and pm:FindFirstChild("Trinkets")
        if trinketsF then
            local t1 = trinketsF:FindFirstChild("Trinket1")
            local t2 = trinketsF:FindFirstChild("Trinket2")
            local v1 = t1 and t1:IsA("StringValue") and t1.Value ~= "" and t1.Value or "None"
            local v2 = t2 and t2:IsA("StringValue") and t2.Value ~= "" and t2.Value or "None"
            lines[#lines+1] = string.format("Trinket(s): (%s/%s)", v1, v2)
        end
    end
    return table.concat(lines, "\n")
end
function S.researchOf(name)
    if type(name) ~= "string" or name == "" then return nil end
    local ok, res = pcall(function()
        local pd = game:GetService("ReplicatedStorage"):FindFirstChild("PlayerData")
        local mine = pd and pd:FindFirstChild(tostring(plr.UserId))
        local rf = mine and mine:FindFirstChild("Research")
        if not rf then return nil end
        local cands = { name }
        if name:sub(-7) == "Monster" then cands[#cands + 1] = name:sub(1, -8)
        else cands[#cands + 1] = name .. "Monster" end
        for _, c in ipairs(cands) do
            local v = rf:FindFirstChild(c)
            if v and (v:IsA("NumberValue") or v:IsA("IntValue")) then return v.Value end
        end
        return 0
    end)
    if ok then return res end
    return nil
end
function S.researchLine(name)
    local v = S.researchOf(name)
    if v == nil then return "Research: N/A" end
    return string.format("Research: %s%%", tostring(math.floor(math.min(v, 100) * 10 + 0.5) / 10))
end
function researchCapsuleInfo(item)
    local monsterVal = ""
    local prompt = item:FindFirstChild("Prompt")
    if prompt then
        local mv = prompt:FindFirstChild("Monster")
        if mv and mv:IsA("StringValue") then monsterVal = mv.Value end
    end
    if monsterVal == "" then
        local mv2 = item:FindFirstChild("Monster", true)
        if mv2 and mv2:IsA("StringValue") then monsterVal = mv2.Value end
    end
    return string.format("Item: (%s)\nFrom: (%s)\n%s",
        item.Name or "?",
        monsterVal ~= "" and monsterVal or "Unknown",
        monsterVal ~= "" and S.researchLine(monsterVal) or "Research: N/A")
end
function monsterInfo(obj, withResearch)
    local raw = obj.Name
    local name
    if raw == "SproutMonster" then
        name = "Sprout"
    elseif raw:find("Sprout") and raw:find("Monster") then
        name = raw:gsub("Monster", ""):gsub("Monster", "")
        if name == "" then name = "Sprout" end
    else
        name = R.cn and R.cn(raw) or raw:gsub("Monster", "")
    end
    if name == "" then name = raw:gsub("Monster", "") end
    if withResearch then return string.format("Twisted %s\n%s", name, S.researchLine(raw)) end
    return string.format("Twisted %s", name)
end
function ignoredMonsterInfo(obj)
    local name = R.cn and R.cn(obj.Name) or obj.Name:gsub("Monster", "")
    return string.format("[Ignored]\n%s\n%s", name, S.researchLine(obj.Name))
end
function itemInfo(item)
