end
local infoLastTick = 0
local infoRate    = 0.25
function refreshOneInfo(entry)
    local obj  = entry.obj
    local cat  = entry.cat
    local text
    if     cat == "generators"      then text = genInfo(obj)
    elseif cat == "players"         then
        local p = entry.plr
        if p and p.Character then text = playerInfo(p, p.Character) end
    elseif cat == "researchCapsule" then text = researchCapsuleInfo(obj)
    elseif cat == "monsters" or cat == "unknownMonsters" then text = monsterInfo(obj, true)
    elseif cat == "tendrils" then text = monsterInfo(obj)
    elseif cat == "ignoredMonsters"  then text = ignoredMonsterInfo(obj)
    elseif cat == "items"            then text = itemInfo(obj)
    end
    if text and text ~= (infoCache[obj] or "") then
        infoCache[obj] = text
        setInfoText(obj, text)
    end
end
local cleanLastTick = 0
local cleanRate    = 0.5
function runCleanup(seenSet)
