    for obj in pairs(infoBBs)      do if not seenSet[obj] or not obj.Parent then removeInfo(obj)        end end
    for obj in pairs(tracerFrames) do if not seenSet[obj] or not obj.Parent then removeTracerFrame(obj) end end
    sweepOrphanedFrames()
end
S.overlayIdle = false
function infoHiddenDone(cat, obj)
    if cat ~= "generators" then return false end
