        for obj in pairs(boxBBs)  do removeBox(obj)  end
        for obj in pairs(infoBBs) do removeInfo(obj) end
        sweepOrphanedFrames()
        S.overlayIdle = true
        return
    end
    S.overlayIdle = false
    local cam      = tCamera or workspace.CurrentCamera
    if not cam then return end
    local vp       = cam.ViewportSize
