                local ang  = math.deg(math.atan2(ep.Y - startPos.Y, ep.X - startPos.X))
                f.ZIndex   = math.max(1, 500 - math.floor(sp.Z))
                f.Size     = UDim2.fromOffset((ep - startPos).Magnitude, 1)
                f.Position = UDim2.fromOffset(mid.X, mid.Y)
                f.Rotation = ang
                f.Visible  = true
            else
                f.Visible = false
            end
        else
            hideTracerFrame(obj)
            if boxBBs[obj] then removeBox(obj) end
        end
        if anyI and infoEnabled[cat] and not infoHiddenDone(cat, obj) then
            ensureInfo(obj, prim)
        else
            if infoBBs[obj] then removeInfo(obj) end
        end
    end
    local now = tick()
    if (now - cleanLastTick) >= cleanRate then
        cleanLastTick = now
        runCleanup(seenNow)
    end
end))
table.insert(_G.YattaConnections, tRunService.Heartbeat:Connect(function()
