function pPF(direction)
    if not fE then return end
    if fIA or fH.Health <= 0 then return end
    if fH.FloorMaterial == Enum.Material.Air then return end
    local P1 = _G.YattaP1
    if P1 and P1.fs and P1.fs.flying then return end
    fIA = true
    local currentVelocity = fRP.AssemblyLinearVelocity
    local lookVector      = fRP.CFrame.LookVector
    local rightVector     = fRP.CFrame.RightVector
    fDC()
    fH:ChangeState(Enum.HumanoidStateType.Physics)
    fRP.AssemblyLinearVelocity = Vector3.new(
        currentVelocity.X * fMM,
        fLP,
        currentVelocity.Z * fMM
    )
    if     direction == "Front" then fRP.AssemblyAngularVelocity = rightVector * -fSS
    elseif direction == "Back"  then fRP.AssemblyAngularVelocity = rightVector *  fSS
    elseif direction == "Left"  then fRP.AssemblyAngularVelocity = lookVector  * -fSS
    elseif direction == "Right" then fRP.AssemblyAngularVelocity = lookVector  *  fSS
    end
    local timeoutDuration   = 1.0
    local elapsed           = 0
    local completedRotation = false
    task.wait(0.1)
    elapsed = elapsed + 0.1
    while elapsed < timeoutDuration do
        local deltaTime = fRS.Heartbeat:Wait()
        elapsed = elapsed + deltaTime
        local currentUp = fRP.CFrame.UpVector
        local worldUp   = Vector3.new(0, 1, 0)
        if currentUp:Dot(worldUp) > 0.7 then
            completedRotation = true; break
        end
    end
    if not completedRotation then
        local p1 = _G.YattaP1
        local onAllowedPlace = p1 and (game.PlaceId == p1.fid or game.PlaceId == p1.rid)
        fRC()
        if onAllowedPlace then
            fRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            fH:ChangeState(Enum.HumanoidStateType.GettingUp)
        else
            fH:ChangeState(Enum.HumanoidStateType.FallingDown)
            fRP.AssemblyAngularVelocity = fRP.AssemblyAngularVelocity * 0.4
            local recoveryTimer = 0
            while recoveryTimer < 4.0 do
                local dt = fRS.Heartbeat:Wait()
                recoveryTimer = recoveryTimer + dt
                if fH.Health <= 0 then break end
                if fH:GetState() ~= Enum.HumanoidStateType.FallingDown then
                    fH:ChangeState(Enum.HumanoidStateType.FallingDown)
                end
            end
            fH:ChangeState(Enum.HumanoidStateType.GettingUp)
        end
        fIA = false
        return
    end
    fRP.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    local blendElapsed = 0
    while blendElapsed < fLS do
        local deltaTime = fRS.Heartbeat:Wait()
        blendElapsed = blendElapsed + deltaTime
        local alpha      = math.sin((blendElapsed / fLS) * (math.pi / 2))
        local currentPos = fRP.Position
        local targetCFrame = CFrame.lookAt(currentPos, currentPos + Vector3.new(lookVector.X, 0, lookVector.Z))
        if S.shActive and not S.shTeleporting then
            break
        end
        fRP.CFrame = fRP.CFrame:Lerp(targetCFrame, alpha)
    end
    fRC()
    fH:ChangeState(Enum.HumanoidStateType.GettingUp)
    local postVelocity = fRP.AssemblyLinearVelocity
    if postVelocity.Magnitude > fMV then
        fRP.AssemblyLinearVelocity = postVelocity.Unit * (fMV * 0.5)
    end
    fIA = false
end
