function aEFindCeilingY(worldPos, searchHeight, extraExclude)
    searchHeight = searchHeight or 80
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    local exc = {}
    for _, p in ipairs(Plrs:GetPlayers()) do
        if p.Character then exc[#exc+1] = p.Character end
    end
    if extraExclude then exc[#exc+1] = extraExclude end
    if R.vf then exc[#exc+1] = R.vf end
    if ae.platform and ae.platform.Parent then
        exc[#exc+1] = ae.platform
    end
    local currentRoom = workspace:FindFirstChild("CurrentRoom")
    if currentRoom then
        for _, rm in ipairs(currentRoom:GetChildren()) do
            local mf = rm:FindFirstChild("Monsters")
            if mf then exc[#exc+1] = mf end
        end
    end
    rp.FilterDescendantsInstances = exc
