function aEIsMonsterChasingMe(monsterModel)
    local me = plr.Name
    local function chk(obj)
        if not obj then return false end
        if obj:IsA("ObjectValue") then
            local v = obj.Value
            if v == plr then return true end
            if v and v.Name == me then return true end
        elseif obj:IsA("StringValue") then
            if obj.Value == me then return true end
            if obj.Value:find(me, 1, true) then return true end
        end
        return false
    end
    for _, child in ipairs(monsterModel:GetChildren()) do
        if child.Name == "ChasingValue" and chk(child) then return true end
    end
    for _, desc in ipairs(monsterModel:GetDescendants()) do
        if desc.Name == "ChasingValue" and chk(desc) then return true end
    end
    local ok, attr = pcall(function() return monsterModel:GetAttribute("ChasingValue") end)
    if ok and attr then
        if attr == me then return true end
        if type(attr) == "string" and attr:find(me, 1, true) then return true end
    end
    return false
end
function S.isFullResearched(name)
    local ok, res = pcall(function()
        local pd = game:GetService("ReplicatedStorage"):FindFirstChild("PlayerData")
        local mine = pd and pd:FindFirstChild(tostring(plr.UserId))
        local rf = mine and mine:FindFirstChild("Research")
        local v = rf and rf:FindFirstChild(name)
        return v ~= nil and v:IsA("NumberValue") and v.Value >= 100
    end)
    return ok and res == true
end
