        if obj:IsA("ObjectValue") then
            local v = obj.Value
            return v == plr or (v ~= nil and v.Name == me)
        elseif obj:IsA("StringValue") then
            return obj.Value == me or (obj.Value ~= "" and obj.Value:find(me, 1, true) ~= nil)
        end
        return false
    end
    local cv = m:FindFirstChild("ChasingValue") or m:FindFirstChild("ChasingValue", true)
    if cv and chk(cv) then return true end
    local ok, attr = pcall(function() return m:GetAttribute("ChasingValue") end)
    if ok and attr then
        if attr == me then return true end
        if type(attr) == "string" and attr:find(me, 1, true) then return true end
    end
    return false
end
