function aEGetCandidates(skipEncountered)
    local out = {}
    S.aeGourdyWaiting = false
    local currentRoom = workspace:FindFirstChild("CurrentRoom")
    if not currentRoom then return out end
    for _, roomModel in ipairs(currentRoom:GetChildren()) do
        if not roomModel:IsA("Model") then continue end
        local mf = roomModel:FindFirstChild("Monsters")
        if not mf then continue end
        for _, obj in ipairs(mf:GetChildren()) do
            if not obj:IsA("Model") then continue end
            if R.TSet[obj.Name] then continue end
            if S.excludeFullResearch and S.isFullResearched(obj.Name) then continue end
            if skipEncountered and ae.encountered[obj] then continue end
            if skipEncountered and S.aeBlacklist and S.aeBlacklist[obj.Name] then continue end
            local cfg = R.mons[obj.Name]
            if obj.Name == "GourdyMonster" then
                local gs = obj:FindFirstChild("GourdyState")
                local gstate = gs and gs:IsA("StringValue") and string.lower(gs.Value) or ""
                if gstate ~= "mobile" then S.aeGourdyWaiting = true; ae.gourdyInvolved = true; continue end
            end
            if cfg then
                if cfg.isGrab then continue end
                if cfg.farmIgnore then continue end
                if cfg.aeIgnore then continue end
            else
                if not R.iumo(obj) then continue end
            end
            local prim = obj.PrimaryPart
                      or obj:FindFirstChild("HumanoidRootPart")
                      or obj:FindFirstChildWhichIsA("BasePart", true)
            if prim then
                out[#out+1] = {
                    model    = obj,
                    prim     = prim,
                    isConnie = (obj.Name == "ConnieMonster"),
                }
            end
        end
    end
    return out
end
function aETeleportAboveMonster(hrp, entry)
    local prim = entry.prim
    if not prim or not prim.Parent then return end
    if entry.isConnie then
        aEDestroyPlatform()
        WaitForSafeHideRelease()
        hrp.CFrame = CFrame.new(prim.Position)
        return
    end
    local mp = prim.Position
    local tx, tz = mp.X, mp.Z
    local ceilY = aEFindCeilingY(Vector3.new(tx, mp.Y, tz), 200, entry.model)
    local footY
    if ceilY then
        footY = ceilY - aeCeilPad
        if footY < mp.Y + 3 then footY = mp.Y + 3 end
    else
        footY = mp.Y + 50
    end
    local isLethal = (entry.model.Name == "DyleMonster" or entry.model.Name == "DandyMonster")
    local maxFootY  = mp.Y + (isLethal and 28 or 20)
    if footY > maxFootY then footY = maxFootY end
    if footY < mp.Y then footY = mp.Y end
    local standY = footY + (aePlatformH / 2) + 1.6
    WaitForSafeHideRelease()
    aEPlacePlatform(tx, tz, footY)
    hrp.CFrame = CFrame.new(tx, standY, tz)
    if S.tpSettle then S.tpSettle(hrp) end
