_G.YattaAdditionals = _G.YattaAdditionals or {}
_G.YattaAdditionals.encounter = function()
    if aeManualBusy then return end
    local char = plr.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local visited = {}
    local usable = 0
    for _, e in ipairs(aEGetCandidates()) do
        if e.isConnie or not aEIsMonsterChasingMe(e.model) then usable = usable + 1 end
    end
    if usable == 0 then
        if _G.YattaNotify then _G.YattaNotify("No Twisteds Found.", true) end
        return
    end
    aeManualBusy = true
    ae.manual    = true
    regSpawn(function()
        local origCF   = hrp.CFrame
        local deadline = tick() + 5
        local target, tStart
        local metCount = 0
        local pre, met = {}, {}
        local function eachMonster(fn)
            local cr = workspace:FindFirstChild("CurrentRoom")
            if not cr then return end
            for _, room in ipairs(cr:GetChildren()) do
                local mf = room:IsA("Model") and room:FindFirstChild("Monsters")
                if mf then
                    for _, m in ipairs(mf:GetChildren()) do
                        if m:IsA("Model") and not R.TSet[m.Name] then fn(m) end
                    end
                end
            end
        end
        eachMonster(function(m) if ae.chasingFast(m) then pre[m] = true end end)
        local function scanMet()
            eachMonster(function(m)
                if not pre[m] and not met[m] and ae.chasingFast(m) then met[m] = true; metCount = metCount + 1 end
            end)
        end
        while tick() < deadline do
            task.wait(aeLoopWait)
            pcall(scanMet)
            local ch = plr.Character
            local h  = ch and ch:FindFirstChild("HumanoidRootPart")
            if not h then break end
            if target then
                local m = target.model
                local done = (not m.Parent)
                    or (not target.isConnie and aEIsMonsterChasingMe(m))
                    or (tick() - tStart >= 10)
                if done then
                    visited[m] = true; target = nil
                elseif tick() - ae.tpCooldown >= aeTpCd then
                    ae.tpCooldown = tick()
                    aETeleportAboveMonster(h, target)
                end
            end
            if not target then
                local cs = aEGetCandidates()
                local best, bd = nil, math.huge
                for _, e in ipairs(cs) do
                    if e.isConnie and not visited[e.model] and e.prim and e.prim.Parent then
                        local isolated = true
                        for _, o in ipairs(cs) do
                            if o ~= e and o.prim and o.prim.Parent
                               and (o.prim.Position - e.prim.Position).Magnitude <= aeConnieAwayDist then
                                isolated = false; break
                            end
                        end
                        if isolated then best = e; break end
                    end
                end
                if not best then
                    for _, e in ipairs(cs) do
                        if visited[e.model] or not e.model.Parent then continue end
                        if not e.isConnie and aEIsMonsterChasingMe(e.model) then
                            visited[e.model] = true; continue
                        end
                        local d = (h.Position - e.prim.Position).Magnitude
                        if d < bd then bd = d; best = e end
                    end
                end
                if not best then break end
                target = best; tStart = tick()
                if best.isConnie and not met[best.model] then met[best.model] = true; metCount = metCount + 1 end
                ae.tpCooldown = tick()
                S.encounterActive = true
                aETeleportAboveMonster(h, best)
            end
        end
        pcall(scanMet)
        aEDestroyPlatform()
        S.encounterActive = false
        ae.manual    = false
        aeManualBusy = false
        local ch2 = plr.Character
        local h2  = ch2 and ch2:FindFirstChild("HumanoidRootPart")
        if h2 then
            WaitForSafeHideRelease()
            h2.CFrame = origCF
        end
        if metCount > 0 and _G.YattaNotify then
            _G.YattaNotify("Encountered " .. metCount .. (metCount == 1 and " twisted." or " twisteds."),
                false, Color3.fromRGB(120, 255, 140))
        end
    end)
end
local aeDangerNames = { GoobMonster = true, ScrapsMonster = true, GigiMonster = true }
function aEDangerNear(hrp)
    local cr = workspace:FindFirstChild("CurrentRoom")
