        ae.cachedCands   = aEGetCandidates(true)
        for model in pairs(ae.visited) do
            if not model.Parent then ae.visited[model] = nil end
        end
        for _, entry in ipairs(ae.cachedCands) do
            if not ae.visited[entry.model]
               and not entry.isConnie
               and aEIsMonsterChasingMe(entry.model) then
                ae.visited[entry.model] = true
            end
        end
    end
    if not ae.allDone and (S.encounterActive or ae.currentTarget) then
        local dm = aEDangerNear(hrp)
        if dm then ae.dangerHoldUntil = now + 3 end
        if dm or (ae.dangerHoldUntil and now < ae.dangerHoldUntil) then
            ae.currentTarget   = nil
            ae.targetStartTime = nil
            S.encounterActive  = true
            local dtF = now - (ae.fleeT or now)
            ae.fleeT = now
            ae.fleeAccum = (ae.fleeAccum or 0) + dtF
            local okW, inElev = pcall(aEWaitInFakeElev, hrp)
            if not (okW and inElev) then
                if S.safeHide and S.safeHideEnter then
                    pcall(S.safeHideEnter, hrp, 3, 15, "seen")
                elseif not S.pathfindMode then
                    local hbase = R.fb()
                    if hbase and not R.ibb(hbase, hrp.Position) then
                        pcall(TeleportToBaseWithRetry, hrp, hbase)
                    end
                end
            end
            continue
        end
        ae.fleeT = nil
    end
    local candidates = ae.cachedCands
    if not candidates then continue end
    local skipToPickNext = false
    if ae.currentTarget then
        local entry = ae.currentTarget
        local model = entry.model
        if not model.Parent then
            ae.visited[model] = true
            ae.currentTarget  = nil
            ae.targetStartTime = nil
            S.encounterActive = false
            skipToPickNext    = true
        end
        if not skipToPickNext and ae.targetStartTime and (now - ae.targetStartTime) >= 10 then
            ae.visited[model]   = true
            ae.currentTarget    = nil
            ae.targetStartTime  = nil
            S.encounterActive   = false
            skipToPickNext      = true
        end
        if not skipToPickNext and entry.isConnie then
            S.encounterActive = true
            if now - ae.tpCooldown >= aeTpCd then
                ae.tpCooldown = now
                aETeleportAboveMonster(hrp, entry)
            end
            if not ae.visited[model] then
                ae.visited[model] = true
            end
        elseif not skipToPickNext then
            if aEIsMonsterChasingMe(model) then
                ae.visited[model] = true
                ae.currentTarget  = nil
                ae.targetStartTime = nil
                S.encounterActive = false
                skipToPickNext    = true
            else
                S.encounterActive = true
                if now - ae.tpCooldown >= aeTpCd then
                    ae.tpCooldown = now
                    aETeleportAboveMonster(hrp, entry)
                end
            end
        end
        if not skipToPickNext then
            continue
        end
    end
    if ae.allDone then
        S.encounterActive = false
        continue
    end
    local bestEntry, bestDist = nil, math.huge
    for _, entry in ipairs(candidates) do
        if entry.isConnie and entry.model.Parent and not ae.visited[entry.model]
           and entry.prim and entry.prim.Parent then
            local isolated = true
            for _, other in ipairs(candidates) do
                if other ~= entry and other.model.Parent and other.prim and other.prim.Parent
                   and (other.prim.Position - entry.prim.Position).Magnitude <= aeConnieAwayDist then
                    isolated = false; break
                end
            end
            if isolated then bestEntry = entry; break end
        end
    end
    for _, entry in ipairs(candidates) do
        if bestEntry then break end
        local model = entry.model
        if not model.Parent then continue end
        if ae.visited[model] then continue end
        if not entry.isConnie and aEIsMonsterChasingMe(model) then
            ae.visited[model] = true
            continue
        end
        local d = (hrp.Position - entry.prim.Position).Magnitude
        if d < bestDist then
            bestDist  = d
            bestEntry = entry
        end
    end
    if not bestEntry then
        aEDestroyPlatform()
        S.encounterActive = false
        if S.aeGourdyWaiting then
            ae.gourdyInvolved = true
            if hrp and hrp.Parent then
                S.encounterActive = true
                local okW, inElev = pcall(aEWaitInFakeElev, hrp)
                if not (okW and inElev) then
                    S.encounterActive = false
                    if S.safeHide then
                        pcall(S.safeHideEnter, hrp, 3, 15, "seen")
                    elseif not S.pathfindMode then
                        local hbase = R.fb()
                        if hbase and not R.ibb(hbase, hrp.Position) then
                            pcall(TeleportToBaseWithRetry, hrp, hbase)
                        end
                    end
                end
            end
            continue
        end
        aEFinishHide()
        ae.allDone        = true
        continue
    end
    if now - ae.tpCooldown >= aeTpCd then
        ae.tpCooldown      = now
        ae.currentTarget   = bestEntry
        ae.targetStartTime = now
        S.encounterActive  = true
        aETeleportAboveMonster(hrp, bestEntry)
    end
end
end)
regSpawn(function()
    local PathSvc = game:GetService("PathfindingService")
    local cfg = {
        hideTrigger  = 55,
        clearDist    = 80,
        clearHold    = 2.5,
        maxColliders = 400,
        maxPathTests = 6,
        commitTime   = 1.5,
        repathEvery  = 3.0,
        dangerCost   = 120,
        dangerSize   = 56,
        lookAhead    = 0.8,
        keepDist     = 45,
        cornerTeleport = true,
        cornerDist   = 9,
        sightDist    = 45,
        dodgeRange   = 22,
        dodgeWidth   = 9,
        dodgeSafe    = 12,
        itemClear    = 40,
        routeClear   = 22,
        routeAbort   = 16,
        specialRange = 45,
        specialClear = 70,
    }
    local weak = { __mode = "k" }
    local PF = {
        active = false, state = "idle",
        colls = {}, collT = 0,
        spot = nil, wps = nil, idx = 1, pathT = 0, commitUntil = 0,
        picking = false, pending = nil, lastPick = 0,
        arrived = false, safeSince = nil, lastStop = 0,
        lastMove = 0, lastMoveIdx = nil,
        stuckPos = nil, stuckT = 0, stuckN = 0,
        tl = nil, dodging = false, lastDodge = 0, dodgeSide = 1, dodgeUntil = 0,
        badParts = setmetatable({}, weak),
        badItems = setmetatable({}, weak),
        badGens  = setmetatable({}, weak),
    }
    _G.yattaPF = PF
    local spotCache = setmetatable({}, weak)

    local gParams = RaycastParams.new()
    gParams.FilterType = Enum.RaycastFilterType.Exclude
    gParams.RespectCanCollide = true
    local occParams = RaycastParams.new()
    occParams.FilterType = Enum.RaycastFilterType.Include
    occParams.RespectCanCollide = false

    local function getChar()
        local ch = plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if ch and hum and hrp and hum.Health > 0 then return ch, hum, hrp end
        return nil, nil, nil
    end

    local velTrack = setmetatable({}, weak)
    local function trackVel(lp, pos, now)
        local rec = velTrack[lp]
        if not rec then
            velTrack[lp] = { pos = pos, t = now, v = Vector3.new(0, 0, 0) }
            return Vector3.new(0, 0, 0)
        end
        local dt = now - rec.t
        if dt < 0.04 then return rec.v end
        local raw = (pos - rec.pos) / dt
        raw = Vector3.new(raw.X, 0, raw.Z)
        if raw.Magnitude > 70 then raw = Vector3.new(0, 0, 0) end
        local v = rec.v:Lerp(raw, 0.5)
        velTrack[lp] = { pos = pos, t = now, v = v }
        return v
    end

    local function threats()
        local out = {}
        local info = {}
        local now = tick()
        local mon = Cache.monsterPositions
        if not mon then PF.nReal = 0; PF.thrInfo = info; return out end
        local ahead = {}
        for i = 1, #mon do
            local e = mon[i]
            if e.farmEligible then
                local lp = e.livePart
                local live = lp and lp.Parent
                local pos = live and lp.Position or e.pos
                out[#out + 1] = pos
                local fv = Vector3.new(0, 0, 0)
                if live then
                    local v = lp.AssemblyLinearVelocity
                    fv = Vector3.new(v.X, 0, v.Z)
                    local tv = trackVel(lp, pos, now)
                    if tv.Magnitude > fv.Magnitude then fv = tv end
                    if fv.Magnitude > 6 then ahead[#ahead + 1] = pos + fv * cfg.lookAhead end
                end
                info[#info + 1] = { pos = pos, vel = fv, model = e.model }
            end
        end
        local ten = Cache.tendrilPositions
        if ten then
            local added = 0
            for i = 1, #ten do
                local te = ten[i]
                if te.pos and (not te.obj or te.obj.Parent) then
                    out[#out + 1] = te.pos
                    info[#info + 1] = { pos = te.pos, vel = Vector3.new(0, 0, 0) }
                    added = added + 1
                    if added >= 30 then break end
                end
            end
        end
        local rpl = S.rollingPumpkins()
        for i = 1, #rpl do
            local e = rpl[i]
            out[#out + 1] = e.pos
            info[#info + 1] = { pos = e.pos, vel = e.vel }
            if e.vel.Magnitude > 6 then ahead[#ahead + 1] = e.pos + e.vel * cfg.lookAhead end
        end
        PF.nReal = #out
        PF.thrInfo = info
        for i = 1, #ahead do out[#out + 1] = ahead[i] end
        return out
    end

    local function twistedSeesMe(model)
        if not (model and model.Parent) then return false end
        if model:GetAttribute("LostInterest") == true then return false end
        if model:GetAttribute("Chasing") == true then
            local cv = model:FindFirstChild("ChasingValue")
            if cv and cv:IsA("ObjectValue") and cv.Value ~= nil then
                local v = cv.Value
                return v == plr or v == plr.Character or v.Name == plr.Name
            end
            return true
        end
        return model:GetAttribute("Alerted") == true
    end
    local function anySeesMe()
        local _, _, myHrp = getChar()
        if myHrp and S.pumpkinNear(myHrp.Position, 30) then return true end
        local mon = Cache.monsterPositions
        if not mon then return false end
        for i = 1, #mon do
            local e = mon[i]
            if e.farmEligible and e.model and twistedSeesMe(e.model) then return true end
        end
        return false
    end

    local SPECIAL = { ScrapsMonster = true, GoobMonster = true, GigiMonster = true }
    local specialHold, specialSeen = false, 0
    local function specialEncounter(hrpPos)
        local mon = Cache.monsterPositions
        if not mon then return false end
        local now = tick()
        local hit, nearD = false, math.huge
        for i = 1, #mon do
            local e = mon[i]
            local m = e.model
            if m and m.Parent and SPECIAL[m.Name] then
                local lp = e.livePart
                local pos = (lp and lp.Parent) and lp.Position or e.pos
                local d = (pos - hrpPos).Magnitude
                if d < nearD then nearD = d end
                if d <= cfg.specialRange or twistedSeesMe(m) or m:GetAttribute("Attacking") == true then
                    hit = true
                end
            end
        end
        if hit then
            specialSeen = now
            if not specialHold then specialHold = true; PF.specialNew = true end
            return true
        end
        if specialHold then
            if nearD > cfg.specialClear and now - specialSeen > 2 then
                specialHold = false
            else
                return true
            end
        end
        return false
    end

    local function nearest(pos, list)
        local bp, bd = nil, math.huge
        for i = 1, #list do
            local d = (list[i] - pos).Magnitude
            if d < bd then bd = d; bp = list[i] end
        end
        return bp, bd
    end

    local function coverMode()
        return S.saferPathfindHide == true or S.floorStopActive == true
    end
    local thrCache, thrT = false, 0
    local function threatened()
        if S.forceHideActive or S.floorStopActive then return true end
        if tick() - thrT < 0.15 then return thrCache end
        thrT = tick()
        thrCache = false
        local _, _, hrp = getChar()
        if not hrp then return false end
        if specialEncounter(hrp.Position) then thrCache = true; return true end
        if S.pumpkinThreat(hrp.Position, 45) then thrCache = true; return true end
        local okD, dg = pcall(GetDangerState)
        if okD and dg then thrCache = true; return true end
        local okP, pa = pcall(IsPanicActive)
        if okP and pa then thrCache = true; return true end
        if anySeesMe() then thrCache = true; return true end
        local _, d = nearest(hrp.Position, threats())
        if d < 14 then thrCache = true end
        return thrCache
    end

    local function abortFn()
        if not (S.pathfindMode and S.autoEnabled) then return true end
        if PF.giveUpUntil and tick() < PF.giveUpUntil then return true end
        return threatened()
    end

    local function isElevatorish(inst)
        local cur = inst.Parent
        while cur and cur ~= workspace do
            if string.find(string.lower(cur.Name), "elevator", 1, true) then return true end
            cur = cur.Parent
        end
        return false
    end

    local COVER_NAMES = { noclip = true, noclip_collider = true, inviswall = true }
    local function isGenOrGigi(d)
        local cur = d.Parent
        while cur and cur ~= workspace do
            local l = string.lower(cur.Name)
            if l == "generator" or string.find(l, "dualgen", 1, true) or string.find(l, "trickortreatgen", 1, true)
               or string.find(l, "generator", 1, true) or string.find(l, "gigi", 1, true)
               or string.find(l, "claw", 1, true) then
                return true
            end
            cur = cur.Parent
        end
        return false
    end
    local function isCoverPart(d)
        if not d:IsA("BasePart") then return false end
        if not COVER_NAMES[string.lower(d.Name)] then return false end
        return not isGenOrGigi(d)
    end

    local function refreshColliders()
        local now = tick()
        if now - PF.collT < 20 then return PF.colls end
        PF.collT = now
        local list, groups, groupOf = {}, {}, {}
        local seen = 0
        local room = workspace:FindFirstChild("CurrentRoom")
        if room then
            for _, d in ipairs(room:GetDescendants()) do
                seen = seen + 1
                if seen % 600 == 0 then task.wait() end
                if isCoverPart(d) and not isElevatorish(d) and not d:FindFirstAncestor("Monsters") then
                    local g = d.Parent
                    list[#list + 1] = d
                    groupOf[d] = g
                    local gl = groups[g]
                    if not gl then gl = {}; groups[g] = gl end
                    gl[#gl + 1] = d
                end
            end
        end
        PF.colls = list
        PF.groups = groups
        PF.groupOf = groupOf
        return list
    end

    local function buildExclude()
        local ex = {}
        local ch = plr.Character
        if ch then ex[#ex + 1] = ch end
        if R.vf then ex[#ex + 1] = R.vf end
        local room = workspace:FindFirstChild("CurrentRoom")
        if room then
            for _, rm in ipairs(room:GetChildren()) do
                local mf = rm:FindFirstChild("Monsters")
                if mf then ex[#ex + 1] = mf end
            end
        end
        gParams.FilterDescendantsInstances = ex
    end

    local function groundAt(pos)
        local hit = workspace:Raycast(pos + Vector3.new(0, 4, 0), Vector3.new(0, -30, 0), gParams)
        return hit and hit.Position or nil
    end

    local function insideCover(pt, grp)
        if not grp then return false end
        for _, q in ipairs(grp) do
            if q.Parent then
                local lp = q.CFrame:PointToObjectSpace(pt)
                local h = q.Size * 0.5
                if math.abs(lp.X) < h.X + 1.5 and math.abs(lp.Y) < h.Y + 3
                   and math.abs(lp.Z) < h.Z + 1.5 then
                    return true
                end
            end
        end
        return false
    end

    local function spotsFor(part)
        local cf, sz = part.CFrame, part.Size
        local grp = nil
        if PF.groupOf and PF.groups then
            local g = PF.groupOf[part]
            if g then grp = PF.groups[g] end
        end
        local out = {}
        local dirs = { { cf.RightVector, sz.X / 2 }, { cf.LookVector, sz.Z / 2 } }
        for _, dd in ipairs(dirs) do
            local ax = Vector3.new(dd[1].X, 0, dd[1].Z)
            if ax.Magnitude > 0.5 then
                ax = ax.Unit
                for _, sgn in ipairs({ 1, -1 }) do
                    local p = part.Position + ax * (sgn * (dd[2] + 3.5))
                    local g = groundAt(p)
                    if g then
                        local sp = g + Vector3.new(0, 0.5, 0)
                        out[#out + 1] = sp
                    end
                end
            end
        end
        return out
    end

    local dzFolder = Instance.new("Folder")
    dzFolder.Name = "YattaDangerZones"
    dzFolder.Parent = workspace
    local dzPool, dzT = {}, 0
    local function dzGet(i)
        local zp = dzPool[i]
        if zp and zp.Parent then return zp end
        zp = Instance.new("Part")
        zp.Name         = "Danger"
        zp.Anchored     = true
        zp.CanCollide   = false
        zp.CanTouch     = false
        zp.CastShadow   = false
        zp.Transparency = 1
        zp.Size         = Vector3.new(cfg.dangerSize, 14, cfg.dangerSize)
        zp.Position     = Vector3.new(0, -5000, 0)
        local m = Instance.new("PathfindingModifier")
        m.Label  = "Danger"
        m.Parent = zp
        zp.Parent = dzFolder
        dzPool[i] = zp
        return zp
    end
    local function updateDanger(tl)
        local now = tick()
        if now - dzT < 0.6 then return end
        dzT = now
        local n = math.min(PF.nReal or #tl, 12)
        for i = 1, n do
            local zp = dzGet(i)
            if (zp.Position - tl[i]).Magnitude > 8 then zp.Position = tl[i] end
        end
        for i = n + 1, #dzPool do
            local zp = dzPool[i]
            if zp and zp.Parent and zp.Position.Y > -4000 then
                zp.Position = Vector3.new(0, -5000, 0)
            end
        end
    end
    local function clearDanger()
        for _, zp in ipairs(dzPool) do
            if zp and zp.Parent then zp.Position = Vector3.new(0, -5000, 0) end
        end
    end

    local function setZoneSize(w)
        for _, zp in ipairs(dzPool) do
            if zp and zp.Parent and zp.Position.Y > -4000 then zp.Size = Vector3.new(w, 14, w) end
        end
    end

    local function computeRaw(fromPos, toPos)
        local costs = { Danger = cfg.dangerCost, Cocoa = math.huge }
        for _ = 1, 4 do
            local path = PathSvc:CreatePath({
                AgentRadius = 2.2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 5,
                Costs = costs,
            })
            local ok = pcall(function() path:ComputeAsync(fromPos, toPos) end)
            if not ok or path.Status ~= Enum.PathStatus.Success then return nil end
            local wps = path:GetWaypoints()
            if #wps < 2 then return nil end
            local badLabel = nil
            for i = 2, #wps do
                if wps[i].Action == Enum.PathWaypointAction.Custom then
                    badLabel = wps[i].Label
                    break
                end
            end
            if badLabel == nil then return wps end
            if badLabel == "" or costs[badLabel] == math.huge then return nil end
            costs[badLabel] = math.huge
        end
        return nil
    end

    local function computePath(fromPos, toPos, noExpose)
        local wps = computeRaw(fromPos, toPos)
        if (not noExpose) and wps and PF.exposed and PF.exposed(wps) then
            setZoneSize(cfg.sightDist * 2)
            task.wait()
            local alt = computeRaw(fromPos, toPos)
            setZoneSize(cfg.dangerSize)
            if alt and not PF.exposed(alt) then return alt end
        end
        return wps
    end

    local function pathSafe(wps, tl, minD)
        if #tl == 0 then return true end
        minD = minD or 12
        for i = 2, #wps do
            local _, d = nearest(wps[i].Position, tl)
            if d < minD then return false end
        end
        return true
    end

    local function clip(p, d, hh, t0, t1)
        if d > -1e-6 and d < 1e-6 then
            if p < -hh or p > hh then return nil end
            return t0, t1
        end
        local ta, tb = (-hh - p) / d, (hh - p) / d
        if ta > tb then ta, tb = tb, ta end
        if ta > t0 then t0 = ta end
        if tb < t1 then t1 = tb end
        if t0 > t1 then return nil end
        return t0, t1
    end

    local function segHits(part, a, b)
        local cf = part.CFrame
        local la, lb = cf:PointToObjectSpace(a), cf:PointToObjectSpace(b)
        local sz = part.Size
        local t0, t1 = clip(la.X, lb.X - la.X, sz.X * 0.5, 0, 1)
        if not t0 then return false end
        t0, t1 = clip(la.Y, lb.Y - la.Y, sz.Y * 0.5, t0, t1)
        if not t0 then return false end
        t0, t1 = clip(la.Z, lb.Z - la.Z, sz.Z * 0.5, t0, t1)
        if not t0 then return false end
        return t0 > 0.001
    end

    local function blockedBy(colls, a, b)
        local ab = b - a
        local len2 = ab:Dot(ab)
        if len2 < 1 then return false end
        for i = 1, #colls do
            local q = colls[i]
            if q.Parent then
                local qp = q.Position
                local t = math.clamp((qp - a):Dot(ab) / len2, 0, 1)
                if (qp - (a + ab * t)).Magnitude <= q.Size.Magnitude * 0.5 + 0.5 then
                    if segHits(q, a, b) then return true end
                end
            end
        end
        return false
    end

    local sightParams = RaycastParams.new()
    sightParams.FilterType        = Enum.RaycastFilterType.Exclude
    sightParams.RespectCanCollide = true
    PF.exposed = function(wps)
        local tl, nReal = PF.tl, PF.nReal or 0
        if not tl or nReal == 0 then return false end
        local ex = { plr.Character }
        local cr = workspace:FindFirstChild("CurrentRoom")
        if cr then
            for _, room in ipairs(cr:GetChildren()) do
                local mf = room:FindFirstChild("Monsters")
                if mf then ex[#ex + 1] = mf end
            end
        end
        sightParams.FilterDescendantsInstances = ex
        local sd = cfg.sightDist
        for i = 2, #wps, 2 do
            local wp  = wps[i].Position
            local eye = wp + Vector3.new(0, 3, 0)
            for t = 1, nReal do
                local tp = tl[t]
                if (tp - wp).Magnitude < sd then
                    local from = tp + Vector3.new(0, 3, 0)
                    if not workspace:Raycast(from, eye - from, sightParams) then return true end
                end
            end
        end
        return false
    end

    local function pickHideSpot(myPos, tl)
        if coverMode() then
            local now = tick()
            buildExclude()
            local excl, tried = {}, 0
            for _ = 1, cfg.maxPathTests * 2 do
                local cp, part
                for _, r in ipairs({ 40, 80, 140 }) do
                    local okC, a, b = pcall(S.shPickCover, myPos, r, false, excl)
                    if okC and a then cp, part = a, b; break end
                    okC, a, b = pcall(S.shPickCover, myPos, r, true, excl)
                    if okC and a then cp, part = a, b; break end
                end
                if not cp then break end
                excl[part] = true
                local bad = PF.badParts[part]
                if not (bad and bad > now) then
                    local spots = spotCache[part]
                    if not spots then spots = spotsFor(part); spotCache[part] = spots end
                    table.sort(spots, function(a, b) return (a - myPos).Magnitude < (b - myPos).Magnitude end)
                    for k = 1, math.min(#spots, 2) do
                        local ap = spots[k]
                        local farOk = true
                        if #tl > 0 then
                            local _, ndS = nearest(ap, tl)
                            farOk = ndS >= 9
                        end
                        if farOk then
                            tried = tried + 1
                            local wpsS = computePath(myPos, ap)
                            if wpsS and (#tl == 0 or pathSafe(wpsS, tl, 4)) then
                                return { pos = ap, part = part, inside = Vector3.new(cp.X, ap.Y, cp.Z), wps = wpsS, t = tick() }
                            end
                        end
                    end
                    if tried >= cfg.maxPathTests * 2 then break end
                end
            end
            return nil
        end

        local colls = refreshColliders()
        if #colls == 0 then return nil end
        local pool = {}
        local now = tick()
        for _, c in ipairs(colls) do
            local bad = PF.badParts[c]
            if c.Parent and not (bad and bad > now) then
                local d = (c.Position - myPos).Magnitude
                if d <= 500 then pool[#pool + 1] = { part = c, d = d } end
            end
        end
        table.sort(pool, function(a, b) return a.d < b.d end)
        buildExclude()
        local cands, fresh = {}, 0
        for i = 1, math.min(#pool, cfg.maxColliders) do
            local part = pool[i].part
            local spots = spotCache[part]
            if not spots then
                spots = spotsFor(part)
                spotCache[part] = spots
                fresh = fresh + 1
                if fresh % 10 == 0 then task.wait() end
            end
            for _, sp in ipairs(spots) do
                cands[#cands + 1] = { pos = sp, part = part, inside = Vector3.new(part.Position.X, sp.Y, part.Position.Z) }
            end
        end
        if #cands == 0 then return nil end

        local function routeLen(wps)
            local len = 0
            for k = 2, #wps do len = len + (wps[k].Position - wps[k - 1].Position).Magnitude end
            return len
        end

        if #tl == 0 then
            table.sort(cands, function(a, b)
                return (a.pos - myPos).Magnitude < (b.pos - myPos).Magnitude
            end)
            for i = 1, math.min(#cands, cfg.maxPathTests) do
                local wps = computePath(myPos, cands[i].pos)
                if wps then
                    cands[i].wps = wps
                    cands[i].t = tick()
                    return cands[i]
                end
            end
            return nil
        end

        local strict, loose, desperate = {}, {}, {}
        for _, c in ipairs(cands) do
            local _, nd = nearest(c.pos, tl)
            local myD = (c.pos - myPos).Magnitude
            c.nd, c.myD = nd, myD
            c.base = math.min(nd, 400) + (nd - myD) * 0.15 - myD * 0.05
            if nd >= cfg.keepDist and nd > myD then
                strict[#strict + 1] = c
            elseif nd >= cfg.keepDist * 0.6 then
                loose[#loose + 1] = c
            elseif nd >= 14 then
                desperate[#desperate + 1] = c
            end
        end
        local list = strict
        if #list < 4 then
            for _, c in ipairs(loose) do list[#list + 1] = c end
        end
        if #list < 4 then
            for _, c in ipairs(desperate) do list[#list + 1] = c end
        end
        if #list == 0 then return nil end
        table.sort(list, function(a, b) return a.base > b.base end)

        local top = math.min(#list, 40)
        for i = 1, top do
            local c = list[i]
            local near = {}
            for _, tp in ipairs(tl) do
                near[#near + 1] = { p = tp, d = (tp - c.pos).Magnitude }
            end
            table.sort(near, function(a, b) return a.d < b.d end)
            local tot = math.min(3, #near)
            local cnt = 0
            for k = 1, tot do
                local o   = near[k].p + Vector3.new(0, 3, 0)
                local tgt = c.pos + Vector3.new(0, 2.5, 0)
                if blockedBy(colls, o, tgt) then cnt = cnt + 1 end
            end
            c.occ = cnt
            c.score = c.base + cnt * 40 + ((cnt == tot) and 60 or 0)
            if i % 5 == 0 then task.wait() end
        end
        local ranked = {}
        for i = 1, top do ranked[#ranked + 1] = list[i] end
        table.sort(ranked, function(a, b) return a.score > b.score end)

        local best, bestFinal = nil, -math.huge
        local tested = 0
        for _, minD in ipairs({ 12, 7, 4 }) do
            local limit = (minD == 12) and cfg.maxPathTests or (cfg.maxPathTests * 2)
            for i = 1, math.min(#ranked, limit) do
                local c = ranked[i]
                if c.tryWps == nil then
                    c.tryWps = computePath(myPos, c.pos) or false
                    tested = tested + 1
                    if tested % 3 == 0 then task.wait() end
                end
                local wps = c.tryWps
                if wps and pathSafe(wps, tl, minD) then
                    local final = c.score - routeLen(wps) * 0.05
                    if final > bestFinal then
                        bestFinal = final
                        best = c
                        best.wps = wps
                    end
                end
            end
            if best then break end
        end
        if best then best.t = tick() end
        return best
    end

    local function startPick(hrp, tl)
        if PF.picking then return end
        PF.picking = true
        PF.lastPick = tick()
        local myPos = hrp.Position
        task.spawn(function()
            local ok, res = pcall(pickHideSpot, myPos, tl)
            PF.picking = false
            if ok and res then
                PF.pending = res
                PF.pickNil = false
            else
                PF.pickNil = true
            end
        end)
    end

    local function stopMove(hum, hrp)
        if hum and hrp then pcall(function() hum:MoveTo(hrp.Position) end) end
    end

    local function elevPos()
        local okE, e1 = pcall(FindFakeElevatorBasePart)
        if okE and e1 and e1.Parent then return e1.Position + Vector3.new(0, 3, 0) end
        local okB, b = pcall(R.fb)
        if okB and b and b.Parent then return b.Position + Vector3.new(0, 3, 0) end
        return nil
    end

    local function nearAny(pos, r)
        local tl = PF.tl
        if not tl then return false end
        local r2 = r * r
        for i = 1, #tl do
            local d = tl[i] - pos
            if d.X * d.X + d.Z * d.Z <= r2 and math.abs(d.Y) < 40 then return true end
        end
        return false
    end

    local function safeRoute(fromPos, toPos)
        local wps = computePath(fromPos, toPos)
        if not wps then return nil end
        local tl = PF.tl
        if not tl or #tl == 0 or pathSafe(wps, tl, cfg.routeClear) then return wps end
        setZoneSize(cfg.routeClear * 2 + 16)
        task.wait()
        local alt = computeRaw(fromPos, toPos)
        setZoneSize(cfg.dangerSize)
        if alt and pathSafe(alt, tl, cfg.routeClear) then return alt end
        return nil
    end

    local function follow(wps, hum, budget)
        local deadline = tick() + budget
        local lastP, lastPT = nil, tick()
        local lastRouteChk = 0
        for i = 2, #wps do
            local wp = wps[i]
            if wp.Action == Enum.PathWaypointAction.Jump then hum.Jump = true end
            hum:MoveTo(wp.Position)
            local t0 = tick()
            local reached = false
            while true do
                if tick() > deadline or abortFn() or (PF.valid and not PF.valid()) then return false end
                local _, h2, r2 = getChar()
                if not r2 then return false end
                if PF.watchRoute and tick() - lastRouteChk > 0.25 then
                    lastRouteChk = tick()
                    local tlw = PF.tl
                    if tlw and #tlw > 0 then
                        for j = i, math.min(#wps, i + 3) do
                            local _, dd = nearest(wps[j].Position, tlw)
                            if dd < cfg.routeAbort then PF.routeAbort = true; return false end
                        end
                    end
                end
                if not lastP or tick() - lastPT > 0.8 then
                    if lastP and (r2.Position - lastP).Magnitude < 0.8 then h2.Jump = true end
                    lastP, lastPT = r2.Position, tick()
                end
                local dx = wp.Position.X - r2.Position.X
                local dz = wp.Position.Z - r2.Position.Z
                local flat = math.sqrt(dx * dx + dz * dz)
                if flat < 3.2 and math.abs(wp.Position.Y - r2.Position.Y) < 6 then
                    reached = true; break
                end
                if tick() - t0 > 2.5 then break end
                if h2.MoveDirection.Magnitude < 0.05 and tick() - t0 > 0.6 then
                    h2:MoveTo(wp.Position)
                end
                task.wait(0.05)
            end
            if not reached then return false end
        end
        return true
    end

    local function walkTo(hum, pos, stopDist, budget)
        local t0 = tick()
        while tick() - t0 < budget do
            local _, h, hrp = getChar()
            if not hrp then return false end
            if abortFn() or (PF.valid and not PF.valid()) then return false end
            if (hrp.Position - pos).Magnitude <= stopDist then return true end
            local wps
            if PF.watchRoute then
                wps = safeRoute(hrp.Position, pos)
                if not wps then PF.routeAbort = true; return false end
            else
                wps = computePath(hrp.Position, pos)
            end
            if wps then
                if follow(wps, h, math.max(0.5, budget - (tick() - t0))) then return true end
                if PF.routeAbort then return false end
            else
                if (hrp.Position - pos).Magnitude > 30 then return false end
                h:MoveTo(pos)
                task.wait(0.2)
            end
        end
        return false
    end

    local function goElevator(hum, hrp)
        local target = elevPos()
        if not target then return end
        if (hrp.Position - target).Magnitude <= 5 then stopMove(hum, hrp); return end
        walkTo(hum, target, 4, 6)
    end

    local function clearHide()
        local oldSp = PF.spot
        if oldSp and oldSp.inside and oldSp.pos and (PF.arrived or PF.entering) then
            PF.leaveSpot = { pos = oldSp.pos, t = tick(), part = oldSp.part }
        end
        PF.spot = nil; PF.wps = nil; PF.pending = nil
        PF.arrived = false; PF.safeSince = nil; PF.entering = false
        PF.hideRes = nil
        PF.enterT0 = nil
        PF.stuckPos = nil; PF.stuckN = 0; PF.lastMoveIdx = nil
    end

    local function adoptSpot(c, hrp)
        local oldS = PF.spot
        if oldS and oldS.part and oldS.part ~= c.part then PF.badParts[oldS.part] = tick() + 8 end
        PF.spotT = tick()
        PF.spot = c
        PF.wps = c.wps
        local bi, bd = 1, math.huge
        for i = 1, #c.wps do
            local d = (c.wps[i].Position - hrp.Position).Magnitude
            if d < bd then bd = d; bi = i end
        end
        PF.idx = math.min(bi + 1, #c.wps)
        PF.pathT = tick()
        PF.commitUntil = tick() + cfg.commitTime
        PF.arrived = false; PF.entering = false
        PF.enterT0 = nil
        PF.stuckPos = nil; PF.stuckN = 0
        PF.lastMoveIdx = nil
    end

    local function issueMove(hum, pos, minGap)
        local now = tick()
        local lt = PF.lastCmdPos
        if lt and (lt - pos).Magnitude < (minGap or 1.5) and now - (PF.lastCmdT or 0) < 0.45 then return end
        PF.lastCmdPos = pos
        PF.lastCmdT = now
        hum:MoveTo(pos)
    end

    local exclT = 0
    local function ensureExclude()
        local now = tick()
        if now - exclT > 1.5 then exclT = now; buildExclude() end
    end

    local function floorAhead(pos, dir, reach)
        local groundY = pos.Y - 3
        local d = 3
        while true do
            if d > reach then d = reach end
            local ox, oz = pos.X + dir.X * d, pos.Z + dir.Z * d
            local hit = workspace:Raycast(Vector3.new(ox, pos.Y + 1, oz), Vector3.new(0, -14, 0), gParams)
            if not hit or hit.Position.Y < groundY - 3.5 then return false end
            if d >= reach then break end
            d = d + 3
        end
        return true
    end

    local function steer(hrp, target, forwardOnly)
        local info = PF.thrInfo
        if not info or #info == 0 then PF.dodgeDir = nil; return nil end
        local pos = hrp.Position
        local to = Vector3.new(target.X - pos.X, 0, target.Z - pos.Z)
        local dist = to.Magnitude
        if dist < 2 then return nil end
        local fwd = to.Unit
        local now = tick()
        local _, hum = getChar()
        local spd = math.max(16, (hum and hum.WalkSpeed) or 16)

        local M = {}
        local nx, nz, nd = 0, 0, math.huge
        for i = 1, #info do
            local th = info[i]
            local dx, dz = pos.X - th.pos.X, pos.Z - th.pos.Z
            local dm = math.sqrt(dx * dx + dz * dz)
            if dm < 90 then
                local vx, vz = th.vel.X, th.vel.Z
                if th.model and dm > 1 and twistedSeesMe(th.model) then
                    local sp = math.max(math.sqrt(vx * vx + vz * vz), 14)
                    vx, vz = dx / dm * sp, dz / dm * sp
                end
                M[#M + 1] = { x = th.pos.X, z = th.pos.Z, vx = vx, vz = vz }
                if dm < nd then nd = dm; nx = -dx; nz = -dz end
            end
        end
        if #M == 0 then PF.dodgeDir = nil; return nil end
        local nl = math.sqrt(nx * nx + nz * nz)
        if nl > 0.01 then nx, nz = nx / nl, nz / nl end

        local function sep(dir, reach)
            local best = math.huge
            for k = 1, 8 do
                local t = k * 0.2
                local tr = math.min(spd * t, reach)
                local qx, qz = pos.X + dir.X * tr, pos.Z + dir.Z * tr
                for i = 1, #M do
                    local m = M[i]
                    local ddx = m.x + m.vx * t - qx
                    local ddz = m.z + m.vz * t - qz
                    local d2 = ddx * ddx + ddz * ddz
                    if d2 < best then best = d2 end
                end
            end
            return math.sqrt(best)
        end

        local sepStraight = sep(fwd, math.min(dist, spd * 1.6))
        local conflict = sepStraight < cfg.dodgeSafe and (sepStraight < nd - 1 or sepStraight < 6)
        if conflict then PF.dodgeLastConflict = now end
        local holding = PF.dodgeDir ~= nil and (now - (PF.dodgeLastConflict or 0)) < 0.9
        if not conflict and not holding then PF.dodgeDir = nil; return nil end

        if PF.dodgeDir and forwardOnly and PF.dodgeDir:Dot(fwd) < -0.1 then
            PF.dodgeDir = nil
        end
        if PF.dodgeDir and now < (PF.dodgeUntil or 0) then
            if sep(PF.dodgeDir, spd * 1.6) >= cfg.dodgeSafe * 0.75
               and floorAhead(pos, PF.dodgeDir, 14) then
                return pos + PF.dodgeDir * 14
            end
        end

        ensureExclude()
        local origin = pos + Vector3.new(0, 2, 0)
        local bestDir, bestScore = nil, -math.huge
        local kMax = forwardOnly and 4 or 8
        for k = -kMax, kMax do
            local ang = k * (math.pi / 9)
            local ca, sa = math.cos(ang), math.sin(ang)
            local dir = Vector3.new(fwd.X * ca - fwd.Z * sa, 0, fwd.X * sa + fwd.Z * ca)
            local hit = workspace:Raycast(origin, dir * 22, gParams)
            local clear = hit and hit.Distance or 22
            if clear >= 6 then
                local reach = math.min(clear - 1.5, spd * 1.6)
                local sp = sep(dir, reach)
                local score = dir:Dot(fwd) * (forwardOnly and 30 or 14) + math.min(sp, 28) * 2.2
                if sp < 7 then score = score - (7 - sp) * 14 end
                local dn = dir.X * nx + dir.Z * nz
                if dn > 0.5 then score = score - (dn - 0.5) * 40 end
                score = score + math.min(clear, 22) * 0.35
                if PF.dodgeDir then score = score + (dir:Dot(PF.dodgeDir) - 0.3) * 40 end
                if score > bestScore and floorAhead(pos, dir, 14) then
                    bestScore = score; bestDir = dir
                end
            end
        end
        if not bestDir then PF.dodgeDir = nil; return nil end
        PF.dodgeDir = bestDir
        PF.dodgeUntil = now + 1.4
        return pos + bestDir * 14
    end

    local function escapeHeading(hrp, tl, prev)
        buildExclude()
        local pos = hrp.Position
        local origin = pos + Vector3.new(0, 2, 0)
        local nTp = nearest(pos, tl)
        local bestDir, bestScore, bestClear, bestRoom = nil, -math.huge, 0, 0
        for k = 0, 15 do
            local ang = k * math.pi / 8
            local dir = Vector3.new(math.cos(ang), 0, math.sin(ang))
            local hit = workspace:Raycast(origin, dir * 30, gParams)
            local clear = hit and (hit.Position - origin).Magnitude or 30
            if clear >= 5 then
                local p1 = pos + dir * math.min(clear - 1.5, 30)
                local room = clear
                if clear < 30 then
                    local side = 0
                    for _, sgn in ipairs({ -1, 1 }) do
                        local d2 = Vector3.new(-dir.Z * sgn, 0, dir.X * sgn)
                        local o2 = p1 + Vector3.new(0, 2, 0)
                        local h2 = workspace:Raycast(o2, d2 * 20, gParams)
                        local c2 = h2 and (h2.Position - o2).Magnitude or 20
                        if c2 > side then side = c2 end
                    end
                    room = clear + side
                end
                local minD = math.huge
                for i = 1, #tl do
                    local dx, dz = tl[i].X - p1.X, tl[i].Z - p1.Z
                    local d = math.sqrt(dx * dx + dz * dz)
                    if d < minD then minD = d end
                end
                local toward = 0
                if nTp then
                    local v = Vector3.new(nTp.X - pos.X, 0, nTp.Z - pos.Z)
                    if v.Magnitude > 0.1 then toward = dir:Dot(v.Unit) end
                end
                local score = math.min(minD, 60) * 1.3 + math.min(room, 50) * 0.8 - toward * 25
                if prev then score = score + (dir:Dot(prev) - 0.2) * 45 end
                if score > bestScore then
                    bestScore, bestDir, bestClear, bestRoom = score, dir, clear, room
                end
            end
        end
        return bestDir, bestClear, bestRoom
    end

    local function flee(hum, hrp, tl)
        local now = tick()
        if now - PF.lastMove < 0.2 then return end
        PF.lastMove = now
        PF.lastMoveIdx = nil
        local pos = hrp.Position
        local tp, td = nearest(pos, tl)
        if tp and td < 80 then
            local prevDir = (PF.fleeDir and now - (PF.fleeDirT or 0) < 2.5) and PF.fleeDir or nil
            local dir = escapeHeading(hrp, tl, prevDir)
            local rx, rz, cnt = 0, 0, 0
            for i = 1, #tl do
                local dx, dz = pos.X - tl[i].X, pos.Z - tl[i].Z
                local d = math.sqrt(dx * dx + dz * dz)
                if d < 70 and d > 0.1 then
                    local w = 1 / (d * d)
                    rx = rx + dx / d * w; rz = rz + dz / d * w; cnt = cnt + 1
                end
            end
            local rep = Vector3.new(rx, 0, rz)
            if (not dir) and rep.Magnitude > 1e-6 then dir = rep.Unit end
            if (not dir) or (cnt >= 2 and rep.Magnitude < 1e-4) then
                local ep = elevPos()
                if ep then
                    local v = Vector3.new(ep.X - pos.X, 0, ep.Z - pos.Z)
                    if v.Magnitude > 1 then dir = v.Unit end
                end
                if not dir then
                    local away = pos - tp
                    away = Vector3.new(away.X, 0, away.Z)
                    if away.Magnitude < 0.1 then away = Vector3.new(1, 0, 0) end
                    dir = away.Unit
                end
            end
            if not PF.fleePos or now - (PF.fleeT or 0) > 1.0 then
                if PF.fleePos and (pos - PF.fleePos).Magnitude < 1.5 then
                    hum.Jump = true
                    dir = Vector3.new(-dir.Z, 0, dir.X)
                end
                PF.fleePos = pos
                PF.fleeT = now
            end
            PF.fleeDir, PF.fleeDirT = dir, now
            issueMove(hum, pos + dir * 20, 3)
        else
            PF.fleeDir = nil
            local ep = elevPos()
            if ep then issueMove(hum, ep, 2) end
        end
    end

    local function cornerCheck(hrp, tl)
        if not cfg.cornerTeleport then return false end
        local now = tick()
        if now < (PF.cornerCd or 0) then return false end
        local _, nD = nearest(hrp.Position, tl)
        if nD > cfg.cornerDist then PF.cornerSince = nil; return false end
        local dir, clear, room = escapeHeading(hrp, tl)
        local trapped = (not dir) or clear < 8 or room < 16
        if not trapped then PF.cornerSince = nil; return false end
        PF.cornerSince = PF.cornerSince or now
        if now - PF.cornerSince < 0.3 then return false end
        PF.cornerSince = nil
        PF.cornerCd = now + 8
        local base = R.fb()
        if not base or S.safeHide then return false end
        S.pfEmergency = true
        pcall(TeleportToBaseWithRetry, hrp, base)
        S.pfEmergency = false
        if _G.YattaNotify then _G.YattaNotify("Cornered - used the base teleport.", false) end
        PF.spot = nil; PF.wps = nil; PF.arrived = false
        return true
    end

    local function walkPath(hum, hrp, noDodge)
        local wps = PF.wps
        if not wps then return false end
        local n = #wps
        local pos = hrp.Position
        while PF.idx < n do
            local wp = wps[PF.idx]
            local dx = wp.Position.X - pos.X
            local dz = wp.Position.Z - pos.Z
            if dx * dx + dz * dz < 16 then
                PF.idx = PF.idx + 1
                if wps[PF.idx].Action == Enum.PathWaypointAction.Jump then hum.Jump = true end
            else
                break
            end
        end
        local fin = wps[n].Position
        local ex, ez = fin.X - pos.X, fin.Z - pos.Z
        if PF.idx >= n and ex * ex + ez * ez < 12 then return true end
        local now = tick()
        local panicking = (PF.state == "panic")
        if panicking and not noDodge then
            local guard = 0
            while PF.idx < n and PF.idx > 1 and guard < 4 do
                guard = guard + 1
                local a, b = wps[PF.idx - 1].Position, wps[PF.idx].Position
                local seg = Vector3.new(b.X - a.X, 0, b.Z - a.Z)
                local rel = Vector3.new(pos.X - b.X, 0, pos.Z - b.Z)
                if seg.Magnitude > 0.5 and rel:Dot(seg.Unit) > 0 then
                    ensureExclude()
                    local nb = wps[PF.idx + 1].Position
                    local o = pos + Vector3.new(0, 2, 0)
                    local d = Vector3.new(nb.X - pos.X, 0, nb.Z - pos.Z)
                    if d.Magnitude < 30 and not workspace:Raycast(o, d, gParams) then
                        PF.idx = PF.idx + 1
                    else
                        break
                    end
                else
                    break
                end
            end
        end
        local adj = nil
        if noDodge then PF.dodgeDir = nil else adj = steer(hrp, wps[PF.idx].Position, panicking) end
        if adj then
            PF.dodging = true
            if now - PF.lastDodge > 0.1 then
                PF.lastDodge = now
                issueMove(hum, adj, 3)
            end
            return false
        elseif PF.dodging then
            PF.dodging = false
            PF.lastMoveIdx = nil
        end
        if PF.lastMoveIdx ~= PF.idx or now - PF.lastMove > 0.5 then
            PF.lastMoveIdx = PF.idx
            PF.lastMove = now
            issueMove(hum, wps[PF.idx].Position, 0.5)
        end
        return false
    end

    local EXIT_DIST = 16
    local function elevFrontPoint(pos)
        local cands = {}
        local okF, b1 = pcall(FindFakeElevatorBasePart)
        if okF and b1 and b1.Parent then cands[#cands + 1] = b1 end
        local okB, b2 = pcall(R.fb)
        if okB and b2 and b2.Parent then cands[#cands + 1] = b2 end
        local best, bd = nil, math.huge
        for _, b in ipairs(cands) do
            local d = Vector3.new(b.Position.X - pos.X, 0, b.Position.Z - pos.Z).Magnitude
            if d < bd then bd = d; best = b end
        end
        if not best then return nil end
        local look = best.CFrame.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude < 0.01 then return nil end
        flat = flat.Unit
        local lp = best.CFrame:PointToObjectSpace(pos)
        local halfX, halfZ = best.Size.X / 2, best.Size.Z / 2
        local inside = math.abs(lp.X) < halfX and math.abs(lp.Z) < halfZ and math.abs(lp.Y) < 8
        local fp = Vector3.new(best.Position.X + flat.X * (halfZ + 4), pos.Y, best.Position.Z + flat.Z * (halfZ + 4))
        return fp, inside
    end

    local function elevIsOut(pos)
        local fp, inside = elevFrontPoint(pos)
        return fp == nil or not inside
    end

    local function exitElevTick(hum, hrp)
        if not PF.exitUntil then return false end
        local now = tick()
        if now > PF.exitUntil then PF.exitUntil = nil; return false end
        local pos = hrp.Position
        local fp, inside = elevFrontPoint(pos)
        if not fp then PF.exitUntil = nil; return false end
        local dx, dz = fp.X - pos.X, fp.Z - pos.Z
        if dx * dx + dz * dz < 9 or not inside then
            PF.exitUntil = nil
            stopMove(hum, hrp)
            return true
        end
        if not PF.exitPos or now - (PF.exitT or 0) > 0.7 then
            if PF.exitPos and (pos - PF.exitPos).Magnitude < 0.8 then hum.Jump = true end
            PF.exitPos = pos
            PF.exitT = now
        end
        issueMove(hum, fp, 1)
        return true
    end

    local function hideTick(hum, hrp, tl)
        local now = tick()
        if PF.pending then
            local c = PF.pending
            PF.pending = nil
            if now - c.t < 3 and c.part and c.part.Parent then
                local old = PF.spot
                local keep = false
                if old and old.part and old.part.Parent then
                    if c.part == old.part then
                        keep = true
                    elseif #tl > 0 and (now - (PF.spotT or 0)) < (PF.arrived and 3.0 or 1.5) then
                        local _, dOld = nearest(old.pos, tl)
                        if dOld and dOld > (PF.arrived and 7 or 9) then keep = true end
                    end
                end
                if not keep then adoptSpot(c, hrp) end
            end
        end
        local spot = PF.spot
        if spot then
            if not (spot.part and spot.part.Parent) then
                PF.spot = nil; PF.wps = nil; spot = nil
            elseif #tl > 0 then
                local _, dS = nearest(spot.pos, tl)
                local toSpot = (spot.pos - hrp.Position).Magnitude
                if PF.arrived and now - (PF.seenT or 0) > 0.25 then
                    PF.seenT = now
                    local seen = false
                    local colls = PF.colls or {}
                    local me = hrp.Position + Vector3.new(0, 2.5, 0)
                    for _, tp in ipairs(tl) do
                        if (tp - hrp.Position).Magnitude < 70
                           and not blockedBy(colls, tp + Vector3.new(0, 3, 0), me) then
                            seen = true; break
                        end
                    end
                    PF.seenByTwisted = seen
                elseif not PF.arrived then
                    PF.seenByTwisted = false
                end
                local compromised
                if coverMode() then
                    compromised = (not PF.arrived) and (dS < 9 or (dS < toSpot * 0.6 and dS < 30))
                else
                    compromised = dS < cfg.keepDist * 0.5
                        or (now >= PF.commitUntil and dS < cfg.keepDist * 0.8)
                        or (dS < toSpot * 0.8 and dS < 60)
                        or (PF.arrived and PF.seenByTwisted)
                end
                if compromised and not PF.picking and now - PF.lastPick > 0.8 then
                    startPick(hrp, tl)
                end
                if compromised and PF.pickNil and not PF.picking then
                    PF.badParts[spot.part] = now + 4
                    PF.spot = nil; PF.wps = nil; PF.arrived = false
                    PF.stuckPos = nil; PF.lastMoveIdx = nil
                    spot = nil
                end
            end
        end
        if not spot then
            if not PF.picking and now - PF.lastPick > 0.6 then startPick(hrp, tl) end
            flee(hum, hrp, tl)
            return
        end
        local res = PF.hideRes
        if res then
            PF.hideRes = nil
            if res.spot == spot then
                if not res.w then
                    PF.badParts[spot.part] = now + 10
                    PF.spot = nil; PF.wps = nil
                    return
                elseif pathSafe(res.w, tl) or not PF.wps then
                    local bi, bd = 1, math.huge
                    for i = 1, #res.w do
                        local dx, dz = res.w[i].Position.X - hrp.Position.X, res.w[i].Position.Z - hrp.Position.Z
                        local d = dx * dx + dz * dz
                        if d < bd then bd = d; bi = i end
                    end
                    PF.wps = res.w
                    PF.idx = math.clamp(bi + 1, 2, #res.w)
                else
                    if not PF.picking and now - PF.lastPick > 0.6 then startPick(hrp, tl) end
                end
            end
        end
        if not PF.hideBusy and (not PF.wps or (not PF.arrived and now - PF.pathT > cfg.repathEvery)) then
            PF.hideBusy = true
            PF.pathT = now
            local fromPos, sp0 = hrp.Position, spot
            task.spawn(function()
                local okP, w = pcall(computePath, fromPos, sp0.pos)
                PF.hideBusy = false
                PF.hideRes = { w = okP and w or nil, spot = sp0 }
            end)
        end
        if not PF.wps and not PF.arrived then
            issueMove(hum, spot.pos, 2)
        end
        if not PF.arrived then
            if not PF.stuckPos or now - PF.stuckT > 1.2 then
                if PF.stuckPos and (hrp.Position - PF.stuckPos).Magnitude < 1.0 then
                    PF.stuckN = PF.stuckN + 1
                    hum.Jump = true
                    PF.pathT = 0
                    if PF.stuckN >= 3 then
                        PF.badParts[spot.part] = tick() + 10
                        PF.spot = nil; PF.stuckN = 0
                    end
                else
                    PF.stuckN = 0
                end
                PF.stuckPos = hrp.Position
                PF.stuckT = now
            end
        end
        if PF.wps and not PF.arrived and PF.entering and spot.inside then
            if coverMode() and S.safeHideEnter and not S.shActive and now - (PF.shTryT or 0) > 0.5 then
                PF.shTryT = now
                S.shByPathfind = true
                local okE, entered = pcall(S.safeHideEnter, hrp, 4, nil, "seen")
                if okE and entered then
                    PF.entering = false; PF.enterT0 = nil; PF.arrived = true
                    PF.hideLatchT = nil; PF.latchClearSince = nil
                    stopMove(hum, hrp)
                    return
                end
                S.shByPathfind = false
            end
            local dx, dz = spot.inside.X - hrp.Position.X, spot.inside.Z - hrp.Position.Z
            PF.enterT0 = PF.enterT0 or now
            local doneR = coverMode() and 2.25 or 4   
            if dx * dx + dz * dz < doneR or (coverMode() and now - PF.enterT0 > 4) then
                PF.entering = false
                PF.enterT0 = nil
                PF.arrived = true
                stopMove(hum, hrp)
            else
                issueMove(hum, spot.inside, 0.5)
            end
            return
        end
        if PF.wps and walkPath(hum, hrp, true) then
            if not PF.arrived then
                if spot.inside then
                    PF.entering = true
                else
                    PF.arrived = true
                    stopMove(hum, hrp)
                end
            end
        end
    end

    local function itemAlive(it, h)
        if not (it and it.Parent and h and h.Parent) then return false end
        return it:IsDescendantOf(workspace) and h:IsDescendantOf(workspace)
    end

    local function itemPrompt(it)
        for _, p in ipairs(it:GetDescendants()) do
            if p:IsA("ProximityPrompt") and p.Parent and p.Enabled ~= false then return p end
        end
        return nil
    end

    local function doItems(hum, hrp)
        PF.itemsWaiting = false
        if not S.pickupEnabled then return false end
        if IsPickupBlocked() then return false end
        local okI, items = pcall(R.gai)
        if not okI or not items or #items == 0 then return false end
        local cands = {}
        for _, it in ipairs(items) do
            local h = it:IsA("BasePart") and it or it:FindFirstChildWhichIsA("BasePart", true)
            local bad = PF.badItems[it]
            if itemAlive(it, h) and not (bad and bad > tick()) and itemPrompt(it) then
                cands[#cands + 1] = { it = it, h = h, d = (h.Position - hrp.Position).Magnitude }
            end
        end
        if #cands == 0 then return false end
        table.sort(cands, function(a, b)
            local pa, pb = a.it.Name == "Pumpkin", b.it.Name == "Pumpkin"
            if pa ~= pb then return pa end
            return a.d < b.d
        end)
        local best, bh, tried = nil, nil, 0
        for _, c in ipairs(cands) do
            if tried >= 4 then break end
            if not nearAny(c.h.Position, cfg.itemClear) then
                tried = tried + 1
                local wps = safeRoute(hrp.Position, c.h.Position)
                if wps then best, bh = c.it, c.h; break end
                PF.badItems[c.it] = tick() + 2.5
            end
        end
        if not best then
            PF.itemsWaiting = true
            PF.itemWaitSince = PF.itemWaitSince or tick()
            return false
        end
        PF.itemWaitSince = nil
        PF.state = "item"
        local lastChk, lastOk = tick(), true
        PF.valid = function()
            if not itemAlive(best, bh) then return false end
            if tick() - lastChk > 0.3 then
                lastChk = tick()
                lastOk = itemPrompt(best) ~= nil
            end
            return lastOk and not nearAny(bh.Position, cfg.itemClear)
        end
        PF.watchRoute = true; PF.routeAbort = false
        walkTo(hum, bh.Position, 3.5, 14)
        PF.watchRoute = false
        local aborted = PF.routeAbort
        PF.routeAbort = false
        PF.valid = nil
        local gone = not (itemAlive(best, bh) and itemPrompt(best) ~= nil)
        if gone then
            if best.Parent then PF.badItems[best] = tick() + 5 end
            return true
        end
        if aborted or nearAny(bh.Position, cfg.itemClear) then
            PF.badItems[best] = tick() + 3
            return true
        end
        local _, _, r2 = getChar()
        if r2 and (r2.Position - bh.Position).Magnitude <= 10 then
            local p = itemPrompt(best)
            if p then fireOnePrompt(p) end
        end
        if best.Parent then PF.badItems[best] = tick() + 15 end
        return true
    end

    local trickRetryAt = 0
    local function doTrick(hum, hrp)
        if not (S.autoTrickTreat and S.autoEnabled and S.trigOk("trick")) then return false end
        if tick() < trickRetryAt then return false end
        local A = _G.YattaAdditionals
        if not (A and A.findTot and A.totMark) then return false end
        if A.totUnsafe and A.totUnsafe() then return false end
        local pp, ground, att = A.findTot(function(e)
            return not IsCachedMonsterNearPosition(e.att.WorldPosition, K.monSkipR, false, true)
               and not nearAny(e.att.WorldPosition, cfg.itemClear)
        end)
        if not pp or not att then return false end
        local pos = att.WorldPosition
        if not safeRoute(hrp.Position, pos) then trickRetryAt = tick() + 2.5; return false end
        PF.state = "trick"
        PF.valid = function() return pp.Parent ~= nil and pp.Enabled ~= false and not nearAny(pos, cfg.itemClear) end
        local reach = math.max(3, (pp.MaxActivationDistance or 8) - 2)
        PF.watchRoute = true; PF.routeAbort = false
        local arrived = walkTo(hum, pos, reach, 25)
        PF.watchRoute = false
        local aborted = PF.routeAbort
        PF.routeAbort = false
        PF.valid = nil
        if aborted then trickRetryAt = tick() + 2.5; return true end
        local done = false
        if arrived and pp.Parent then
            fireOnePrompt(pp)
            for _ = 1, 4 do
                if not pp.Parent or pp.Enabled == false then break end
                task.wait()
            end
            done = (not pp.Parent) or pp.Enabled == false
        end
        if arrived or not (pp.Parent and pp.Enabled ~= false) then A.totMark(pp, done) end
        return true
    end

    local function doCollect(hum, hrp)
        if not (S.autoCollect and S.autoEnabled and S.trigOk("collect")) then return false end
        if S.pickupFloorBlocked(true) then return false end   
        local A = _G.YattaAdditionals
        if not (A and A.collectibles and A.pieceTarget) then return false end
        local cands = {}
        for _, c in ipairs(A.collectibles()) do
            local t = A.pieceTarget(c)
            local bad = PF.badItems[c]
            if t and t.Parent and not (bad and bad > tick())
               and not IsCachedMonsterNearPosition(t.Position, K.monSkipR, false, true)
               and not nearAny(t.Position, cfg.itemClear) then
                cands[#cands + 1] = { c = c, t = t, d = (t.Position - hrp.Position).Magnitude }
            end
        end
        if #cands == 0 then return false end
        table.sort(cands, function(a, b) return a.d < b.d end)
        local best, bt, tried = nil, nil, 0
        for _, k in ipairs(cands) do
            if tried >= 3 then break end
            tried = tried + 1
            if safeRoute(hrp.Position, k.t.Position) then best, bt = k.c, k.t; break end
            PF.badItems[k.c] = tick() + 2.5
        end
        if not best then return false end
        PF.state = "item"
        PF.valid = function()
            return best.Parent ~= nil and bt.Parent ~= nil and not nearAny(bt.Position, cfg.itemClear)
        end
        PF.watchRoute = true; PF.routeAbort = false
        walkTo(hum, bt.Position, 2.5, 20)
        PF.watchRoute = false
        local aborted = PF.routeAbort
        PF.routeAbort = false
        PF.valid = nil
        if aborted then PF.badItems[best] = tick() + 3; return true end
        if best.Parent then
            local _, _, r2 = getChar()
            if r2 and firetouchinterest and (r2.Position - bt.Position).Magnitude <= 9 then
                local parts = {}
                if best:IsA("BasePart") then parts[1] = best
                else
                    for _, d in ipairs(best:GetDescendants()) do
                        if d:IsA("BasePart") then
                            parts[#parts + 1] = d
                            if #parts >= 6 then break end
                        end
                    end
                end
                for _, bp2 in ipairs(parts) do
                    pcall(function() firetouchinterest(r2, bp2, 0); firetouchinterest(r2, bp2, 1) end)
                end
            end
            PF.badItems[best] = tick() + 8
        end
        return true
    end

    local function pickGen(hrp, skip)
        local best, bd, bestTread = nil, math.huge, false
        local anyLeft = false
        for _, gen in ipairs(Cache.genList) do
            if gen.Parent and not IsConnieGen(gen) and not IsGenCompleted(gen) then
                anyLeft = true
                local bad = PF.badGens[gen]
                if not (bad and bad > tick()) and not (skip and skip[gen]) then
                    local gp = Cache.genPivotCache[gen] or gen:GetPivot().Position
                    local hasTen, hasBlot = IsTendrilNearGen(gp)
                    local free
                    if IsDualGen(gen.Name) then
                        free = (not IsDualGenFullyOccupied(gen)) and (DualGenSlotUsable(gen) ~= nil)
                    else
                        free = not IsGenOccupiedByOtherPlayer(gen)
                    end
                    if (not hasTen) and (not hasBlot) and free and R.igs(gen)
                       and IsGenSafeFromBalls(gen)
                       and not IsCachedMonsterNearGen(gp, C.genApproachClearRadius, false)
                       and not nearAny(gp, cfg.itemClear) then
                        local isTread = (gen:GetAttribute("MinigameType") == "MovementTreadmill")
                        local d = (gp - hrp.Position).Magnitude
                        if (S.genAvoid[gen] or 0) > tick() then d = d + 100000 end
                        local better = false
                        if S.extractTreadmillsFirst and isTread ~= bestTread then
                            better = isTread
                        else
                            better = d < bd
                        end
                        if best == nil or better then best = gen; bd = d; bestTread = isTread end
                    end
                end
            end
        end
        return best, anyLeft
    end

    local function genTarget(gen)
        local pp = nil
        local prompts = GetCachedProximityPrompts(gen)
        for _, p in ipairs(prompts) do
            if p and p.Parent and p.Enabled then pp = p; break end
        end
        if not pp then
            for _, p in ipairs(prompts) do
                if p and p.Parent then pp = p; break end
            end
        end
        local ppPos = gen:GetPivot().Position
        if pp then
            local par = pp.Parent
            if par:IsA("BasePart") then ppPos = par.Position
            elseif par:IsA("Attachment") then ppPos = par.WorldPosition end
        end
        return pp, ppPos
    end

    local function doExtract(hum, hrp)
        local skip = {}
        local gen, anyLeft, pp, ppPos
        for _ = 1, 3 do
            local g, left = pickGen(hrp, skip)
            anyLeft = left
            if not g then return false, anyLeft end
            local p, pos = genTarget(g)
            if safeRoute(hrp.Position, pos) then
                gen, pp, ppPos = g, p, pos
                break
            end
            skip[g] = true
            PF.badGens[g] = tick() + 2.5
        end
        if not gen then return false, anyLeft end
        PF.state = "extract"
        local gpv = gen:GetPivot().Position
        local reach = math.max(3, (pp and pp.MaxActivationDistance or 8) - 2)
        PF.valid = function()
            return gen.Parent ~= nil and not IsGenCompleted(gen)
               and not IsCachedMonsterNearGen(gpv, C.genApproachClearRadius, false)
        end
        PF.watchRoute = true; PF.routeAbort = false
        local arrived = walkTo(hum, ppPos, reach, 25)
        PF.watchRoute = false
        local aborted = PF.routeAbort
        PF.routeAbort = false
        PF.valid = nil
        if not arrived then
            PF.badGens[gen] = tick() + (aborted and 3 or 8)
            return true, anyLeft
        end
        if R.gag() ~= gen then FireGenProximityPrompts(gen) end
        for _ = 1, 10 do
            if R.gag() == gen then break end
            task.wait(0.05)
        end
        if R.gag() ~= gen then PF.badGens[gen] = tick() + 5 end
        return true, anyLeft
    end

    local function realElevPos()
        local okR, b = pcall(R.fpb)
        if okR and b and b.Parent then return b.Position + Vector3.new(0, 3, 0) end
        local elevs = workspace:FindFirstChild("Elevators")
        local elev  = elevs and elevs:FindFirstChild("Elevator")
        local base  = elev and elev:FindFirstChild("Base", true)
        if base and base:IsA("BasePart") then return base.Position + Vector3.new(0, 3, 0) end
        return nil
    end

    local function panicPath(from, base)
        local w = computePath(from, base, true)
        if w then return w end
        buildExclude()
        for k = 0, 7 do
            local ang = k * math.pi / 4
            for _, rad in ipairs({ 6, 11 }) do
                local p = base + Vector3.new(math.cos(ang) * rad, 0, math.sin(ang) * rad)
                local g = groundAt(p)
                if g and math.abs(g.Y - (base.Y - 3)) < 12 then
                    w = computePath(from, g + Vector3.new(0, 3, 0), true)
                    if w then return w end
                end
            end
            if k % 2 == 1 then task.wait() end
        end
        return nil
    end

    local function panicRequestPlan(from, target)
        if PF.panicBusy then return end
        PF.panicBusy = true
        PF.panicT = tick()
        task.spawn(function()
            local goalAtReq = PF.pHopLast
            local ok, w = pcall(panicPath, from, target)
            PF.panicBusy = false
            if ok and w and PF.state == "panic" and goalAtReq == PF.pHopLast then PF.panicRes = w end
        end)
    end

    local function panicForwardIdx(w, pos)
        local n = #w
        local bi, bd = 1, math.huge
        for i = 1, n do
            local dx, dz = w[i].Position.X - pos.X, w[i].Position.Z - pos.Z
            local d = dx * dx + dz * dz
            if d < bd then bd = d; bi = i end
        end
        return math.clamp(bi + 1, 2, n)
    end

    local function panicHopGoal(pos, elev)
        local hop = PF.pHop
        if hop and (not hop.part.Parent or math.abs(hop.inside.X - pos.X) + math.abs(hop.inside.Z - pos.Z) < 3.5) then
            hop = nil; PF.pHop = nil
        end
        if (pos - elev).Magnitude <= 30 then PF.pHop = nil; return nil end
        if hop then return hop.inside end
        if tick() - (PF.pHopT or 0) < 0.4 then return nil end
        PF.pHopT = tick()
        local colls = PF.colls
        if not colls or #colls == 0 then return nil end
        local dTotal = (pos - elev).Magnitude
        local best, bs = nil, math.huge
        for _, c in ipairs(colls) do
            if c.Parent then
                local cp = c.Position
                local dMe = (cp - pos).Magnitude
                local dEl = (cp - elev).Magnitude
                if dMe >= 6 and dMe <= 70 and dEl < dTotal - 12 and math.abs(cp.Y - pos.Y) < 25 then
                    local bad = PF.badParts[c]
                    if not (bad and bad > tick()) then
                        local sc = dEl + dMe * 0.35
                        if sc < bs then bs = sc; best = c end
                    end
                end
            end
        end
        if not best then return nil end
        local ins = Vector3.new(best.Position.X, pos.Y, best.Position.Z)
        PF.pHop = { part = best, inside = ins }
        return ins
    end

    local function panicTick(hum, hrp, tl)
        local target = realElevPos()
        if not target then flee(hum, hrp, tl); return end
        local now = tick()
        PF.panicWps = nil; PF.panicRes = nil; PF.pHop = nil; PF.pHopLast = nil
        if (hrp.Position - target).Magnitude <= 5 then
            if PF.wps then PF.wps = nil; stopMove(hum, hrp) end
            return
        end
        if now - (PF.panicTpT or 0) < 0.5 then return end
        PF.panicTpT = now
        PF.wps = nil
        stopMove(hum, hrp)
        pcall(function()
            R.TpTo(hrp, CFrame.new(target) * (hrp.CFrame - hrp.CFrame.Position))
        end)
    end

    task.spawn(function()
        if R.isR then return end
        while true do
            task.wait(0.15)
            if PF.active then
                local okC, colls = pcall(refreshColliders)
                if okC and colls then
                    local n = 0
                    for _, c in ipairs(colls) do
                        if c.Parent and not spotCache[c] then
                            if n == 0 then buildExclude() end
                            spotCache[c] = spotsFor(c)
                            n = n + 1
                            if n >= 10 then break end
                        end
                    end
                end
            end
        end
    end)

    do
        local animChar, animator, tracks = nil, nil, {}
        local function trackFor(ch, hum, name)
            if animChar ~= ch then
                animChar, tracks = ch, {}
                animator = hum:FindFirstChildOfClass("Animator")
            end
            if not animator or not animator.Parent then animator = hum:FindFirstChildOfClass("Animator") end
            local t = tracks[name]
            if t then return t end
            local cfgFolder = ch:FindFirstChild("Animations")
            local anim = cfgFolder and cfgFolder:FindFirstChild(name)
            if not (anim and anim:IsA("Animation") and animator) then return nil end
            local okL, tr = pcall(function() return animator:LoadAnimation(anim) end)
            if not okL or not tr then return nil end
            tr.Priority = Enum.AnimationPriority.Action
            tr.Looped   = true
            tracks[name] = tr
            return tr
        end
        local function gameAlreadyPlays(tr)
            if not animator then return false end
            local id = tr.Animation and tr.Animation.AnimationId
            for _, other in ipairs(animator:GetPlayingAnimationTracks()) do
                if other ~= tr and other.Animation and other.Animation.AnimationId == id
                   and other.WeightCurrent > 0.2 then
                    return true
                end
            end
            return false
        end
        local function stopAll()
            for _, tr in pairs(tracks) do
                if tr.IsPlaying then pcall(function() tr:Stop(0.15) end) end
            end
        end
        S.regGame(function()
            while true do
                task.wait(0.1)
                local ch  = plr.Character
                local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
                if not (hum and hrp and hum.Health > 0) then stopAll(); continue end
                local v = hrp.AssemblyLinearVelocity
                local speed = math.sqrt(v.X * v.X + v.Z * v.Z)
                local moving = S.pathfindMode and S.autoEnabled and PF.active
                    and (hum.MoveDirection.Magnitude > 0.1 or speed > 2)
                if not moving then stopAll(); continue end
                local qset = _G.YattaQuirkSet and _G.YattaQuirkSet(ch) or {}
                if animator then
                    for _, pt in ipairs(animator:GetPlayingAnimationTracks()) do
                        local pa = pt.Animation
                        if _G.YattaIsQuirkTrack(pt) then
                            pcall(function() pt:Stop(0.1) end)
                        end
                    end
                end
            end
        end)
    end

    local maxStam = 0
    local sprintFlipOn, sprintFlipAt = true, 0
    regC(plr.CharacterAdded, function() S.isSprinting = false; S.flipOwned = false; sprintFlipAt = 0 end)
    task.spawn(function()
        if R.isR then return end
        while true do
            task.wait(0.1)
            if S.sprintLoopActive then sprintFlipAt = 0; continue end
            if S.shTweening or S.shSprintOwned or S.shActive then sprintFlipAt = 0; continue end
            local want = false
            local faS = R.gfv()
            local floorOn = faS and faS:IsA("BoolValue") and faS.Value == true
            local extracting = (R.gag() ~= nil) or PF.state == "extracting"
            local hidingStill = PF.arrived and (PF.state == "hide" or PF.state == "wait-hide")
            if PF.active and floorOn and S.pathfindMode
               and not extracting and not hidingStill then
                want = true
                local okS, st = pcall(R.gcs)
                if okS and type(st) == "number" and st < 1e9 then
                    if st > maxStam then maxStam = st end
                    local top = (maxStam > 0) and maxStam or 100
                    if st <= top * C.staminaStopPct then PF.stamLocked = true
                    elseif st >= top * 0.6 then PF.stamLocked = false end
                    if PF.stamLocked then want = false end
                end
            else
                sprintFlipAt = 0
            end
            if want then
                if not S.sprintReal() and tick() - (S.flipSentAt or 0) > 0.5 then
                    S.flipSentAt = tick(); S.flipOwned = true
                    pcall(R.FSprt, true)
                end
            elseif S.flipOwned then
                S.flipOwned = false
                local uis = game:GetService("UserInputService")
                local shiftHeld = uis:IsKeyDown(Enum.KeyCode.LeftShift) or uis:IsKeyDown(Enum.KeyCode.RightShift)
                if S.sprintReal() and not shiftHeld then
                    S.flipSentAt = tick()
                    pcall(R.FSprt, false)
                end
            end
        end
    end)

    task.spawn(function()
        if R.isR then return end
        local anchorPos, anchorT = nil, 0
        local level, side = 0, 1
        local function forceRepath()
            PF.lastMoveIdx = nil; PF.lastCmdPos = nil; PF.lastCmdT = 0; PF.pathT = 0
        end
        local function push(hum, hrp, dir, dist, secs)
            local tgt = hrp.Position + dir * dist
            local t0 = tick()
            while tick() - t0 < secs do
                if hum.Health <= 0 then return end
                pcall(function() hum:MoveTo(tgt) end)
                task.wait(0.1)
            end
        end
        local function pickDir(hrp, cands, dist)
            local tl = PF.tl
            if not tl or #tl == 0 then return cands[1] end
            local pos = hrp.Position
            local _, d0 = nearest(pos, tl)
            local best, bestD = cands[1], -1
            for _, c in ipairs(cands) do
                local _, d1 = nearest(pos + c * dist, tl)
                if d1 >= d0 - 1 then return c end
                if d1 > bestD then best, bestD = c, d1 end
            end
            return best
        end
        while true do
            task.wait(0.25)
            local faW = R.gfv()
            local floorOn = faW and faW:IsA("BoolValue") and faW.Value == true
            local _, hum, hrp = getChar()
            local active = hum and hrp and floorOn and PF.active and S.pathfindMode and S.autoEnabled
            local skip = (not active) or S.shActive or S.shTweening or hum.Sit or (R.gag() ~= nil)
                or PF.state == "extracting" or PF.encPaused
                or (PF.arrived and (PF.state == "hide" or PF.state == "wait-hide" or PF.state == "hold"))
            if skip or hum.MoveDirection.Magnitude < 0.1 then
                anchorPos = nil; level = 0
            else
                local pos = hrp.Position
                if not anchorPos then
                    anchorPos, anchorT = pos, tick()
                elseif tick() - anchorT >= 1.4 then
                    local moved = Vector3.new(pos.X - anchorPos.X, 0, pos.Z - anchorPos.Z).Magnitude
                    if moved >= 1.2 then
                        level = 0
                    else
                        level = level + 1
                        local dir = Vector3.new(hum.MoveDirection.X, 0, hum.MoveDirection.Z)
                        if dir.Magnitude < 0.05 then dir = hrp.CFrame.LookVector end
                        dir = dir.Unit
                        hum.Jump = true
                        local perp = Vector3.new(-dir.Z, 0, dir.X)
                        if level == 1 then
                            side = -side
                            push(hum, hrp, pickDir(hrp, { perp * side, perp * -side, -dir }, 6), 6, 0.7)
                        elseif level == 2 then
                            push(hum, hrp, pickDir(hrp, { -dir, perp * side, perp * -side }, 6), 6, 0.8)
                        elseif level == 3 then
                            local d1 = CFrame.Angles(0, math.rad(135 * side), 0):VectorToWorldSpace(dir)
                            local d2 = CFrame.Angles(0, math.rad(-135 * side), 0):VectorToWorldSpace(dir)
                            push(hum, hrp, pickDir(hrp, { d1, d2, perp * side, perp * -side }, 8), 8, 0.9)
                        else
                            PF.giveUpUntil = tick() + 1.0
                            push(hum, hrp, pickDir(hrp, { -dir, perp * side, perp * -side }, 5), 5, 0.6)
                            level = 0
                        end
                        forceRepath()
                    end
                    local _, _, h2 = getChar()
                    anchorPos, anchorT = (h2 and h2.Position or pos), tick()
                end
            end
        end
    end)

    if R.isR then return end
    while true do
        task.wait(0.05)
        local faPf = R.gfv()
        local floorOn = faPf and faPf:IsA("BoolValue") and faPf.Value == true
        if not (S.pathfindMode and S.autoEnabled and floorOn) or R.isR then
            if PF.active then
                PF.active = false
                S.shByPathfind = false
                PF.hideLatchT = nil; PF.latchClearSince = nil
                PF.leaveSpot = nil
                local _, h, r = getChar()
                stopMove(h, r)
                clearHide()
                clearDanger()
                PF.tl = nil
                PF.valid = nil
            end
            continue
        end
        local ch, hum, hrp = getChar()
        if not PF.active then
            PF.exitPos = nil; PF.exitUntil = nil
            if hrp and not elevIsOut(hrp.Position) then
                local fp = elevFrontPoint(hrp.Position)
                if fp then
                    buildExclude()
                    local g = groundAt(fp + Vector3.new(0, 6, 0))
                    local tp = g and (g + Vector3.new(0, 3, 0)) or (fp + Vector3.new(0, 3, 0))
                    pcall(function()
                        hrp.AssemblyLinearVelocity = Vector3.zero
                        R.TpTo(hrp, CFrame.new(tp) * (hrp.CFrame - hrp.CFrame.Position))
                    end)
                    stopMove(hum, hrp)
                    task.wait(0.25)
                end
            end
        end
        PF.active = true
        if not ch then continue end
        do
            local okPn, pn = pcall(IsPanicActive)
            if okPn and pn and (S.encounterActive or S.aeGourdyWaiting or (S.autoEncounter and _G.yattaAE and not _G.yattaAE.allDone)) then
                if not PF.encPaused then
                    PF.encPaused = true
                    S.shByPathfind = false
                    PF.spot = nil; PF.wps = nil; PF.pending = nil; PF.arrived = false
                    clearHide()
                    stopMove(hum, hrp)
                end
                continue
            elseif PF.encPaused then
                PF.encPaused = false
            end
        end
        if S.shActive then
            if S.shByPathfind then
                local okT, thrNow = pcall(threatened)
                if okT and thrNow then S.shSeenUntil = math.max(S.shSeenUntil or 0, tick() + 1.5) end
            end
            continue
        end
        if S.shByPathfind then
            S.shByPathfind = false
            PF.arrived = false; PF.entering = false; PF.enterT0 = nil; PF.spot = nil; PF.wps = nil
        end
        if R.idso() or R.icv() then continue end
        if S.gigiBusy or S.collectBusy or S.totBusy then continue end
        if PF.exitUntil then
            if exitElevTick(hum, hrp) then PF.state = "exit-elevator"; continue end
        end

        local tl = threats()
        PF.tl = tl
        local okPn0, pn0 = pcall(IsPanicActive)
        if okPn0 and pn0 then
            if not PF.inPanic then PF.inPanic = true; clearDanger() end
        else
            PF.inPanic = false
            updateDanger(tl)
        end
        local _, myMin = nearest(hrp.Position, tl)
        local needHide = threatened()
        if coverMode() then
            if needHide then
                PF.hideLatchT = PF.hideLatchT or tick()
                PF.latchClearSince = nil
            elseif PF.hideLatchT then
                local clearNow = true
                local okC, c = pcall(S.shDetClear, hrp.Position)
                if okC and c == false then clearNow = false end
                if myMin < 40 then clearNow = false end
                if PF.spot and PF.spot.pos then
                    local _, dSpot = nearest(PF.spot.pos, tl)
                    if dSpot < 25 then clearNow = false end
                end
                if clearNow then PF.latchClearSince = PF.latchClearSince or tick() else PF.latchClearSince = nil end
                if PF.latchClearSince and tick() - PF.latchClearSince >= 3 then
                    PF.hideLatchT = nil; PF.latchClearSince = nil
                elseif tick() - PF.hideLatchT > 120 then
                    PF.hideLatchT = nil; PF.latchClearSince = nil
                else
                    needHide = true
                end
            end
        else
            PF.hideLatchT = nil; PF.latchClearSince = nil
        end
        if PF.specialNew then
            PF.specialNew = false
            PF.spot = nil; PF.wps = nil; PF.pending = nil
            PF.arrived = false; PF.lastPick = 0
            PF.hideFromSeen = true
            needHide = true
        end
        if not needHide and PF.hideFromSeen then
            PF.hideFromSeen = false
            clearHide()
            stopMove(hum, hrp)
        end

        local ag = R.gag()
        if ag then
            if needHide then
                if tick() - PF.lastStop > 0.6 then
                    PF.lastStop = tick()
                    pcall(R.fsg, ag)
                    pcall(R.fsgcr, ag)
                end
            else
                PF.state = "extracting"
                continue
            end
        end

        local okPn, panic = pcall(IsPanicActive)
        if okPn and panic then
            PF.safeSince = nil
            PF.spot = nil; PF.pending = nil
            PF.state = "panic"
            panicTick(hum, hrp, tl)
            continue
        elseif PF.panicWps or PF.panicRes then
            PF.panicWps = nil; PF.panicRes = nil; PF.pStuckPos = nil
            clearHide()
        end

        if needHide then
            PF.safeSince = nil
            PF.state = "hide"
            PF.hideFromSeen = true
            if not (coverMode() and PF.arrived) and cornerCheck(hrp, tl) then continue end   
            hideTick(hum, hrp, tl)
            continue
        end

        if PF.spot or PF.picking or PF.pending then
            if myMin >= cfg.clearDist then
                PF.safeSince = PF.safeSince or tick()
                if tick() - PF.safeSince >= cfg.clearHold then clearHide() end
            else
                PF.safeSince = nil
            end
            if PF.spot then
                PF.state = "hold"
                hideTick(hum, hrp, tl)
                continue
            end
        end

        do
            local ls = PF.leaveSpot
            if ls then
                local dxl, dzl = ls.pos.X - hrp.Position.X, ls.pos.Z - hrp.Position.Z
                local dl = math.sqrt(dxl * dxl + dzl * dzl)
                if dl <= 2.5 or tick() - ls.t > 3.5 or math.abs(ls.pos.Y - hrp.Position.Y) > 12 then
                    PF.leaveSpot = nil
                    PF.lastCmdPos = nil; PF.lastCmdT = 0; PF.pathT = 0
                else
                    PF.state = "leave-spot"
                    issueMove(hum, ls.pos, 0.5)
                    if not PF.leaveLastP or tick() - (PF.leaveLastT or 0) > 0.7 then
                        if PF.leaveLastP and (hrp.Position - PF.leaveLastP).Magnitude < 0.6 then hum.Jump = true end
                        PF.leaveLastP, PF.leaveLastT = hrp.Position, tick()
                    end
                    task.wait(0.05)
                    continue
                end
            end
        end
        if doItems(hum, hrp) then continue end
        if doTrick(hum, hrp) then continue end
        if doCollect(hum, hrp) then continue end
        local handled, anyLeft = doExtract(hum, hrp)
        if handled then continue end
        local waitItems = PF.itemsWaiting and PF.itemWaitSince and (tick() - PF.itemWaitSince) < 30
        if anyLeft or waitItems then
            PF.state = "wait-hide"
            hideTick(hum, hrp, tl)
        else
            PF.state = "elevator"
            goElevator(hum, hrp)
        end
    end
end)
_G.YattaPart3Done = true
end
BootPart3()
